-- GENERATED by `wfj generate` from data/quest/quest-0000.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [1] = { "La missione \"Chow\" (123)aa", "Uccidi Kobold Vermin, 2 in tutto.", "$N1! Uccidi Kobold Vermin, 2 in tutto. NUOVO TEST ANCORA", nil, nil, 0xdb0905c3, 0x314b469d, 0x671a32c1, nil, nil, "...mm" },
  [2] = { "⟦Sharptalon's Claw=Artiglio di Grinfiafina⟧", "Porta l'⟦Sharptalon's Claw=Artiglio di Grinfiafina⟧ a Senani Thunderheart all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "Il possente ippogrifo Sharptalon è stato ucciso, e l'artiglio della bestia abbattuta è la testimonianza della tua vittoria. Senani Thunderheart, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, vorrà senz'altro vedere questo trofeo come prova delle tue imprese.", "Sì, possente {class}, ho percepito il tuo arrivo. Immagino tu abbia altre notizie da riferirmi sulla tua caccia?", "Davvero notevole, {name}... l'artiglio di Sharptalon non dev'essere stato facile da prendere! La caccia di ⟦Ashenvale=Valtetra⟧ procede bene per te!\n\nSharptalon terrorizzava da tempo i peoni dei campi di taglio lungo il suo cammino, mentre cercavano di raggiungere l'⟦Splintertree Post=Avamposto di Troncorotto⟧. Non c'è dubbio che, quando si spargerà la voce che sei stat<o/a> tu ad abbattere la bestia, attorno ai fuochi e nelle segherie di tutta ⟦Ashenvale=Valtetra⟧ si sentiranno molti canti entusiasti sul tuo coraggio!", 0xd311f9a5, 0x0ed5211e, 0x0d8319c7, 0x4dd41a0e, 0xfc0f918c, "....." },
  [5] = { "La pancia brontolona di Jitters", "Parla con lo chef Grual.", "Sono settimane che sto nascosto in questa città fantasma e non ho mangiato altro che larve ed erbacce! Mi serve del cibo decente, e sono disposto a pagarlo bene.\n\nPortami un banchetto e ti pagherò profumatamente.\n\nHo sentito che lo chef Grual, alla Scarlet Raven Tavern di ⟦Darkshire=Borgoscuro⟧, prepara un ottimo ⟦Dusky Crab Cakes=Tortino di Granchio Scuro⟧...", nil, "Ti servono dei tortini di granchio, eh? Beh, forse potrei cucinartene qualcuno...", 0x13753190, 0x3c550677, 0xb656ff77, nil, 0x9ca7596b, "...m." },
  [6] = { "Taglia su Garrick Padfoot", "Uccidi Garrick Padfoot e porta la sua testa al vicesceriffo Willem all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Garrick Padfoot, un tagliagole che da settimane tormenta i nostri contadini e mercanti, è stato visto in una baracca vicino alle vigne, a est dell'Abbazia, oltre il ponte. Portami la testa di quel furfante e la taglia sarà tua!\n\nMa stai in guardia, {name}. Garrick si è circondato di una banda di delinquenti. Non sarà facile arrivare fino a lui.", "Hai trovato la baracca di Garrick? Siamo finalmente liberi da quel furfante?", "Ah! L'hai preso! Hai reso un gran servizio a Elwynn e ti sei guadagnato una bella taglia!", 0xd9a1ea2f, 0xb35875a3, 0x674275ec, 0xe205dce0, 0x8edda1cf, "....." },
  [7] = { "Ripulire l'accampamento dei coboldi", "Uccidi 10 Kobold Vermin, poi torna dal maresciallo McBride.", "Il tuo primo compito è fare pulizia, {name}. Un clan di coboldi ha infestato i boschi a nord. Va' laggiù e combatti i Kobold Vermin che trovi. Riduci il loro numero, così che un giorno potremo cacciarli dalla ⟦Northshire=Contea del Nord⟧.", "Come va la caccia, {name}? Hai trovato e sconfitto quei parassiti?", "Ben fatto, cittadino. Quei coboldi sono ladri e codardi, ma in gran numero sono una minaccia per noi. E gli umani di ⟦Stormwind=Roccavento⟧ non hanno bisogno di un'altra minaccia.\n\nPer averli sconfitti, hai la mia gratitudine.", 0x5d10a531, 0xc0a62578, 0x54635c79, 0x4eb51373, 0xb52dae46, "....." },
  [8] = { "L'affare di un furfante", "Consegna la ⟦Nondescript Letter=Lettera Insignificante⟧ alla locandiera Renee nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Ehi, amico! Mi fai un favore? Sono un giovanotto che ha già combattuto più zombi senza mente e ragni di quanti gliene spettassero.\n\nHo qui una lettera che deve arrivare a Brill... a una locandiera di nome Renee, o qualcosa del genere. Il cognome non importa granché.\n\nComunque, è un posticino caldo e accogliente, pieno di vittime della pestilenza che cercano di tirare avanti. Ed è anche un ottimo posto per riposarti, se ne hai bisogno. Dovresti farci un salto... fallo e ti pagherò bene.", "Sì? Sì? Che c'è?\n\nI Reietti hanno di certo un appetito enorme. Fa' come se fossi a casa tua... sì, riposa quelle ossa stanche. Mi chiamo Renee, se ti serve qualcosa.", "Oh? Una lettera? Che bella notizia! Aspettavo notizie dalla mia cara vecchia madre ad ⟦Deathknell=Albamorta⟧. È una santa, davvero. Chissà come se la passa.\n\nCosa? Troppo allegra? Non ci credi, eh?\n\nAllora sparisci... tanto non sono affari tuoi da chi viene la lettera. Avanti! Sparisci!\n\nTorna quando avrai qualche moneta da spendere... fannullone.\n\nVedrai che finirai per tornare a riposarti dopo una lunga giornata di avventure o qualche stupidaggine del genere.", 0x824c6911, 0xb1b93800, 0x71981765, 0x1ea589a5, 0x6285e1f4, "....." },
  [9] = { "Campi di sterminio", "Il contadino Saldean vuole che tu uccida 20 Harvest Watcher.", "Guarda cos'è successo a questo posto! Un tempo queste terre erano abitate da brava gente di campagna. Ma quei maledetti ladri li hanno cacciati tutti. Me no, però! Solo che, a quanto pare, alcuni Harvest Watcher si sono impadroniti dei campi.\n\nSe te la senti, vorrei che andassi là fuori e ne uccidessi venti. Torna quando hai finito e avrai la tua paga. Se finisci con quelli del mio campo, ripulisci anche i campi vicini.", "Ah, vedo che sei tornat<o/a>! Spero che tu abbia lavorato sodo per ripulire quei campi dagli Harvest Watcher. Ne hai già uccisi venti?", "Ottimo lavoro, amico. Ti sei guadagnat<o/a> la paga. Chissà, forse le ⟦Westfall=Marche Occidentali⟧ torneranno a prosperare.", 0xe8dc51f9, 0xb1fcb3e9, 0xc49a0580, 0x0e0d21d8, 0x9ce4bf4e, "....." },
  [11] = { "Taglia sugli gnoll Riverpaw", "Porta 8 Painted Gnoll Armband al vicesceriffo Rainer, alla caserma.", "Gli gnoll, creature brutali che non hanno nulla da fare in queste terre, sono stati avvistati lungo i confini della ⟦Elwynn Forest=Foresta di Elwynn⟧. Un grosso branco, molto più numeroso di quanto possiamo affrontare da soli, ha infestato i boschi a sud di quella torre di guardia laggiù. Un altro gruppo ha infestato la zona vicino al ⟦Stone Cairn Lake=Lago del Memoriale⟧, a est.\n\nL'esercito di ⟦Stormwind=Roccavento⟧ renderà onore a chiunque aiuti a sterminarli. Portami i loro bracciali dipinti da gnoll come prova della tua impresa.", "Salve, {name}. Hai dato la caccia agli gnoll...?", "Vedo che ti sei <dato/data> da fare! Hai la nostra gratitudine, {name}.", 0x9b53bb87, 0x8f6713f0, 0x9259d68e, 0x11769f64, 0xc6ac4114, "....." },
  [12] = { "La ⟦People's Militia=Milizia del Popolo⟧", "Gryan Stoutmantle vuole che tu uccida 15 Defias Trapper e 15 Defias Smuggler, poi torni da lui a ⟦Sentinel Hill=Guardiacolle⟧.", "La ⟦People's Militia=Milizia del Popolo⟧ ha un solo obiettivo: difendere le terre delle ⟦Westfall=Marche Occidentali⟧ e riportare la pace in questi luoghi. Purtroppo il prezzo della pace è spesso il sangue.\n\nUno dei miei esploratori mi ha riferito di una banda di Defias Trapper che semina il caos qui vicino. Ho rapporti di avvistamenti vicino alla ⟦Jangolode Mine=Miniera Venacava⟧, a nord-ovest, oltre che alla fattoria dei Molsen e al ⟦Furlbrow's Pumpkin Farm=Campo di Zucche dei Ciglioarcuato⟧. Se vuoi unirti alle nostre file, uccidi 15 Defias Trapper e 15 Defias Smuggler, poi torna da me.", "Forse non sono stato chiaro, recluta. Per dimostrare il tuo valore al servizio della ⟦People's Militia=Milizia del Popolo⟧ e della Luce devi uccidere 15 Defias Trapper e 15 Defias Smuggler, poi tornare da me a lavoro finito.", "Ben fatto, {name}. Il mio esploratore ha visto le tue gesta valorose. Finora ti stai dimostrando all'altezza.", 0xe151209f, 0x16896ec7, 0x8596ea3e, 0xecfd7c3c, 0x84930ba2, "....." },
  [13] = { "La ⟦People's Militia=Milizia del Popolo⟧", "Gryan Stoutmantle vuole che tu uccida 15 Defias Pillager e 15 Defias Looter e poi torni da lui a ⟦Sentinel Hill=Guardiacolle⟧.", "Una banda di feroci Defias Pillager è stata vista saccheggiare la ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧, ⟦Moonbrook=Rivoluna⟧ e la ⟦Alexston Farmstead=Cascina degli Alexston⟧. La ⟦People's Militia=Milizia del Popolo⟧ non tollererà un simile comportamento. Parti subito, {name}, e fai sentire la presenza della Luce nelle ⟦Westfall=Marche Occidentali⟧.\n\nLa ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧ è vicino alla riva, a ovest della torre. Come prossima fase del tuo addestramento, voglio che tu uccida 15 di quei luridi Defias Pillager e 15 Defias Looter.", "Non c'è tempo per parlare, {name}. I Defias Pillager negano alla gente delle ⟦Westfall=Marche Occidentali⟧ la pace e la prosperità che merita. Assicurati che almeno 15 Defias Pillager e 15 Defias Looter vengano uccisi. Sarà un messaggio chiaro: qui la corruzione non è gradita.", "Le tue azioni coraggiose hanno finora confermato il tuo valore per la ⟦People's Militia=Milizia del Popolo⟧.", 0xe151209f, 0x6d788fcc, 0x1eea16a0, 0x687557dd, 0xb859c405, "....." },
  [14] = { "La ⟦People's Militia=Milizia del Popolo⟧", "Gryan Stoutmantle vuole che tu uccida 15 Defias Highwayman, 5 Defias Pathstalker e 5 Defias Knuckleduster, poi torni da lui a ⟦Sentinel Hill=Guardiacolle⟧.", "Alcuni Defias ci sono sfuggiti. Il mio esploratore più fidato riferisce che hanno saccheggiato e depredato le campagne fino alle ⟦Westfall=Marche Occidentali⟧ meridionali. Crediamo che si nascondano nella Catena delle Daghe, a tramare la loro prossima mossa. Uccidi quei miserabili in nome della ⟦People's Militia=Milizia del Popolo⟧.", "{name}, non è il momento delle chiacchiere. Se vuoi ancora dimostrare il tuo valore alla ⟦People's Militia=Milizia del Popolo⟧, devi uccidere i Defias di cui ti ho parlato prima. Torna da me quando avrai compiuto il tuo dovere.", "Quando ho lasciato le terre contaminate di Lordaeron, sono tornato in patria e ho trovato una triste situazione. Ma per le ⟦Westfall=Marche Occidentali⟧ c'è ancora speranza. Il valore che hai dimostrato in battaglia mi rende evidente che servi la nostra causa con onore. È con grande orgoglio che ti accolgo nella ⟦People's Militia=Milizia del Popolo⟧. Che la Luce splenda su di te.", 0xe151209f, 0x78ad5d7f, 0xab47f493, 0xa480f62a, 0xf947b26e, "....." },
  [15] = { "Indagini a Cresta dell'Eco", "Uccidi 10 Kobold Worker, poi torna a fare rapporto al maresciallo McBride.", "{name}, i miei esploratori mi dicono che l'infestazione di coboldi è più grande di quanto pensassimo. Un gruppo di Kobold Worker si è accampato vicino alla ⟦Echo Ridge Mine=Miniera Cresta dell'Eco⟧, a nord.\n\nVa' alla miniera e cacciali via. Sappiamo che sono almeno 10. Uccidili, controlla se ce ne sono altri, poi torna a fare rapporto da me.", "Sei stat<o/a> alle miniere? Sei pront<o/a> a fare rapporto?", "Non mi piace sentire che ci sono tutti questi coboldi nella nostra miniera. Non ne verrà niente di buono. Ecco, prendi questo come pagamento e, quando sei pront<o/a>, parlami di nuovo. Vorrei che tornassi alle miniere ancora una volta...", 0xb43a6289, 0xa368f704, 0x2cb816b5, 0x063df25d, 0xf0b6a1c7, "....." },
  [16] = { "Da bere per Gerard", nil, nil, "Lavorare nei campi mette sete, e cerco sempre acqua di fonte fresca.\n\nSe ne hai un po', sono disposto a fare uno scambio.", "Grazie, {name}! E torna pure se vuoi fare un altro scambio.", 0x8a697a25, nil, nil, 0x6a289e06, 0x46e9e47e, ".mm.." },
  [18] = { "Una fratellanza di ladri", "Porta 12 Red Burlap Bandana al vicesceriffo Willem, fuori dall'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Da poco una nuova banda di ladri si aggira per la ⟦Northshire=Contea del Nord⟧. Si fanno chiamare ⟦Defias Brotherhood=Fratellanza dei Defias⟧ e li hanno visti oltre il fiume, a est.\n\nNon so cosa stiano tramando, ma di certo niente di buono! Portami le bandane che indossano e ti ricompenserò con un'arma.", "Hai già raccolto quelle bandane per me?", "Sei tornato con qualche bandana, vedo. L'esercito di ⟦Stormwind=Roccavento⟧ ti è grato per l'aiuto.", 0x2f1eb64e, 0x0376329b, 0x0ff5818f, 0x59c5a6d0, 0x9eec7aad, "....." },
  [19] = { nil, "Porta la ⟦Tharil'zun's Head=Testa di Tharil'zun⟧ al maresciallo Marris, a ⟦Redridge=Crestarossa⟧.", "I Blackrock Outrunner e i Blackrock Renegade tendono imboscate tra qui e il ⟦Stonewatch Keep=Mastio di Guardamasso⟧. Il capo degli Outrunner è un orco di nome Tharil'zun: è lui che vogliamo. Portami la testa di Tharil'zun!", "La pressione degli orchi ⟦Blackrock=Roccianera⟧ è ancora forte. Ma almeno ci hai liberati da Tharil'zun?", "Tharil'zun era un orco feroce e astuto. Ben fatto: sono sicuro che non è caduto facilmente. Ecco la tua ricompensa, {name}.", 0x22ab2f51, 0x7c13c137, 0x8b3cf21c, 0x55e47621, 0x3c4e5d23, "e...." },
  [20] = { "La minaccia dei ⟦Blackrock=Roccianera⟧", "Porta 10 Ascia Usurata al maresciallo Marris a ⟦Lakeshire=Borgolago⟧.", "Gli orchi ⟦Blackrock=Roccianera⟧ sono arrivati dalle ⟦Burning Steppes=Steppe Ardenti⟧ e si sono presi il ⟦Stonewatch Keep=Mastio di Guardamasso⟧, a nord. Da lì razziano le terre a nord di ⟦Lakeshire=Borgolago⟧ e costringono i cittadini a restare in paese, chiusi come bestiame.\n\nAiuta ⟦Lakeshire=Borgolago⟧ a liberarsi di questa minaccia. Uccidi gli orchi ⟦Blackrock=Roccianera⟧ e portami dieci delle loro asce usurate come prova.\n\nE anche se i ⟦Blackrock=Roccianera⟧ ci minacciano da nord, abbiamo notizie di altri nell'angolo sudorientale di ⟦Redridge=Crestarossa⟧. Se ne trovi anche lì, dai la caccia pure a loro.", "Hai ucciso degli orchi, {name}? Se è così, fammi vedere...", "Così ci sono molti meno orchi di cui preoccuparsi, grazie.", 0xeb0d5482, 0x427516c3, 0xdcc24f55, 0x9b1e452c, 0x1c8fce29, "....." },
  [21] = { "Schermaglia a Cresta dell'Eco", "Uccidi 12 Kobold Laborer, poi torna dal maresciallo McBride all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Le tue indagini precedenti dimostrano che la ⟦Echo Ridge Mine=Miniera Cresta dell'Eco⟧ va ripulita. Torna alla miniera e aiuta a liberarla dai coboldi.\n\nNon perdere tempo, {name}. Più a lungo i coboldi restano indisturbati nella miniera, più salda diventa la loro presa sulla ⟦Northshire=Contea del Nord⟧.", "So che è un lavoro sanguinoso, {name}, ma è vitale per la sicurezza della ⟦Northshire=Contea del Nord⟧. Sei pront<o/a> a fare rapporto?", "Ancora una volta ti sei guadagnat<o/a> il mio rispetto e la gratitudine dell'esercito di ⟦Stormwind=Roccavento⟧. Potrebbero esserci ancora coboldi nella miniera, ma manderò altri contro di loro. Abbiamo altri compiti per te.", 0xa7a12dbe, 0x26b99d1f, 0xeb16bc2b, 0xf565255c, 0x019e5401, "....." },
  [22] = { "⟦Goretusk Liver Pie=Pasticcio di Fegato di Cinghiospino⟧", "Salma Saldean ha bisogno di 8 Goretusk Liver per preparare un ⟦Goretusk Liver Pie=Pasticcio di Fegato di Cinghiospino⟧.", "Le cipolle sono sbucciate. L'aglio è tritato. Il rosmarino è pestato. La crosta è cotta. L'aneto è sminuzzato. Il sugo sta sobbollendo. Ora per il mio famoso pasticcio di carne mi servono solo 8 Goretusk Liver!", "Per il mio famoso pasticcio di carne mi servono solo 8 Goretusk Liver!", "Sono semplicemente perfetti, {name}! Grazie mille. Stasera il contadino Saldean e io faremo un banchetto. Ed ecco un pensierino per te, per il tuo duro lavoro. Non penserai che lasci patire la fame a un {class} come te, vero?", 0x8e33704e, 0x0a34a00f, 0xa7490995, 0xe421b346, 0x2f880112, "....." },
  [23] = { "La zampa di Ursangous", "Porta Ursangous's Paw a Senani Thunderheart all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "<La zampa del possente orso Ursangous è il tuo trofeo per questa parte della Caccia di ⟦Ashenvale=Valtetra⟧. Sulla zampa c'è un piccolo emblema a forma di quarto di luna crescente; il significato dell'emblema resta un mistero.\n\nLa zampa va portata a Senani Thunderheart, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, per dimostrare che hai sconfitto la possente creatura e completato questa parte della caccia.>", "Ah, {name}, stavo proprio pensando a te! Come va la caccia?", "Ah, la zampa di Ursangous! La tua abilità è notevole, {class}; gli si attribuiscono numerose uccisioni. La mezzaluna sulla sua zampa è senza dubbio il segno che era stato addestrato dagli elfi della notte che si aggirano furtivi per ⟦Ashenvale=Valtetra⟧. Ursangous è... era uno degli orsi più possenti che si potessero trovare da queste parti. Aver sconfitto una simile creatura è una prova della tua volontà e della tua determinazione.\n\nI tuoi antenati sarebbero fieri!", 0xa9132297, 0xe5f93b0e, 0x8d898f17, 0x060f3631, 0xb2ec6d11, "....." },
  [24] = { "⟦Shadumbra's Head=Testa di Shadumbra⟧", "Porta la ⟦Shadumbra's Head=Testa di Shadumbra⟧ a Senani Thunderheart, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "Shadumbra, un tempo così veloce, ora giace immobile: la vittoria è tua. La testa della fiera della notte uccisa è un trofeo degno di questa prova della Caccia di ⟦Ashenvale=Valtetra⟧. Senani Thunderheart, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, vorrà vedere un simile trofeo per riconoscerti il merito di questa parte della Caccia di ⟦Ashenvale=Valtetra⟧.", "Salute di nuovo, {name}! Sei qui per mostrarmi la prova della tua caccia?", "Una vittoria per {name} nella Caccia di ⟦Ashenvale=Valtetra⟧! Ben fatto: la testa di Shadumbra è senza dubbio un trofeo degno di uno scontro così impressionante.\n\nLa ferocia di Shadumbra era nota a tutti qui all'avamposto. Ogni viaggio verso ovest, specie a piedi per raggiungere la ⟦Zoram Strand=Spiaggia di Zoram⟧, era pieno di pericoli per colpa di questa tigre. Grazie a te, il pericolo è passato.", 0x337fe567, 0xc190c862, 0xf9f1000a, 0x11d924fd, 0xd2710e6b, "....." },
  [25] = { "Stallo verso ⟦Stonetalon=Petrartiglio⟧", "Elimina 12 Befouled Water Elemental al ⟦Mystral Lake=Lago Mystral⟧, a est del Talondeep Path e a sud-ovest dell'⟦Splintertree Post=Avamposto di Troncorotto⟧.\n\nPerlustra il gazebo sul ⟦Mystral Lake=Lago Mystral⟧ che domina il vicino avamposto dell'⟦Alliance=Alleanza⟧.\n\nTorna da Mastok Wrilehiss all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "Se vuoi renderti utile, perché non fai qualcosa per la situazione vicino al Talondeep Path?\n\nI trasporti tra ⟦Ashenvale=Valtetra⟧ e ⟦Stonetalon=Petrartiglio⟧ sono fermi perché il lago si è animato e attacca qualunque cosa gli si avvicini... cioè chiunque passi per il sentiero. Ancora più utile che fare piazza pulita degli elementali dell'acqua sarebbe che qualcuno perlustrasse il gazebo sul ⟦Mystral Lake=Lago Mystral⟧, quello da cui si vede bene l'avamposto dell'⟦Alliance=Alleanza⟧.\n\nTe la senti di renderti utile?", "Già di ritorno? Com'è la situazione là fuori? Tutto risolto, grazie a te?", "Già, ho sentito che qualcuno ha messo sottosopra il lago laggiù come un mulinello di polvere nelle ⟦Barrens=Savane⟧. A quanto pare, potremmo anche riuscire a piazzare là fuori un punto d'osservazione per tenere d'occhio i nostri amici dell'⟦Alliance=Alleanza⟧. Sempre che riusciamo a tenerlo segreto...\n\nAlla fine ti sei rivelat<o/a> davvero utile: i trasporti tra qui e ⟦Stonetalon=Petrartiglio⟧ dovrebbero avere vita più facile. Prendi questo, te lo sei guadagnato.", 0xced629b9, 0xaeb13247, 0x827ebbec, 0x1dfb053a, 0x0d2cc7d3, "....." },
  [26] = { "Una lezione da imparare", "Parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "{name}, ho seguito i tuoi progressi con grande gioia. Stai senza dubbio diventando un prezioso protettore della natura.\n\nÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci: uno che ti dona il controllo e la padronanza dell'acqua. Per questo dovrai recarti nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧, e parlare con Dendrite Starblaze del ⟦Cenarion Circle=Circolo Cenariano⟧. Sarà lui a guidarti.", nil, "Salute a te, giovane druido; è giunto il momento che tu conosca la nostra forma acquatica. È una forma che ti permette di muoverti nell'acqua liberamente e senza limiti. Troverai in questo aspetto uno strumento utile e una benedizione... ma prima di padroneggiarlo dovrai guadagnartelo.\n\nDovrai superare due prove. La prima metterà alla prova la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione nel comprendere gli aspetti della forma stessa.\n\nTieniti pront<o/a>, perché il momento della prova è giunto.", 0xab90ac10, 0x127a78ca, 0x21ea754f, nil, 0x058b67b8, "...m." },
  [27] = { "Una lezione da imparare", "Parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "{name}, ho seguito i tuoi progressi con grande gioia. Stai senza dubbio diventando un prezioso protettore della natura.\n\nÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci: uno che ti dona il controllo e la padronanza dell'acqua. Per questo dovrai recarti nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧, e parlare con Dendrite Starblaze del ⟦Cenarion Circle=Circolo Cenariano⟧. Sarà lui a guidarti.", nil, "Salute a te, giovane druido; è giunto il momento che tu conosca la nostra forma acquatica. È una forma che ti permette di muoverti nell'acqua liberamente e senza limiti. Troverai in questo aspetto uno strumento utile e una benedizione... ma prima di padroneggiarlo dovrai guadagnartelo.\n\nDovrai superare due prove. La prima metterà alla prova la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione nel comprendere gli aspetti della forma stessa.\n\nTieniti pront<o/a>, perché il momento della prova è giunto.", 0xab90ac10, 0x127a78ca, 0x21ea754f, nil, 0x058b67b8, "...m." },
  [28] = { "La prova del lago", "Trova una ⟦Shrine Bauble=Bolla del Santuario⟧ nel ⟦Lake Elune'ara=Lago Elune'ara⟧ e portala al ⟦Shrine of Remulos=Santuario di Remulos⟧, nella parte nordoccidentale di ⟦Moonglade=Radaluna⟧. Una volta lì, usa la ⟦Shrine Bauble=Bolla del Santuario⟧.\n\nPoi dovrai parlare con Tajarri al santuario per completare la prova.", "Per la tua prima prova, esplora le profondità del ⟦Lake Elune'ara=Lago Elune'ara⟧ per trovare una ⟦Shrine Bauble=Bolla del Santuario⟧. Si deteriora rapidamente, quindi portala senza indugio al ⟦Shrine of Remulos=Santuario di Remulos⟧. Usa la bolla al santuario, poi parla con Tajarri, che si trova lì: è una delle guardiane più fidate di Radaluna.\n\nHai solo un tempo limitato per portare a termine il compito, e potresti trovarti in gara con altri druidi in cerca di bolle a loro volta. Agilità mentale e fisica saranno fondamentali per la tua riuscita.\n\nBuona fortuna, {name}.", "Per completare la prova del lago, devi usare la ⟦Shrine Bauble=Bolla del Santuario⟧ entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.", "Bene, bene, a quanto pare un altro druido ha superato con successo la prova del lago! Ben fatto, mio giovane amico, ben fatto.\n\nCome ti ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio servire come guardiana di ⟦Moonglade=Radaluna⟧, e in particolare di questo santuario. Il custode Remulos guida il ⟦Cenarion Circle=Circolo Cenariano⟧ nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare qui la bolla è un omaggio all'importanza di questo luogo per il Circolo.", 0xee209044, 0x40c0c195, 0x38927bd5, 0x95bbb916, 0x88cadd95, "....." },
  [29] = { "La prova del lago", "Trova una ⟦Shrine Bauble=Bolla del Santuario⟧ nel ⟦Lake Elune'ara=Lago Elune'ara⟧ e portala al ⟦Shrine of Remulos=Santuario di Remulos⟧, nella parte nordoccidentale di ⟦Moonglade=Radaluna⟧. Una volta lì, usa la ⟦Shrine Bauble=Bolla del Santuario⟧.\n\nPoi dovrai parlare con Tajarri al santuario per completare la prova.", "Per la tua prima prova, esplora le profondità del ⟦Lake Elune'ara=Lago Elune'ara⟧ per trovare una ⟦Shrine Bauble=Bolla del Santuario⟧. Si deteriora rapidamente, quindi portala senza indugio al ⟦Shrine of Remulos=Santuario di Remulos⟧. Usa la bolla al santuario, poi parla con Tajarri, che si trova lì: è una delle guardiane più fidate di Radaluna.\n\nHai solo un tempo limitato per portare a termine il compito, e potresti trovarti in gara con altri druidi in cerca di bolle a loro volta. Agilità mentale e fisica saranno fondamentali per la tua riuscita.\n\nBuona fortuna, {name}.", "Per completare la prova del lago, devi usare la ⟦Shrine Bauble=Bolla del Santuario⟧ entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.", "Bene, bene, a quanto pare un altro druido ha superato con successo la prova del lago! Ben fatto, mio giovane amico, ben fatto.\n\nCome ti ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio servire come guardiana di ⟦Moonglade=Radaluna⟧, e in particolare di questo santuario. Il custode Remulos guida il ⟦Cenarion Circle=Circolo Cenariano⟧ nella salvaguardia della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare qui la bolla è un omaggio all'importanza di questo luogo per il Circolo.", 0xee209044, 0x40c0c195, 0x38927bd5, 0x95bbb916, 0x88cadd95, "....." },
  [30] = { "La prova del leone marino", "Trova il ⟦Half Pendant of Aquatic Agility=Mezzo Pendente dell'Agilità Acquatica⟧ e il ⟦Half Pendant of Aquatic Endurance=Mezzo Pendente della Resistenza Acquatica⟧. Parla con gli abitanti di ⟦Moonglade=Radaluna⟧ per ottenere indizi su dove potrebbero trovarsi.\n\nUnisci le due metà per formare il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧. Per farlo devi trovarti nei pressi del ⟦Shrine of Remulos=Santuario di Remulos⟧.\n\nPorta il pendente completo a Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Per la seconda prova ti serviranno le due metà che compongono il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dalla sua incredibile resistenza. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro forma acquatica.\n\nParla con la gente di ⟦Moonglade=Radaluna⟧ per scoprire dove possano trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.", "Hai formato il pendente da farmi esaminare, {name}? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.", "Hai completato la prova del leone marino, {name}: congratulazioni.\n\nOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua volontà di accogliere l'aspetto del leone marino.\n\nRicorda bene queste lezioni e affidati a esse quando avrai ottenuto la tua forma acquatica.", 0x5cc8ed68, 0xdf177053, 0x23c219a5, 0x3520b13e, 0xb90d61f2, "....." },
  [31] = { "⟦Aquatic Form=Forma Acquatica⟧", "Torna a ⟦Thunder Bluff=Picco del Tuono⟧ e mostra il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧ a Turak Runetotem.", "Hai completato le lezioni che tutti i giovani druidi devono apprendere prima di poter assumere un aspetto acquatico. Ora torna dal tuo istruttore, Turak Runetotem, a ⟦Thunder Bluff=Picco del Tuono⟧. Mostragli il tuo pendente e dimostragli che sei pront<o/a> a imparare ciò che ha da insegnarti. Sarà lui a completare il tuo addestramento, permettendoti di diventare tutt'uno con l'acqua.\n\nAddio, giovane druido. Ci rivedremo.", "Il tuo ritorno a ⟦Thunder Bluff=Picco del Tuono⟧ non passa inosservato, ma mi servirà una prova delle lezioni apprese a ⟦Moonglade=Radaluna⟧ prima di insegnarti la tua forma acquatica.\n\nHai il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧?", "Davvero notevole, {name}. I tuoi antenati sarebbero fieri dei tuoi progressi! Sei pront<o/a> a imparare la tua forma acquatica, ed è un piacere per me insegnartela.\n\nInoltre, in riconoscimento di ciò che hai compiuto nelle due prove, ti dono questo oggetto. Spero che sarà un'aggiunta gradita al tuo equipaggiamento di protettore della natura e custode dell'equilibrio.", 0xb41f2b6a, 0x3327253f, 0x19914008, 0xe6d7ebbe, 0xf05b6e02, "....." },
  [33] = { "Lupi oltre il confine", "Porta 8 pezzi di ⟦Tough Wolf Meat=Carne Tigliosa di Lupo⟧ a Eagan Peltskinner, fuori dall'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "Odio quei maledetti lupi dei boschi! Però le bistecche di lupo mi piacciono proprio... Portami della carne di lupo tigliosa e te la scambierò con qualcosa che ti tornerà utile.\n\nLa carne di lupo tigliosa si ricava cacciando i lupi dei boschi e i giovani lupi che vagano per le campagne della ⟦Northshire=Contea del Nord⟧.", "Ehi, {name}. Mi sta venendo fame... hai preso quella carne di lupo tigliosa?", "Ti sei dato da fare! Non vedo l'ora di cucinare quella carne di lupo...\n\nHo qui alcune cose che potrebbero interessarti: scegli pure!", 0xf2272f07, 0xdf199ead, 0x5ce8cfac, 0xf5cb8e2e, 0x63c80a97, "....." },
  [34] = { "Un ospite sgradito", "Martie Jainrose di ⟦Lakeshire=Borgolago⟧ vuole che tu uccida Bellygrub. Portale la sua zanna come prova.", "Ancora una volta il mio giardino è stato calpestato e saccheggiato. E so bene chi è il bruto che lo fa. È quel maledetto cinghiale, quello che il maresciallo Marris ha preso a chiamare Bellygrub.\n\nOra non potrò ripiantare i narcisi fino alla prossima stagione. Rovinati! Tutti rovinati da quel cinghiale minaccioso. Metti fine a quella peste! Mostrami la sua zanna e sarò felice di ricompensarti. Sembra passare il tempo a cercare cibo nel campo a sud-ovest di ⟦Lakeshire=Borgolago⟧, ma ogni tanto si spinge fin qui, nel mio giardino.", "Bellygrub è ancora all'opera o sei riuscit<o/a> a liberare ⟦Lakeshire=Borgolago⟧ da quella peste una volta per tutte?", "Finalmente quella minaccia è stata eliminata! Grazie, {name}, mi hai reso un grande servizio. Questa stagione il giardino sarà in piena fioritura!", 0x5c809bb5, 0xabb3c5cc, 0xd5dec96a, 0x26e466ea, 0x3fd295c2, "....." },
  [35] = { "Altre preoccupazioni", "Il maresciallo Dughan vuole che tu parli con la guardia Thomas.", "Se temi che le voci sui murloc siano vere, allora fai così: va' al ponte orientale di Elwynn e parla con la guardia Thomas. È di stanza al ponte da una settimana e saprà com'è la situazione nella zona.\n\nPortami il suo rapporto.", nil, "Sì, i murloc si sono insediati dentro e attorno ai torrenti dell'est di Elwynn. Non sappiamo perché siano qui, ma sono aggressivi e almeno in parte intelligenti.", 0xbf37aefc, 0xd1c199f2, 0x0d41f7ae, nil, 0xfbe5b854, "...m." },
  [36] = { "⟦Westfall Stew=Stufato delle Marche Occidentali⟧", "Verna Furlbrow vuole che tu consegni a Salma Saldean la sua ricetta dello ⟦Westfall Stew=Stufato delle Marche Occidentali⟧.", "Non avrei mai pensato che sarebbe arrivato il giorno in cui avrei lasciato la fattoria. Ma i campi sono invasi dai ladri e ormai qui è troppo pericoloso per noi. Appena il contadino Furlbrow avrà sistemato il carro, ce ne andremo.\n\nForse potresti farmi un favore? Lascia che ti scarabocchi la mia ricetta dello stufato delle ⟦Westfall=Marche Occidentali⟧. Ti prego, portala a Salma Saldean, nella fattoria laggiù. La fattoria dei Saldean è appena oltre il bivio.", "Quanto mi mancherà quella Verna Furlbrow. Non è che per caso l'hai vista venendo qui?", "Quella Verna è sempre stata una ragazza così dolce. Qui nelle ⟦Westfall=Marche Occidentali⟧ ci mancherà, ma detto tra noi, in fondo è una ragazza di città e ⟦Stormwind=Roccavento⟧ le andrà benissimo. Ma basta pettegolezzi! Ora possiamo preparare lo ⟦Westfall Stew=Stufato delle Marche Occidentali⟧!", 0xb05bfdaf, 0xd3f82a15, 0xce62c0a2, 0xdfbf0990, 0xd01407d2, "....." },
  [37] = { "Ritrova le guardie scomparse", "La guardia Thomas vuole che tu risalga il fiume verso nord e cerchi le due guardie scomparse, Rolf e Malakai.", "Qualche giorno fa abbiamo mandato due guardie, Rolf e Malakai, a ispezionare il fiume, e non sono ancora tornate. Per completare il mio rapporto devo sapere che fine hanno fatto quegli uomini.\n\nRisali il fiume verso nord e trova le guardie... o quel che ne resta.", nil, "Anche se il cadavere è stato in gran parte spogliato, lì vicino giace un medaglione con incise le parole: «Fante Malakai Stone».", 0xbd0b84c3, 0xc79cfdb3, 0x96ec21d0, nil, 0xf410e026, "...m." },
  [38] = { "⟦Westfall Stew=Stufato delle Marche Occidentali⟧", "Salma Saldean vuole 3 ⟦Stringy Vulture Meat=Carne d'Avvoltoio Fibrosa⟧, 3 Muso di Cinghiospino, 3 Occhio di Murloc, 3 Okra.", "Aiutami a preparare lo ⟦Westfall Stew=Stufato delle Marche Occidentali⟧! Torna con questi ingredienti:\n\n3 ⟦Stringy Vulture Meat=Carne d'Avvoltoio Fibrosa⟧\n\n3 Muso di Cinghiospino\n\n3 Occhio di Murloc\n\n3 Okra", "Torna con questi ingredienti:\n\n3 ⟦Stringy Vulture Meat=Carne d'Avvoltoio Fibrosa⟧\n\n3 Muso di Cinghiospino\n\n3 Occhio di Murloc\n\n3 Okra", "Quest'okra renderà questo brodo bello denso! Ora aggiungiamo solo la ⟦Stringy Vulture Meat=Carne d'Avvoltoio Fibrosa⟧, qualche occhio di murloc e quei deliziosi musi di cinghiospino. Ed è fatta! Per tutto il tuo aiuto, {name}, voglio che tu prenda la prima infornata di oggi di ⟦Westfall Stew=Stufato delle Marche Occidentali⟧!", 0xb05bfdaf, 0x1fd3a0f2, 0xe339c1dc, 0xbc377ac8, 0xe18bc596, "....." },
  [39] = { "Il rapporto di Thomas", "Fai rapporto al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.", "Informa il maresciallo Dughan della morte di Malakai e Rolf, e riferiscigli che con le truppe che abbiamo ora non possiamo contenere i murloc nell'est di Elwynn.\n\nSo che non abbiamo molti uomini da impiegare, ma spero che Dughan riesca a trovare qualcuno.", nil, "Mm, notizie preoccupanti. Le nostre difese sono già allo stremo, e aver perso Rolf e Malakai per colpa di quei murloc ci mette in una posizione ancora peggiore.\n\nSe le cose non migliorano, entro la fine della settimana si combatterà a ⟦Goldshire=Borgodoro⟧!", 0x25228270, 0x3f1aa863, 0x2d7986ad, nil, 0xae2657cb, "...m." },
  [40] = { "Un pericolo che sa di pesce", "Remy «Two Times» vuole che tu parli con il maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.", "{name}, c'è una nuova minaccia nella ⟦Elwynn Forest=Foresta di Elwynn⟧! I murloc risalgono i torrenti dell'est di Elwynn, fanno scappare i pesci e aggrediscono la brava gente!\n\nHo avvisato il maresciallo Dughan, ma lui è più preoccupato per gli gnoll e i banditi. Non è convinto che i murloc siano un pericolo.\n\nTi prego, {name}, parla con Dughan e convincilo a mandare più truppe a est!", nil, "Sì, ho parlato con Remy. Lo rispetto come mercante, ma tutte le segnalazioni di murloc a est sono state, nel migliore dei casi, vaghe.\n\nPrendo nota delle tue preoccupazioni, ma se non ricevo un rapporto militare su una minaccia dei murloc, non possiamo permetterci di mandare altre truppe a est.", 0x02cfe285, 0x67e1f5a8, 0xb8d781bd, nil, 0xf6272f28, "...m." },
  [45] = { "La sorte di Rolf", "Cerca Rolf, o tracce della sua morte, nel villaggio dei murloc.", "Cercando meglio nella zona, trovi delle impronte palmate che vanno verso est lungo la riva del ⟦Stone Cairn Lake=Lago del Memoriale⟧. In lontananza, a est, riesci a malapena a scorgere un villaggio di murloc.\n\nForse è lì che Rolf ha trovato la sua fine...", nil, "Attorno al collo del cadavere trovi un medaglione di metallo con incise le parole «Fante Rolf Hartford».", 0x119e499d, 0x93412d0c, 0xbf0a2396, nil, 0x0692a2fa, "...m." },
  [46] = { "Taglia sui murloc", "Porta 8 Torn Murloc Fin alla guardia Thomas, al ponte orientale di Elwynn.", "L'esercito di ⟦Stormwind=Roccavento⟧ ha messo una taglia sui murloc predoni e raccoglitori di Elwynn. Massacrali e portami le loro pinne di murloc strappate, e l'esercito di ⟦Stormwind=Roccavento⟧ ti ricompenserà a dovere.\n\nI murloc hanno costruito un villaggio al ⟦Stone Cairn Lake=Lago del Memoriale⟧, a nord di qui, e un altro a sud, dove il torrente si biforca.", "Come va la caccia, {name}?", "Hai le pinne? Ottimo! Il maresciallo Dughan è in ansia per la situazione dei murloc nell'est di Elwynn, e vorrei dirgli che la stiamo tenendo sotto controllo.\n\nÈ anche grazie a te se ci stiamo riuscendo.", 0xd7ee6932, 0x320c64a3, 0x05a40606, 0xd84cca78, 0xff08c2c6, "....." },
  [47] = { "Scambio di ⟦Gold Dust=Polvere d'Oro⟧", "Porta 10 ⟦Gold Dust=Polvere d'Oro⟧ a Remy \"Two Times\" a ⟦Goldshire=Borgodoro⟧. La ⟦Gold Dust=Polvere d'Oro⟧ si ottiene dai coboldi nella ⟦Elwynn Forest=Foresta di Elwynn⟧.", "I coboldi da queste parti a volte hanno addosso della ⟦Gold Dust=Polvere d'Oro⟧. Mi farebbe proprio comodo: portamene un bel carico e ti farò il miglior prezzo in città... il miglior prezzo in città!\n\nTrovi i coboldi nella ⟦Fargodeep Mine=Miniera Antrocupo⟧, a sud, e intorno alla ⟦Jasperlode Mine=Miniera Venarossa⟧, a nord-est.", "Psst! Hai quella ⟦Gold Dust=Polvere d'Oro⟧ per me... per me?", "Grazie per la polvere, {name}. Ecco i tuoi soldi, e... ecco un pegno da parte di alcuni miei soci. Potrebbe tornarti utile... utile.", 0x6fc1c811, 0x54bcff94, 0xcbdc7c22, 0xfc397987, 0x26e50fd4, "....." },
  [52] = { "Proteggere la frontiera", "Uccidi 8 Prowler e 5 Young Forest Bear, poi torna dalla guardia Thomas al ponte orientale di Elwynn.", "Salve, {name}. Più ci si allontana da ⟦Goldshire=Borgodoro⟧, più gli animali selvatici diventano aggressivi, e il ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧ subisce attacchi quasi continui di lupi e orsi!\n\nQui il tuo aiuto ci farebbe comodo.", "Hai ucciso quei lupi e quegli orsi?", "Grazie mille per l'aiuto, {name}. Dev'esserci qualcosa nella foresta che rende questi animali così audaci.\n\nQualunque cosa sia, spero che resti lì.", 0x2e116184, 0x03f5e0ac, 0x866a4bcd, 0xfcb3bc90, 0xe7a250d3, "....." },
  [54] = { "Rapporto a ⟦Goldshire=Borgodoro⟧", "Porta i ⟦Marshal McBride's Documents=Documenti del Maresciallo McBride⟧ al maresciallo Dughan a ⟦Goldshire=Borgodoro⟧.", "{name}, sei un {class} che ha dimostrato di avere a cuore la sicurezza della ⟦Northshire=Contea del Nord⟧. D'ora in poi ti è affidata la protezione della ⟦Elwynn Forest=Foresta di Elwynn⟧ che la circonda.\n\nSe accetti questo incarico, ho preparato dei documenti da consegnare al maresciallo Dughan a ⟦Goldshire=Borgodoro⟧. ⟦Goldshire=Borgodoro⟧ si trova lungo la strada a sud, oltre i cancelli di confine.", "Hai notizie da McBride? La ⟦Northshire=Contea del Nord⟧ è un giardino in confronto alla ⟦Elwynn Forest=Foresta di Elwynn⟧, ma chissà cosa avrà da riferire il maresciallo McBride.\n\nForza, dammi i suoi documenti...", "Bene, qui dice che ti è stato conferito il grado di vicesceriffo facente funzione presso i Marescialli di ⟦Stormwind=Roccavento⟧. Congratulazioni.\n\nE buona fortuna: tenere al sicuro Elwynn non è una passeggiata... con quasi tutto l'esercito impegnato a fare chissà cosa per chissà quale nobile!\n\nÈ difficile stare dietro alla politica in questi tempi bui...", 0xccb7dcaf, 0xc0ef425f, 0xd8bc24db, 0xf6530924, 0xb56df9b4, "....." },
  [56] = { "I Guardiani della Notte", "La comandante Althea Ebonlocke di ⟦Darkshire=Borgoscuro⟧ vuole che tu uccida 8 Skeletal Warrior e 6 Skeletal Mage.", "In qualità di comandante dei Guardiani della Notte, ho giurato di proteggere i cittadini di ⟦Darkshire=Borgoscuro⟧. ⟦Stormwind=Roccavento⟧ ha ritirato dai loro posti le guardie che aveva assegnato qui, lasciandoci a cavarcela da soli.\n\nSe ti senti all'altezza del compito, abbiamo bisogno del tuo aiuto! Aiuta i Guardiani della Notte: avventurati nel Cimitero Parcosereno, appena a sud di ⟦Darkshire=Borgoscuro⟧, e uccidi 8 Skeletal Warrior e 6 Skeletal Mage. La minaccia dei non morti va sventata!", "Vedo che sei tornat<o/a>, {name}. Se vuoi dimostrare di poter servire i Guardiani della Notte, torna da me quando avrai ucciso 8 Skeletal Warrior e 6 Skeletal Mage.", "Splendido, {name}. Per il tuo servizio alla gente di ⟦Darkshire=Borgoscuro⟧ sarai ricompensat<o/a>.", 0x50990c24, 0x988ea067, 0xb762390c, 0x426a38c5, 0x00bdfe75, "....." },
  [57] = { "I Guardiani della Notte", "La comandante Althea Ebonlocke di ⟦Darkshire=Borgoscuro⟧ vuole che tu uccida 15 Skeletal Fiend e 15 Skeletal Horror.", "{name}, mi arrivano notizie di un'infestazione di non morti nella foresta! Se te la senti, va' al cimitero di ⟦Raven Hill=Collecorvo⟧ e uccidi 15 di quei vili Skeletal Fiend e 15 Skeletal Horror. Si segnalano scheletri anche appena a sud di ⟦Darkshire=Borgoscuro⟧, dentro e attorno al ⟦Tranquil Gardens Cemetery=Cimitero Parcosereno⟧. I non morti vanno cacciati da ⟦Duskwood=Boscovespro⟧!", "Torna da me quando avrai ucciso 15 Skeletal Fiend e 15 Skeletal Horror, {name}.", "La gente di ⟦Darkshire=Borgoscuro⟧ ti ringrazia, {name}. Hai dimostrato di essere <un/una> grande <alleato/alleata> dei Guardiani della Notte.", 0x50990c24, 0xb2d050a2, 0xc3805ea3, 0x159417dc, 0xfa65ff23, "....." },
  [58] = { "I Guardiani della Notte", "La comandante Althea Ebonlocke di ⟦Darkshire=Borgoscuro⟧ vuole che tu uccida 20 Plague Spreader nel mausoleo orientale di ⟦Raven Hill=Collecorvo⟧.", "La situazione a ⟦Raven Hill=Collecorvo⟧ è ancora cupa. La sicurezza di ⟦Darkshire=Borgoscuro⟧ è nelle tue mani, {name}. Non ho abbastanza guardiani per proteggere il villaggio. Devi tornare ancora una volta a ⟦Raven Hill=Collecorvo⟧ e liberare il mausoleo orientale da 20 Plague Spreader!", "Ho bisogno del tuo aiuto, {name}. Va' al cimitero a nord-ovest e libera il mausoleo orientale da 20 Plague Spreader.\n\nTorna da me quando avrai finito.", "A nome della gente di ⟦Darkshire=Borgoscuro⟧ e come comandante dei Guardiani della Notte, ti ringrazio, {name}, per il tuo coraggio e la tua dedizione. Che la Luce illumini il tuo cammino.", 0x50990c24, 0x1fb37e1e, 0xf156af7a, 0x20d0eab3, 0xe664400d, "....." },
  [59] = { "Armature di stoffa e di cuoio", "Consegna a Sara Timberlain il ⟦Stormwind Armor Marker=Buono per un'Armatura di Roccavento⟧.", "Per la tua astuzia e il tuo valore, ho qui un buono che vale un pezzo di armatura. Voglio che tu lo porti a Sara Timberlain, al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧. Dalle il buono e lei ti forgerà l'armatura. E quando l'avrai ricevuta, {name}, usala per difendere Elwynn.\n\nIl ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧ si trova a est, oltre il posto di guardia di Thomas.", "L'esercito di ⟦Stormwind=Roccavento⟧ mi ha incaricata di fornire alla sua gente armature di stoffa e di cuoio.\n\nSe hai un buono per me, sarò felice di prepararti qualcosa.", "Ah, grazie per il buono. Scegli pure l'armatura che preferisci.\n\nBuona fortuna, <valoroso/valorosa> {class}. E che questa armatura ti serva bene.", 0x751bcd47, 0x88cbb6e2, 0xec149fa7, 0xa0219e98, 0xff5c34aa, "....." },
  [60] = { "Candele dei coboldi", "Porta 8 Large Candle a William Pestle a ⟦Goldshire=Borgodoro⟧.", "Salve, <signore/signora>! Hai un momento?\n\nIo e mio fratello gestiamo una bottega di speziale a ⟦Stormwind=Roccavento⟧, e sono qui per raccogliere grosse candele per la loro cera. Puoi aiutarmi?\n\nLe grosse candele si ottengono dai coboldi, e girano voci che i coboldi stiano infestando le miniere di Elwynn... la Miniera Antrocupo a sud e la ⟦Jasperlode Mine=Miniera Venarossa⟧ a est. Ti consiglio di cercare le candele in uno di quei posti.", "Hai già raccolto quelle candele?", "Eri <impegnato/impegnata> a dare la caccia ai coboldi, eh? Grazie per le candele, {name}, ed ecco la tua ricompensa...", 0x514933bf, 0xd8ce4567, 0x6cce32c4, 0x77e7ca88, 0x98618684, ".....", nil, nil, 0x1993cf97, nil, nil },
  [61] = { "Un carico per ⟦Stormwind=Roccavento⟧", "Porta il ⟦William's Shipment=Carico di William⟧ a Morgan Pestle nel ⟦Trade District=Quartiere del Commercio⟧ di ⟦Stormwind=Roccavento⟧.", "Mio fratello Morgan aspetta a ⟦Stormwind=Roccavento⟧ il mio carico di candele. Non ho abbastanza tempo per fare il viaggio di persona, ma se ti va di portargli il carico, ti pagherà bene.\n\nHo già impacchettato le candele: trovi Morgan nel nostro negozio, Pestle's Apothecary, nel ⟦Trade District=Quartiere del Commercio⟧ di ⟦Stormwind=Roccavento⟧.", "Oh, un carico da parte di mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", "Ecco il tuo compenso... e già che sei qui, da' un'occhiata in giro! Sono sicuro che abbiamo una pozione o qualche altro ninnolo che potrebbe esserti utile.", 0x6a825135, 0xdeec4138, 0xd71ae934, 0x89b01d8f, 0xdf7db746, "....." },
  [62] = { "La ⟦Fargodeep Mine=Miniera Antrocupo⟧", "Esplora la ⟦Fargodeep Mine=Miniera Antrocupo⟧, poi torna dal maresciallo Dughan a ⟦Goldshire=Borgodoro⟧.", "La miniera della ⟦Northshire=Contea del Nord⟧ non è l'unica ad avere problemi! Mi giungono rapporti secondo cui anche la ⟦Fargodeep Mine=Miniera Antrocupo⟧, a Elwynn, è diventata un covo di coboldi.\n\nEsplora la miniera e verifica questi rapporti, poi torna da me. La miniera si trova quasi esattamente a sud di ⟦Goldshire=Borgodoro⟧, tra le fattorie degli Stonefield e dei Maclure.", "Cos'hai da riferire, {name}? Sei <stato/stata> alla ⟦Fargodeep Mine=Miniera Antrocupo⟧?", "Brutte notizie. Che altro ci aspetta, i draghi?!? Dovremo intensificare le pattuglie vicino a quella miniera. Grazie per il tuo impegno, {name}. E aspetta un momento... potrei avere un altro compito per te.", 0x3a373e5c, 0x068c7c5b, 0x196f6d77, 0x620f4981, 0x902000cc, "....." },
  [63] = { "Il richiamo dell'acqua", "Sconfiggi la Corrupt Manifestation of Water e metti i Corrupted Manifestation's Bracers e le ⟦Remaining Drops of Purest Water=Ultime Gocce di Acqua Purissima⟧ sul Brazier of Everfount, nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Lungo la costa di ⟦Silverpine=Pinargento⟧, a ovest della ⟦Sepulcher=Mausolea⟧, troverai un santuario contaminato dalla piaga. Gli spiriti di quel luogo non parlano più al nostro popolo e toccherà a te sconfiggere la manifestazione e purificare la pozza.\n\nPrendi i bracciali dell'elementale e, insieme alle ultime gocce della pozione di Brine, mettili sul braciere. Il rituale dovrebbe bastare a evocare uno spirito puro con cui comunicare.\n\nPortami la prova che il compito è svolto e ti ricompenserò con il tuo totem.", "Il braciere riflette ancora la luce dei dintorni, e la fiamma ondeggia appena mentre ti avvicini.\n\nLa corruzione sulle colline sembra essersi tenuta a distanza e, a parte i componenti mancanti, il braciere sembra pronto per il rituale che evocherà una manifestazione purificata dell'acqua.", "Metti i bracciali sopra il braciere e versi nella fiamma le ultime gocce della pozione di Brine. Le gocce crepitano a contatto con la fiamma e cominci a recitare le semplici parole che ti ha insegnato Islen...", 0x1f0e11aa, 0xaa58c2a7, 0xf6931e98, 0x94ae3991, 0x8260098f, "....." },
  [64] = { "Il cimelio dimenticato", "Il contadino Furlbrow vuole che tu recuperi il suo orologio da taschino dall'armadio della sua fattoria, nel campo di zucche a ovest.", "È stato terribile! Verna mi ha svegliato quando ha sentito un gran baccano nei campi. I campi erano pieni di teppisti. Siamo scappati di corsa e ho dimenticato di prendere il mio orologio da taschino. Il padre di Verna me l'ha regalato il giorno delle nostre nozze e mi sento male al pensiero che ce l'abbiano quei ladri. L'ho lasciato nell'armadio della fattoria. Cerca il campo di zucche a ovest: non puoi sbagliare. Se me lo riporti, te ne sarò davvero grato!", "Non è che sei riuscit<o/a> a prendere il mio orologio?", "Il mio orologio! Grazie mille, gentile <signore/signora>!\n\nSiamo solo poveri contadini e abbiamo perso la nostra terra, ma ti prego, accetta questa ricompensa in segno della nostra gratitudine.", 0xf0e121ad, 0xdbaefd0c, 0xf295ad64, 0xc78af9a9, 0x1ca851f8, ".....", nil, nil, nil, nil, 0xd9a3b24b },
  [65] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Gryan Stoutmantle vuole che tu parli con Wiley a ⟦Lakeshire=Borgolago⟧.", "La banda di miserabili che ha cacciato la brava gente delle ⟦Westfall=Marche Occidentali⟧ dalle sue terre si fa chiamare ⟦Defias Brotherhood=Fratellanza dei Defias⟧. Ho bisogno che tu ti infiltri in questo branco di delinquenti. Dobbiamo sapere chi è a capo dell'organizzazione e dove si nascondono. A ⟦Lakeshire=Borgolago⟧, nella locanda, c'è un ladro di nome Wiley che mi deve un favore.\n\nVa' a ⟦Lakeshire=Borgolago⟧, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧, a est di Elwynn, e scopri quello che puoi.", nil, "Allora ti manda Stoutmantle? Be', gli devo un favore.", 0x2a2224c0, 0x5c71d76f, 0x567bbd13, nil, 0xd8800e68, "...m." },
  [66] = { "La leggenda di Stalvan", "Cerca l'impiegato Daltry nel municipio di ⟦Darkshire=Borgoscuro⟧.", "La scorsa notte un terribile turbamento mi ha attraversato le vene. Ho percepito che mia nipote, Alyssa, era in grave pericolo. Ho consultato le carte e la Morte mi ha fissato dal tavolo.\n\nDopo un lungo viaggio in un'oscura trance sono riuscita a scoprire un indizio di questo terrificante mistero. Mi è giunto un nome, il nome di Stalvan.\n\nCerca l'impiegato nel municipio e vedi se riesci a scoprire di più su questo personaggio. Temo per tutti noi.", nil, "Ah, dunque ti manda Madame Eva...", 0xeb6571fb, 0xef91d1ff, 0x44b56c82, nil, 0x4de8a455, "...m." },
  [67] = { "La leggenda di Stalvan", "Va' alla scuola di ⟦Moonbrook=Rivoluna⟧ e riporta all'impiegato Daltry ogni nuova informazione su Stalvan.", "Stalvan, eh? Fammi controllare il registro cittadino.\n\nStalvan... Stalvan... vediamo. Ah, eccolo! Ho una registrazione di un certo signor Stalvan Mistmantle. L'ultimo indirizzo registrato è la scuola di ⟦Moonbrook=Rivoluna⟧. Accidenti, altro che dati vecchi!\n\nMi faresti un favore, amico? Se ti capita di andare a ⟦Moonbrook=Rivoluna⟧, fammi sapere se hai notizie di questo tizio. Mi piace tenere i registri in ordine.", nil, "Il vecchio baule si apre cigolando...", 0xeb6571fb, 0x660c738d, 0x277b14bd, nil, 0x45ee8251, "...m." },
  [68] = { "La leggenda di Stalvan", "Porta la Lettera Polverosa Mai Spedita all'impiegato Daltry.", "Nel vecchio baule trovi una Dusty Unsent Letter.", "Ah, mi ricordo di te. Sei quell<o/a> che chiedeva di quel tale Stalvan. Hai poi trovato quello che cercavi?", "Interessante. Quindi quel tale ha passato davvero un po' di tempo a ⟦Moonbrook=Rivoluna⟧. È piuttosto strano che la lettera non sia mai stata consegnata. Comunque sia, aggiornerò il registro.", 0xeb6571fb, 0x4e15fabb, 0x5b2de8d4, 0x78055707, 0x9c5b8cbb, "....." },
  [69] = { "La leggenda di Stalvan", "Va' alla Lion's Pride Inn per scoprire se qualcuno ha mai sentito il nome Stalvan.", "Oh, accidenti! Devo essermelo perso la prima volta. Nel registro, proprio sotto il primo indirizzo di Stalvan, ce n'è un altro, cancellato solo in parte. Sembra che fosse diretto alla Lion's Pride Inn, a ⟦Goldshire=Borgodoro⟧. Forse vale la pena controllare lì, {name}.", nil, "Stalvan? Mi dice proprio qualcosa.", 0xeb6571fb, 0x4acc049c, 0xa5734139, nil, 0xe0613a9e, "...m." },
  [70] = { "La leggenda di Stalvan", "Recupera la Stalvan's Undelivered Letter dal forziere e consegnala al Canal District di ⟦Stormwind=Roccavento⟧.", "Il nome Stalvan mi dice qualcosa. Ora ricordo.\n\nMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di riparo per la notte. Verso mezzanotte, l'uomo si precipitò giù dalle scale urlando, il volto pallido di paura. Ancora in camicia da notte, sparì sotto l'acquazzone.\n\nNella fretta dimenticò le sue lettere nel forziere al piano di sopra. Non tornò mai a riprenderle. Ne resta una di quel tale Stalvan, destinata al Canal District di ⟦Stormwind=Roccavento⟧. Prendila pure.", "Cos'hai lì? Fammi dare un'occhiata...", "Hai un bel coraggio a portare questa roba qui.", 0xeb6571fb, 0xec87b2a9, 0xcf8206e0, 0xad2d2675, 0xf3e822c5, "....." },
  [71] = { "Rapporto a Thomas", "Consegna i ⟦Rolf and Malakai's Medallions=Medaglioni di Rolf e Malakai⟧ alla guardia Thomas, al ponte orientale di Elwynn.", "Ora che hai entrambi i medaglioni, portali alla guardia Thomas al ponte, perché sappia che fine hanno fatto le sue guardie assassinate.", "Ciao, {name}. Hai scoperto che fine hanno fatto Rolf e Malakai?", "Hai confermato i miei timori, {name}. I murloc sono una minaccia che non possiamo ignorare.", 0xcad5f606, 0xdfec0126, 0xfecbb9ef, 0x8c9b780e, 0xab891fb8, "....." },
  [72] = { "La leggenda di Stalvan", "Fruga tra gli averi imballati in cerca di un indizio.", "Mio padre era il custode della tenuta molto prima di me. Toccò a lui lavare via il sangue dopo il massacro. Ma questo non c'entra.\n\nGli ultimi fondi del patrimonio dei Flintridge si sono esauriti. Ora gli ultimi beni della famiglia finiranno all'asta. Prenditela con quegli avvoltoi delle tasse. Se muori proprio dalla voglia di saperne di più, puoi frugare tra queste cianfrusaglie. Chissà cosa potresti trovare.", nil, "Fai scivolare lentamente il coperchio della cassa...", 0xeb6571fb, 0x119baf0f, 0xf129a3f9, nil, 0xe56b8406, "...m." },
  [74] = { "La leggenda di Stalvan", "La Pagina di Diario Stracciato che hai scoperto ti fornisce il prossimo indizio.", "Dentro la cassa trovi vari oggetti: cimeli ammuffiti, un ritratto di famiglia, qualche trofeo di caccia e alcuni vecchi libri. Vicino al fondo, sotto un vaso di ceramica, scopri una ⟦A Torn Journal Page=Pagina di Diario Stracciato⟧.", "Cos'hai lì? Non ci vedo. La mia vista è pessima. Mettimelo in mano.", "Riesco a malapena a distinguere quelle lettere. Ma quella calligrafia mi ricorda qualcosa che ho visto una volta, prima che la mia vista peggiorasse tanto.", 0xeb6571fb, 0x0bc0d882, 0xe3b43f83, 0x20b24ea6, 0x3a5de944, "....." },
  [75] = { "La leggenda di Stalvan", "Il maresciallo Haggard vuole che tu cerchi la ⟦Journal Page=Pagina di Diario⟧ Sbiadita nel forziere al piano di sopra.", "Quando mi sono trasferito qui, nel forziere al piano di sopra c'era un fascio di pergamene. Le ho guardate una volta appena arrivato, ma ho lasciato perdere quando la nebbia mi ha velato gli occhi.\n\nFai un favore a un vecchio quasi cieco e controlla il forziere di sopra: cerca qualcosa che possa aiutarti nella tua ricerca su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.", "Hai trovato la pagina di cui ti ho parlato, {name}?", "L'hai trovata!", 0xeb6571fb, 0x74cb8926, 0x33923181, 0x856913a4, 0x3715d975, "....." },
  [76] = { "La ⟦Jasperlode Mine=Miniera Venarossa⟧", "Esplora la ⟦Jasperlode Mine=Miniera Venarossa⟧, poi torna a fare rapporto al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.", "Grazie a te sappiamo che la ⟦Fargodeep Mine=Miniera Antrocupo⟧ è infestata dai coboldi. Ora ci serve un esploratore che vada a ispezionare la ⟦Jasperlode Mine=Miniera Venarossa⟧, più lontana.\n\nEsplora la ⟦Jasperlode Mine=Miniera Venarossa⟧ e verifica se ci sono coboldi. Per raggiungerla, segui la strada verso est fino alla ⟦Tower of Azora=Torre di Azora⟧. Dalla torre, dirigiti a nord e troverai la miniera ai piedi delle colline.", "Salve, {name}. Che cosa hai da riferire? Hai perlustrato la ⟦Jasperlode Mine=Miniera Venarossa⟧?", "Coboldi nella ⟦Jasperlode Mine=Miniera Venarossa⟧, dici? Maledizione! La situazione peggiora di minuto in minuto!\n\nGrazie per il rapporto, {name}. Ma vorrei che mi avessi portato buone notizie.", 0x0323d68b, 0xb489dc45, 0xd63cfe6e, 0x3d82a623, 0xf3bd38e1, "....." },
  [78] = { "La leggenda di Stalvan", "Porta la ⟦Journal Page=Pagina di Diario⟧ Sbiadita all'oste Smitts.", "Conosco qualcuno che potrebbe aiutarti. Ai tempi in cui guidavo la Guardia di ⟦Stormwind=Roccavento⟧, andavamo a bere alla taverna Scarlet Raven, a ⟦Darkshire=Borgoscuro⟧. L'oste, Smitts, era un vero esperto delle leggende locali. Mostragli questa pagina e senti cosa ne pensa.", "Ti manda il maresciallo Haggard? Perché non l'hai detto subito?\n\nAh, il buon vecchio Haggard. Povero diavolo, tra non molto sarà completamente cieco. Comunque, fammi vedere cos'hai lì.", "Per la Luce! Altroché se la riconosco, quella calligrafia.", 0xeb6571fb, 0x9665adb8, 0xd11badb8, 0x01f28add, 0x017fe17b, "....." },
  [79] = { "La leggenda di Stalvan", "Porta la pagina infangata alla comandante Ebonlocke.", "Ho seguito per anni la leggenda di quel tale Stalvan. Quando, qualche anno fa, quei nobili in visita furono massacrati, andai con Haggard a indagare. Trovai queste pagine infangate, ma non riuscimmo mai a collegare la calligrafia a quel pazzo nei boschi. La tua scia di prove dimostra la sua colpevolezza. Porta subito questo alla comandante Ebonlocke e mettila al corrente di ciò che hai scoperto!", "Spero sia qualcosa di serio, {class}. Fammi vedere cos'hai e raccontami la tua storia. Ma, per la Luce, sbrigati. La difesa di Borgoscuro è la mia priorità assoluta. Non ho tempo da sprecare dietro a piste senza uscita.", "Però, hai dimostrato di essere un vero segugio, {class}.", 0xeb6571fb, 0xa2f0228c, 0x74cec9b0, 0xac774803, 0x7a5abbbe, "....." },
  [80] = { "La leggenda di Stalvan", "Mostra all'impiegato Daltry la Pagina di Diario Macchiata di Sangue.", "Tengo d'occhio quel verme di Stalvan da parecchio tempo. Ma se questa pagina è stata scritta dalla stessa mano, prova la sua colpevolezza al di là di ogni ombra di dubbio.\n\nIn tutti i suoi anni passati a tenere il registro cittadino, l'impiegato Daltry è diventato un esperto nel riconoscere le calligrafie. Mostragli questa pagina e vedi se la scrittura corrisponde a quella della firma nel registro.", "Di nuovo qui, {name}? Cos'hai stavolta?", "Ma certo! La scrittura su questa pagina corrisponde davvero a quella delle firme del registro.", 0xeb6571fb, 0xde53f421, 0x3946b54a, 0x851ef05a, 0xedad08fb, "....." },
  [83] = { "Articoli di lino rosso", "Porta 6 Red Linen Bandana a Sara Timberlain al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧.", "La banda dei Defias nella ⟦Northshire=Contea del Nord⟧ porta maschere di tela di sacco, ma i Defias di Elwynn indossano lino, che posso usare per confezionare ottimi articoli di lino.\n\nPortami le bandane di lino rosso e ci ricaverò qualcosa per te.\n\nI membri della banda dei Defias hanno accampamenti sparsi per tutta Elwynn.", "Sto finendo il lino, {name}. Ne hai per me?", "Ah, sono belle bandane, anche se un po' ruvide...\n\nEcco qua!", 0xab13ee46, 0x6ab947a0, 0x2f31ce58, 0x13c355f0, 0xb808f80e, "....." },
  [84] = { "Ritorno da Billy", "Porta il ⟦Pork Belly Pie=Pasticcio di Carne di Cinghiale⟧ a Billy Maclure, ai Maclure Vineyards.", "Ecco qua. E quando dai questo pasticcio a quel Billy, digli che spero ci si strozzi!", "Uff... sto morendo di fame! Hai quel pasticcio per me, {name}?", "Mm, che buono! Questo pasticcio è il migliore!\n\nMi sa che mi sta tornando la memoria...", 0x77e92707, 0xb3802d9c, 0x8c11f6b5, 0xa7950cc8, 0x90374641, "....." },
  [85] = { "La collana perduta", "Parla con Billy Maclure.", "Ho perso la mia collana, e credo che l'abbia presa quel monello di Billy Maclure! Di solito sgattaiola come un topo per i vigneti dei Maclure, a est di qui.\n\nRiportami la mia collana e scalderai il cuore di una vecchia vedova.", nil, "Hai perso cosa? Be', io non ho preso nessuna collana, perché non sono mica un ladro!\n\nForse so chi è stato, ma... <sogghigna>... ho troppa fame per ricordarmelo.", 0x1a691c23, 0x3c0d0519, 0xc37d5922, nil, 0xc488cf29, "...m." },
  [86] = { "Un pasticcio per Billy", "Porta 4 Chunk of Boar Meat a zia Bernice Stonefield, alla Stonefield's Farm.", "Magari, se avessi un pasticcio, potrei dirti chi ha quella collana. E sai, credo che quella vecchia signora Bernice, nell'altra fattoria, faccia degli ottimi pasticci di carne di cinghiale...\n\nSe le portassi qualche pezzo di carne dei cinghiali che girano intorno alle nostre fattorie e le dicessi a cosa serve, magari ti preparerebbe un pasticcio.", "Non mi sembra giusto sfamare il ragazzo che mi ha rubato la collana, ma se è questo che serve per riavere ciò che è mio, e così sia!\n\nHai quella carne di cinghiale?", "Questa carne di cinghiale selvatico è dura, ma se la fai sobbollire abbastanza ne viene fuori proprio un pasticcio gustoso!", 0xe258953a, 0x3d1f7b01, 0xb9e0bfdc, 0xd53bb684, 0x6b1f64bc, "....." },
  [87] = { nil, "Porta la ⟦Bernice's Necklace=Collana di Bernice⟧ a \"zia\" Bernice Stonefield alla Stonefield Farm.", "Stavo giocando vicino alla ⟦Fargodeep Mine=Miniera Antrocupo⟧ e credo di aver perso, ehm... cioè, di aver visto la collana della vecchia signora. Non chiedermi come ci sia finita... non sono stato io!\n\nComunque, ho visto un grosso coboldo con un dente d'oro raccogliere la collana e scappare nella miniera. Trova quel coboldo e troverai la collana, lo giuro!", "Ciao, {name}. Hai trovato la mia collana?", "Oh, l'hai trovata! Grazie, grazie, <caro/cara>!\n\nTieni, prendi questo. Era di mio marito e diceva sempre che portava fortuna. Se solo non l'avesse dimenticato durante la sua ultima campagna! *sniff*", 0xe78fd7d9, 0xec235807, 0x329228f9, 0x511d94a7, 0x9137e39e, "e...." },
  [88] = { "Princess deve morire!", "Uccidi Princess, prendi il suo collare e riportalo a Ma Stonefield alla Stonefield Farm.", "I Brackwell hanno una scrofa da concorso, Princess. È ENORME, ed è diventata così venendo di nascosto qui a mangiarsi le mie verdure!\n\nQuindi, prima che arrivi ai nostri campi... Princess deve morire! Portami il suo collare come prova dell'opera e ti darò qualcosa per il disturbo!\n\nDi solito Princess sta al ⟦Brackwell Pumpkin Patch=Campo di Zucche dei Pozzonero⟧, a est, oltre la fattoria dei Maclure. Prendila prima che le venga fame e torni qui!", "L'hai già vista? L'hai presa?", "Meno male! Quella maiala stava diventando così grossa che si sarebbe mangiata tutto il nostro raccolto! Grazie, {name}.\n\nAllora, ti va bene uno di questi?", 0xd0c3b757, 0x87ee4e48, 0xb6b583eb, 0x6ce3847c, 0x8ee1d213, "....." },
  [89] = { "Il ponte del Lago Placido", "Porta 5 Iron Pike e 5 Iron Rivet al caposquadra Oslow a ⟦Lakeshire=Borgolago⟧.", "Durante l'ultima invasione degli orchi siamo stati costretti a fondere il nostro ferro per farne proiettili, spade e armature. Abbiamo chiesto a ⟦Stormwind=Roccavento⟧ un nuovo carico di materiali, ma una banda di gnoll di ⟦Redridge=Crestarossa⟧ ha assaltato la carovana ed è fuggita sulle colline dietro ⟦Lakeshire=Borgolago⟧.\n\nOra ci mancano i materiali per ricostruire questo ponte. Se riesci a portarmi 5 picche di ferro e 5 rivetti di ferro, {name}, ti assicuro che sarai <ricompensato/ricompensata>.\n\nE ora al lavoro!", "Questo ponte non si costruirà da solo! Allora, dove sono quelle picche di ferro e quei rivetti di ferro?", "Ottimo lavoro, {name}. Questi materiali aiuteranno moltissimo i lavori del ponte. Rimetteremo in sesto questa bellezza in un baleno.", 0xfbe560d1, 0x5c73aae5, 0xcb575d10, 0xf3038219, 0xf1b96a47, "....." },
  [90] = { "Kebab Speziato di Lupo", "Raccogli 10 Costato di Lupo e torna dallo chef Grual a ⟦Darkshire=Borgoscuro⟧.", "Il Kebab Speziato di Lupo è una specialità della casa! Certo, posso preparartene un po'. Ma prima mi servono gli ingredienti. Portami 10 Lean Wolf Flank. Con tutti i lupi che ci sono qui nella foresta, sono sicuro che trovarli non sarà un problema. Per tua fortuna mi è appena arrivata la nuova partita di erbe aromatiche di ⟦Stormwind=Roccavento⟧, quindi per cominciare mi servono solo i fianchi.", "Hai già trovato 10 Lean Wolf Flank? E le erbe di Felicia, da ⟦Stormwind=Roccavento⟧?", "Ottimo lavoro, {name}! Goditi questa prelibatezza chiamata ⟦Seasoned Wolf Kabob=Kebab Speziato di Lupo⟧!", 0x382c5f99, 0xb8f7846f, 0x7f6f2eef, 0x00eddfcd, 0x6c901c98, "....." },
  [91] = { "La legge di Solomon", "Porta 10 Pendente dei Mantombroso al balivo Conacher nel municipio di ⟦Lakeshire=Borgolago⟧.", "Un nemico di ⟦Stormwind=Roccavento⟧ si è stabilito sulle colline orientali di ⟦Redridge=Crestarossa⟧. Questo malvagio furfante usa l'Arcano per seminare terrore e miseria nella nostra città e tra la nostra gente. Conduce i suoi loschi affari sotto il nome di Morganth.\n\nOra Morganth controlla il clan degli gnoll Mantombroso, che eseguono i suoi ordini. Come stabilisce la Legge di ⟦Lakeshire=Borgolago⟧, aiutare un criminale del Regno è punibile con la morte.\n\nQuesti vili gnoll vanno uccisi!\n\nConsegnami 10 pendenti dei Mantombroso e sarai <ricompensato/ricompensata>.", "Consegnami 10 pendenti dei Mantombroso e sarai <ricompensato/ricompensata>.", "La Corte di ⟦Lakeshire=Borgolago⟧ riconosce il tuo impegno per la giustizia, {name}. Facendo rispettare le leggi del Regno hai contribuito a difendere la giustizia di queste terre.", 0x4cdcd468, 0x14f882a1, 0xdf5729ff, 0x236bce06, 0x10ddb922, "....." },
  [92] = { "⟦Redridge Goulash=Gulasch alla Crestarossa⟧", "La cuoca Breanna di ⟦Lakeshire=Borgolago⟧ vuole cinque pezzi di ⟦Tough Condor Meat=Carne Tigliosa di Condor⟧, cinque Great Goretusk Snout e cinque porzioni di ⟦Crisp Spider Meat=Carne Croccante di Ragno⟧.", "Niente mi farebbe più piacere che prepararti un ⟦Redridge Goulash=Gulasch alla Crestarossa⟧. Ma c'è un piccolo problema. Durante la recente rivolta degli orchi ho sfamato l'intera brigata delle truppe di ⟦Stormwind=Roccavento⟧. Ora la mia dispensa è vuota. Però, se mi procuri gli ingredienti, sarò felice di accontentarti.\n\nPortami solo cinque pezzi di ⟦Tough Condor Meat=Carne Tigliosa di Condor⟧, cinque Great Goretusk Snout e cinque porzioni di ⟦Crisp Spider Meat=Carne Croccante di Ragno⟧.", "Mi servono ancora cinque pezzi di ⟦Tough Condor Meat=Carne Tigliosa di Condor⟧, cinque Great Goretusk Snout e cinque porzioni di ⟦Crisp Spider Meat=Carne Croccante di Ragno⟧.", "Ben fatto, {name}. E che begli esemplari! Ecco a te la deliziosa specialità nota come ⟦Redridge Goulash=Gulasch alla Crestarossa⟧!", 0x3d45e6f7, 0xa292ee13, 0x05480404, 0x61808eeb, 0xd0740ab9, "....." },
  [93] = { "⟦Dusky Crab Cakes=Tortino di Granchio Scuro⟧", "Raccogli 6 Gooey Spider Leg e portale allo chef Grual a ⟦Darkshire=Borgoscuro⟧.", "Ti svelo un piccolo segreto: i Tortini di «Granchio» Scuro in realtà sono fatti con zampe di ragno! Lo so, è un po' disgustoso, ma i tortini hanno un sapore piacevole e acidulo e sono ottimi come spuntino! Portami delle zampe di ragno appiccicose e te ne preparo qualcuno.\n\nHo sentito che i Venom Web Spider sono una buona fonte: fanno il nido a nord, tra le colline e il fiume.", "Salve, {name}. Hai già preso quelle zampe di ragno appiccicose?", "Ah sì, un bel mucchio di zampe quello che hai lì! Lascia solo che le condisca con le mie spezie segrete (non sbirciare!) e le faccia sfrigolare in padella per un po'...\n\nE anche se il ⟦Dusky Crab Cakes=Tortino di Granchio Scuro⟧ è la mia specialità e non ne rivelo la ricetta, eccoti la ricetta di un piatto buono quasi altrettanto.", 0x20b89ad4, 0x8efb36e6, 0x27a03112, 0x7c48a403, 0x83bd0d84, "....." },
  [94] = { "Un occhio vigile", "Porta il ⟦Glyph of Azora=Glifo - Azora⟧ alla statua del leone vicino alla ⟦Tower of Ilgalar=Torre di Ilgalar⟧, a ⟦Redridge=Crestarossa⟧.", "Il mio rivale, Morganth, è un mago spietato e potentissimo che vive nella ⟦Tower of Ilgalar=Torre di Ilgalar⟧, a ⟦Redridge=Crestarossa⟧. Ho messo a punto un mezzo per spiarlo, l'Eye of Azora, e ora posso osservarlo da lontano.\n\nMa per studiarne i pensieri... mi serve altro aiuto.\n\nSe te la senti, porta il mio ⟦Glyph of Azora=Glifo - Azora⟧ alla ⟦Tower of Ilgalar=Torre di Ilgalar⟧. Posalo sulla statua del leone vicino alla torre.\n\nFatto questo, il potere di Azora mi concederà visioni dei piani futuri di Morganth.", "Questa statua del leone è qui da decenni e veglia solitaria sulla famigerata ⟦Tower of Ilgalar=Torre di Ilgalar⟧.\n\nAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...", "Posi il ⟦Glyph of Azora=Glifo - Azora⟧ sulla pietra. Vi aderisce... e ne senti uscire la voce disincarnata di Theocritus:\n\nHai la mia gratitudine, giovane {name}. Ora puoi parlare con me attraverso questo glifo, e forse avrò altri compiti per te... dopo aver sondato i pensieri del mio rivale.", 0x4ce3e4cb, 0xae7ae989, 0x32080b45, 0x5d05e43a, 0x338c1c3b, "....." },
  [95] = { "La vendetta di Sven", "Va' alla fattoria di Sven e trova ciò che è stato sepolto dietro il vecchio ceppo.", "Lavoravo in una delle fattorie a sud-est... finché i Dark Rider del ⟦Deadwind Pass=Valico Ventomorto⟧ non sono piombati sulla mia fattoria e hanno massacrato la mia famiglia mentre ero via!\n\nQuando sono tornato ho visto una figura nell'ombra aggirarsi furtiva vicino al mio fienile e seppellire qualcosa. È fuggita prima che potessi prenderla, e non potevo trattenermi perché ero sulle tracce dei Dark Rider. Così non ho mai scoperto cosa avesse nascosto.\n\nSe riesci a trovare ciò che quella figura ha sepolto, te ne sarò grato. Il nascondiglio è dietro il vecchio ceppo vicino al mio fienile.", nil, "Qui c'è un cumulo di terra, ammucchiata in fretta, come se qualcuno avesse avuto bisogno di nascondere qualcosa... senza molto tempo per farlo.", 0x09c1ac2f, 0x7218d46f, 0x01da608e, nil, 0xacd152b2, "...m." },
  [96] = { "Il richiamo dell'acqua", "Porta la ⟦Shard of Water=Scheggia d'Acqua⟧ a Islen Waterseer nelle ⟦Barrens=Savane⟧.", "Prendi scheggia. Prendi scheggia e dai vita.\n\nDai vita e comprendi. Comprendi che acqua è vita... corruzione ferma vita.\n\nTu proteggi e dai vita con potere dell'acqua.", "Sei tornat<o/a>. Splendido!\n\nCom'è andato il tuo viaggio a ⟦Silverpine=Pinargento⟧? Ti ci è voluto molto?\n\nMi è difficile capire se laggiù hai avuto successo, perché gran parte di quella terra è ormai corrotta. Il suo fetore soverchia qualunque bene tu possa aver fatto. Ma i piccoli successi a volte contano quanto quelli grandi. Purificare l'acqua laggiù è stato fondamentale per te e per tutti gli sciamani.", "Questa è la prova che ti avevo chiesto. Hai fatto bene, {name}.\n\nSono felice di essere la prima a congratularmi con te e a darti questo... il tuo totem dell'acqua.\n\nUsalo bene, e buona fortuna.\n\nLa tua prossima prova non arriverà prima di un po' di tempo, quindi impara bene le tue lezioni. L'acqua pura non solo ridà la vita a chi è ferito, ma può avere molti altri effetti. Ti suggerisco di cercare un istruttore degli sciamani quando ne avrai il tempo. Potrebbe avere altri incantesimi da insegnarti.", 0x1f0e11aa, 0xb068b278, 0x1bc4c72c, 0xb4ccba7c, 0x8edac29b, "....." },
  [97] = { "La leggenda di Stalvan", "Riferisci la notizia al comandante Ebonlocke.", "Fai sapere subito al comandante Ebonlocke che la calligrafia corrisponde, {name}! I suoi sospetti erano fondati!", "Sì, {name}?", "Lo sapevo! Ottimo lavoro, {name}.", 0xeb6571fb, 0xf668237f, 0x89f670d8, 0xabfc0333, 0xe1fbbf40, "....." },
  [98] = { "La leggenda di Stalvan", "Uccidi Stalvan Mistmantle e mostra a Madame Eva il suo anello di famiglia.", "Stalvan Mistmantle ha condotto una vita depravata. Vittime innocenti sono morte per mano sua. Senza dubbio è colpevole di innumerevoli crimini. Ora quel folle minaccia ⟦Darkshire=Borgoscuro⟧. Solo la Luce sa quali atti abietti stia tramando. Va' al suo casolare, appena a nord della città, {class}, e giustizia Stalvan una volta per tutte.\n\nQuando l'avrai fatto, recati da Madame Eva e mostrale il suo anello di famiglia. Dopotutto, è stata la sua premonizione a portare a questa macabra scoperta. Ma ⟦Darkshire=Borgoscuro⟧ è più sicura grazie a lei.", "Sì, {name}?", "Lo so, {name}: Stalvan è morto. Ho percepito un'ondata di speranza attraversare la foresta contaminata. Una volta per tutte, ⟦Duskwood=Boscovespro⟧ è libero dalla sua sete di sangue. La mia gioia è offuscata dal pensiero di coloro che sono caduti preda di quell'orribile bestia. Ciò nonostante, sei <un/una> {class} <coraggioso/coraggiosa> e <astuto/astuta>.", 0xeb6571fb, 0x6cc7a1f9, 0xf2779455, 0xabfc0333, 0x9b99fbec, "....." },
  [99] = { "La follia di Arugal", "Porta 6 Pyrewood Shackle a Dalar Dawnweaver, alla ⟦Sepulcher=Mausolea⟧.", "Più comprendo la magia di Arugal, più cresce il mio disprezzo per quello sciocco sventurato. Sono vicino a concludere le mie ricerche sul suo cosiddetto rimedio.\n\nLa mia conoscenza sarà completa quando scoprirò quale incantesimo provoca lo strano comportamento degli abitanti di ⟦Pyrewood Village=Rovonero⟧. Di giorno i contadini sembrano di razza Umana. Ma quando il sole tramonta, la gente del villaggio si trasforma in Moonrage Worgen.\n\nDevo attingere energia dai ceppi incantati che Arugal ha posto su di loro. Portami sei Pyrewood Shackle incantati, {name}.", "Hai già recuperato i Pyrewood Shackle, {name}?", "La tua perseveranza è encomiabile. Grazie alle conoscenze che mi hai aiutato a raccogliere, Arugal cadrà e la sua magia sconsiderata sarà annullata. Alla tua, {name}.", 0x93f7323d, 0x8d806801, 0x0bdd1c31, 0xfff3d9e5, 0x1cd1fde1, "....." },
  [100] = { "Il richiamo dell'acqua", "Parla con la Minor Manifestation of Water nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Una luce esplode mentre concludi l'incantesimo. Il suono delle gocce d'acqua che colpiscono la fiamma si spegne e i tuoi sensi vengono sopraffatti mentre gli spiriti corrotti intorno a te vengono distrutti.", nil, "Grazie a te. Grazie agli sciamani.\n\nCorruzione si ritira ma vita continua a svanire. Tocca a sciamani proteggere vita.", 0x1f0e11aa, 0x768f3e87, 0x2627182c, nil, 0xa657df1b, "...m." },
  [101] = { "Il ⟦Totem of Infliction=Totem del Castigo⟧", "Porta 10 Zanna di Ghoul, 10 Dito di Scheletro e 5 Fiala di Veleno di Ragno a Madame Eva, a ⟦Darkshire=Borgoscuro⟧.", "Mentre la corruzione mistica si insinua nella foresta, il bisogno di proteggersi è innegabile, {name}. I venti mi sussurrano e mi parlano di un grande pericolo che ti attende paziente nel prossimo futuro.\n\nSe desideri proteggerti, nobile {class}, portami 10 zanne di ghoul, 10 dita di scheletro e 5 fiale di veleno di ragno. Per te incanterò un ⟦Totem of Infliction=Totem del Castigo⟧, che ferirà chi tenterà di usarti violenza.", "Portami 10 zanne di ghoul, 10 dita di scheletro e 5 fiale di veleno di ragno. Per te incanterò un ⟦Totem of Infliction=Totem del Castigo⟧, che ferirà chi tenterà di usarti violenza.", "Molto saggio da parte tua, {name}. Questo ⟦Totem of Infliction=Totem del Castigo⟧ ti aiuterà a proteggerti dal male che si annida in tutta Azeroth e oltre. Quando ti senti minacciat<o/a>, stringi questo totem e trova conforto nella sua aura magica. Sii coraggios<o/a>, nobile {class}. Ti servirà tutto il coraggio che riesci a raccogliere, perché vedo molto sangue nel tuo futuro.", 0x35b94d5e, 0xef7c0c6e, 0x1e1257d7, 0x90276681, 0xfa828321, "....." },
  [102] = { "Pattuglia nelle ⟦Westfall=Marche Occidentali⟧", "Porta 8 Gnoll Paw al capitano Danuvin a ⟦Sentinel Hill=Guardiacolle⟧.", "⟦Stormwind=Roccavento⟧ ci ha abbandonati. Un vento malsano di depravazione soffia sulle pianure delle ⟦Westfall=Marche Occidentali⟧. Questa era la mia terra natia e non volterò le spalle ai cittadini che scelgono di restare. Noi, che un tempo eravamo contadini, resisteremo.\n\nIl tuo compito, se vorrai accettarlo, è pattugliare le praterie delle ⟦Westfall=Marche Occidentali⟧. Trova e uccidi i turpi gnoll che sembrano agire in combutta con i ladri delle ⟦Deadmines=Miniere della Morte⟧. Portami otto zampe di gnoll e ricompenserò il tuo coraggio.", "Hai già raccolto 8 zampe da quegli gnoll infidi?", "Ben fatto, {name}. Con avventurieri valorosi come te a combattere al fianco della ⟦People's Militia=Milizia del Popolo⟧, le ⟦Westfall=Marche Occidentali⟧ potrebbero tornare a essere il prospero granaio di un tempo. Ti prego, accetta questo in segno di riconoscenza per il tuo instancabile impegno.", 0xbdbd8c1d, 0xb285aa6c, 0x08d3c8d8, 0x34967c23, 0xe6d9e3f6, "....." },
  [103] = { "Il custode della fiamma", "Porta 5 Flask of Oil al capitano Grayson, al ⟦Westfall Lighthouse=Faro delle Marche Occidentali⟧.", "La notte in cui morì la famiglia del guardiano del faro fu orribile. Rimasi a guardare, impotente, mentre Old Murk-Eye guidava l'attacco. Ma quel che è fatto è fatto, e ora mi preoccupo per la vita dei marinai del ⟦The Great Sea=Grande Mare⟧, le cui navi si avvicinano agli scogli insidiosi della costa. Senza nessuno che vegli sulla fiamma, la responsabilità è ricaduta su di me.\n\nAiutami a tenere accesa la torcia portandomi 5 fiaschi d'olio presi agli Harvest Monster.", "Senza olio la fiamma non arderà a lungo, {name}.", "Che tu sia lodat<o/a>, valoroso {class}. Grazie al tuo duro lavoro, gli scogli della costa delle ⟦Westfall=Marche Occidentali⟧ saranno illuminati. Molte vite saranno risparmiate finché la torcia resterà accesa.\n\nSono morto inutilmente proprio su questa riva. Il mio compito nell'aldilà è fare in modo che nessun altro segua il mio destino.", 0x3ef7ad7a, 0xadaf38bb, 0x2c40ca7a, 0xd537b66e, 0x38ec3914, "....." },
  [104] = { "La minaccia della costa", "Porta una squama di Old Murk-Eye al capitano Grayson al ⟦Westfall Lighthouse=Faro delle Marche Occidentali⟧.", "Quando la mia vita si è spenta su quegli scogli, non avevo idea di cosa mi riservasse l'aldilà. Quella notte il Faro era spento perché Old Murk-Eye aveva fatto fuggire la famiglia del guardiano. Tornarono e riaccesero la fiamma, ma Old Murk-Eye costrinse i murloc più deboli di mente ad assaltare di nuovo il Faro con lui. La seconda volta la famiglia non fu così fortunata e perì impotente davanti ai miei occhi.\n\nUccidi Old Murk-Eye se lo vedi lungo la riva, portami una delle sue squame e ti ricompenserò.", "Hai già eliminato la minaccia nota come Old Murk-Eye? È stato avvistato mentre vagava lungo la costa delle ⟦Westfall=Marche Occidentali⟧.\n\nTorna da me quando quella bestia immonda sarà morta.", "Dunque quell'immondo pagano, Murk-Eye, è morto. Ben fatto, {name}. Per mano tua una vita è stata messa a riposo, ma forse molte altre sono state salvate. Il ⟦The Great Sea=Grande Mare⟧, irto di pericoli com'è, stanotte sarà un pochino più sicuro grazie al tuo eroismo.", 0x2f06382c, 0x9bc7f6db, 0xa6201dcb, 0xd389c8ba, 0xf95015fd, "....." },
  [106] = { "Giovani innamorati", "Consegna la ⟦Maybell's Love Letter=Lettera d'Amore di Maybell⟧ a Tommy Joe Stonefield.", "Oh, sono maledetta! Il mio cuore appartiene a Tommy Joe Stonefield, ma le nostre famiglie sono nemiche giurate. Così non posso vederlo, anche se i miei occhi bramano di contemplare quel bel viso!\n\nTi prego, prendi questa lettera e dalla a Tommy Joe. Di solito è al fiume a ovest della fattoria degli Stonefield, che si trova dritto a ovest di qui.", "Hai cosa?? Maybell è la luce della mia grigia esistenza. Presto, fammi vedere la sua lettera!", "Ah! Non sopporto di stare lontano da lei. Devo vederla!!", 0x39bb27e6, 0xaca204cb, 0x455a69fe, 0x8ed56116, 0xaef57c73, "....." },
  [107] = { "Un biglietto per William", "Porta la ⟦Gramma Stonefield's Note=Nota di Nonna Pietradura⟧ a William Pestle.", "Scommetto che William Pestle ha una pozione per unire i nostri due giovani innamorati!\n\nEcco, porta questo biglietto a William. Alloggia alla Lion's Pride Inn, a ⟦Goldshire=Borgodoro⟧.", "Hai un biglietto da \"nonna\" Stonefield, eh? Non vedo Mildred da anni! Chissà cosa avrà da dire...", "Il mio cuore è con quelle due povere anime, Maybell e Tommy Joe. Ricordo cosa vuol dire essere giovani e innamorati, un tempo.\n\nCi deve essere qualcosa che posso fare per aiutarli! Fammi pensare...", 0x94227104, 0x6cf2cbc4, 0x613551b1, 0x4d3b404b, 0xd5a99e73, "....." },
  [109] = { "Rapporto a Gryan Stoutmantle", "Parla con Gryan Stoutmantle. Di solito si trova nella torre di pietra di ⟦Sentinel Hill=Guardiacolle⟧, appena fuori dalla strada, al centro delle ⟦Westfall=Marche Occidentali⟧.", "Mi sembra che tu di battaglie ne abbia viste parecchie, {class}. Se non l'hai ancora fatto, dovresti presentarti a Gryan Stoutmantle. Guida la ⟦People's Militia=Milizia del Popolo⟧, che si occupa di proteggere i campi delle ⟦Westfall=Marche Occidentali⟧. Scommetto che il tuo aiuto gli farebbe comodo. Di solito lo trovi nella torre di pietra di ⟦Sentinel Hill=Guardiacolle⟧, appena fuori dalla strada, al centro delle ⟦Westfall=Marche Occidentali⟧.", nil, "Ah, quindi ti ha mandato qui il mio amico? Molto gentile.\n\nBe', la monarchia di ⟦Stormwind=Roccavento⟧ ha abbandonato la nostra causa. Ora tocca alla ⟦People's Militia=Milizia del Popolo⟧ tenere questa terra libera dalla corruzione. Se la nostra causa ti interessa, posso mettere le tue capacità di combattimento al servizio della libertà.", 0xc82e5075, 0x03f579cf, 0x50233a5c, nil, 0xb444ea08, "...m." },
  [111] = { "Una parola con la nonna", "Parla con nonna Stonefield.", "Ti prego, {name}, parla con mia nonna. Se c'è qualcuno che può trovare il modo di farmi stare con Maybell, è lei.\n\nÈ dentro casa nostra, a est di qui.", "Non vedo l'ora di vedere come reagiranno i miei amici!\n\nNon se lo aspetteranno mai", "Finché le nostre famiglie sono in lite, Tommy Joe e Maybell non hanno molto futuro, ma... forse possiamo farli stare insieme almeno per un po'.\n\nMm, cosa possiamo fare...", 0x6b3f9d7c, 0xf51e0819, 0x90033b93, 0x96b93e46, 0x2fa7cabf, "....." },
  [112] = { "Raccolta di alghe", "Porta 4 Crystal Kelp Frond a William Pestle a ⟦Goldshire=Borgodoro⟧.", "Posso preparare un Liquore dell'Invisibilità per Maybell, così potrà sgattaiolare via dalla vigna dei Maclure e raggiungere Tommy Joe. Ma per fare il liquore mi serve dell'alga cristallina.\n\nDi solito quest'alga cresce nell'oceano... ma a volte i murloc la raccolgono. Vedi se i murloc vicino al ⟦Crystal Lake=Lago di Cristallo⟧ ne hanno un po'. Il ⟦Crystal Lake=Lago di Cristallo⟧ è appena a est di ⟦Goldshire=Borgodoro⟧.", "Hai l'alga cristallina? Sono sicuro che Maybell non vede l'ora di rivedere il suo innamorato...", "Ce l'hai fatta. Ottimo lavoro! Ora, un momento mentre preparo la pozione...", 0x2bebb48c, 0x3fc93ac6, 0x9e5c1b2e, 0x73f21124, 0xca7123ec, "....." },
  [114] = { "La fuga", "Porta il ⟦Invisibility Liquor=Liquore dell'Invisibilità⟧ a Maybell Maclure.", "Porta questo Liquore dell'Invisibilità alla giovane Maybell. Dovrebbe durare abbastanza perché possa andare a trovare Tommy Joe.", "Hai consegnato la mia lettera a Tommy Joe? Che cosa ha detto??", "Oh... cielo! Mi sento in colpa a ingannare la mia famiglia, ma i miei sentimenti per Tommy Joe sono troppo forti per ignorarli.\n\nGrazie, {name}. Berrò questo liquore appena ne avrò l'occasione e scapperò dal mio amore.\n\nE per te... ti prego, prendi questo.", 0x437cedda, 0x7b2f4392, 0x62549b36, 0x692ffc74, 0xe0cf61c2, "....." },
  [115] = { "Magia oscura", "Porta 3 Globo della Mezzanotte al maresciallo Marris a ⟦Lakeshire=Borgolago⟧.", "Gli orchi ⟦Blackrock=Roccianera⟧ hanno arruolato dei maghi d'ombra per sostenere i loro attacchi a ⟦Redridge=Crestarossa⟧, e hanno portato con sé congegni dall'oscuro potere: i globi della mezzanotte. Questi globi hanno inferto colpi pesanti ai difensori di ⟦Redridge=Crestarossa⟧, ed è indispensabile togliere dal conflitto questi oggetti contaminati dai demoni.\n\nTrova i globi della mezzanotte sui maghi d'ombra ⟦Blackrock=Roccianera⟧ uccisi e portameli. Poi li farò distruggere, perché questo mondo starebbe meglio senza di loro!", "Come va lo scontro con i maghi d'ombra? Hai trovato i globi della mezzanotte?", "Grazie, {name}. Li farò distruggere immediatamente.", 0x904fce2a, 0x60db0353, 0x5b872785, 0x92dca9d4, 0x6e8c3d71, "....." },
  [116] = { "Tempi di secca", "L'oste Daniels di ⟦Lakeshire=Borgolago⟧ ha bisogno di un barile di Thunderbrew Lager, una botte di Merlot, una bottiglia di Moonshine e un otre di Sweet Rum.", "Mi trovo proprio in un bel guaio, {name}. Le bottiglie sono quasi a secco. L'ultima consegna di liquori è in ritardo da un pezzo. L'invasione degli orchi è stata un inferno.\n\nForse potresti lavorare per me?\n\nHo bisogno che tu vada a prendere un barile di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline delle ⟦Westfall=Marche Occidentali⟧, una botte di Merlot a ⟦Stormwind=Roccavento⟧, una bottiglia di Moonshine a ⟦Darkshire=Borgoscuro⟧ e un otre di Sweet Rum a ⟦Goldshire=Borgodoro⟧. Portameli e avrai la tua ricompensa.", "Ho bisogno che tu vada a prendere un barile di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline delle ⟦Westfall=Marche Occidentali⟧, una botte di Merlot a ⟦Stormwind=Roccavento⟧, una bottiglia di Moonshine a ⟦Darkshire=Borgoscuro⟧ e un otre di Sweet Rum a ⟦Goldshire=Borgodoro⟧. Portameli e avrai la tua ricompensa.", "Un lavoro ben fatto, {name}! Conosco bene le strade che hai dovuto percorrere per procurarti questo bell'assortimento di liquori. Ma i miei clienti saranno di nuovo contenti!\n\nMia moglie è una sarta davvero brava. Accetta questo mantello che ha cucito lei, come compenso per i tuoi servigi.", 0x1c0c7a25, 0x8d7bd5b0, 0xd5a46db2, 0x61956f46, 0xbe7fa4ea, "....." },
  [117] = { nil, "Porta 5 Hops a Grimbooze Thunderbrew per completare la sua birra speciale.", "Presto, amico mio, muoviti in fretta:\n\nperché la nostra lager sia perfetta,\n\npiù simile a birra che a brodaglia,\n\nserve il luppolo, e non si sbaglia.", "Presto, amico mio, muoviti in fretta:\n\nperché la nostra lager sia perfetta,\n\npiù simile a birra che a brodaglia,\n\nserve il luppolo, e non si sbaglia.", "Luppolo e orzo, lievito e malto,\n\nle papille subiscono un vero assalto,\n\nnon c'è da supplicare né da pregare:\n\nla Thunderbrew Lager in barile si fa trovare!", 0x06ba24f2, 0xcca1a58d, 0xf52ffef7, 0xf52ffef7, 0xed1e1cbe, "e...." },
  [118] = { "Il prezzo dei ferri", "Porta la ⟦Verner's Note=Nota di Verner⟧ al fabbro Argus a ⟦Goldshire=Borgodoro⟧.", "Ho usato così tanto ferro per equipaggiare le Guardie di ⟦Stormwind=Roccavento⟧ che non me ne resta abbastanza per ferrare i cavalli della stalla!\n\nPorta questa nota al fabbro Argus a ⟦Goldshire=Borgodoro⟧. Gli spiega il mio problema e chiede una spedizione di ferri di cavallo.", "Come? Ti manda Verner, dici? Be', dammi la sua nota. E PARLA PIÙ FORTE!", "Eh, così il vecchio Verner ha bisogno di ferri, eh!?!", 0x0dd0b1f0, 0x58b93226, 0xff4bd583, 0xf790dafa, 0x3e4e8e76, "....." },
  [119] = { "Ritorno da Verner", "Torna da Verner Osgood a ⟦Redridge=Crestarossa⟧. Dagli la ⟦Crate of Horseshoes=Cassa di Ferri di Cavallo⟧.", "E va bene, gli darò i suoi 50 ferri di cavallo...\n\nEccoli, tutti imballati e pronti a partire! Di' a Verner che è stato un piacere fare affari con lui, e assicurati che legga la nota attaccata a questa cassa!", "Magnifico, sei tornat<o/a>! Hai preso i ferri?", "Grazie, mi sei davvero d'aiuto.\n\nMa cos'è questo? Argus ha mandato una nota con la cassa... Cosa?? Argus vuole che lo PAGHI? Bah!\n\nBe', {name}, grazie per il tuo aiuto.", 0x1296097e, 0x49433401, 0xe1ab4783, 0xa467f765, 0x16236c6c, "....." },
  [120] = { "Messaggero per ⟦Stormwind=Roccavento⟧", "Il magistrato Solomon ti ha dato un rapporto da consegnare al generale Marcus Jonathan a ⟦Stormwind=Roccavento⟧. Il giudice vuole che tu torni da lui appena fatta la consegna.", "Sono tempi difficili, {class}. Il borgo è sotto assedio continuo. Senza rinforzi andremo di certo incontro alla sconfitta. Il messaggio che ora ti affido è della massima importanza. Porta subito questo rapporto al generale Marcus Jonathan di ⟦Stormwind=Roccavento⟧. Una volta fatta la consegna, torna immediatamente da me con qualunque notizia, buona o cattiva.\n\nOra sbrigati!", "Che cos'hai lì?", "Riposo, {class}.\n\nIl magistrato Solomon è un capo nobile. Le sue parole hanno molto peso per me. Chiederò consiglio al re e gli esporrò chiaramente la situazione. Assicura al buon giudice che ha il sostegno dell'esercito di ⟦Stormwind=Roccavento⟧. I rinforzi saranno inviati non appena Sua Maestà darà l'ordine.", 0x7fd00169, 0xf2be5934, 0x06176f7a, 0x19bf3607, 0x6d2fb894, "....." },
  [121] = { "Messaggero per ⟦Stormwind=Roccavento⟧", "Porta la lettera di risposta del generale Marcus Jonathan al magistrato Solomon a ⟦Lakeshire=Borgolago⟧.", "Mentre attendo una risposta dal re, voglio che tu porti questa lettera al magistrato Solomon.\n\nPuoi andare, {class}!", "Il generale ha mandato notizie? I rinforzi sono in arrivo?", "Grazie per il tuo tempo, {class}. Per il servizio reso a ⟦Lakeshire=Borgolago⟧ e a ⟦Stormwind=Roccavento⟧ ti ricompenso con queste monete.\n\nOra, se vuoi scusarmi, trovo questa corrispondenza piuttosto misteriosa. Qualcosa non va nel nostro regno. Temo che questo sia l'inizio di un conflitto, non la fine.", 0x7fd00169, 0xa53df32a, 0xf1bab4f4, 0xf8129079, 0x4d427db5, "....." },
  [122] = { "Scaglie del ventre", "Raccogli 6 Underbelly Whelp Scale dai Black Dragon Whelp e portale a Verner Osgood a ⟦Redridge=Crestarossa⟧.", "Mi servono delle scaglie del ventre dei draghetti neri per pagare i ferri che Argus mi ha mandato da ⟦Goldshire=Borgodoro⟧. Se me ne procuri 6, potrò pagare Argus con alcune... e me ne resteranno abbastanza per forgiare qualcosa per te.\n\nI draghetti neri volano spesso a sud di ⟦Lakeshire=Borgolago⟧, ma amano vagare. Forse dovrai solo tenere gli occhi aperti e dargli la caccia quando li vedi.", "Lo so che quell'avido di Argus manderà qualcuno a riscuotere le sue scaglie, se non gliele do presto. Le hai già trovate?", "Grazie! Con queste salderò il mio debito con Argus...", 0x068001c9, 0xd4d12cd6, 0xcda5c273, 0xef1640b6, 0xf521558d, "....." },
  [123] = { "Il Collezionista", "Va' dal maresciallo Dughan a ⟦Goldshire=Borgodoro⟧ e consegnagli il ⟦The Collector's Schedule=Programma del Collezionista⟧", "Questo biglietto è un programma con un elenco di giorni e orari in cui una persona, descritta solo come «il Collezionista», riceverà un carico d'oro dalle miniere della ⟦Elwynn Forest=Foresta di Elwynn⟧.\n\nDal programma sembra che il Collezionista si trovi vicino al ⟦Brackwell Pumpkin Patch=Campo di Zucche dei Pozzonero⟧, nell'est di Elwynn.\n\nSembra importante. Dovresti riferirlo al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.", "Cosa?! Sono mesi che la nostra gente non lavora nelle miniere di Elwynn!\n\nFammi vedere quel biglietto che hai...", "Mm... ho sentito parlare di questo «Collezionista», ma non so per chi lavori. Grazie per il programma. Ci aiuterà a risolvere questo mistero.", 0x5318a151, 0x3b835957, 0x5a3d01e4, 0xb33d4341, 0x318a1e2f, "....." },
  [124] = { "Un ululato di gnoll", "Uccidi 10 Bruti di ⟦Redridge=Crestarossa⟧ e 8 Mistici di ⟦Redridge=Crestarossa⟧, poi torna da Verner Osgood.", "Come se gli orchi all'attacco non bastassero! Ora ho gnoll bruti e mistici che si aggirano sul crinale a nord della mia stalla e mi prendono i cavalli quando si allontanano...\n\nSe riesci a liberarti di quegli gnoll, io e i miei cavalli te ne saremo molto grati.", "I miei cavalli sono ancora agitati e di notte sento ancora quel maledetto ululato di lupo. Ti prego, {name}, fa' qualcosa per quegli gnoll!", "Grazie per tutto il tuo aiuto, {name}.", 0xe85ed098, 0xa4d31ccd, 0xaddbfb20, 0x1ef3dbfd, 0xac71f116, "....." },
  [125] = { "Gli attrezzi perduti", "Il caposquadra Oslow di ⟦Lakeshire=Borgolago⟧ vuole che tu recuperi la sua cassetta degli attrezzi dal fondo del ⟦Lake Everstill=Lago Placido⟧.", "Mi servirebbe proprio una mano, {name}. Con la città sotto assedio, è dura procurarsi rifornimenti. I miei attrezzi dovevano arrivare da ⟦Goldshire=Borgodoro⟧ su un carro, ma il ponte è saltato. Abbiamo messo gli attrezzi su una barca, ma gli orchi l'hanno colpita con una catapulta. Con la fortuna che mi ritrovo, la mia cassetta degli attrezzi è finita dritta sul fondo del lago.\n\nRecupera la mia cassetta, {name}, e ne varrà la pena.", "Sei riuscit<o/a> a trovare i miei attrezzi?", "Ottimo recupero, {name}! Non pensavo che avrei più rivisto questi attrezzi.", 0xc690e293, 0xe17d01d0, 0x00f67f4e, 0xc0af6727, 0xa3088c9c, "....." },
  [126] = { "Ululati sulle colline", "Porta la ⟦Yowler's Paw=Zampa di Ghignolungo⟧ a Verner Osgood, a ⟦Lakeshire=Borgolago⟧.", "{name}, gli gnoll sono ancora là fuori. Li sento latrare mentre cacciano sulle colline sopra ⟦Lakeshire=Borgolago⟧. E un verso è più forte degli altri: quello di Yowler, il loro capo.\n\nUccidi Yowler e disperdi il suo branco! Portami la sua zampa come prova.\n\nE fai attenzione: questo gnoll non è il loro capo per caso. Non è un Mongrel qualunque...", "Yowler è una creatura pericolosa, {name}. Se non sei pront<o/a> ad affrontarlo, lo capisco.", "Grazie ancora per il tuo aiuto. L'esercito di ⟦Stormwind=Roccavento⟧ è così impegnato con gli orchi che non ha truppe per proteggere ⟦Redridge=Crestarossa⟧ dalle minacce locali, come gli gnoll.", 0x8dfeeed2, 0x12e4af10, 0x3fd1157a, 0x33d0330f, 0x3ba08361, "....." },
  [127] = { "Pesce in vendita", "Porta 10 ⟦Spotted Sunfish=Pesce Mola Maculato⟧ al capitano di porto Baren a ⟦Lakeshire=Borgolago⟧.", "Il ⟦Lake Everstill=Lago Placido⟧ è famoso per i suoi pesci mola maculati. La richiesta non manca mai... e io sono quasi a secco!\n\nPortamene una partita di 10 e ti pagherò bene. Se non sai pescare, allora... magari puoi prenderli ai murloc!", "Hai dei pesci mola per me, eh?", "Un piacere fare affari con te, compare!", 0x8959426d, 0x299dd9a7, 0x595008a9, 0x1c00230f, 0x0c2062ce, "....." },
  [128] = { "Taglia sui ⟦Blackrock=Roccianera⟧", "Uccidi 15 Blackrock Champion e la guardia Howe di ⟦Lakeshire=Borgolago⟧ ti ricompenserà.", "Il clan ⟦Blackrock=Roccianera⟧ va distrutto. Il Nemico ha invaso le nostre terre. Queste montagne sono sotto il legittimo dominio del Re di ⟦Stormwind=Roccavento⟧. Le nostre fonti dicono che i capi di ogni unità del clan sono chiamati Campioni. Li troverai nel loro accampamento a nord, appena a ovest della strada per le ⟦Burning Steppes=Steppe Ardenti⟧.\n\nIl magistrato Solomon vuole morti questi bruti immondi. Uccidi 15 Blackrock Champion e torna da me.", "Torna quando avrai ucciso 15 Blackrock Champion.", "Vedo che hai combattuto con valore contro il clan ⟦Blackrock=Roccianera⟧, {class}. Il tuo servizio alla nostra comunità è davvero grande.", 0xccdac34a, 0x3dc788d9, 0x3c6954d1, 0x465f09c0, 0x3ae1dc90, "....." },
  [129] = { "Un pranzo gratis", "Porta il pranzo di Parker alla guardia Parker. Pattuglia la strada che porta a ⟦Darkshire=Borgoscuro⟧.", "Puoi farmi un favore? Ho preparato il pranzo per la guardia Parker, ma è fuori di pattuglia... è una guardia di ⟦Stormwind=Roccavento⟧ grande e grossa e sa difendersi da sé, ma là fuori è troppo pericoloso per una paesana come me.\n\nQuindi, se gli porti il pranzo da parte mia e poi torni qui, ti offrirò un pranzo gratis! Parker pattuglia il tratto di strada che porta a ⟦Duskwood=Boscovespro⟧.", "Darcy mi ha mandato il pranzo, eh? Che cuore gentile ha. Be'... dammelo!", "Grazie, avevo proprio bisogno di mangiare. Proteggere ⟦Lakeshire=Borgolago⟧ da orchi e gnoll è un lavoro duro!", 0x88d7e35c, 0xaad7a98b, 0x9db66007, 0x3d1d5d66, 0xe1a276a1, "....." },
  [130] = { "Visita all'erborista", "Parla con l'erborista di ⟦Redridge=Crestarossa⟧, Martie Jainrose.", "Prima di tornare da Darcy, potresti portarle dei fiori da parte mia? Li trovi dall'erborista di ⟦Lakeshire=Borgolago⟧, all'estremità occidentale del paese.\n\nMa quando prendi i fiori... non dire all'erborista, Martie, da parte di chi sono, né per chi sono...", nil, "Ti serve un mazzo di fiori? Non sei in paese da molto... hai già trovato un amore qui?\n\nLo so che non dovrei impicciarmi, ma è bello vedere che c'è amore nell'aria... soprattutto in tempi pericolosi come questi.", 0x71fe59f9, 0xa1ba4f91, 0x49da55c6, nil, 0x081a325e, "...m." },
  [131] = { "Consegna di narcisi", "Dai il ⟦Daffodil Bouquet=Bouquet di Narciso⟧ a Darcy.", "Ecco il tuo bouquet. Ho scelto dei narcisi per te. Sono i miei preferiti!", "Ciao di nuovo, {name}. A Parker è piaciuto il pranzo che gli ho mandato?", "Oh, sono bellissimi! Non vedo l'ora di metterli in acqua!\n\nMa... questi sono i fiori preferiti di Martie. Non sarà stato Parker a mandarti da quella vipera gelosa per questo mazzo, vero? Non le hai detto per chi erano, vero? Se gliel'hai detto, non mi stupirei se li avesse avvelenati.\n\nOh, ma non è colpa tua. Grazie, ed ecco il tuo pranzo.", 0xf4e8832d, 0x70089ffd, 0x81de289a, 0xa471da13, 0x046112fa, "....." },
  [132] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Porta la ⟦Wiley's Note=Nota di Wiley⟧ a Gryan Stoutmantle nelle ⟦Westfall=Marche Occidentali⟧.", "Quello che sto per dirti potrebbe costarmi la vita. La banda dei Defias sta tramando qualcosa di grosso. L'ultima volta che ho sentito, lavoravano insieme a vari gnoll, coboldi e perfino goblin.\n\nPorta questa nota a Stoutmantle. Spiega tutto quello che so sull'argomento.", "Bentornat<o/a>, {name}. Che cosa aveva da dire Wiley a sua discolpa?", "Bah! Avrei dovuto lasciar marcire quel furfante quando ne avevo l'occasione. Ma questa informazione è fondamentale. Ottimo lavoro.", 0x2a2224c0, 0x790d2fad, 0xda37a6c4, 0xf10ad446, 0x494d4d81, "....." },
  [133] = { "Un'effigie per i ghoul", "Raccogli 7 Costola di Ghoul e portale ad Abercrombie, nella sua baracca.", "Vivo così lontano dalla protezione del villaggio che è un miracolo se i ghoul e i morti che camminano non mi hanno ancora mangiato! Anzi, proprio ieri un branco di Bone Chewer prendeva a pugni i muri di casa mia!\n\nVoglio costruire un'effigie, una specie di «spaventapasseri» per ghoul. Per farlo mi servono delle costole di ghoul. Puoi prenderle da Flesh Eater, Bone Chewer, Brain Eater, Rotted One e Plague Spreader.\n\nProcurami le costole e ti ripagherò con qualche moneta.", "Mi pare di sentire un branco di ghoul che si aggira dietro casa... farei meglio a montare subito quell'effigie! Mi hai portato quelle costole di ghoul?", "Ah, grazie. Queste faranno proprio al caso mio!", 0x47c35f07, 0x7edccc10, 0x24de59e7, 0xa7553706, 0x54d74c26, "....." },
  [134] = { "Ogre ladri", "Riporta la ⟦Abercrombie's Crate=Cassa di Abercrombie⟧ ad Abercrombie.", "Qualche settimana fa stavo raccogliendo erbe lontano da casa, e una banda di ogre mi ha attaccato! Sono scappato e ho dovuto abbandonare una cassa di attrezzi ed erbe preziosi.\n\nDopo avermi cacciato via, gli ogre sono tornati tutti spavaldi al loro tumulo, nel sud di ⟦Duskwood=Boscovespro⟧. Sono sicuro che la mia cassa è da qualche parte vicino al tumulo.\n\nTi prego, {name}, recupera questa cassa per me, perché mi manca terribilmente.", "Hai la mia cassa? Se è così, ti prego... dammela, presto!", "Sia ringraziato il Nec-... be', grazie a TE, {name}! Ti sei più che meritat<o/a> la ricompensa.\n\nAha! Felice! Notti felici in arrivo!!", 0xfbfe2bc3, 0x2e382dde, 0x04be4123, 0xb52cb521, 0x8cc08e89, "....." },
  [135] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Porta la ⟦Wiley's Note=Nota di Wiley⟧ a Mathias Shaw a ⟦Stormwind=Roccavento⟧.", "Mi chiedo cosa intendesse Wiley quando ha nominato gli Stonemasons. Forse gli è sfuggito. Possibile che la banda dei Defias abbia a che fare con gli Stonemasons? Solo un uomo potrebbe saperlo con certezza: Mathias Shaw, capo dell'⟦SI:7=IR:7⟧. Mostragli la ⟦Wiley's Note=Nota di Wiley⟧ e vedi se ha qualcosa da aggiungere a questo mistero sempre più fitto. Se hai difficoltà a trovare Shaw, cerca nella caserma di Old Town.", "Che affari hai con me? Sono un uomo molto impegnato...", "La faccenda potrebbe essere più complessa di quanto Stoutmantle immagini.", 0x2a2224c0, 0x95f26f8f, 0x0882b814, 0x12eeb2a7, 0x48d02edd, "....." },
  [136] = { "Il tesoro nascosto del capitano Sander", "Trova il baule del capitano Sanders e cercaci dentro il prossimo indizio.", "Se stai leggendo 'sta roba, vuol dire che il vecchio capitano Sanders è in una tomba d'acqua. Perciò il mio tesoro adesso è tuo, devi solo seguire gli indizi.\n\nPer prima cosa devi trovare il mio baule. Ormai sarà mezzo sepolto nella sabbia, lungo la costa occidentale delle ⟦Westfall=Marche Occidentali⟧, vicino al relitto. Di relitti ce ne sono tanti, ma sulla costa c'è un'ancora arrugginita sola. Trova quell'ancora e troverai il mio baule! Guarda lì dentro per il prossimo indizio.", nil, "Il baule si apre lentamente, cigolando. Sembra contenere solo sabbia e acqua. Ma un momento! Un granchietto zampetta fuori con un indizio sul tesoro tra le chele!", 0x06bba426, 0x0a7c4cb3, 0xa2d6009c, nil, 0x386945df, "...m." },
  [138] = { "Il tesoro nascosto del capitano Sander", "Trova il vecchio barile vicino al camino in rovina e cercaci dentro il prossimo indizio.", "L'indizio per il tesoro dice: Bel lavoro, compare! Ora devi andare dritto verso est. A est su per le scogliere, a est fino alla strada. Cerca le rovine del vecchio camino sul ciglio della strada. Lì troverai un vecchio barile con il prossimo indizio.", nil, "Bel lavoro, cacciatore di tesori!", 0x06bba426, 0x1440041d, 0xf26acf24, nil, 0x7ca63b45, "...m." },
  [139] = { "Il tesoro nascosto del capitano Sander", "Fruga nella brocca vuota accanto al mulino a vento per trovare il prossimo indizio.", "Frugando nel barile scopri un altro pezzo di pergamena. Questo dice: Ora, da 'sto barile, voltati verso nord. Dritto come vola il corvo, continua a camminare finché non vedi la brocca vuota accanto al mulino a vento solitario sulle scogliere sul mare. Se frughi attorno a quella brocca, potresti trovare quel che cerchi.", nil, "Sei sulla strada del bottino grosso, cercatore di tesori!", 0x06bba426, 0x7ab5b5af, 0x0b996e82, nil, 0xd8473e97, "...m." },
  [140] = { "Il tesoro nascosto del capitano Sander", "Trova lo scrigno del capitano Sanders e aprilo per ottenere la tua ricompensa.", "Proprio così: in fondo alla vecchia brocca c'è un altro indizio sul tesoro di Sander. L'inchiostro è colato in alcuni punti e la carta puzza di whisky, ma riesci a decifrare parte del testo: Ora che hai trovato la mia vecchia brocca di whisky, sei quasi arrivat<o/a> al tesoro! Dalla bottiglia voltati verso ovest e scendi fino alla riva. Quando arrivi all'acqua, non fermarti! Nuota dritto verso ovest finché non trovi l'isola con il mio scrigno del tesoro!", nil, "I cardini del vecchio scrigno sono arrugginiti, ma funzionano ancora. Forzi lo scrigno e prendi il bottino.\n\nCongratulazioni!", 0x06bba426, 0x01f557fa, 0xc7539c95, nil, 0x6ef48c97, "...m." },
  [141] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Porta il rapporto di Shaw a Gryan Stoutmantle nelle ⟦Westfall=Marche Occidentali⟧.", "La Stonemasons' Guild era guidata da un uomo di nome Edwin VanCleef. VanCleef fu incaricato di ricostruire ⟦Stormwind=Roccavento⟧ dopo che gli orchi la rasero al suolo nella Prima Guerra. A quanto pare, VanCleef e i suoi uomini non erano soddisfatti del trattamento ricevuto dal re una volta completata la ricostruzione. Questo potrebbe spiegare un paio di cose.\n\nHo scritto un resoconto più dettagliato per il tuo superiore nelle ⟦Westfall=Marche Occidentali⟧. Portaglielo subito!", "Mastro Shaw ha fatto un po' di luce sulla faccenda?", "Edwin VanCleef... Conosco bene quel nome. Mi turba pensare che un uomo tanto operoso e di talento possa essere diventato un simile furfante. Mi servono altre prove prima di crederci.", 0x2a2224c0, 0x7a7f1227, 0x42f42474, 0xb9945de0, 0xe1668a3c, "....." },
  [142] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Rintraccia il Defias Messenger nelle ⟦Westfall=Marche Occidentali⟧ e porta il suo messaggio a Stoutmantle.", "Dobbiamo scoprire dove si trova il nascondiglio dei Defias. {name}, il mio esploratore riferisce che un Defias Messenger è stato avvistato sulle strade fra ⟦Moonbrook=Rivoluna⟧, la ⟦Gold Coast Quarry=Cava della Costa d'Oro⟧ e la ⟦Jangolode Mine=Miniera Venacava⟧. Voglio che tu lo catturi. Se oppone resistenza, uccidilo e portami qualunque cosa abbia con sé.", "{name}, sei riuscit<o/a> a raccogliere qualche informazione? Hai trovato il messaggero?", "Questa è davvero la prova certa che a capo di tutto c'è VanCleef. Ora ci basta sapere dove si nasconde la banda dei Defias.\n\nMentre eri via abbiamo avuto un colpo di fortuna. Abbiamo catturato un ladro che cercava di rubare il carro di Saldean. Ha promesso di condurci al nascondiglio in cambio della vita. Voglio che tu difenda il traditore, così che possa rivelarci il nascondiglio. Torna da me quando avrai scoperto dove si trova.", 0x2a2224c0, 0x243342aa, 0xf31363c7, 0x484fe496, 0xf9189f7b, "....." },
  [143] = { "Messaggero per le ⟦Westfall=Marche Occidentali⟧", "Il magistrato Solomon vuole che tu porti la sua richiesta scritta a Gryan Stoutmantle nelle ⟦Westfall=Marche Occidentali⟧.", "Sta succedendo qualcosa di strano con l'esercito di ⟦Stormwind=Roccavento⟧. A quest'ora dovrebbero già essere qui in forze. Il tempo, però, è un lusso che non abbiamo. Non resterò a guardare la gente di ⟦Lakeshire=Borgolago⟧ dare la vita senza cercare altro aiuto. Ho sentito dire che nelle ⟦Westfall=Marche Occidentali⟧ si sta formando una brigata del popolo.\n\nPorta questa richiesta d'aiuto al loro capo, Gryan Stoutmantle. Forse gli uomini di Stoutmantle potranno darci man forte finché il re non manderà le riserve.", "Salute, {class}. Che affari hai con la ⟦People's Militia=Milizia del Popolo⟧?", "Buon messaggero, hai servito bene il tuo signore.", 0xf6c85306, 0x57b20c17, 0xf7e36946, 0xd03393da, 0x8b9e2f77, "....." },
  [144] = { "Messaggero per le ⟦Westfall=Marche Occidentali⟧", "Torna dal magistrato Solomon con la risposta di Gryan Stoutmantle.", "Leggere il messaggio del magistrato Solomon mi addolora. Ma è chiaro che non sa nulla della guerra che si combatte nelle ⟦Westfall=Marche Occidentali⟧, altrimenti saprebbe che non deve aspettarsi aiuto dalla Brigata. Se anche ⟦Stormwind=Roccavento⟧ non ci avesse abbandonati, non avremmo bisogno della Brigata.\n\nPorta questa risposta al tuo signore a ⟦Redridge=Crestarossa⟧, {class}. E fagli sapere che ho il cuore pesante per la perdita di tanti uomini valorosi.", "Possiamo aspettarci presto la ⟦People's Militia=Milizia del Popolo⟧? Le notizie di lord Stoutmantle sono buone?", "Devo dire che non va affatto bene. Non mi ero reso conto che la situazione di Stoutmantle fosse simile alla nostra qui a ⟦Lakeshire=Borgolago⟧. Quale impresa è così importante da allontanare l'esercito di ⟦Stormwind=Roccavento⟧ dalla sua gente? Bah, non dovrei pensare ad alta voce.\n\nEcco, messaggero. Accetta queste monete per il servizio reso al borgo. Potrei chiamarti di nuovo.", 0xf6c85306, 0x82d09720, 0x39c0aa3b, 0x16225e09, 0x7726c3a3, "....." },
  [145] = { "Messaggero per ⟦Darkshire=Borgoscuro⟧", "Il magistrato Solomon vuole che tu porti una lettera a lord Ebonlocke a ⟦Darkshire=Borgoscuro⟧.", "Ho di nuovo bisogno del tuo aiuto. Ho scritto a lord Ebonlocke chiedendogli di mandare le sue guardie addestrate, la Night Watch, ad aiutare nella difesa di Borgolago. È indispensabile che questo messaggio gli arrivi in fretta. Devi agire con estrema cautela. Ebonlocke è il sindaco di ⟦Darkshire=Borgoscuro⟧, nel cuore di ⟦Duskwood=Boscovespro⟧. Non allontanarti dalle strade.", "Sembri venire da lontano, {class}. Che affari ti portano qui a ⟦Darkshire=Borgoscuro⟧?", "Grazie per aver affrontato il lungo viaggio fin qui. Questa è davvero un'informazione importante.", 0x74e46a13, 0xbe30acba, 0x0448bdaa, 0x1745350a, 0x089c2d62, "....." },
  [146] = { "Messaggero per ⟦Darkshire=Borgoscuro⟧", "Torna dal magistrato Solomon con la lettera di risposta di lord Ebonlocke.", "Se non conoscessi di persona il magistrato Solomon, direi che è impazzito. Mandare la Night Watch a ⟦Lakeshire=Borgolago⟧ perché ⟦Stormwind=Roccavento⟧ rifiuta di aiutarlo? La Night Watch è nata proprio perché ⟦Stormwind=Roccavento⟧ ci ha abbandonati quando questa magia immonda si è infiltrata nella terra. Se mandassi la mia Night Watch, questa città sarebbe travolta dal male prima ancora che le guardie raggiungessero il limitare della foresta.\n\nPorta questa lettera di risposta al tuo superiore a ⟦Lakeshire=Borgolago⟧.", "Ah, bentornato, messaggero. Devo informare il maresciallo che la Night Watch è in marcia da ⟦Darkshire=Borgoscuro⟧?", "Per la Luce! L'esercito di ⟦Stormwind=Roccavento⟧ si è ritirato dalle ⟦Westfall=Marche Occidentali⟧. E la Guardia non protegge più ⟦Darkshire=Borgoscuro⟧? C'è sotto un tradimento. Come può essere?\n\nOh, dimenticavo di ricompensarti per il tuo servizio, {class}. Ecco qualche moneta. Ora scusami. Qualcosa non va a ⟦Stormwind=Roccavento⟧ e devo andare a fondo della faccenda.", 0x74e46a13, 0x83daf12d, 0x98c1d172, 0x465827c6, 0x3452ae00, "....." },
  [147] = { "Caccia all'uomo", "Trova e uccidi «il Collezionista», poi torna dal maresciallo Dughan con l'⟦The Collector's Ring=Anello del Collezionista⟧.", "Se il «Collezionista» prende l'oro dalle nostre miniere, allora sta derubando il regno! Consegna il Collezionista alla giustizia e portami l'anello citato nel programma dei ritiri che mi hai dato. Potrebbe dirci per chi lavora il Collezionista...\n\nQuel programma dice che il Collezionista si nasconde al ⟦Brackwell Pumpkin Patch=Campo di Zucche dei Pozzonero⟧. Dovresti cercarlo lì.", "Hai trovato il Collezionista? Hai scoperto per chi lavora?", "L'hai trovato? Ben fatto, {name}. Non verrà più a «collezionare» nelle miniere di Elwynn!\n\nE questo anello che hai trovato è interessante... è un anello di appartenenza alla vecchia Stonemason's Guild di ⟦Stormwind=Roccavento⟧. Perché un ladruncolo dovrebbe avere l'anello di una gilda di artigiani, e perché i ladri Defias riscuotono denaro dalle nostre miniere?\n\nDomande difficili. Spero che un giorno avremo delle risposte.", 0x3fd32b4a, 0xaffbf97d, 0xcaee2d0b, 0x03263e82, 0xe881e64e, "....." },
  [148] = { "Provviste da ⟦Darkshire=Borgoscuro⟧", "Parla con Madame Eva.", "Oh, che deve fare un povero vecchio? Mi servono delle provviste da ⟦Darkshire=Borgoscuro⟧, ma il villaggio è così lontano e io sono così vecchio e debole... non arriverei mai fin là.\n\nPuoi andare a ⟦Darkshire=Borgoscuro⟧ e riportarmi del ⟦Ghost Hair Thread=Filo di Capelli Spettrali⟧? Puoi averlo da Madame Eva, a casa sua sulla piazza di ⟦Darkshire=Borgoscuro⟧.", nil, "Ah, è il ⟦Ghost Hair Thread=Filo di Capelli Spettrali⟧ che ti serve, vero? Temo di non averne in magazzino, ma posso fartene un po'... se riesci a procurarmi i capelli spettrali.", 0x3942c9e4, 0xe153bd5f, 0xf32e36c4, nil, 0xd45d9df9, "...m." },
  [149] = { "⟦Ghost Hair Thread=Filo di Capelli Spettrali⟧", "Porta il ⟦Spectral Comb=Pettine Spettrale⟧ a Blind Mary.", "C'è uno spirito povero e triste, Blind Mary, che infesta una vecchia fattoria sulle colline a sud di ⟦Darkshire=Borgoscuro⟧.\n\nEcco, prendi questo ⟦Spectral Comb=Pettine Spettrale⟧ e chiedi a Blind Mary di pettinarsi i capelli. Poi riportami il pettine e ne ricaverò i capelli spettrali che mi servono per il filo.\n\nE fa' attenzione, perché ora vicino a quella casa si annidano cose oscure...", "<Singhiozza> Oh, ti prego, non guardarmi! Mi sono strappata questi occhi con le mie mani, ma sento ancora il tuo sguardo!\n\nSono orrenda! Orrenda! Ti prego, guarda altrove!!", "Cos'è questo? Un pettine? È bellissimo! E scivola tra i miei capelli come se non fossero l'orrore rigido e stopposo che sono.\n\nOh, se solo avessi uno specchio...", 0xe3bdde6f, 0x528815c6, 0x616f9a53, 0xe0b4c1fb, 0x47317f65, "....." },
  [150] = { "Murloc bracconieri", "Porta 8 Murloc Fin al mastro portuale Baren a ⟦Lakeshire=Borgolago⟧.", "I murloc stanno diventando un problema. Gruppi sempre più numerosi di uomini-pesce gettano l'ancora lungo le rive del ⟦Lake Everstill=Lago Placido⟧ e pescano a più non posso! Dobbiamo levarceli di torno prima che si mangino tutto il pesce del lago!\n\nDai la caccia ai murloc! Portami otto delle loro pinne e forse avrò qualcosa per te...", "Hai quelle pinne? Sbrigati, dobbiamo cacciare quei murloc dal lago!", "Ben fatto, {name}. Spero che quei murloc non ti abbiano dato troppi problemi.\n\nÈ strano vederli così lontani dal mare. Mi chiedo se siano qui perché stanno fuggendo da qualcosa...", 0x812e47f7, 0xbe5f0814, 0xc927bcbc, 0xabeb396e, 0x9a51f356, "....." },
  [151] = { "La povera vecchia Blanchy", "Verna Furlbrow, nelle ⟦Westfall=Marche Occidentali⟧, vuole che tu le porti 8 Handful of Oats.", "Povera vecchia Blanchy! È così stanca dopo tutto il lavoro che le abbiamo fatto fare. Le ho dato da mangiare prima di lasciare la fattoria, ma non ci aspettavamo che il carro si rompesse. Se potessi portarle qualche manciata d'avena dai campi, te ne sarei grata.\n\nScommetto che ne troverai un po' attorno a tutte le fattorie delle ⟦Westfall=Marche Occidentali⟧, se riesci a stare alla larga da quelle macchine orribili che hanno preso il sopravvento. Ci sono diverse fattorie a sud-ovest di qui.", "La vecchia Blanchy è allo stremo. Hai per caso trovato un po' d'avena per lei?", "Grazie infinite, {name}! La povera vecchia Blanchy sarà così felice!", 0x9bfac4dc, 0x7daa1244, 0x1fc2eef2, 0xfc0646d0, 0x51216ba8, "....." },
  [152] = { "La costa non è sicura", "Uccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e torna dal capitano Grayson al ⟦Westfall Lighthouse=Faro delle Marche Occidentali⟧.", "Avrai sicuramente notato tutti i relitti lungo la costa. Il ⟦The Great Sea=Grande Mare⟧ è davvero insidioso. La costa delle ⟦Westfall=Marche Occidentali⟧ deve restare sgombra, così che i marinai che approdano sulle nostre spiagge siano al sicuro. Ma i murloc sono un problema.\n\nUccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e mi assicurerò che tu venga ricompensat<o/a>.", "Uccidi 7 Tidehunter, 7 Warrior, 7 Oracle e 7 Coastrunner e mi assicurerò che tu venga ricompensat<o/a>.", "Ben fatto, {name}. Hai un vero talento per il combattimento. Grazie a te la costa delle ⟦Westfall=Marche Occidentali⟧ è un posto più sicuro.", 0xcdad2308, 0x88ca96a9, 0xbc9bf3cb, 0xf2f2deb7, 0x27f90f2d, "....." },
  [153] = { "Bandane di cuoio rosso", "Porta 15 Red Leather Bandana all'esploratore Galiaan, a ⟦Sentinel Hill=Guardiacolle⟧.", "Il fronte dei Defias si sposta di continuo. Seguo i loro movimenti da parecchio tempo ormai. Tra l'altro, ho accertato che molti membri della banda si possono riconoscere dalle Red Leather Bandana che indossano.\n\nPortami 15 di queste bandane e avrai la tua ricompensa.", "Portami 15 bandane di cuoio rosso e ti pagherò bene.", "Bel lavoro, {race}. Accetta uno di questi oggetti come compenso per tutto il tuo duro lavoro.", 0x91de9f29, 0x15be8c76, 0xdc4ad0de, 0xca1a09c5, 0x9ab69279, "....." },
  [154] = { "La restituzione del pettine", "Riporta il ⟦Ghost Hair Comb=Pettine con Capelli Spettrali⟧ a Madame Eva, a ⟦Darkshire=Borgoscuro⟧.", "NO!!!!!\n\nPrendilo, porta via da me questo pettine!\n\nSono un mostro, e nessuno mi troverà mai più bella!", "Sento che hai visto Blind Mary. Hai il mio pettine...?", "Con questo posso fare un rocchetto di ⟦Ghost Hair Thread=Filo di Capelli Spettrali⟧, e mi avanza qualche ciocca. Ecco qualche moneta per le ciocche in più.", 0x67d027b2, 0x183f2e90, 0x78e5d132, 0x390dbc0c, 0x307b8fa2, "....." },
  [155] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Scorta il Defias Traitor fino al nascondiglio segreto della ⟦Defias Brotherhood=Fratellanza dei Defias⟧. Quando il Defias Traitor ti avrà mostrato dove si nascondono VanCleef e i suoi uomini, torna da Gryan Stoutmantle con l'informazione.", "Così Stoutmantle manda un {race} mingherlino come te a proteggermi? Mi accontenterò. Meglio che ti porti anche qualche amico.\n\nConosci l'accordo, vero? Tu mi copri le spalle e io ti porto al nascondiglio dei Defias. Ma faresti meglio a starmi vicino. La banda dei Defias ora vuole la mia testa. Se mi vedono con te, cercheranno di uccidermi.\n\nFammi sapere quando tu e gli amici che riesci a radunare sarete pronti a partire.", "Che affari hai con me? Sono un uomo molto impegnato...", "Eccellente, {name}! Ora che sappiamo dove si nasconde, VanCleef è praticamente nostro.", 0x2a2224c0, 0x3c4fa4f6, 0xf3c6ce7f, 0xa49dc7ac, 0xd5d9b9c8, "....." },
  [156] = { "La raccolta dei fiori marci", "Raccogli 8 Fiore Marcio e portali all'oste Smitts, a ⟦Darkshire=Borgoscuro⟧.", "Se mi porti qualche fiore marcio, posso prepararti una partita di distillato di zombi.\n\nI fiori marci crescono in posti strani. In particolare, ho sentito dire che si trovano dentro i teschi degli Skeletal Horror e degli Skeletal Fiend... non che io mi sia mai avvicinato abbastanza da guardare!\n\nIl ⟦Raven Hill Cemetery=Cimitero di Collecorvo⟧ e il Cimitero Parcosereno brulicano di quegli scheletri. Già che cerchi i fiori marci, tanto vale che te ne sbarazzi. La città di ⟦Darkshire=Borgoscuro⟧ te ne sarebbe grata.", "Ciao, {name}. Hai già quei fiori marci per me?", "Bene, hai preso i fiori marci. E dirò ad Althea Ebonlocke dei Guardiani della Notte che hai ucciso degli scheletri.\n\nTenere al sicuro la gente di ⟦Darkshire=Borgoscuro⟧ è un fardello pesante per i Guardiani della Notte, e sapere che altri aiutano ad arginare l'ondata di mostri a ⟦Duskwood=Boscovespro⟧ è davvero una buona notizia.", 0x4964f847, 0x04339e2b, 0x9f150c59, 0xd77731e5, 0x03dd4941, "....." },
  [157] = { "La consegna del filo", "Porta il ⟦Ghost Hair Thread=Filo di Capelli Spettrali⟧ ad Abercrombie, nella sua baracca a nord del ⟦Raven Hill Cemetery=Cimitero di Collecorvo⟧.", "Ecco il tuo filo, {name}. Ha mille usi, dal vincolare gli spiriti maligni al cucire la vita negli oggetti inanimati.", "Devo tendere il ⟦Ghost Hair Thread=Filo di Capelli Spettrali⟧ lungo la porta e le finestre per tenere lontani gli spiriti indesiderati. Me l'hai portato?", "Delizioso! Andrà benissimo...\n\nEcco, <buon/buona> {name}, prendi questo come compenso per la tua azione onorevole.", 0x80a7141b, 0x2aed716b, 0x68798fe6, 0x9910144d, 0xd4c4f3eb, "....." },
  [158] = { "Distillato di zombi", "Parla con l'oste Smitts.", "Mi serve una bottiglia di un certo liquore: il Distillato di Zombi. L'oste Smitts, alla taverna Scarlet Raven di ⟦Darkshire=Borgoscuro⟧, dovrebbe averne un po'.\n\nE sbrigati, per favore, {name}. Queste notti si fanno fredde, e ho bisogno di quel liquore per rimettermi il fuoco nelle vene!", nil, "Ti serve del Distillato di Zombi, eh? Mmm... è roba forte: di solito non me lo chiede nessuno.", 0xbabab408, 0xefdb9d5e, 0xbb7de0a2, nil, 0xee62c9dd, "...m." },
  [159] = { "La consegna del distillato", "Porta il Distillato di Zombi ad Abercrombie, alla sua baracca.", "Ecco il tuo Distillato di Zombi...\n\n...e fa' attenzione con questa roba. È abbastanza forte da resuscitare i morti!", "Mi serve quel Distillato di Zombi per scaldarmi in queste notti fredde e buie. Me l'hai portato?", "Mille grazie, {name}. Scaldi il cuore di un vecchio con la tua stupid... cioè... con la tua gentilezza!\n\nEcco a te, amico. Prendi questo come segno della mia gratitudine.", 0x820ab7e9, 0x7ac1d84f, 0xb9ae7652, 0xbae73c5a, 0xf27a5a51, "....." },
  [160] = { "Un biglietto per il sindaco", "Porta la ⟦Letter to Ello=Lettera per Ello⟧ di Abercrombie a Ello Ebonlocke, sindaco di ⟦Darkshire=Borgoscuro⟧.", "Porta questo biglietto a Ello Ebonlocke, il sindaco di ⟦Darkshire=Borgoscuro⟧.\n\nLui e io siamo vecchi amici... e quando lo leggerà e scoprirà cosa hai fatto per me... sono sicuro che sarà felice quanto me! Ahahahah!", "Abercrombie...? Non conosco nessuno con quel nome. Dici di avere una lettera per me da questo tale Abercrombie?\n\nBe', allora dammela...", "<Ello guarda la lettera...>\n\nChe lingua è questa? Sembra antica... non riesco a leggerla.", 0xbf2ebcd6, 0x60a07e98, 0xf87484eb, 0xb6aabb3e, 0xa50301f2, "....." },
  [161] = { "Incombe una minaccia oscura", "L'ingegnere capo Hinderweir vuole che tu porti la polvere dall'odore strano ad Ashlan Stonesmirk, l'esperto di esplosivi a Dun Modr.", "Se i miei sospetti sono giusti, questa è una specie di polvere esplosiva. Deve analizzarla un esperto di esplosivi, così sapremo con cosa abbiamo a che fare. Ashlan Stonesmirk è stato assegnato al reggimento che sorveglia Dun Modr e il ⟦Thandol Span=Viadotto di Thandol⟧. Ho bisogno che tu intraprenda un viaggio difficile e pericoloso, {name}.\n\nAttraversa la ⟦Algaz Gate=Porta di Algaz⟧, segui la strada attraverso le ⟦Wetlands=Paludi Grigie⟧ e cerca Stonesmirk a Dun Modr. Da' retta al mio consiglio: resta sulle strade e non fermarti per nessun motivo!", "Hai detto qualcosa, <giovanotto/signorina>? Non sento un accidente, a parte il fischio nelle orecchie. Ehi, cos'è quella roba che hai lì?", "Ah, be', il vecchio Hinderweir fa bene a preoccuparsi.", 0x285fa090, 0x10adbf1b, 0xc80198ee, 0xbcaa84da, 0xdf7a71cc, ".....", nil, nil, nil, 0x60a6efdd, nil },
  [163] = { "⟦Raven Hill=Collecorvo⟧", "Scopri cosa infesta ⟦Raven Hill=Collecorvo⟧.", "Qualcosa non va a ⟦Raven Hill=Collecorvo⟧, {name}. Calor giura che qualcuno, o qualcosa, infesta gli edifici laggiù. Per due notti di fila ha visto delle ombre muoversi, e la notte prima di quelle dice di aver visto una luce a una delle finestre.\n\nSe, come dici, ti sta a cuore la sicurezza di ⟦Duskwood=Boscovespro⟧, scopri quale mostro infesta ⟦Raven Hill=Collecorvo⟧.", nil, "No! Ti prego, non uccidermi! Sono solo io... Jitters!! Sono dappertutto... non riesco a sfuggirgli! Mostri a ⟦Raven Hill=Collecorvo⟧? N-n-n-no... impossibile. Solo l'innocuo Jitters.", 0xcfccf464, 0x22ae4d0b, 0x2349862f, nil, 0x6183fbd0, "...m." },
  [164] = { "Consegne per Sven", "Consegna i rifornimenti a Sven.", "Conosci Sven? Ecco un uomo che compie l'opera della Luce! Lui e i suoi seguaci hanno un accampamento al margine nord-occidentale di ⟦Duskwood=Boscovespro⟧.\n\nPurtroppo sono così pochi che non possono nemmeno risparmiare un uomo per venire a prendere i rifornimenti in città. Gli porteresti tu queste provviste?", "Hai l'aria robusta, {class}. Sei <venuto/venuta> a unirti alla nostra lotta?", "Queste provviste saranno utilissime. L'aiuto della famiglia Carevin è sempre gradito. Ecco una piccola cosa per il disturbo.", 0x47ecd948, 0x353999cb, 0xebb9fbaa, 0xe4428de9, 0xa502323b, "....." },
  [165] = { "L'eremita", "Va' a vedere come sta il vecchio che vive nella baracca vicino al cimitero di ⟦Raven Hill=Collecorvo⟧.", "C'era un vecchio che veniva in città piuttosto spesso a comprare provviste, ma è parecchio tempo che non lo vedo. Se ricordo bene, vive in una baracca che domina il cimitero di ⟦Raven Hill=Collecorvo⟧. Forse dovresti andare a vedere se c'è qualcosa che non va.", nil, "Elaine Carevin? Eheh, oh sì... certo, i Carevin.\n\nNo, non c'è niente che non va, ma per me ora è difficile andare in città. Le strade sono pericolose e non sto ringiovanendo. Forse potresti fare qualche favore a un vecchio?", 0x424f8542, 0x6e8400ee, 0x94338923, nil, 0x8022318a, "...m." },
  [166] = { "La ⟦Defias Brotherhood=Fratellanza dei Defias⟧", "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.", "Ti resta un ultimo compito. Edwin VanCleef deve essere assassinato. Anche se mi addolora condannare a morte un uomo, è per il bene superiore della gente delle ⟦Westfall=Marche Occidentali⟧ che VanCleef venga tolto di mezzo una volta per tutte. Quando avrai finito, portami la testa di quel furfante.", "Come procede la caccia a Edwin VanCleef?", "{name}, il tuo coraggio è straordinario. La ⟦People's Militia=Milizia del Popolo⟧ ti ringrazia per il servizio reso alla gente delle ⟦Westfall=Marche Occidentali⟧. Con la morte di VanCleef comincia la fine della ⟦Defias Brotherhood=Fratellanza dei Defias⟧. Speriamo che presto la pace torni ad allietare le pianure di questa bella terra.\n\nTi saluto, <signore/signora>!", 0x2a2224c0, 0xaf5696f5, 0xeeda81af, 0xb9d86261, 0x9f2be902, ".....", nil, nil, nil, nil, 0xf7825732 },
  [167] = { "Oh, fratello...", "Porta il distintivo della ⟦Explorers' League=Lega degli Esploratori⟧ del caposquadra Thistlenettle a Wilder Thistlenettle a ⟦Stormwind=Roccavento⟧.", "Eravamo in fondo a una vasta miniera nelle ⟦Westfall=Marche Occidentali⟧, nascosta sotto un granaio a ⟦Moonbrook=Rivoluna⟧. Non ho idea da dove siano sbucati quei ladri puzzolenti. Comunque, la galleria della miniera ci è crollata addosso. Io sono uscito, ma gli altri... beh... degli altri non si è saputo più niente.\n\nTu sembri uno che là dentro potrebbe avere più fortuna. Se potessi cercare mio fratello, te ne sarei grato. Portava sempre con sé il suo distintivo della ⟦Explorers' League=Lega degli Esploratori⟧. Se non riesci a trovare lui, almeno quel distintivo mi darebbe un po' di pace.", "Hai trovato qualche traccia di mio fratello? C'è ancora speranza, dopo tutto questo tempo?", "Avevo ragione a sospettarlo. Il mio povero fratello.... Beh, grazie per aver dato una conclusione a questo mistero, anche se è una conclusione triste.", 0xc4d380c0, 0xe0579023, 0xa169aa0b, 0x9c2bb4b4, 0x9c87936b, "....." },
  [168] = { "Raccogliere i ricordi", "Recupera 4 Miners' Union Card e riportale a Wilder Thistlenettle a ⟦Stormwind=Roccavento⟧.", "Molti dei miei amici sono morti quel giorno terribile, quando la galleria della miniera è crollata. Se le tue avventure dovessero portarti in quell'ala della miniera di ⟦Moonbrook=Rivoluna⟧, ti prego, cerca qualunque segno che possa identificarli. Se trovi qualcuna delle loro Miners' Union Card, riportamela e farò in modo che le loro famiglie trovino un po' di pace dopo questo orribile incidente.", "Sei riuscit<o/a> a recuperare qualcuna delle Miners' Union Card dei miei vecchi compagni di lavoro?", "Grazie per averle raccolte, {name}. I tuoi sforzi aiuteranno a dare pace ai morti dopo questa tragedia. Mi assicurerò che le famiglie vengano avvisate.", 0x2c56586a, 0xe0ab3ca6, 0x610a9b53, 0x358b3d1b, 0x320f3ed3, "....." },
  [169] = { "RICERCATO: Gath'Ilzogg", "Uccidi Gath'Ilzogg e porta la sua testa al magistrato Solomon a ⟦Lakeshire=Borgolago⟧ per riscuotere la ricompensa.", "Ricercato! Gath'Ilzogg, capo degli attacchi ⟦Blackrock=Roccianera⟧ contro il ⟦Stonewatch Keep=Mastio di Guardamasso⟧ e delle razzie contro la municipalità di ⟦Lakeshire=Borgolago⟧.\n\nGath'Ilzogg è estremamente pericoloso. Pare che sia asserragliato nel mastio appena conquistato, a tramare nuovi crimini del clan ⟦Blackrock=Roccianera⟧ contro l'umanità. L'infestazione di orchi va stroncata a ogni costo. Una generosa ricompensa andrà all'anima coraggiosa che consegnerà la testa di Gath'Ilzogg al magistrato Solomon.", "Che cos'hai lì, {race}?", "Lavoro fantastico, {name}! Gath'Ilzogg guidava in battaglia quei bruti, uccidendo molti umani innocenti. Giustizia è fatta. Questo è il primo passo per riconquistare il mastio per il regno di ⟦Stormwind=Roccavento⟧!", 0x1fa3cb70, 0xdb0eb6e4, 0x8a4b873e, 0x46dc827d, 0x5c3ce0be, "....." },
  [170] = { "Una nuova minaccia", "Balir Frosthammer vuole che tu uccida 6 Rockjaw Trogg e 6 Burly Rockjaw Trogg.", "Spero che tu sia qui per darci una mano, {class}. Dopo l'ultimo attacco dei trogg, ci serve tutto l'aiuto possibile.\n\nHo sentito che quei maledetti spuntano dappertutto, e pare che la ⟦Coldridge Valley=Valle Crestafredda⟧ non faccia eccezione. Li hanno avvistati su tutte le colline a sud-est e vicino al lago ghiacciato.\n\nE non è tutto: solo poche notti fa hanno attaccato e travolto il nostro accampamento a ovest!\n\nSiamo a corto di uomini qui, <ragazzo/ragazza>, e ci servono braccia forti per ricacciare indietro i trogg.", "Ostinati, quei piccoli bastardi, eh?", "Se i problemi che abbiamo avuto qui sono un segno di ciò che succede altrove nelle nostre terre, per la barba di Magni, ci aspettano dei guai! Posso solo sperare che il re e il Senato stiano prendendo provvedimenti contro la minaccia dei trogg.", 0xea33a69d, 0x6b72f6c0, 0xa8fc7352, 0x37fa0bba, 0x09e25d88, ".....", nil, nil, 0x6c85e362, nil, nil },
  [172] = { nil, "Usa il ⟦Orcish Orphan Whistle=Fischietto dell'Orfano Orco⟧ per parlare con il bambino di cui ti occuperai durante la Children's Week.", "Sei dispost<o/a> ad aiutarci qui all'orfanotrofio? Che tu sia benedett<o/a>, amico; il tuo aiuto durante la Children's Week sarà prezioso.\n\nPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non oltre la Children's Week stessa. Quando lo userai, potrai parlare con il bambino di cui hai accettato di occuparti. Usandolo di nuovo, il bambino se ne andrà.\n\nForza, {name}: usa il fischietto e conosci il tuo protetto! Di certo il bambino non vede l'ora di conoscerti.", nil, "Zug zug! Mi chiamo Grunth, e immagino che sarai tu a occuparti di me? Fai l'avventurier<o/a>, come facevano la mia mamma e il mio papà. La direttrice dice che sono morti con onore in battaglia. Sono felice di conoscerti.\n\nSpero che faremo un sacco di cose insieme. Ci sono alcune cose che vorrei fare, e la direttrice dice che durante questa settimana sarai per me come <un/una> <fratello/sorella> maggiore. Mi piacerebbe tantissimo.", 0x70336621, 0x77f9f0a9, 0x427476d3, nil, 0x06358008, "e..m.", nil, nil, nil, nil, 0xd6c28757 },
  [173] = { "Worgen nei boschi", "Uccidi 6 worgen Nightbane Shadow Weaver per Calor, a ⟦Darkshire=Borgoscuro⟧.", "L'oscurità sembra attratta inesorabilmente da ⟦Duskwood=Boscovespro⟧. La missione di mastro Carevin è scacciare il male e l'eresia. È grazie ai nostri sforzi che la gente di ⟦Darkshire=Borgoscuro⟧ resta al sicuro.\n\nTi credi degn<o/a> di unirti a noi?\n\nUn tempo la pensavo come te. Deluso dall'indolenza dei Guardiani, mi sono unito a mastro Carevin. Se vuoi dimostrare il tuo valore, non sarà con le parole.\n\nMetti alla prova le tue abilità contro i worgen Nightbane Shadow Weaver nel ⟦Brightwood Grove=Bosco Legnoradioso⟧ (radioso, ah!) e nel Rotting Orchard.", "{name}, come procede la caccia?", "Notevole, {name}. Sembra che tu sia abbastanza capace da cavartela da sol<o/a>. Forse si potrebbe trovare una sfida più adatta a qualcuno con le tue capacità.\n\nEppure è curioso... I worgen sembrano essere comparsi dal nulla. Ma d'altronde, con tutte le altre strane creature che hanno varcato i nostri confini, immagino sia solo una delle tante preoccupazioni.", 0x47dbaa77, 0xdbe54601, 0x0c5c5fbf, 0xc089edc0, 0x3d143d4d, "....." },
  [174] = { "Guarda le stelle", "Viktori Prism'Antras di ⟦Darkshire=Borgoscuro⟧ vuole che tu gli porti un tubo di bronzo.", "Il mio amico gnomo, Cog, ha promesso di aiutarmi a costruire un congegno che mi permetterà di scrutare le stelle. Esiste una verità, al di là della magia, che può spiegare la strana trasformazione della foresta.\n\nPortami un tubo di bronzo fatto da un ingegnere esperto. Secondo il progetto di Cog, è il primo passo.", "Hai già trovato un ingegnere esperto che faccia un tubo di bronzo?", "È perfetto, {name}. Il primo passo è compiuto!", 0xb0b2f53c, 0x95b70dc4, 0x93fe2947, 0x7340ad08, 0xfdd8d8da, "....." },
  [175] = { "Guarda le stelle", "Trova Mary e convincila a cedere una superficie riflettente per il progetto di Viktori.", "Secondo il progetto di Cog, ora mi serve un modo per riflettere la luce. Ricordo una donna di nome Mary, diventata famosa da queste parti perché portava sempre con sé uno specchio. Forse puoi rintracciare Mary e vedere se ci presterebbe una superficie riflettente per questo progetto? Credo che un tempo vivesse nel sud di ⟦Duskwood=Boscovespro⟧...", nil, "Ma certo, un tempo avevo uno specchio.", 0xb0b2f53c, 0x5c290da2, 0xbbc7b806, nil, 0xf80d3335, "...m." },
  [176] = { "RICERCATO: «Hogger»", "Uccidi lo gnoll Hogger e porta il suo ⟦Huge Gnoll Claw=Artiglio di Gnoll Smisurato⟧ al maresciallo Dughan.", "Ricercato: Hogger\n\nUn enorme gnoll, Hogger, si aggira nei boschi a sud-ovest di Elwynn. Ha avuto la meglio su ogni tentativo di catturarlo.\n\nL'esercito di ⟦Stormwind=Roccavento⟧ ha posto una generosa taglia sullo gnoll. Per ottenere la ricompensa, i cacciatori di taglie devono portare la prova della morte di Hogger al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.", "Sì, Hogger è stato una vera spina nel fianco per me e i miei uomini. Hai qualcosa da riferire su quella bestia?", "Ah! Ben fatto! Cominciavo a pensare che nessuno sarebbe riuscito ad abbattere quel mostro!\n\nEcco a te, {name}. E grazie: quello gnoll mi stava facendo venire un mal di testa grande quanto i ⟦Blackrock Spire=Bastioni di Roccianera⟧!", 0x9dcd29e7, 0x318a3a3b, 0xab83e5ae, 0xadee0c74, 0xc7de9815, "....." },
  [177] = { "Guarda le stelle", "Recupera dall'Insane Ghoul lo ⟦Mary's Looking Glass=Specchio di Mary⟧, appartenuto a Blind Mary, e consegnalo a Viktori, a ⟦Darkshire=Borgoscuro⟧.", "Lo specchio era uno dei miei tesori più preziosi, finché... non è successo il fatto. Dopo l'ho buttato dietro il fienile. Laggiù si aggirava un Insane Ghoul. Forse l'ha raccolto lui. Si dice che quella bestia diabolica si nasconda nel ⟦Tranquil Gardens Cemetery=Cimitero Parcosereno⟧.", "Ho mostrato a Cog l'inizio della nostra macchina per osservare le stelle. Ne è rimasto colpito. Hai per caso trovato qualcosa che rifletta la luce?", "Magnifico! Andrà benissimo. Mille grazie!", 0xb0b2f53c, 0x7a6c1b09, 0xc5f77146, 0x22ff6d7e, 0x34eef752, "....." },
  [178] = { "Il recupero di Theocritus", "Porta il ⟦Faded Shadowhide Pendant=Pendente dei Mantombroso Sbiadito⟧ a Theocritus il Mago.", "<Senti una voce disincarnata...>\n\nNon allarmarti. Sono Theocritus, sommo mago della Torre di Azora nella ⟦Elwynn Forest=Foresta di Elwynn⟧. Il pendente che stringi è un mezzo di comunicazione tra gli gnoll Mantombroso e il loro padrone, Morganth.\n\nDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi pendenti. Se senti questo messaggio, il mio incantesimo ha avuto successo.\n\nPortami questo pendente e ti ricompenserò per il servizio.", "Dici che ti ho parlato attraverso un pendente? Mmm... dammelo, così posso studiarlo.", "Hai la mia gratitudine, {name}. Ho inviato quel messaggio ai pendenti dei Mantombroso settimane fa e lo credevo un fallimento. Ma pare che l'incantesimo abbia raggiunto almeno alcuni pendenti, con un notevole ritardo.\n\nCol tempo spero di imparare a inviare un attacco attraverso i pendenti, per immobilizzare gli gnoll Mantombroso che li indossano.\n\nMa prima che sia possibile, temo che serviranno molte altre ricerche.", 0xd1b6915b, 0xe9f541db, 0x7788c2a9, 0xdac36d0d, 0xd28bd097, "....." },
  [179] = { "Equipaggiamento nanico", "Sten Stoutarm vuole 8 pezzi di ⟦Tough Wolf Meat=Carne Tigliosa di Lupo⟧.", "Che abbiamo qui? Hai l'aria di chi avrebbe bisogno di qualcosa per tenersi al caldo le mani, eh?\n\nTi dico io cosa ci vorrebbe: un bel paio di guanti caldi. E, anima generosa come sono, sarei più che felice di procurartene un paio adatto. A una condizione, però.\n\nDevi andare a prendermi un po' di carne di lupo. Bell'accordo, eh? Tu mi porti la carne di lupo e io mi assicuro che il gelo non ti porti via nemmeno un dito. Allora, che ne dici?", "I lupi ti danno qualche grattacapo? Faresti bene a stare alla larga da zanne, artigli e altre parti appuntite, eh?", "Ah! Splendido. La carne di lupo andrà benissimo. Oh, non preoccuparti, {name}, non dimentico la mia parte dell'accordo. Ecco, uno di questi dovrebbe andarti bene.", 0x26b28f66, 0x458fcb05, 0x26a8c43e, 0x4ab5a842, 0x3fbf9365, "....." },
  [180] = { "RICERCATO: il tenente Fangore", "Uccidi il tenente Fangore e torna dal magistrato Solomon a ⟦Lakeshire=Borgolago⟧ con la sua zampa.", "Ricercato: tenente Fangore\n\nNoto capo del clan gnoll dei Mantombroso, al servizio di Morganth, nemico della municipalità e del regno. Per mandato del magistrato Solomon, questo vile traditore di ⟦Stormwind=Roccavento⟧ è ricercato morto. Mostra la sua zampa al magistrato come prova della sua morte.", "Quali notizie porti davanti alla Corte?", "Quindi il malvagio tenente Fangore è morto? Che quella creatura immonda vada al diavolo. Sei molto <coraggioso/coraggiosa>, {class}. La municipalità di ⟦Lakeshire=Borgolago⟧ ti ringrazia per il tuo aiuto.", 0x8dd050b7, 0xeaf3268f, 0xeb39ff35, 0xb6305447, 0x338741ad, "....." },
  [181] = { "Guarda le stelle", "Trova Zzarc'Vul nel tumulo degli ogre a sud di ⟦Duskwood=Boscovespro⟧ e porta il suo monocolo a Viktori, a ⟦Darkshire=Borgoscuro⟧.", "Ora manca solo un ultimo pezzo per completare questo congegno. Il progetto di Cog richiede una lente di qualche tipo. L'unica lente che conosco abbastanza grande sarà molto difficile da procurarsi.\n\nC'è un ogre di nome Zzarc'Vul che vive nel tumulo nel sud di ⟦Duskwood=Boscovespro⟧. Se ci riesci, portami il suo monocolo e lo useremo come lente!", "Sei riuscit<o/a> a convincere Zzarc'Vul a prestarci il suo monocolo per il nostro esperimento?", "Finalmente! Il congegno per osservare le stelle è completo! Grazie, {name}. Ora posso continuare le mie ricerche...", 0xb0b2f53c, 0x7425bc28, 0x1a69cde0, 0x9e98b22d, 0x548bc1fc, "....." },
  [182] = { "La caverna dei troll", "Grelin Whitebeard vuole che tu uccida 14 Frostmane Troll Whelp.", "Mio fratello Senir e io siamo stati mandati in zone diverse di Dun Morogh per indagare sulla minaccia dei troll. Il Senato ha già il suo da fare con i trogg, quindi non ha bisogno di altre seccature.\n\nDa quel che ho visto, i troll non sono ben insediati qui nella ⟦Coldridge Valley=Valle Crestafredda⟧: stanno soprattutto nella caverna a sud. Direi che l'esercito non servirà. Bastano poche braccia forti.\n\nTi andrebbe di dare una mano in questa impresa? Ho l'autorità per offrirti un compenso per il tuo aiuto.", "Da quel che ho scoperto, questi troll vengono dal clan dei ⟦Frostmane=Mantogelido⟧. Temo di non sapere molto altro su di loro che possa esserti utile, {name}.", "Argh! Quei maledetti troll, che la Luce li fulmini!\n\n<Fa qualche respiro e sembra calmarsi... un po'.>\n\nUn gruppo di loro è arrivato di notte e mi ha rubato il diario! Lo sapevo che non dovevo fidarmi di quel buono a nulla di un appr...", 0xf6bcfb62, 0x0fe3fd39, 0x4d645eea, 0x76fb86d2, 0xfe9f5262, "....." },
  [183] = { "Il cacciatore di cinghiali", "Talin Keeneye vorrebbe che tu uccidessi 12 Small Crag Boar.", "Niente di meglio di una giornata di caccia al cinghiale, eh?\n\nAnche se qui nella ⟦Coldridge Valley=Valle Crestafredda⟧ ci sono così tanti cinghiali che quasi non c'è più gusto. Non serve nemmeno provocarli: sono già tutti arrabbiati e pronti a caricare da soli. Anzi, ultimamente ce ne sono così tanti in zona che è diventato pericoloso fare la mia caccia quotidiana.\n\nPer farla breve, se potessi aiutarmi a uccidere un po' di cinghiali, te ne sarei grato.", "Come va la caccia?", "Eccellente! Ora posso tornare alla mia... rilassante... caccia. Grazie, {name}.", 0xd760ac9a, 0xd69ca3ad, 0xc4ab0b64, 0xe02b27bb, 0xc985f25a, "....." },
  [184] = { "⟦Furlbrow's Deed=Atto dei Ciglioarcuato⟧", "Porta l'⟦Furlbrow's Deed=Atto dei Ciglioarcuato⟧ al contadino Furlbrow.", "Questo è l'atto di proprietà di una distesa di terreni agricoli nelle ⟦Westfall=Marche Occidentali⟧. È firmato da un certo Theodore Furlbrow e controfirmato da sua moglie, Verna. Sul retro dell'atto ci sono alcune parole scarabocchiate in fretta:\n\n\"Abbiamo fatto pressione su Furlbrow e ci siamo presi l'atto. Abbiamo pensato che potesse tornarti utile se volessi falsificarne uno per un posto tutto tuo.\n\nI Furlbrow non ci daranno fastidi. L'ultima volta che li ho visti stavano lasciando le ⟦Westfall=Marche Occidentali⟧, bloccati con un carro rotto.\"\n\nPensi che i Furlbrow potrebbero rivolere il loro atto...", "Hai l'atto della mia fattoria?? Che bella notizia! Dei furfanti me l'hanno rubato giorni fa... pensavo di averlo perso per sempre!\n\nTi prego, dammelo. Stiamo lasciando le ⟦Westfall=Marche Occidentali⟧ e non torneremo tanto presto, ma se mai tornassimo ci serviranno quelle carte...", "Grazie mille, {name}! Come dicevo, da queste parti non c'è più posto per la gente onesta, ma se le cose miglioreranno, questo atto ci permetterà di riprenderci la nostra terra.\n\nNon ho molto da offrirti, ma ecco, prendi questo.", 0xfdbbe6bb, 0x11feda88, 0x57a4e970, 0x5eec9a09, 0x4f2a8d57, "....." },
  [199] = { "Incombe una minaccia oscura", "Torna dall'ingegnere capo Hinderweir e mostragli l'indizio che hai scoperto.", "Prendi un campione della polvere dall'odore strano.", "Hai scoperto qualche indizio, {name}?", "Questa è una scoperta allarmante, a dir poco!", 0x285fa090, 0xf35c45fc, 0x6aeb4ed8, 0xf6db5556, 0x5a6f77c1, "....." },
  [214] = { "Bandane di seta rossa", "L'esploratrice Riell, alla torre di ⟦Sentinel Hill=Guardiacolle⟧, vuole che tu le porti 10 Red Silk Bandana.", "Non è un segreto che il segno distintivo della banda dei Defias siano le bandane rosse. Ma abbiamo scoperto che il tessuto di cui sono fatte indica il grado di chi le porta.\n\nDetto questo, voglio che elimini quanti più Defias di alto grado puoi. I membri di grado più alto si trovano senza dubbio nel nascondiglio segreto di VanCleef. Quando hai finito, portami 10 Red Silk Bandana come prova della loro morte e ti ricompenserò. Buona fortuna, {name}.", "Hai strappato la nostra terra alla banda dei Defias? Se è così, mostrami 10 Red Silk Bandana come prova.", "Ben fatto, {name}! A nome della ⟦People's Militia=Milizia del Popolo⟧ ti rendo onore per i tuoi sforzi. Presto restituiremo questa terra al popolo, con l'aiuto di anime coraggiose come te.", 0xe3536628, 0x16e9af40, 0xca668909, 0x9de63344, 0xb8efc2a9, "....." },
  [216] = { "Tra l'incudine e i Mantocardo", "Abbatti 12 Thistlefur Avenger e 12 Thistlefur Shaman: la maggior parte si trova a est della ⟦Zoram Strand=Spiaggia di Zoram⟧, nel ⟦Thistlefur Village=Villaggio dei Mantocardo⟧. Fatto questo, torna da Karang Amakkar all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, a ⟦Ashenvale=Valtetra⟧.", "I mezzorsi Mantocardo minacciano la nostra espansione! Il ⟦Thistlefur Village=Villaggio dei Mantocardo⟧, a est di qui, blocca la strada tra noi e l'⟦Splintertree Post=Avamposto di Troncorotto⟧. È un percorso che aggirerebbe il villaggio di Astranaar; senza di esso, diamo all'⟦Alliance=Alleanza⟧ una via d'espansione in più.\n\n{name}, non possiamo permettere... un buco nelle vie d'espansione!\n\nVa' al ⟦Thistlefur Village=Villaggio dei Mantocardo⟧ e sfoltisci i mezzorsi. Riceverai un compenso per questo compito, ma soprattutto farai il tuo dovere per l'⟦Horde=Orda⟧!", "Hai portato la battaglia ai Mantocardo? Con una via libera tra le nostre basi, le nostre possibilità di conquistare tutta ⟦Ashenvale=Valtetra⟧ aumentano enormemente.", "Ben fatto, {class}, ben fatto! Continuerò a mandare truppe a sfoltire i mezzorsi, ma almeno posso contare su un'altra via, libera dagli intralci dell'⟦Alliance=Alleanza⟧. La conquista di ⟦Ashenvale=Valtetra⟧ da parte dell'⟦Horde=Orda⟧ è ormai in pieno svolgimento!\n\nOggi ti sei guadagnat<o/a> la paga, <eroe/eroina>. Ti saluto!", 0xd36b69c6, 0x2c0ceb47, 0x41a07ec4, 0x6d3e78a5, 0x5109bb8d, "....." },
  [217] = { "In difesa delle terre del re", "Uccidi il capo dei trogg, Grawmug, e le sue due guardie, Gnasher e Brawler, poi fai rapporto al capitano Rugelfuss nella torre di guardia meridionale.", "{name}, i nostri esploratori hanno individuato il capo di questa recente incursione dei trogg. Pare che queste bestie di Loch Modan seguano un capotribù di nome Grawmug. Grawmug, però, è ben protetto. Due delle sue guardie migliori, Gnasher e Brawler, non lo lasciano mai.\n\nSe ti ritieni all'altezza, {name}, voglio che sia tu a guidare la missione per assassinare Grawmug e i suoi due scagnozzi. Con i capi dei trogg morti, forse avremo una possibilità di ricacciare queste bestie sottoterra.", "Grawmug e le sue due guardie, Gnasher e Brawler, sono ancora vivi. La tua missione non sarà compiuta finché tutti e 3 non saranno morti. L'impero nanico conta su di te, {name}.", "Eccellente, {name}! Hai portato speranza a Loch Modan. Con Grawmug morto, abbiamo più possibilità di eliminare i trogg da queste terre.", 0xc965c9da, 0xd0adb1a9, 0xd1d3aab4, 0x080d24f4, 0x996b47d7, "....." },
  [218] = { "Il diario rubato", "Grelin Whitebeard vuole che tu uccida Grik'nir the Cold e recuperi il suo diario.", "Il mio diario! L'hanno portato via nella grotta. Quello che ce l'aveva... era un bestione con degli strani segni sulla pelle e sulla faccia. Non sono riuscito a vederlo meglio di così.\n\nCon i troll te la sei cavata bene, magari potresti andare a riprenderlo per me?", "{name}! Novità?", "Magnifico, {name}! Grazie mille per aver recuperato il mio taccuino. Be', sembra che la situazione dei troll qui nella ⟦Coldridge Valley=Valle Crestafredda⟧ sia sotto controllo e non dia molti motivi di preoccupazione.\n\nQuando avrò dato gli ultimi ritocchi al mio rapporto, mi servirà qualcuno che lo porti a mio fratello Senir.", 0x5df25f99, 0x1dd2f28b, 0xfc2a9b7a, 0x224c9107, 0x3df5a70e, "....." },
  [219] = { "Disperso in azione", "Proteggi il caporale Keeshan nel viaggio di ritorno a ⟦Redridge=Crestarossa⟧.", "Finalmente, amici dell'⟦Alliance=Alleanza⟧!\n\nAiuto... vi prego...\n\nL'ultima cosa che ricordo è che questi luridi orchi hanno sopraffatto il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Ho preso un colpo forte alla testa e poi è diventato tutto buio. Ora sono tenuto prigioniero in questa grotta. Aiutami, sono ferito gravemente.\n\nHo bisogno d'aiuto per tornare in città... ti prego... sei la mia ultima speranza...", "Sì?", "Hai servito bene il Regno, {class}. Grazie per aver aiutato il caporale Keeshan a fuggire da quei temibili orchi ⟦Blackrock=Roccianera⟧. Sarai ricompensat<o/a> per le tue azioni coraggiose di oggi.", 0xd4ba8881, 0x846a56f1, 0x9fe9b7bf, 0x0c07a888, 0x3364444e, "....." },
  [220] = { "Il richiamo dell'acqua", "Porta la ⟦Vial of Purest Water=Fiala d'Acqua Purissima⟧ a Islen Waterseer nelle ⟦Barrens=Savane⟧.", "Islen avrà un ultimo compito per te prima di ricompensarti con il tuo prossimo totem. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque esso sia.\n\nOra va' a cercarla. Un giorno ci rivedremo.", "Ben ritrovat<o/a>, {name}. Hai un bell'aspetto.\n\nCosa ti riporta da me così presto?", "Ah, una fiala d'acqua creata e benedetta da Brine, e per giunta raccolta da te.\n\nIl liquido in questa fiala sarà fondamentale per creare un sapta per te, ma servirà anche per un altro compito.\n\nIl sapta che creerò per te dovrà essere usato per vedere gli spiriti dell'acqua al santuario nella ⟦Silverpine Forest=Selva Pinargento⟧, a sud di ⟦Undercity=Sepulcra⟧. Le gocce rimanenti... be', delle gocce rimanenti ti parlerò se ti senti <pronto/pronta>.\n\nSei <preparato/preparata> per un ultimo viaggio, {name}?", 0x1f0e11aa, 0xba2ead60, 0x6f760e93, 0x959ae071, 0x94f993e0, "....." },
  [221] = { "Worgen nei boschi", "Uccidi 12 Nightbane Dark Runner per Calor, a ⟦Darkshire=Borgoscuro⟧.", "Hai notato che nei boschi, insieme agli Shadow Weaver, si aggirano dei worgen più grossi? Da quanto possiamo capire, questi Dark Runner sono il grosso delle forze dei worgen.\n\nDurante le mie perlustrazioni ho visto anche che hanno invaso il Frutteto Marcescente, a sud-ovest del paese. Questi worgen sono un po' più duri degli ultimi che hai affrontato.\n\nStai in guardia.", "Già di ritorno, {name}? Spero che tu non sia venut<o/a> a dirmi che ti sei res<o/a>.", "Te la sei cavata bene contro i Dark Runner, {name}. Ma sembra che il loro numero sia inesauribile. Ogni volta che facciamo progressi, ne spuntano altri a riempire i ranghi.\n\nQual è il potere malvagio che li attira qui? Perché sono venuti a turbare il nostro infelice regno...\n\nRiporrò la mia fiducia nel maestro Carevin. Senza dubbio arriverà al fondo del problema.", 0x47dbaa77, 0x77e86e2a, 0xb1107ac6, 0x33d61b21, 0xc02e7176, "....." },
  [222] = { "Worgen nei boschi", nil, nil, nil, nil, 0x47dbaa77, nil, nil, nil, nil, ".mmmm" },
  [223] = { "Worgen nei boschi", nil, nil, nil, nil, 0x47dbaa77, nil, nil, nil, nil, ".mmmm" },
  [224] = { "In difesa delle terre del re", "Il montanaro Cobbleflint della torre di guardia meridionale vuole che tu uccida 10 Stonesplinter Trogg e 10 Stonesplinter Scout.", "Dobbiamo proteggere il Loch, {name}! Con tanti soldati del re che combattono valorosamente su campi di battaglia lontani, qui in patria siamo sopraffatti. I trogg sbucano da ogni crepa! L'infestazione dei trogg è la minaccia più grave per ⟦Ironforge=Forgiardente⟧. Questi mutanti disgustosi vanno distrutti.\n\nAbbiamo bisogno di te, <coraggioso/coraggiosa> avventurier<o/a>: parti e spazza via la minaccia dei trogg. Uccidi 10 Stonesplinter Trogg e 10 Stonesplinter Scout e torna a fare rapporto.", "Loch Modan è sotto assedio, {name}! Ci serve ogni membro dell'⟦Alliance=Alleanza⟧ in grado di combattere. Hai già ucciso 10 Stonesplinter Trogg e 10 Stonesplinter Scout?", "Ben fatto, {name}! Hai dimostrato un coraggio straordinario sul campo di battaglia. La nostra guerra contro i trogg si vincerà con sforzi come il tuo. Hai servito bene re Magni.\n\nSe pensi che questo genere di avventure faccia per te, ti consiglio di parlare con il montanaro Gravelgaw. Il capitano gli ha assegnato una pattuglia difficile e sono sicuro che un aiuto gli farebbe comodo. Cerca Gravelgaw appena dentro la torre.", 0xc965c9da, 0x6d03495e, 0xc3723201, 0x75084503, 0xe35c303e, "....." },
  [226] = { "Lupi alle calcagna", "Uccidi 12 Starving Dire Wolf e 8 Rabid Dire Wolf, poi torna da Lars al Sven's Camp, sul confine occidentale di ⟦Duskwood=Boscovespro⟧.", "A me e a Sven aspettano giorni pericolosi, con il Negromante a est e tutto il resto. E stando qui fuori da soli, dobbiamo cacciare per procurarci il cibo. Sembra che ogni volta che torno all'accampamento con un po' di carne addosso, dalla foresta escano lupi famelici o rabbiosi in cerca di un boccone. Inutile dirlo, vivere qui fuori è un mestiere pericoloso!\n\nMa se riuscissi a liberarci di un po' di quei lupi, per noi sarebbe più facile. Si aggirano soprattutto a nord e a est di qui, vicino al fiume.", "Sei ancora a caccia di lupi...?", "Oh, bene. Hai sfoltito parecchio quel branco, e senza quei lupi alle calcagna possiamo concentrarci su Morbent Fel.\n\nEcco, prendi alcuni di questi Fagotti Lampeggianti. Li fanno in paese, e molti sono stati donati a Sven per aiutarlo nella sua causa.", 0xdeb794ec, 0xae5c308b, 0x0b5b5fe6, 0x3371447a, 0x489aecd3, "....." },
  [230] = { "L'accampamento di Sven", "Porta il ⟦Book from Sven's Farm=Libro della Fattoria di Sven⟧ a Sven.", "Scavando nel cumulo di terra, trovi un piccolo libro sporco di terra.\n\nIl libro non ha titolo, ma... contiene informazioni che Sven vorrebbe conoscere.", "Hai trovato cosa?? Ti prego, fammelo vedere...", "<Sven legge le pagine del libro, poi lo chiude di scatto.>\n\nQuella figura nell'ombra che ho visto ha assistito alla morte della mia famiglia! Avrei delle domande da fare a quell'uomo... se solo sapessi chi è!", 0x03adfb1c, 0xb1da24c8, 0x4cc2761b, 0x9d6eaf1e, 0x4f4f7346, "....." },
  [233] = { "Posta per la ⟦Coldridge Valley=Valle Crestafredda⟧", "Consegna il pacco di lettere a Talin Keeneye.", "Mm, non è che ti andrebbe di farmi un favore, <ragazzo/ragazza>? Oggi è arrivato dal passo un pacco di lettere, ma non ho il tempo di consegnarle.\n\nSono tutte indirizzate a Talin Keeneye. Lo trovi più a ovest, lungo la strada. Si è accampato accanto al lago ghiacciato.\n\nChe ne dici?", "Sì? Hai qualcosa per me?", "Grazie, aspettavo queste lettere da un bel po'...\n\nPurtroppo non sono tutte per me. Questa è indirizzata a Grelin Whitebeard. Non è molto lontano, se vuoi consegnargliela tu.", 0xeea45c41, 0x43673bfd, 0x2f02ac16, 0xc599dffe, 0x2dbb1502, ".....", nil, nil, 0xce85efc5, nil, nil },
  [234] = { "Posta per la ⟦Coldridge Valley=Valle Crestafredda⟧", "Consegna la lettera a Grelin Whitebeard.", "Se ricordo bene, l'accampamento di Grelin è lungo la strada, a sud-est. Di sicuro non vedrà l'ora di avere la sua posta.", "Posso aiutarti in qualche modo?", "Ahh, eccellente. Era da un po' che non ricevevo notizie da ⟦Ironforge=Forgiardente⟧. Ah, queste lettere di mia mamma mi scaldano il cuore. Tieni, non è giusto che tu non abbia niente da leggere. Prendi uno di questi manuali che abbiamo in giro.", 0xeea45c41, 0x9842e5d5, 0x570047d8, 0x931ded5d, 0xafa727e9, "....." },
  [235] = { "La caccia di ⟦Ashenvale=Valtetra⟧", "Parla con Senani Thunderheart all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "Attenzione, giovani avventurieri! Le terre selvagge di ⟦Ashenvale=Valtetra⟧ vi attendono!\n\nL'⟦Horde=Orda⟧ si è insediata saldamente nelle terre a nord delle ⟦Barrens=Savane⟧. I nostri due avamposti, l'⟦Splintertree Post=Avamposto di Troncorotto⟧ e l'avamposto della ⟦Zoram Strand=Spiaggia di Zoram⟧, si battono per portare gloria all'⟦Horde=Orda⟧! Chi vuole mettersi alla prova dovrebbe cercare una guida laggiù. Da segnalare: Senani Thunderheart, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, direttamente a nord delle ⟦Barrens=Savane⟧, cerca avventurieri disposti a partecipare a una grande caccia a ⟦Ashenvale=Valtetra⟧!", nil, "Benvenut<o/a> nella nuova frontiera, {name}. ⟦Ashenvale=Valtetra⟧ è una terra di opportunità, dove un giovane {class} come te può trovare infinite occasioni per dimostrare il proprio valore. Dai un'occhiata all'avamposto e non mancare di spingerti fino alla ⟦Zoram Strand=Spiaggia di Zoram⟧, dove l'⟦Horde=Orda⟧ ha un altro avamposto.\n\nLa tua presenza qui mi dice che sei <venuto/venuta> per saperne di più sulla caccia. Ascolta bene, e ti dirò volentieri ciò che devi sapere.", 0x1bf465b8, 0x0a003978, 0x7489a1c6, nil, 0xedbc036b, "...m." },
  [237] = { "In difesa delle terre del re", "Il montanaro Gravelgaw, nella torre di guardia meridionale, vuole che tu uccida 10 Stonesplinter Skullthumper e 10 Stonesplinter Seer e che poi torni a fare rapporto da lui.", "Il montanaro Cobbleflint ha detto solo cose buone di te, {race}. Per questo ti affiderò una missione della massima importanza. Dobbiamo tenere sotto pressione le forze dei trogg invasori finché i nostri fratelli nani non torneranno dal fronte dell'⟦Alliance=Alleanza⟧.\n\nDirigiti verso le colline meridionali e uccidi 10 Stonesplinter Skullthumper e 10 Stonesplinter Seer. I tuoi attacchi ci faranno guadagnare tempo. Fai rapporto quando avrai portato a termine la missione.", "Ci serve altro tempo, {race}. I tuoi ordini sono di uccidere 10 Stonesplinter Skullthumper e 10 Stonesplinter Seer. Tieni il nemico sotto pressione finché non ci concederanno rinforzi. Non è il momento di stare con le mani in mano.", "Hai portato a termine bene la tua missione, {race}. Il re in persona ne sarebbe fiero.\n\nI rinforzi che ci erano stati promessi, però, non sono mai arrivati. A quanto pare il fronte dell'⟦Alliance=Alleanza⟧ è un mare cremisi per il sangue dei nostri fratelli caduti. La notizia delle perdite lascia l'amaro in bocca. Ma non dobbiamo lasciare che la loro morte sia vana. Dobbiamo serrare i ranghi in questi tempi cupi e riportare la gloria all'⟦Alliance=Alleanza⟧.\n\nParla con il montanaro Wallbang per un nuovo incarico. C'è bisogno di te ora più che mai.", 0xc965c9da, 0xecf18b12, 0xd0c449f5, 0x92de6ab6, 0x3ebcd8dc, "....." },
  [239] = { "Il ⟦Westbrook Garrison=Presidio Rivombroso⟧ chiede aiuto!", "Va' al ⟦Westbrook Garrison=Presidio Rivombroso⟧ e parla con il vicesceriffo Rainer.", "Il presidio sul nostro confine occidentale riferisce che gnoll e ladri sono sempre più attivi. Ci chiedono di mandare altri soldati di ⟦Stormwind=Roccavento⟧... ma non ne abbiamo nessuno da mandare!\n\nSe puoi dare una mano, ci farebbe comodo. Va' a parlare con il vicesceriffo Rainer al ⟦Westbrook Garrison=Presidio Rivombroso⟧ e senti di cosa ha bisogno.\n\nIl presidio è lungo la strada, a ovest. Dopo aver attraversato il ponte sul ruscello, lo troverai sulla destra.", nil, "Ti manda il maresciallo Dughan, eh? Be', non fai parte dell'esercito, ma se ti manda Dughan per me va più che bene!\n\nLa nostra situazione è, a dir poco, difficile. Spero che tu possa darci una mano.", 0xdc5c2624, 0x2e02a498, 0x8d2938bf, nil, 0x3b449a23, "...m." },
  [240] = { "Ritorno da Jitters", "Torna da Jitters con il ⟦Dusky Crab Cakes=Tortino di Granchio Scuro⟧.", "Ed eccoci qua: Tortini di «Granchio» alla Grual!", "{name}, sei qui! Hai il mio cibo?!?", "Aha! Grazie, {name}. Erano proprio quello che ci voleva!\n\nE tieni, lascia che te li paghi!", 0x1c60e6ea, 0xe6ff66e0, 0x74df57a6, 0x49ff2ae7, 0xb54be29c, "....." },
  [244] = { "Gnoll in avanzata", "Fai rapporto al vicesceriffo Feldon.", "Salute, {class}. Ho l'incarico di pattugliare questo tratto di strada. Per ora la strada è sicura, ma ho visto accampamenti di gnoll a nord e a est di qui.\n\n⟦Lakeshire=Borgolago⟧ deve sapere delle forze gnoll che si stanno radunando! Fai rapporto al vicesceriffo Feldon a ⟦Lakeshire=Borgolago⟧ e parlagli degli gnoll. Fallo, e sono sicuro che Feldon ti darà una paga da esploratore.\n\nDi solito Feldon ispeziona la zona a sud del ponte per ⟦Lakeshire=Borgolago⟧.", nil, "Ci sono gnoll di ⟦Redridge=Crestarossa⟧ così vicini a Elwynn?? Potrebbero essere pronti ad avanzare nella nostra patria. Presto la gente di ⟦Lakeshire=Borgolago⟧ potrebbe non essere l'unica tra gli umani sotto assedio!\n\nEcco la tua paga, anche se ci porti notizie terribili. E arrivano in un brutto momento, perché non siamo attrezzati per affrontarle.", 0x8c8be2e9, 0x7bc054fc, 0xae1593a2, nil, 0x3e80651e, "...m." },
  [245] = { "Minacce a otto zampe", "Uccidi 15 Pygmy Venom Web Spider, poi torna a fare rapporto al guardiano Dodds a ⟦Duskwood=Boscovespro⟧.", "Salute, {class}. Forse hai visto quei ragni che hanno invaso il confine occidentale? Queste minacce a otto zampe sono troppo per noi, e il comandante non ha abbastanza uomini da distaccare così lontano da ⟦Darkshire=Borgoscuro⟧.\n\nMi dispiace chiedertelo, ma sembri in grado di affrontarli. Non posso prometterti nulla di gran valore, ma posso ricompensarti se mi aiuti a sradicare quelle luride bestiacce.\n\nAh, un consiglio: se puoi, evita il loro veleno.", "Faresti meglio a stare attent<o/a> con quei ragni: ci ho rimesso alcuni dei miei uomini e, credimi, non è un bello spettacolo vedere un uomo appeso a testa in giù nelle loro ragnatele, dopo che il veleno ha cominciato a intenerirlo.\n\nNon vorrei vedere una di quelle bestiacce mangiarti a pranzo.", "Ah! Sei tornat<o/a>. E non troppo malridott<o/a>, a quanto pare. Naturalmente, {name}, i Guardiani della Notte ti sono grati per il tuo lavoro, e ti avevo promesso una ricompensa, quindi eccola.", 0xd491b1a7, 0x9eafc706, 0x22732e4f, 0xe12e0aee, 0x1c080d20, "....." },
  [246] = { "Valutare la minaccia", "Uccidi 10 Redridge Mongrel e 6 Redridge Poacher a ⟦Redridge=Crestarossa⟧, poi fai rapporto al vicesceriffo Feldon a ⟦Lakeshire=Borgolago⟧.", "Non abbiamo uomini da distogliere, ma bisogna fare qualcosa per quegli gnoll che mi hai segnalato.\n\nPerlustra il sud di ⟦Redridge=Crestarossa⟧ in cerca di gnoll. Tormentali, uccidi quelli che puoi e torna a riferirmi quanti sono e quanto è grave la minaccia che rappresentano. Troverai quegli gnoll accampati lungo tutta la strada meridionale di ⟦Redridge=Crestarossa⟧.\n\nFallo per l'esercito di ⟦Stormwind=Roccavento⟧, {name}, e riceverai una ricompensa.", "Scusami, {name}, ma qui abbiamo le mani piene. Se non hai nulla da riferire, devo pensare ad altro.", "<Il vicesceriffo Feldon ascolta il tuo rapporto...>\n\nLaggiù è accampata una forza consistente di gnoll, e da quel che mi dici sono tipi tosti. Non dev'essere stato facile raccogliere queste informazioni.\n\nEcco a te, {name}. Ti siamo grati per il tuo aiuto.\n\nE se non l'hai già fatto, parla con il maresciallo Marris e con il magistrato Solomon a ⟦Lakeshire=Borgolago⟧. La nostra situazione si fa sempre più disperata: sono sicuro che quei due avranno bisogno di te.", 0xcdd38f62, 0x1de28477, 0x75c1cdab, 0xfd431e78, 0x3a73678c, "....." },
  [247] = { "La caccia è compiuta", nil, nil, nil, "{name}, hai ucciso tutte e tre le bestie della caccia di ⟦Ashenvale=Valtetra⟧. Mi hai portato prove sufficienti della loro fine; non c'è dubbio sulla tua forza e sulla tua tenacia. Il sangue di un cacciatore ti scorre nelle vene, e meriti un encomio!\n\nTi prego, accetta questo ninnolo come segno di congratulazioni per le possenti imprese compiute oggi a ⟦Ashenvale=Valtetra⟧ per l'⟦Horde=Orda⟧. Che i tuoi antenati veglino su di te!", 0x14ca8c7a, nil, nil, nil, 0xa17a9acd, ".mmm." },
  [248] = { "Guardare oltre", "Sali sulla torre di guardia intatta accanto al ⟦Stonewatch Keep=Mastio di Guardamasso⟧.\n\nTrova un contenitore adatto in cui mettere il ⟦Glyph of Azora=Glifo - Azora⟧.", "Ho tenuto d'occhio la ⟦Tower of Ilgalar=Torre di Ilgalar⟧ e percepisco che Morganth è in conflitto con gli orchi del ⟦Stonewatch Keep=Mastio di Guardamasso⟧. Non conosco il motivo della loro contesa, ma puoi aiutarmi a svelare questo mistero.\n\nPrendi un altro ⟦Glyph of Azora=Glifo - Azora⟧, poi sali in cima alla torre di guardia intatta accanto al ⟦Stonewatch Keep=Mastio di Guardamasso⟧.\n\nTrova un oggetto adatto su cui porre il glifo. Un forziere o una giara... un posto dove il glifo passi inosservato andrà bene per il mio scopo.", "Questa giara un tempo conteneva un liquore maleodorante, ma ora giace vuota e dimenticata su un paio di barili.", "È un recipiente adatto al ⟦Glyph of Azora=Glifo - Azora⟧, e permette a Theocritus di scrutare nelle menti all'interno del ⟦Stonewatch Keep=Mastio di Guardamasso⟧.", 0x6310d65d, 0x375e6926, 0x7c764f66, 0x08216341, 0x02b3cbef, "....." },
  [249] = { nil, "Sconfiggi Morganth.\n\nPorta il suo ⟦Pendant of Shadow=Pendente dell'Ombra⟧ a Theocritus, alla ⟦Tower of Azora=Torre di Azora⟧ nella ⟦Elwynn Forest=Foresta di Elwynn⟧.", "Dopo lunghe osservazioni ho scoperto i piani di Morganth.\n\nCerca la Scythe of Elune... e potrebbe averla trovata! Se è così, le ⟦Redridge Mountains=Montagne Crestarossa⟧ e il regno di ⟦Stormwind=Roccavento⟧ sentiranno presto il suo oscuro potere.\n\nNon sono pronto a misurarmi con Morganth, ma temo che vada affrontato subito. Perciò devi entrare nella ⟦Tower of Ilgalar=Torre di Ilgalar⟧ e affrontare Morganth.\n\nSconfiggilo e portami il suo ⟦Pendant of Shadow=Pendente dell'Ombra⟧. Fallo, e il regno ti sarà molto debitore.", "Sbrigati, {name}, prima che il mio timore che Morganth estenda il suo potere diventi realtà!", "Hai fatto bene, {name}. Sconfiggendo lo stregone Morganth hai salvato ⟦Stormwind=Roccavento⟧ da un grave pericolo.\n\nTi offro questa ricompensa con la massima umiltà. E ti augurerei pace, se questi fossero tempi di pace.\n\nInvece ti augurerò fortuna nelle tue prove e vittoria nei conflitti che ti attendono.", 0x64aa5799, 0x879964dd, 0x12522098, 0x0143479a, 0x425a6647, "e...." },
  [250] = { "Incombe una minaccia oscura", "Indaga nella zona vicino alla rampa orientale della diga e porta all'ingegnere capo Hinderweir un indizio che possa rivelare cosa stanno tramando i ⟦Dark Iron Dwarves=Nani Ferroscuro⟧.", "Grazie al cielo qualcuno si preoccupa della sicurezza della diga. Prima la distruzione del ⟦Thandol Span=Viadotto di Thandol⟧ e poi il saccheggio di Dun Modr! Non ho dubbi che la diga sarà il prossimo bersaglio della minaccia ⟦Dark Iron=Ferroscuro⟧. Gran parte della squadra di sicurezza di qui è stata riassegnata al fronte dell'⟦Alliance=Alleanza⟧, compreso il mio miglior ispettore.\n\nPer questo ho bisogno di te, {name}. Ho visto alcuni Dark Iron Sapper aggirarsi presso la rampa orientale della diga. Indaga nella zona e riporta un indizio.", nil, "Il barile dall'aria sospetta contiene una polvere dall'odore strano.", 0x285fa090, 0xd58cd749, 0x3b5e1a8f, nil, 0xcbe807ee, "...m." },
  [251] = { "Tradurre il biglietto di Abercrombie", "Porta la ⟦Letter to Ello=Lettera per Ello⟧ a Sirra Von'Indi.", "Porta il biglietto che mi hai dato a Sirra Von'Indi. È molto esperto di lingue e arti antiche: se qualcuno qui può tradurre questo messaggio, è lui.", "Un biglietto da Abercrombie l'eremita, eh? Non lo conosco, però se vive laggiù al cimitero allora so che il cervello gli è marcito!", "<Sirra comincia a tradurre il biglietto...>", 0x5d4115a2, 0x14115437, 0xcf076a63, 0x22e67061, 0xcc1a43e1, "....." },
  [252] = { "La traduzione per Ello", "Porta la ⟦Translated Letter=Lettera Tradotta⟧ a lord Ello Ebonlocke", "Santo cielo! Se ciò che è scritto in questo biglietto è vero, allora Abercrombie ha fatto qualcosa di... indicibile.\n\nFaresti meglio a riportare il biglietto tradotto a Ello.\n\nE fallo in fretta, perché temo che una sciagura stia già avanzando a passi pesanti verso il nostro villaggio...", "Ah, il biglietto è tradotto? Ti prego, fammelo vedere...", "<Ello legge la lettera... e impallidisce. Poi ti guarda...>\n\nAnche se l'aiuto che hai dato ad Abercrombie può essere nato dalla gentilezza, le tue azioni hanno condannato il nostro villaggio.\n\n<Ello si perde nei suoi pensieri...>", 0xe1358fe4, 0x997dc93d, 0x30bdbc4f, 0x303a0cc2, 0xbf52b0c4, "....." },
  [253] = { "La sposa dell'Imbalsamatore", "Trova la tomba di Eliza. Prendile il Cuore dell'Imbalsamatore, poi torna da Ello Ebonlocke.", "L'Imbalsamatore è un nome che compare in una delle storie per i nostri bambini. Era un alchimista gentile, impazzito per la morte della moglie, Eliza. Per riportarla in vita usò la magia oscura e pose il proprio cuore nel petto della sposa defunta.\n\nCiò rianimò Eliza... ma la maledisse con una fame di carne umana, costringendo l'Imbalsamatore a tenerla sepolta.\n\nIl suo cuore è il suo potere. Trova la tomba di sua moglie, prendi il cuore e portamelo finché batte ancora. Fallo, e il suo potere sarà spezzato.", "Hai già trovato la tomba di Eliza? Hai il cuore dell'Imbalsamatore?", "Ce l'hai fatta! La magia nel suo cuore ci proteggerà dal male dell'Imbalsamatore, e sarà un potente scudo sul villaggio di ⟦Darkshire=Borgoscuro⟧.\n\nHai fatto una grande cosa per la nostra gente, {name}. Il tuo nome resterà per sempre nei nostri annali.", 0xe86145e0, 0x23727411, 0x572b08ce, 0xa3411c44, 0x7066ca1d, "....." },
  [255] = { "Mercenari", "Il magistrato Bluntnose di Thelsamar ti ha assoldato per uccidere 4 Mo'grosh Ogre, 4 Mo'grosh Brute e 4 Mo'grosh Enforcer.", "Due mesi solo per sentirci dire da ⟦Ironforge=Forgiardente⟧ che ci concederanno una manciata di soldati per la nostra difesa, e altri due mesi prima che arrivino! Già è grave che il paese resti senza protezione, ma anche lo scavo e la diga... la diga!... sono esposti agli attacchi.\n\nA quanto pare non ho scelta. Mi servono braccia a pagamento.\n\nChe ne dici? Mi sembri il tipo giusto, {class}. Un gruppo di ogre si è accampato a nord-est del lago. Forse potresti radunare qualche altro volontario e aiutarci a eliminare la minaccia che incombe sul paese?", "Hai avuto fortuna?", "Ah, questa sì che è un'ottima notizia! Io e la gente di Thelsamar apprezziamo molto i tuoi sforzi. E c'è di meglio: se risolviamo il problema degli ogre, potremo concentrarci su quei trogg maledetti dalla Luce.", 0x68e67e79, 0xd9633fd2, 0x6eaa85fa, 0x580fb5c3, 0x89841e1a, "....." },
  [256] = { "RICERCATO: Chok'sul", "Uccidi Chok'sul e porta la sua testa al magistrato Bluntnose di Thelsamar.", "Per ordine del magistrato di Thelsamar:\n\nChok'sul, l'ogre ritenuto il capo e l'organizzatore degli attacchi contro il paese di Thelsamar, la ⟦Stonewrought Dam=Diga di Pietrasalda⟧ e il sito di scavo, è ricercato morto, con ogni mezzo necessario.\n\nUna ricompensa in denaro sarà corrisposta a chi porterà al magistrato la prova della morte di Chok'sul.\n\nChok'sul è stato avvistato l'ultima volta all'accampamento degli ogre nella parte nordorientale di Loch Modan.", "Sì? Posso fare qualcosa per te?", "Bleah! Cos'è quella roba? E perché mai la porti...\n\nMaledizione...! È davvero lei? Che la Luce mi bruci, è la testa di quel maledetto ogre? Allora è proprio un bel colpo! Ecco la tua ricompensa, con i ringraziamenti miei e della gente di Thelsamar.", 0xd76c7e39, 0xf939ce2f, 0x8fcfd75f, 0x74cd0668, 0x2b1ae6f2, "....." },
  [257] = { "Il vanto di un cacciatore", "Uccidi 6 Mountain Buzzard e torna da Daryl the Youngling al ⟦Farstrider Lodge=Padiglione Lungopasso⟧ entro 15 minuti.", "Credi di poterti misurare in astuzia con Daryl the Bold, eh? Direi proprio di no! Certo, sei liberissim<o/a> di provarci. Ecco una sfida che dovrebbe rivelarsi al di sopra delle tue capacità, quindi non prendertela troppo se non sarai all'altezza.\n\nUno stormo di poiane ha fatto il nido qui a Loch Modan. Perché non provi ad abbattere qualcuna di quelle bestie? Facciamo così: se superi la mia sfida in quindici minuti, ti darò il mio arco o il mio fucile.\n\n<Ti squadra con aria sprezzante.>\n\nTanto non mi sembra che tu abbia molto da perdere.", "Niente da fare? Non prendertela troppo, {name}...\n\nNon tutti possono essere come me.", "Cosa? Ce l'hai fatta?\n\nDa' retta a me, {name}, non montarti la testa. Voglio dire, qualunque ragazzino imberbe con un arco avrebbe potuto uccidere esemplari così... piccoli. E spero che non ti diverta troppo ammazzare le poiane, eh? Non vorremmo che si estinguessero.\n\nBeh, ehm... Che non si dica mai che Daryl the Bold non mantiene la parola data.", 0x0a7320b6, 0x5b163583, 0x5ce8605c, 0xe9d625da, 0x867e7877, "....." },
  [258] = { "La sfida di un cacciatore", "Uccidi 5 Elder Mountain Boar e torna da Daryl the Youngling al ⟦Farstrider Lodge=Padiglione Lungopasso⟧ entro 12 minuti.", "{name}ath, giusto? Si vede che scoppi d'orgoglio per aver superato la prima prova, eh? Come ti ho già detto, non è una grande impresa.\n\nDovresti cimentarti nella caccia al cinghiale. Fidati, questa non è una caccia al cinghiale nella ⟦Coldridge Valley=Valle Crestafredda⟧, quindi faresti meglio a fare attenzione. Stavolta ti do solo dodici minuti.\n\nNon prendertela se fallisci. Se ci riuscissi, ti darei la camicia che ho addosso!\n\nTi ho mai raccontato come mi sono procurato la mia famosa cicatrice? No? Era due anni fa...", "È naturale commiserarsi quando si viene superati da qualcuno così nuovo di questo mondo. Non devi prendertela, {name}ah.\n\nMm? Ho sbagliato il tuo nome?", "Mi sembri un po' malconci<o/a>. Senza dubbio i cinghiali ti hanno dato qualche grattacapo, eh? Non preoccuparti, sarò discreto sulle tue difficoltà; immagino quanto debba essere dura per te anche senza le malelingue.\n\nOh! Sei riuscit<o/a> a uccidere i cinghiali? Io... beh, cioè... voglio dire, non sono sorpreso! Qualsiasi bambino avrebbe potuto... scommessa?\n\nQuale scommessa?", 0xc117168c, 0xf6f7aed2, 0x53a3b2ac, 0x73714f0b, 0x6757139d, "....." },
  [262] = { "La figura nell'ombra", "Prendi il libro che hai trovato alla fattoria di Sven e mostralo agli abitanti di ⟦Darkshire=Borgoscuro⟧.", "Devo sapere chi era quella figura furtiva che ho visto nell'ombra la notte in cui la mia famiglia è stata uccisa!\n\nTi prego, {name}, hai dimostrato di essere pien<o/a> di risorse. Trova quella figura nell'ombra. Devo scoprire quali segreti nasconde!\n\nNon ho indizi che tu non conosca già, ma tieni: prendi il libro che hai trovato alla mia fattoria. Forse qualcuno in città saprà collegarlo al suo proprietario.", "Se hai qualcosa che appartiene alla figura nell'ombra che cerchi, fammelo vedere. Forse potrò intuire qualcosa sul suo proprietario.", "Mm... Qualcuno ha maneggiato questo libro di recente, qualcuno spinto dalla vendetta. Ma le impressioni lasciate su di esso, almeno quelle del proprietario originale, sono deboli.\n\nPosso dirti, però, che il proprietario originale di questo libro non è di ⟦Darkshire=Borgoscuro⟧.", 0x314895c6, 0x43340f49, 0x13c0ea44, 0x383fb720, 0x6233a5dd, "....." },
  [263] = { "In difesa delle terre del re", "Il montanaro Wallbang, nella torre di guardia meridionale, vuole che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnapper.", "I montanari mi dicono che sei molto coraggios<o/a> e capace, {name}. Ci serve un {race} come te da queste parti. Il problema dei trogg non migliora. Le riserve sono state richiamate al fronte e qui siamo rimasti soli. Ma ora che abbiamo qui un {class} con esperienza, vediamo cosa sai fare.\n\nVa' a uccidere 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnapper. Vediamo se sei all'altezza della tua fama, Ammazzatrogg.", "Già di ritorno? Nel caso non fossi stato chiaro, abbiamo bisogno che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnapper, {name}. E ora vai a prenderli, Ammazzatrogg!", "L'ho capito appena ho posato gli occhi su di te, {name}: avresti reso fiera ⟦Ironforge=Forgiardente⟧. Hai servito bene re Magni. Ora che hai dimostrato di essere un aiuto così leale per il Regno, forse dovresti parlare con il capitano per vedere se ti affiderà un incarico più importante.\n\nTi saluto, {name}.", 0xc965c9da, 0x4a79e4d2, 0x0a04bb9f, 0xe5f1b1fc, 0xfc0b08bb, "....." },
  [264] = { "Finché morte non ci separi", "Metti il ⟦Clarice's Pendant=Pendente di Clarice⟧ sulla tomba di Yuriv, a ⟦Silverpine=Pinargento⟧.", "Lurido verme! Mi lascia per la sua maledetta crociata. Perché \"la Luce è la cosa più importante che abbiamo contro le minacce dei non morti\".\n\nE i suoi figli, allora?! E IO?! Notte dopo notte sono rimasta ad aspettarlo con pazienza... sempre seconda a quel suo dannato dovere!\n\nEbbene, guarda cosa ti porta la \"giustizia\", {name}! Lui è morto e io porto in me proprio ciò che cercava di fermare!\n\nPrendi questa robaccia e mettila sulla sua tomba, alla ⟦Sepulcher=Mausolea⟧. Non voglio più averci niente a che fare... né con lui!", "La pietra è fredda al tatto, ma è stata chiaramente maltrattata. L'area è disseminata di rifiuti; tacche e sfregi segnano il rilievo sul coperchio della bara, e la vegetazione intorno alla tomba ha cominciato a ricoprirla.\n\nA nessuno importa di chi è sepolto qui, men che meno alle vittime della pestilenza.", "Posi l'inutile pendente sulla tomba, e la gemma incastonata sembra opacizzarsi visibilmente.\n\nMentre ti alzi per andartene, abbassi lo sguardo sul pendente: giace inerte sulle mani del rilievo scolpito sul coperchio della bara. I tuoi pensieri vengono interrotti da una brezza fresca e pungente che soffia sulla ⟦Sepulcher=Mausolea⟧. Per un istante, intorno a te, tutto tace.", 0xa73209cc, 0xbb2445eb, 0xdadc8728, 0x4b0ea1a7, 0xf1fedc56, "....." },
  [265] = { "La ricerca nell'ombra continua", "Scopri se altri abitanti hanno indizi sulla figura nell'ombra.", "Ecco il tuo libro, {name}, e buona fortuna con le tue ricerche. Se chiedi ad altri in città, forse potranno darti altri indizi.\n\nE eccotene un altro: anche se l'autore di questo libro è un forestiero a ⟦Darkshire=Borgoscuro⟧, il libro è stato comprato qui.", "A volte vendo libri bianchi a studiosi e maghi, o a chiunque voglia tenere un diario.\n\nRicordo bene tutti quelli a cui ho venduto un libro negli ultimi mesi...", "Ah, sì. Ho venduto questo libro un mese fa a un tipo losco. Non mi ha detto il suo nome, ma era un tipo nervoso e agitato, che si guardava sempre alle spalle.\n\nSpero che ti sia d'aiuto...", 0x15f6b643, 0xfc327109, 0xbf55c340, 0x1c3e5d22, 0x7f698a5e, "....." },
  [266] = { "Indagini alla locanda", "Cerca nella locanda indizi sulla figura nell'ombra.", "Ecco il tuo libro, e buona fortuna con le tue indagini.\n\nForse dovresti estendere la ricerca alla locanda. Se la persona che cerchi è stata in città, è probabile che qualcuno l'abbia vista lì.", "Lo Scarlet Raven non ha più i clienti di una volta, ma qualche viaggiatore di passaggio ci capita ancora.\n\nSe mi descrivi la persona che cerchi, forse me la ricorderò.", "Oh sì, mi ricordo di questo libro. Il suo proprietario ha preso una stanza per qualche giorno e passava le notti al bancone, a scrivere.\n\nSe n'è andato di corsa, borbottando che era braccato da... qualcosa. L'ultima volta che l'ho visto si dirigeva a ovest, fuori città, in cerca di un nuovo nascondiglio.\n\nIl primo posto che troverebbe a ovest è ⟦Raven Hill=Collecorvo⟧...", 0x4736a4dc, 0xbe6a7054, 0x6d658e06, 0xe05a3817, 0x7f159659, "....." },
  [267] = { "La minaccia dei trogg", "Porta 8 Trogg Stone Tooth al capitano Rugelfuss, nella torre di guardia meridionale.", "{class}, forse sai già, o forse no, della minaccia dei trogg che incombe sulle terre dei nani. Con la Riserva di ⟦Ironforge=Forgiardente⟧ richiamata al fronte dell'⟦Alliance=Alleanza⟧, ci resta solo una frazione delle forze necessarie a tenere al sicuro queste terre. Il mio reggimento deve sorvegliare il Cancello e non possiamo lasciare il posto per paura di un'invasione.\n\nMa bisogna mettere sotto pressione quei dannati trogg che si annidano sulle colline. Se te la senti, lancia un attacco contro i trogg. Portami 8 Trogg Stone Tooth come prova.", "Hai 8 Trogg Stone Tooth da mostrarmi? Se no, c'è ancora lavoro da fare, {name}.", "Sono davvero colpito, {name}. Hai fatto un grande favore alla razza dei nani difendendo le nostre terre. Lo stesso re Magni Bronzebeard ne sarebbe fiero!", 0x5feba290, 0x14a4d831, 0xc4e3d0e9, 0xfb5e59d0, 0xe9c8efe3, "....." },
  [268] = { "Ritorno da Sven", "Torna da Sven con il diario completo di Jitters.", "Il libro che hai trovato era solo a metà. Ho dovuto lasciarlo alla fattoria di Sven quando sono fuggito da lì...\n\nTieni. Porta a Sven il mio diario completo. Descrive meglio cos'è successo alla sua fattoria.\n\nQuesto diario è stato la mia unica compagnia in queste ultime settimane, ma se cederlo mi evita di dover affrontare Sven e la sua furia, lo faccio volentieri!", "Hai scoperto chi era la figura nell'ombra?", "Questo diario mi spiega molte cose e mi mette sulle tracce dei Dark Rider! Li ho visti a ⟦Duskwood=Boscovespro⟧, e li ho visti parlare con lo stregone Morbent Fel, alla ⟦Forlorn Rowe=Magione Desolata⟧.", 0xb5e4d4a7, 0xddfbac78, 0xa746e876, 0x34bcef3e, 0x11d4dc98, "....." },
  [269] = { "In cerca di saggezza", "Consegna il ⟦Jitters' Completed Journal=Diario completo di Jitters il Teso⟧ al vescovo Farthing, a ⟦Stormwind=Roccavento⟧.", "Va' nella città di ⟦Stormwind=Roccavento⟧ e parla con il vescovo Farthing nella ⟦Cathedral of Light=Cattedrale della Luce⟧. Dagli il diario di Jitters e digli che intendi affrontare Morbent Fel.\n\nAnche se ⟦Stormwind=Roccavento⟧ ha abbandonato ⟦Darkshire=Borgoscuro⟧, Farthing è un'anima buona e molto saggia. Potrebbe aiutarti nella tua missione per salvarci.\n\nIl tuo compito è pericoloso, ma sbrigati, {name}. Ogni ora che passa, le ombre di ⟦Duskwood=Boscovespro⟧ si fanno più scure.", "Riposa, <fratello/sorella>. Vedo che hai viaggiato a lungo e che porti un pesante fardello. Puoi dirmi cos'è quell'ombra oscura che ti grava addosso?", "<Dopo aver letto il diario e ascoltato le tue intenzioni...>\n\nUna corruzione malvagia ha messo radici nella già tormentata ⟦Duskwood=Boscovespro⟧. Ringrazio la Luce di avere qualcuno di valoroso come te ad affrontarla.\n\nMa prima devi prepararti alla prova che ti attende... perché il negromante Morbent Fel è immensamente potente e si è circondato di incantesimi oscuri che lo proteggono dagli attacchi fisici. Se vuoi sconfiggerlo, ti servirà un'arma capace di vincere queste protezioni.", 0xa17403e8, 0xe615de8a, 0xc211aa79, 0x0ed6c310, 0xce1c3c43, ".....", nil, nil, nil, 0x36e5648e, nil },
  [270] = { "La flotta condannata", "Va' al ⟦Menethil Harbor=Porto di Menethil⟧, nelle ⟦Wetlands=Paludi Grigie⟧, e parla con Glorin Steelbrow.", "Anni fa la Terza Flotta di Kul'Tiras affondò lungo le coste delle ⟦Wetlands=Paludi Grigie⟧, una distesa di acquitrini a nord del regno nanico di ⟦Ironforge=Forgiardente⟧. A bordo di una delle navi c'era un carico di ferro della Forgia della Luce.\n\nQuesto metallo per noi è prezioso, perché gli oggetti forgiati con esso colpiscono con la verità sacra. Se devi affrontare Morbent Fel, ti servirà un'arma del genere.\n\nVa' al ⟦Menethil Harbor=Porto di Menethil⟧ e parla con il mio collega nano Glorin Steelbrow. Se quel metallo perduto si può ritrovare, lui saprà dove cercarlo.", nil, "Il ferro della Forgia della Luce è un metallo prezioso, ma la tua missione sembra disperata. Hai fatto molta strada, <fratello/sorella>. Con un po' di fortuna, potresti trovare proprio ciò che cerchi!\n\nE se riuscirai a procurarti il ferro, so chi può forgiarlo in un'arma contro quel negromante di ⟦Duskwood=Boscovespro⟧ di cui parli.", 0xb30a2ab9, 0xb61b8cec, 0x14f1ea19, nil, 0xd5d90125, "...m.", nil, nil, nil, nil, 0x62417845 },
  [271] = { "La vendetta di Vyrin", "Uccidi Ol' Sooty, poi mostra il frutto del tuo lavoro a Daryl the Youngling al ⟦Farstrider Lodge=Padiglione Lungopasso⟧.", "Immagino non ti interessi una piccola rivincita su Sua Sfrontatezza? Daryl ha un certo talento, mi duole ammetterlo.\n\nUn anno fa, un grosso orso era la preda del ⟦Farstrider Lodge=Padiglione Lungopasso⟧, ma nessuno dei cacciatori aveva avuto fortuna con lui. Così Daryl pensò di tentare la sorte. Tutto ciò che ottenne fu quella brutta cicatrice sopra l'occhio.\n\nUccidi l'orso, e sono sicuro che persino Daryl resterà senza parole, per una volta.\n\nL'orso, Ol' Sooty, si trova nei pressi della sua tana, sulle colline sopra Thelsamar.", "Ah, {name}! Già di ritorno? Di sicuro sei <stato/stata> di nuovo a caccia, vero? Non preoccuparti se hai avuto qualche intoppo: alla lunga ti renderà migliore!\n\n...Tanto peggio di così non potresti diventare...", "Ehm... cos'è questa? La testa di un orso, a quanto pare.\n\n<Si passa un dito sulla cicatrice senza accorgersene.>\n\nBeh, è una preda piuttosto interessante quella che hai lì. Non può essere l'orso di allora...\n\n<La voce gli si spegne, poi comincia a tremare visibilmente.>\n\nOh, portala via, portala via! Togli di qui quell'orrore!", 0xeb8bf51a, 0x9c0267f5, 0x0f0813b8, 0xce498672, 0x84cbe4fe, "....." },
  [272] = { "La prova del leone marino", "Trova il ⟦Half Pendant of Aquatic Agility=Mezzo Pendente dell'Agilità Acquatica⟧ e il ⟦Half Pendant of Aquatic Endurance=Mezzo Pendente della Resistenza Acquatica⟧. Parla con gli abitanti di ⟦Moonglade=Radaluna⟧ per ottenere indizi su dove potrebbero trovarsi.\n\nUnisci le due metà per formare il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧. Per farlo devi trovarti nei pressi del ⟦Shrine of Remulos=Santuario di Remulos⟧.\n\nPorta il pendente completo a Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Per la seconda prova ti serviranno le due metà che compongono il ⟦Pendant of the Sea Lion=Pendente del Leone Marino⟧. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dalla sua incredibile resistenza. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro forma acquatica.\n\nParla con la gente di ⟦Moonglade=Radaluna⟧ per scoprire dove possano trovarsi le due parti, e portale entrambe qui per unirle. Una volta formato il pendente, portalo a Dendrite Starblaze.", "Hai formato il pendente da farmi esaminare, {name}? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni alla gente del posto. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.", "Hai completato la prova del leone marino, {name}: congratulazioni.\n\nOgni passo per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua volontà di accogliere l'aspetto del leone marino.\n\nRicorda bene queste lezioni e affidati a esse quando avrai ottenuto la tua forma acquatica.", 0x5cc8ed68, 0xdf177053, 0x23c219a5, 0x3520b13e, 0xb90d61f2, "....." },
  [273] = { "Rifornimenti per lo scavo", "Parla con Huldar.", "Però non è troppo tardi, puoi andare a cercare Huldar. Non può essere andato molto lontano: per quanto siano forti, Miran e Saean non possono andare tanto veloci, carichi di quei barili.\n\nFanno la solita strada per il sito: escono dal paese verso sud e seguono la curva del lago.\n\nNon dovresti avere problemi a trovarli, a meno che non siano già arrivati.", nil, "Mpf, ci vorrà più di un'imboscata dei ⟦Dark Iron=Ferroscuro⟧ per fermare le consegne!\n\nMa Saean... non avrei mai sospettato che fosse uno dei loro simpatizzanti. Lavoriamo con lui da quasi un anno... forse non ho colto i segnali.\n\nBe', ci penserò più tardi.", 0xff211d45, 0x48ac2cba, 0xa385adaf, nil, 0xd8cf8be4, "...m." },
  [274] = { "Incombe una minaccia oscura", "Ashlan Stonesmirk vuole che tu torni dall'ingegnere capo Hinderweir e lo informi della nuova scoperta.", "Questa non è una comune polvere da sparo. Guarda questi minuscoli cristalli d'argento. E quell'odore inconfondibile! È chiaro come il sole che si tratta di polvere di Seaforium. Il Seaforium di per sé è abbastanza innocuo. Ma una volta bagnato potrebbe far saltare ⟦Ironforge=Forgiardente⟧ fuori dalla montagna.\n\nLa reazione chimica si può neutralizzare mescolando quattro componenti: Veleno di Solcatore, Cristallo dei Mo'grosh tritato, una lacrima di crocolisco e questo colloide disinnescante. Ora avvisa Hinderweir prima che sia troppo tardi!", "Che cosa mi porti da parte di Ashlan?", "Un colloide disinnescante? Per il Seaforium? Santo cielo!", 0x285fa090, 0xff4b9027, 0xae733e3d, 0x9e72d87b, 0x6bbfd674, "....." },
  [275] = { "Piaghe sulla terra", "Uccidi 12 Fen Creeper, poi torna da Rethiel the Greenwarden nelle ⟦Wetlands=Paludi Grigie⟧.", "Non so perché, ma nelle ⟦Wetlands=Paludi Grigie⟧ cresce un'infezione. I Fen Creeper si sono sollevati. Sono piaghe malate e febbricitanti sulla terra, e perché la febbre passi vanno abbattuti, così che possano tornare a posarsi nelle paludi.\n\nI Fen Creeper si trascinano lungo i corsi d'acqua delle ⟦Wetlands=Paludi Grigie⟧.", "Le ⟦Wetlands=Paludi Grigie⟧ piangono ancora, e i Fen Creeper infuriano ancora. Torna da me quando il tuo compito sarà concluso.", "Grazie ai tuoi sforzi questa terra trova sollievo, e per questo ti concederò un dono.", 0x98ec1fa6, 0xa3687664, 0x588d9f5d, 0x987a7155, 0xd673054a, "....." },
  [276] = { "Zampe che calpestano", "Uccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel, poi torna da Rethiel il Greenwarden nelle ⟦Wetlands=Paludi Grigie⟧.", "Gli gnoll Pelomusco vivono in pace nelle ⟦Wetlands=Paludi Grigie⟧ da molti anni, ma ora il loro numero cresce. I loro piedi schiacciano i cespugli e i fiori della palude, e le loro asce immonde tagliano troppa legna per alimentare i fuochi.\n\nNon sono più in equilibrio con la terra. Perché le ⟦Wetlands=Paludi Grigie⟧ sopravvivano, gli gnoll vanno ridotti di numero.\n\nUccidi 15 Mosshide Gnoll e 10 Mosshide Mongrel. Cacciali a sud, vicino alla porta nanica di Algaz. Fatto questo, torna da me.", "Il tuo compito ti attende ancora, giovane {class}.", "Riducendo il numero degli gnoll, hai curato la salute delle ⟦Wetlands=Paludi Grigie⟧. Anche se in passato la mia fiducia nella tua gente è stata messa alla prova, {race}, potrebbe ancora tornare.", 0xc2e1895b, 0xefe8bed1, 0x1e6b39f8, 0x5811b98d, 0xd1151a2d, "....." },
  [277] = { "Il tabù del fuoco", "Porta 9 Pietra Focaia Rudimentale a Rethiel the Greenwarden.", "I Pelomusco tagliano gli alberi delle ⟦Wetlands=Paludi Grigie⟧ e ne bruciano la carne per scaldarsi. Non sopporterò più questo dolore!\n\nTogli ai Pelomusco le loro pietre focaie rudimentali, gli attrezzi che usano per accendere il fuoco. Le portano tutti i Pelomusco, tranne i più piccoli Mosshide Gnoll e Mosshide Mongrel.", "Hai gli attrezzi da fuoco degli gnoll?", "... grazie. Spaccherò queste pietre focaie e le getterò in mare, perché non possano mai più servire a bruciare legno vivo.", 0xf9fd95dd, 0x98bf308d, 0x0d5db968, 0x4c8714a1, 0xf8f39043, "....." },
  [278] = { "Incombe una minaccia oscura", "L'ingegnere capo Hinderweir vuole che tu raccolga il ⟦Lurker Venom=Veleno di Solcatore⟧, un ⟦Mo'grosh Crystal=Cristallo dei Mo'grosh⟧ e una Crocolisk Tear.", "Comincia subito a raccogliere i materiali per il disinnesco, {name}. Il ⟦Lurker Venom=Veleno di Solcatore⟧ si trova sui ragni che vivono a Loch Modan. Anche le lacrime di crocolisco si trovano qui sul lago. Ma un cristallo dei Mo'grosh sarà molto difficile da procurare. Gli ogre a nord-est li estraggono, ma quei cristalli sono merce rarissima.\n\nDobbiamo essere pronti a sventare un attacco dei ⟦Dark Iron=Ferroscuro⟧! Torna da me quando avrai raccolto tutto il necessario e preparerò la mistura.", "Hai quello che serve? Il tempo stringe!!", "Appena in tempo, {name}!", 0x285fa090, 0x7dcc9e32, 0xda78b8d7, 0x6ba64689, 0x4c641a56, "....." },
  [279] = { "Artigli dagli abissi", "Uccidi 12 Bluegill Murloc.\n\nUccidi Gobbler e prendi la sua testa.\n\nPorta la ⟦Gobbler's Head=Testa di Glugot⟧ a Karl Boran, a ⟦Menethil Harbor=Porto di Menethil⟧.", "I murloc strisciano fuori dalle acque profonde e costruiscono i loro villaggi sulla costa. Tormentano i nostri pescatori e mercanti, e vanno fermati.\n\nUno di questi murloc, Glugot, si aggira con altri murloc Branchiazzurra e assale i mercanti lungo la strada, per poi ritirarsi sempre al sicuro nelle vicine tane dei murloc. I nostri mercanti sono in pericolo, e pagheremo per proteggerli.\n\nGlugot si aggira nell'insenatura del fiume a nord di qui. Trovalo, uccidi i suoi simili e portami la sua testa.", "I nostri mercanti non saranno al sicuro finché non ci saremo liberati di Glugot e di quei murloc.", "Ah, ben fatto, {name}.\n\nAccetta questo come pagamento per aver adempiuto al tuo contratto con i Merchant Marines.", 0xb2853dd5, 0xf105a28f, 0x413ad26f, 0xf4549fd2, 0x3b289c36, "....." },
  [280] = { "Incombe una minaccia oscura", "L'ingegnere capo Hinderweir vuole che tu nuoti fino alla base della diga, trovi il barile di polvere e ci mescoli la ⟦Disarming Mixture=Mistura Disarmante⟧ per evitare un'esplosione.", "Stamattina ho visto alcuni Dark Iron Insurgent nuotare verso la diga con un grosso barile. Non c'erano montanari a fermarli! Temo che abbiano piazzato il Seaforium alla base della diga, e potrebbe esplodere da un momento all'altro! Lascia che unisca tutti questi ingredienti nella ⟦Disarming Mixture=Mistura Disarmante⟧. Ecco fatto.\n\nOra devi prendere questa mistura e mescolarla nel barile prima che sia troppo tardi! Sbrigati!", "Il coperchio del barile si svita lentamente.", "Il barile sfrigola appena mentre la ⟦Disarming Mixture=Mistura Disarmante⟧ si deposita.", 0x285fa090, 0x49e1c755, 0xcabe6c09, 0x1bf6801c, 0x3e97c160, "....." },
  [281] = { "Recupero della merce", "Perquisisci le casse e i barili negli accampamenti costieri dei murloc.", "Non molto tempo fa un mercantile, la Blind Princess, è stato assalito dai murloc. La nave è riuscita a fuggire intatta, ma quelle creature hanno trascinato in mare gran parte del carico, tra cui una preziosissima statuetta di Terenas Menethil. Vogliamo che quella statuetta venga recuperata.\n\nPerquisisci le capanne dei murloc sulla costa in cerca di casse, barili e altre tracce del carico perduto. Trova la ⟦Menethil Statuette=Statuetta di Menethil⟧ e riportamela.", nil, "Questa cassa è piena di graffi di artigli e di segni lasciati dall'acqua. Forzandola, trovi paglia fradicia e marcia, come se dentro fosse stato custodito qualcosa di valore. Frughi nella paglia...\n\n...e trovi una bracciata di bottiglie rosse.", 0x20e23136, 0x92703920, 0xae0acc9a, nil, 0x1db70c6a, "...m." },
  [282] = { "Le osservazioni di Senir", "Parla con il montanaro Thalos.", "Pensavo di mandare il mio apprendista da mio fratello Senir con il rapporto, ma mi sentirei molto più tranquillo se fosse in mani più... affidabili. Sempre che non ti dispiaccia, s'intende.\n\nMm... dovrai passare per il tunnel per arrivare a Kharanos.\n\nParla con il montanaro Thalos prima di attraversare il tunnel. Ormai è completamente infestato dai trogg.\n\nSegui la strada fino a ⟦Anvilmar=Forgiamara⟧, poi continua verso est fino al tunnel: Thalos è di stanza lì vicino.", "Salute! Fa' attenzione, {name}: il tunnel per Dun Morogh è infestato dai trogg e non è sicuro viaggiarci.\n\nSe non hai affari urgenti a Dun Morogh, devo chiederti di restare a ⟦Anvilmar=Forgiamara⟧ finché il tunnel non sarà più sicuro.", "Mm, be', se Whitebeard ti manda a Dun Morogh per affari importanti, non posso certo fermarti, no?\n\nAlmeno lascia che ti dia qualche consiglio e qualche indicazione.", 0x034f6959, 0x04633807, 0xa94e25b2, 0xfbfd2fad, 0xe36152d6, "....." },
  [283] = { "Incombe una minaccia oscura", "La ⟦Disarming Mixture=Mistura Disarmante⟧ sembra aver fatto effetto. Torna dall'ingegnere capo Hinderweir per riferire la buona notizia.", "Il barilotto sfrigola leggermente.", nil, "Grazie infinite, {name}!! Hai salvato la ⟦Stonewrought Dam=Diga di Pietrasalda⟧! Senza il tuo aiuto, i terroristi ⟦Dark Iron=Ferroscuro⟧ avrebbero di certo provocato la rovina di questo imponente monumento. Hai reso fieri il Regno e l'⟦Alliance=Alleanza⟧, valoros<o/a> {class}.\n\nLa Diga è di nuovo al sicuro... almeno per il momento....", 0x285fa090, 0x59adb22f, 0x5529aef7, nil, 0x6249196b, "...m." },
  [284] = { "La ricerca continua", "Cerca la ⟦Menethil Statuette=Statuetta di Menethil⟧.", "Perquisisci a fondo questo gruppo di capanne dei murloc, ma non trovi traccia della ⟦Menethil Statuette=Statuetta di Menethil⟧.\n\nForse una delle due capanne vicine, a nord e a nord-est, nasconderà altri indizi.", nil, "Questo barile è quasi intatto. Lo forzi...\n\n...e vieni investit<o/a> dall'odore pungente del formaggio. È un po' bagnato, ma ancora gustoso!", 0xf8a6514c, 0x2fa34187, 0xc6d42d7d, nil, 0xf8bf63bc, "...m." },
  [285] = { "Altre capanne da perquisire", "Continua a perquisire le capanne dei murloc in cerca della ⟦Menethil Statuette=Statuetta di Menethil⟧.", "Dopo un'ispezione accurata, questo gruppo di capanne dei murloc non rivela nulla.\n\n...ma sei sicur<o/a> che il prossimo indizio sarà quello buono.\n\nUna delle capanne a nord deve avere la ⟦Menethil Statuette=Statuetta di Menethil⟧!", nil, "Questo barile è mezzo sepolto tra fango ed erba...", 0x37a342ab, 0xe542c0b8, 0x164b5557, nil, 0xc166ecf6, "...m." },
  [286] = { "La restituzione della statuetta", "Porta la ⟦Menethil Statuette=Statuetta di Menethil⟧ a Karl Boran.", "Dopo aver liberato il barile dal fango e averlo aperto, trovi una statuina argentata avvolta in paglia fine. Raffigura un giovane Paladino dai capelli lunghi con il martello sollevato.\n\nDev'essere la ⟦Menethil Statuette=Statuetta di Menethil⟧! Ora devi riportarla a Karl Boran, a ⟦Menethil Harbor=Porto di Menethil⟧.", "Hai la statuetta?", "Il capitano della Blind Princess sarà sollevato di sapere che questo prezioso carico è stato recuperato. Ti sei ben guadagnat<o/a> questo compenso per i servigi resi.\n\nFa piacere vedere gente affidabile come te, soprattutto in tempi difficili come questi.", 0x6359787c, 0xe755db7e, 0x468c1b10, 0xc8e24594, 0xee837828, "....." },
  [287] = { "⟦Frostmane Hold=Covo dei Mantogelido⟧", "Esplora il ⟦Frostmane Hold=Covo dei Mantogelido⟧ e uccidi 5 Frostmane Headhunter per Senir Whitebeard a Kharanos.", "Sono in ritardo con il mio rapporto e mi farebbe comodo il tuo aiuto, {name}. Sono appena riuscito a scoprire dove si sono rintanati i troll, ma ne ho visti così tanti che ho avuto paura di entrare.\n\nEcco cosa mi serve... Scendi alla grotta, dai un'occhiata all'interno, uccidi qualche troll e poi torna qui.\n\nPrendi la strada a nord di Kharanos; quando arrivi al ponte, segui il fiume ghiacciato verso ovest fino al ⟦Iceflow Lake=Lago di Ghiacciospesso⟧. Troverai ⟦Brewnall Village=Borgo Luppolo⟧ sulla riva occidentale. Il Covo è a sud-ovest del villaggio.", "Non riesci a trovarlo? Le mie indicazioni erano chiarissime! Non abbiamo molto tempo, devi sbrigarti! Non tornare finché non hai trovato la grotta.", "Ah, {name}! Non pensavo che avresti avuto problemi a trovare il posto, le mie indicazioni sono eccellenti, sai...\n\nFammi solo finire il rapporto, allora.\n\n<Tira fuori un foglio e ci scarabocchia sopra per qualche istante.>\n\nEcco! Be', ah ah, questa sì che è buffa... Non è che ti dispiacerebbe, {name}, farmi un ultimo favore?", 0xef0caa5c, 0x7d5b3c3e, 0x6aadc3c6, 0x81548c58, 0x832ea7a7, "....." },
  [288] = { "La Terza Flotta", "Offri un Flagon of Mead al primo ufficiale Fitzsimmons.", "Un tempo ero primo ufficiale sulla Wave Mistress, nave di linea della Terza Flotta di Kul Tiras. La Flotta Maledetta. Maledetta, perché nel suo ultimo viaggio la flotta fu attaccata da draghi rossi. Draghi controllati dagli orchi!\n\nNon avevamo speranze contro quel fuoco di drago... e la nostra flotta fu bruciata e affondata al largo di questa costa. Sono l'unico sopravvissuto di quelle povere navi...\n\n...Oh, la testa mi martella e mi pulsa! Mi serve un altro goccio se voglio tenere a bada questi postumi e continuare la mia storia.", "Oh, che sete terribile! Non offriresti da bere a questo povero, patetico sciocco?", "Ah! Questo sì che ci voleva, e scioglie pure la lingua. Grazie, compare!", 0xd344ba5e, 0x9f386e77, 0x4f64105d, 0x0916d95e, 0x77f68422, "....." },
  [289] = { "L'equipaggio maledetto", "Uccidi 13 Cursed Sailor, 5 Cursed Marine e First Mate Snellig. Porta la ⟦Snellig's Snuffbox=Scatola di Tabacco di Snellig⟧ al primo ufficiale Fitzsimmons, al ⟦Menethil Harbor=Porto di Menethil⟧.", "<Rinfrancato, Fitzsimmons continua il suo racconto...>\n\nSono l'unico superstite della sventurata Terza Flotta di Kul Tiras, naufragata al largo della costa, a nord. Ma anche se sono l'unico della flotta che respira ancora, non sono l'unico che va ancora in giro! Su una delle nostre navi era nascosto un tesoro grande e terribile, e il suo potere sinistro tiene le anime dei miei fratelli prigioniere negli scafi marci delle navi.\n\nMa se riesci a liberare alcuni dei miei fratelli, forse potrai spezzare la loro maledizione.", "Nei miei sogni a volte sento i lamenti disperati dei miei fratelli! Ti prego, <buon/buona> <signore/signora>, liberali dalle catene e placa le loro grida.", "Ti ringrazio, {name}. E ricevi anche la gratitudine dei miei fratelli maledetti.", 0x0118d790, 0x450465a8, 0x35bb2a47, 0x9a98af9c, 0xaaba9d50, ".....", nil, nil, nil, 0xa3fe69e6, nil },
  [290] = { "Spezzare la maledizione", "Ottieni la ⟦Intrepid Strongbox Key=Chiave del Forziere dell'Intrepida⟧ dal capitano Halyndor.\n\nUsa la chiave per aprire l'Intrepid's Locked Strongbox.", "Per spezzare la maledizione e liberare tutti i miei compagni, la... cosa... nascosta sulla mia nave deve essere recuperata e purificata! Non so cosa fosse, ma so che era custodita al sicuro nel forziere della nave, su cui vegliava il capitano Halyndor.\n\nIl mio vecchio capitano è ancora nei miei sogni. So che si aggira sulla mia nave maledetta, l'Intrepida. Prendi la chiave da lui e usala per aprire il forziere dell'Intrepida.\n\nPoi, quando avrai la cosa maledetta, portala al sacerdote Glorin Steelbrow, in città.", "Questo scrigno è chiuso saldamente a chiave.", "La chiave è arrugginita, ma entra perfettamente nella serratura.", 0x67d85feb, 0x99644b95, 0x74e1986b, 0x24ee971a, 0xfcdb2cc9, "....." },
  [291] = { "I rapporti", "Consegna il rapporto di Senir al senatore Barin Redstone, a ⟦Ironforge=Forgiardente⟧.", "Ottimo! Porta il mio rapporto al senatore Barin Redstone. È un tipo scorbutico, quindi non farti abbattere dal suo carattere poco solare. Lo trovi a ⟦Ironforge=Forgiardente⟧, nella sala dove re Magni tiene udienza.\n\nNon conosci la strada per ⟦Ironforge=Forgiardente⟧? Esci da Kharanos prendendo la strada a nord, attraversa il ponte e poi segui la strada verso est (ci sono grandi stendardi ai lati) su per il fianco della montagna.\n\nE già che ci sei, potresti evitare di dire che mi hai aiutato? Non posso lasciargli pensare che qui non lavori sodo, capisci?", "Mm... a quanto pare le mie guardie stanno diventando meno esigenti con chi viene a supplicare. Be', che cosa vuoi? Sbrigati.", "<Scorre rapidamente il rapporto.>\n\nL'autorità del RE!? Magni ha perso del tutto il senno?! E quel dannato Whitebeard... Ha preso in mano la situazione, eh? Il Senato non sarà affatto contento di saperlo, per niente.\n\nCosa, sei ancora qui? Vattene, prima che chiami le guardie!", 0xdad7b810, 0xaeae0022, 0x237d8c9e, 0x1abc830a, 0xe6cf8786, "....." },
  [292] = { "L'⟦Eye of Paleth=Occhio di Paleth⟧", "Porta l'⟦Cursed Eye of Paleth=Occhio di Paleth Maledetto⟧ a Glorin Steelbrow.", "Aprendo lo scrigno compare un globo annerito, che pulsa di una luce sinistra. È il tesoro di cui parlava Fitzsimmons: un ⟦Cursed Eye of Paleth=Occhio di Paleth Maledetto⟧.\n\nPorta l'⟦Cursed Eye of Paleth=Occhio di Paleth Maledetto⟧ al sacerdote nanico Glorin Steelbrow, a ⟦Menethil Harbor=Porto di Menethil⟧. Chiedigli come togliere la maledizione dall'Occhio.", "Quell'ubriacone di Fitzsimmons ti ha mandato da me? Be', puoi dirgli che non ho birra da avanzare. Dovrà andare a scroccare da qualcun altro!", "Un ⟦Eye of Paleth=Occhio di Paleth⟧? Straordinario! Mmm... c'è qualcosa che non va in questo. L'hai trovato su uno di quei relitti? Be', questo spiega tutto! Però... non sapevo che ci fosse un Occhio del genere nella Terza Flotta...\n\nNon c'è da stupirsi che Fitzsimmons fosse così spaventato. Un ⟦Cursed Eye of Paleth=Occhio di Paleth Maledetto⟧ non è certo motivo di allegria.", 0xc0c774ae, 0x82ab47a4, 0x610cc5e1, 0xd79890d9, 0x4fe3c3df, "....." },
  [293] = { "Purificare l'Occhio", "Porta l'⟦Cursed Eye of Paleth=Occhio di Paleth Maledetto⟧ all'arcivescovo Benedictus. Benedictus si trova nella ⟦Cathedral of Light=Cattedrale della Luce⟧, nella città di ⟦Stormwind=Roccavento⟧.", "Non riesco a togliere la maledizione dall'⟦Eye of Paleth=Occhio di Paleth⟧. Gli Occhi furono creati da sacerdoti umani, quindi dovrai andare a ⟦Stormwind=Roccavento⟧ per trovare qualcuno che possa aiutarti. Parla con l'arcivescovo Benedictus. È a capo della ⟦Cathedral of Light=Cattedrale della Luce⟧, a ⟦Stormwind=Roccavento⟧. Lui può aiutarti.\n\nLo spero, per il tuo bene.", "Cos'è quel globo che hai? Sembra... contaminato.", "Un ⟦Eye of Paleth=Occhio di Paleth⟧. Ma questo ha visto molto dolore... dev'essere stato testimone di una terribile, terribile tragedia.\n\nLascia che lo purifichi, perché gli Occhi furono creati per risplendere, e i loro poteri possono essere molto pericolosi se contaminati come questo.", 0x2f74c1ea, 0xbdcdebd1, 0x6e4ad21f, 0xed3db153, 0x32563e90, "....." },
  [294] = { "La vendetta di Ormer", "Ormer Ironbraid, agli Scavi di Whelgar, vuole che tu uccida 10 Mottled Screecher e 10 Mottled Raptor.", "La situazione è grave, questo è certo. Quando abbiamo dissotterrato queste ossa, abbiamo attirato i raptor. Quelle bestie schifose hanno ucciso i miei compagni e hanno intrappolato quassù me, Merrin e il povero prospettore.\n\nAiutaci a liberare le ⟦Wetlands=Paludi Grigie⟧ da questi raptor, {name}. I Mottled Raptor e i Mottled Screecher sono appena a ovest di quell'altura. Uccidine 10 per tipo, se ci riesci.\n\nSarà un buon inizio per la vendetta che ho in serbo per loro.", "Uccidi 10 Mottled Raptor e 10 Mottled Screecher, {name}. I miei compagni di lavoro non meritavano la fine che hanno fatto. È ora di pareggiare i conti.", "Uccidere è un lavoro sporco, ma hai fatto bene il tuo, {name}. Se non fossi obbligato a restare con il prospettore e con Merrin, sarei laggiù a versare sangue al tuo fianco.", 0x9f3d027d, 0x635d743b, 0x5fa2aa4a, 0x3737f909, 0x4931c25a, "....." },
  [295] = { "La vendetta di Ormer", "Ormer Ironbraid vuole che tu uccida 10 raptor Mottled Scytheclaw e 10 raptor Mottled Razormaw, poi torni da lui agli Scavi di Whelgar.", "Ora è il momento di far pentire davvero quei maledetti raptor della loro sete di sangue. Proprio qui sotto ci sono decine di Mottled Scytheclaw e Mottled Razormaw. Fagliela pagare a quelle bestiacce: uccidine 10 di ciascun tipo!", "Voglio far pagare a quei Mottled Scytheclaw e Mottled Razormaw quello che hanno fatto. Ne hai già uccisi 10 di ciascun tipo?", "Hai fatto un lavoro coi fiocchi a ripulire la zona da quei raptor, {name}!", 0x9f3d027d, 0xcc43a4ca, 0xe2f5b517, 0xedd86ff7, 0x8ba1a22c, "....." },
  [296] = { "La vendetta di Ormer", "Ormer Ironbraid, agli Scavi di Whelgar, vuole che tu uccida Sarltooth e che, a compito eseguito, torni da lui con uno dei suoi artigli.", "Mentre eri laggiù ho notato che una di quelle bestie spiccava sulle altre. Era più grossa e più minacciosa. Scommetto che è stata lei a guidare le altre fin qui a mettere a soqquadro gli scavi.\n\nTi chiedo un ultimo compito, {name}. Fa' in modo che Dentesauro sia consegnato alla giustizia. E vista la gravità dei suoi crimini, in questo caso giustizia vuol dire morte! Portami uno dei suoi artigli come prova della sua morte.", "Dentesauro è morto? Hai riscattato la memoria dei caduti?", "Grazie, {name}. I tuoi sforzi qui non saranno dimenticati. Molti nani innocenti sono morti in questo sito, mentre facevano semplicemente il loro lavoro. La vendetta che hai portato a quelle creature malvagie dovrebbe farle pensare due volte prima di attaccare di nuovo i sudditi di re Magni.", 0x9f3d027d, 0x55a6e9a9, 0xb18d561a, 0xa3d83fdb, 0xdef3baa5, "....." },
  [297] = { "Raccolta di idoli", "Porta a Magmar Fellhew 8 Carved Stone Idol.", "Di recente, poco prima che i trogg emergessero nel sito, avevamo portato alla luce un gran numero di strani idoli scolpiti. Ma non abbiamo avuto modo di studiarli, perché subito dopo la scoperta i trogg ci hanno cacciati dalle rovine! E quegli idoli hanno uno strano effetto sui trogg. Li fanno andare su tutte le furie!\n\nPortami 8 idoli: voglio studiarli, e li voglio fuori dalle mani dei trogg! Puoi trovarli addosso ai trogg che infestano il sito.", "Hai quegli idoli? Dobbiamo studiarli e riferire le nostre scoperte a ⟦Ironforge=Forgiardente⟧!", "Ce l'hai fatta! Ben fatto, {name}!\n\nE non sembri neanche troppo malconci<o/a>, con tutti quei trogg infuriati in giro. Ti terrò d'occhio... hai del potenziale.", 0x34178260, 0x0eaf668c, 0xf3ba4390, 0x2fd4cc59, 0xd1d1aa18, "....." },
  [298] = { "Rapporto sui progressi dello scavo", "Porta il ⟦Ironband's Progress Report=Rapporto sui Progressi a Ferrocollo⟧ a Jern Hornhelm, a Thelsamar.", "Devo mandare un rapporto sui progressi a Thelsamar: un rapporto sui progressi e una nuova richiesta di altra polvere esplosiva! Ecco il rapporto. Portalo a Jern Hornhelm. È il nostro contatto a Thelsamar.\n\nNon è un compito difficile, ma va fatto.", "Oh, un rapporto sui progressi dal sito? Ottimo!", "Bah! Ironband ha problemi con i trogg. Mi chiedo se voglia quella polvere esplosiva per aiutarsi negli scavi o nella lotta contro quelle bestie di trogg...\n\nBe', in ogni caso è polvere ben spesa!\n\nMa la cosa strana è che gli ho mandato un bel po' di polvere esplosiva settimane fa. Chissà dov'è finita...", 0xc9016865, 0x22803ca7, 0x4dd4de52, 0xe37dea91, 0x509d05e4, "....." },
  [299] = { "Alla scoperta del passato", "Il prospettore Whelgar vuole che tu setacci il sito di scavo in cerca dei 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru.", "Poco prima dell'invasione ho portato alla luce una grande tavoletta chiamata Goaz Stone. Il testo tradotto si interrompe in 4 punti. Parla di un «piano divino» e di una «profezia di sventura».\n\nTemo che il tempo stia per scadere. Sono troppo vecchio per scendere laggiù ad affrontare quelle bestie. Ma tu sei forte.\n\nSetaccia il sito di scavo e trova i 4 frammenti mancanti della tavoletta: Ados, Modr, Golm e Neru. Cercali negli antichi manufatti o dove il terreno è smosso. Portameli, così potrò cominciare a svelare il mistero!", "Hai già trovato i quattro frammenti, {name}? Ados, Modr, Golm e Neru...", "Ah, la Goaz Stone è completa! Ottimo lavoro, {name}. Davvero ottimo. Ora posso proseguire con la delicata traduzione di questa scrittura dei Titani. Riesco già a distinguere parole nuove! Mmm... qui dice: «Dei Antichi... Incatenati Sotto la Terra». Questo è l'inizio di qualcosa di epico.", 0xd591b8f3, 0x9774ad41, 0xdce1b81f, 0x1bd68c28, 0x5c615bf5, "....." },
  [301] = { "Rapporto a ⟦Ironforge=Forgiardente⟧", "Porta il ⟦Ironband's Progress Report=Rapporto sui Progressi a Ferrocollo⟧ al prospettore Stormpike.", "Ci servirà un'autorizzazione per dare a Ironband altra polvere esplosiva. Dovrai portare il suo rapporto al quartier generale della ⟦Explorers' League=Lega degli Esploratori⟧, a ⟦Ironforge=Forgiardente⟧.\n\nEcco il rapporto. Consegnalo al prospettore Stormpike, e non dimenticare di abbassarti dopo averglielo dato. Stormpike è una testa calda, e non sarà contento di sapere che Ironband va così a rilento con lo scavo.\n\nTroverai Stormpike nell'Assembly of Explorers.", "A noi Stormpike non piace essere disturbati per questioni insignificanti, {class}. Spero che tu abbia portato notizie degne della mia preziosa attenzione.", "Maledetto Ironband! Gli ho mandato un carico di polvere esplosiva settimane fa, ma in questo rapporto non ne fa parola.\n\nE allora... dov'è finita la polvere esplosiva?!?", 0x7f3b765a, 0x08c53212, 0xdc3ccebc, 0xd762c5af, 0x79fbe892, "....." },
  [302] = { "Polvere per Ironband", "Parla con Jern Hornhelm, a Thelsamar.", "Se Ironband ha ancora bisogno di polvere esplosiva, per Magni, l'avrà! Ho già mandato l'autorizzazione con un messaggero a Jern Hornhelm, a Thelsamar. Lui preparerà la polvere e le altre provviste da portare a Ironband.\n\nE un'altra cosa: voglio che tu ti assicuri di persona che il carico di polvere arrivi a destinazione. L'ultimo non c'è arrivato, quindi tieni la mente sveglia e gli occhi aperti.", nil, "Cosa? Stormpike vuole che tu accompagni di persona il carico fino a Ironband?\n\nBe'... immagino che vada bene, l'unico problema è che ho già mandato Huldar con i portatori, Miran e Saean. Li hai mancati per poco, sono partiti da pochissimo.", 0xf6a7639f, 0x990221eb, 0x8208845e, nil, 0xe08e3029, "...m." },
  [303] = { "La guerra dei ⟦Dark Iron=Ferroscuro⟧", "Motley Garmason, a Dun Modr, vuole che tu uccida 15 ⟦Dark Iron Dwarves=Nani Ferroscuro⟧, 5 Dark Iron Tunneler, 5 Dark Iron Saboteur e 5 Dark Iron Demolitionist.", "La guerra infuria in patria e all'estero. Mentre i possenti soldati nanici danno la vita in terre lontane in nome dell'⟦Alliance=Alleanza⟧, le nostre terre cadono preda delle malefatte dei ⟦Dark Iron Dwarves=Nani Ferroscuro⟧. Hanno devastato il ⟦Thandol Span=Viadotto di Thandol⟧. Poco dopo è caduta Dun Modr.\n\nDevi raccogliere le forze e ricacciare indietro il fronte. Se riesci a uccidere 15 ⟦Dark Iron Dwarves=Nani Ferroscuro⟧, 5 minatori, 5 sabotatori e 5 guastatori, i rinforzi potrebbero arrivare in tempo per completare l'avanzata.\n\nOra sbrigati!", "Roggo non è riuscito a contattare i rinforzi. Dobbiamo tenere sotto pressione quell'accampamento dei ⟦Dark Iron=Ferroscuro⟧, {class}. Ora torna là fuori e fa' il tuo dovere per re Magni!", "Hai eseguito bene i tuoi ordini, {class}. Hai dato prova di valore come soldato e di lealtà verso re Magni, e per questo ti saluto! Con la pressione che hai esercitato sull'accampamento dei ⟦Dark Iron=Ferroscuro⟧, ora abbiamo la possibilità di cacciarli dalle nostre terre per sempre... se solo quei dannati rinforzi si facessero vivi...", 0xb421cac2, 0xfb9fbc0f, 0x6d3dee8c, 0xbeddfaae, 0xf0eb01de, "....." },
  [305] = { "Alla ricerca della squadra di scavo", "Tarrel Rockweaver vuole che tu vada al sito di scavo e contatti Merrin Rockweaver.", "Non puoi immaginare quanto sia stato in pensiero.\n\nMia moglie, Merrin, mi ha mandato una lettera ogni settimana per tutto l'ultimo mese. Fa parte della squadra degli Scavi di Whelgar. Ma sono passate quasi due settimane dalla sua ultima lettera. Di sicuro c'è qualcosa che non va!\n\nLongbraid ha detto che avrebbe mandato un esploratore a controllare, se non avessimo avuto presto notizie della squadra. Immagino che quell'esploratore sia tu, {name}. Trova Merrin al sito di scavo, a est!", nil, "Oh, sia ringraziato il cielo, sei qui!", 0x1719a646, 0x2d2e1e26, 0x39755cdf, nil, 0xe6062395, "...m." },
  [306] = { "Alla ricerca della squadra di scavo", "Torna da Tarrel Rockweaver con il biglietto di Merrin.", "È stato orribile! Stavamo portando alla luce dei manufatti rari e abbiamo cominciato a scoprire queste grandi ossa.\n\nPrima che capissimo cosa stava succedendo, i Mottled Raptor hanno invaso lo scavo. Abbiamo perso molte vite.\n\nOrmer, qui, così coraggioso, ha salvato me e il prospettore. Ci ha difesi mentre correvamo al riparo. Ora siamo intrappolati. E tutto il nostro duro lavoro è andato in rovina.\n\nEcco, porta questo biglietto al mio dolce Tarrel. Gli spiegherà la situazione.", "Sei riuscit<o/a> a trovare Merrin? Ti ha dato notizie per me?", "Che notizie orribili! Almeno 3 di loro sono sopravvissuti. Ma quando finiranno le uccisioni? Sogno il giorno in cui i sudditi di re Magni potranno vivere senza paura.", 0x1719a646, 0x8401118b, 0x88a97402, 0x78ff4985, 0x07626a00, "....." },
  [307] = { "Zampe sudicie", "Va' alla ⟦Silver Stream Mine=Miniera Vena d'Argento⟧ e raccogli 4 carichi di ⟦Miners' Gear=Equipaggiamento dei Minatori⟧.\n\nTorna dal montanaro Stormpike.", "La ⟦Silver Stream Mine=Miniera Vena d'Argento⟧, a est, si è esaurita molto tempo fa. La Miners' League l'ha trasformata in un deposito, ma ora ci si sono stabiliti i coboldi, che mettono le loro zampe sudicie su ottimi attrezzi nanici!\n\nPresto staneremo quei parassiti, ma la Miners' League vuole che qualcuno porti fuori la sua attrezzatura dalla miniera prima che noi guerrieri ci entriamo e mandiamo tutto in pezzi. Sarà una discesa dura: forse ti conviene avere dei compagni al tuo fianco.\n\nL'attrezzatura è custodita nelle Miners' League Crate sparse per la miniera. Buona fortuna.", "Hai l'⟦Miners' Gear=Equipaggiamento dei Minatori⟧, {name}?", "Hai visto tanti coboldi là dentro? Non vedo l'ora che arrivi l'ordine di cacciarli dalla miniera. Il pensiero delle loro manacce sudicie che frugano nella nostra miniera mi fa brontolare lo stomaco!", 0xe6dfbab1, 0x6239462b, 0x8b70f766, 0x83e3d7a0, 0x6be768cd, "....." },
  [308] = { "Distrarre Jarven", nil, nil, "Uff! C'è tutto questo alcol qua sotto, ma ho l'ordine tassativo di non toccarlo. Se solo potessi assaggiare un po' della nostra ⟦Thunder Ale=Birra del Tuono⟧... mi schiarirebbe le idee, parola mia!", "Per me? Sei <un/una> <vero/vera> <eroe/eroina>, {name}!", 0xef7d7727, nil, nil, 0xd7c692ec, 0xe0ee940d, ".mm.." },
  [309] = { "Proteggere il carico", "Assicurati che Miran e il carico arrivino al sito di scavo, poi informa il prospettore Ironband.", "Pront<o/a> a partire, {name}?\n\nPrima di tutto, dobbiamo portare questa polvere a Ironband. Sarà un bel carico da portare per me, e queste zone possono diventare pericolose... e chissà cos'altro potrebbero avere in serbo per me i Ferroscuro.\n\nMi sentirò molto più tranquillo se vieni con me.", "Dov'è la mia polvere, {name}? Ogni giorno il mio bisogno si fa più disperato.", "Oh, sia lodata la Luce, la polvere è arrivata. Ma porti anche notizie preoccupanti. E pensare che i Ferroscuro hanno simpatizzanti capaci di procurare questo genere di materiale per i loro piani infami.\n\nÈ una questione che dovrà valutare qualcun altro, un'altra volta. Io devo fare buon uso di questa polvere.", 0x086b0483, 0xbcb09af3, 0xaf7d4d4e, 0xcad7bca5, 0x0c439c60, "....." },
  [310] = { "Rivali acerrimi", "Nello scantinato della ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ a Kharanos, sostituisci un barile di ⟦Thunder Ale=Birra del Tuono⟧ con un ⟦Barrel of Barleybrew Scalder=Barile di Ustionante dei Maltorzo⟧.", "Devo ammetterlo, quei Thunderbrew fanno delle buone bevande. Ma devono imparare che la loro non è l'unica birra decente! Forse puoi aiutarmi a dar loro una lezione...\n\nEcco, prendi questo barile di ⟦Barleybrew Scalder=Ustionante dei Maltorzo⟧. Intrufolati nello scantinato della ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ a Kharanos e scambialo con uno dei loro barili di ⟦Thunder Ale=Birra del Tuono⟧. Poi vedremo se ai loro clienti piacerà più la mia birra della loro!\n\nE se i barili sono sorvegliati, forse dovrai distrarre la guardia...", "La data su questo barile indica che verrà spillato presto.", "Metti in fretta il barile di ⟦Barleybrew Scalder=Ustionante dei Maltorzo⟧ di Marleth tra i barili dei Thunderbrew.", 0xf6727a81, 0x0eee3138, 0x4aba5129, 0x1e29e7f1, 0x61e614ef, "....." },
  [311] = { "Ritorno da Marleth", "Porta il barile di ⟦Thunder Ale=Birra del Tuono⟧ a Marleth Barleybrew a ⟦Brewnall Village=Borgo Luppolo⟧.", "Dopo aver piazzato un barile dell'Ustionante di Marleth nella cantina della distilleria di Kharanos, prendi un barile di ⟦Thunder Ale=Birra del Tuono⟧ come prova dell'impresa...", "Hai fatto lo scambio?", "Niente male, {name}! Hai avuto difficoltà a superare la loro guardia?\n\nNon importa: mille grazie, e se mai avrai bisogno di una birra scura che ti dia la carica, non dimenticare i Barleybrew!", 0x3a28c9e8, 0xf80b297f, 0x6e9701ee, 0x31a1b899, 0x1b072cf7, "....." },
  [312] = { "La scorta rubata di Tundra MacGrann", "Recupera la carne secca di Tundra MacGrann dalla dispensa rubata nella grotta di Old Icebeard.", "Avevo un mese di carne secca, salata e chiusa sotto chiave per la stagione fredda. La tenevo chiusa perché gli orsi non ci arrivassero! Ma mentre ero a caccia di cervi, quella bestiaccia, Old Icebeard, si è portato via la dispensa. Il torio non riuscirà a sfondarlo, però. Ma io morirò di fame se non mi riprendo la mia carne.\n\nTu sembri un po' più furtiv<o/a> di me. Forse puoi recuperare la mia scorta? Con questa gamba malandata non riuscirei mai a entrare e uscire da quella grotta abbastanza in fretta.", "Sei riuscit<o/a> a entrare nella mia dispensa, {name}?", "Che anima generosa sei, {name}! Grazie al tuo coraggio non morirò di fame quando arriveranno le bufere della stagione fredda.", 0x992959f9, 0x5b0707e1, 0xa3f43510, 0x754c3b09, 0xd5b6ac1e, "....." },
  [313] = { "La ⟦The Grizzled Den=Tana Selvaggia⟧", "Raccogli 8 Wendigo Mane e portali al pilota Stonegear.", "Guidare una macchina d'assedio non è da tutti. Ci vogliono una presa di ferro e nervi d'acciaio... per fortuna io li ho entrambi! E tu? Che fegato hai? Vuoi dimostrarmelo?\n\nBe'... sto cercando di rendere la mia macchina, Trollplow, un po' più accogliente. Che ne dici di procurarmi un bel mucchio di criniere di wendigo dalla Tana Selvaggia, a ovest di Kharanos? Quelle criniere sarebbero un tappeto perfetto per il ponte interno di Trollplow!", "Ehi, {name}. Sei già <stato/stata> alla Tana Selvaggia? Quei wendigo sanno essere feroci.", "Ah sì, queste criniere andranno benissimo! Hai molta grinta, {class}: scommetto che farai grandi cose.", 0x9d1372af, 0xa90aa758, 0xac88ca21, 0xb2b8b4b1, 0x6f400b46, "....." },
  [314] = { "Proteggere il gregge", "Rudra Amberstill vuole che tu uccida Vagash e le porti la sua zanna al ranch degli arieti.", "Abbiamo sentito le grida nel cuore della notte. E stamattina, come temevamo, al gregge mancavano due arieti. Quella bestia infame che chiamano Vagash sta divorando il nostro sostentamento. Con gran parte dell'esercito di re Magni in terre lontane a combattere con l'⟦Alliance=Alleanza⟧, non c'è nessuno che tenga a bada Vagash.\n\nForse tu hai il coraggio di cercare la bestia e ucciderla. Portami una delle sue zanne e ti ricompenserò. Vagash si aggira proprio sopra il ranch, ma fai attenzione: è letale.", "Vagash terrorizza ancora il gregge! Ti prego, aiutaci uccidendo quella bestia maledetta.", "Ottimo lavoro! Veron sarà felicissimo quando sentirà la bella notizia. Uccidere Vagash non è un'impresa facile. Immagino che un giorno combatterai al fianco degli uomini di re Magni sul fronte dell'⟦Alliance=Alleanza⟧.", 0xefa031f4, 0x2475a572, 0x9f0339dd, 0xf712a472, 0x3bc82f3e, "....." },
  [315] = { "La birra scura perfetta", "Porta 6 Shimmerweed a Rejold Barleybrew a ⟦Brewnall Village=Borgo Luppolo⟧.", "Ho una missione: creare la birra scura perfetta. So di potercela fare: la birra ce l'ho nel sangue. Devo solo trovare la ricetta giusta...\n\nI troll ⟦Frostmane=Mantogelido⟧ coltivano una pianta, la shimmerweed, in alto sulle colline a est. La usano nei loro strani rituali tribali. Noi nani non ne abbiamo mai trovato un grande uso, ma ha un gusto unico... e voglio sperimentarla nelle mie birre!\n\nProcurami un po' di shimmerweed dai veggenti ⟦Frostmane=Mantogelido⟧, oppure sgraffignala dai cesti di shimmerweed dei troll.", "Hai quella shimmerweed? Ho quasi pronta una partita di birra scura da fermentare e voglio provare a buttarci dentro l'erba.", "Fantastico! Non vedo l'ora di usarle in qualcuna delle mie ricette. Ce n'è una in particolare in cui credo che andrà benissimo...", 0xadc5e20f, 0xfc736db3, 0x4c0b4974, 0xc1da3265, 0x068f94a8, "....." },
  [317] = { "Rifornimenti per Jetsteam", "Raccogli 4 Chunk of Boar Meat e 2 Thick Bear Fur e consegnali al pilota Bellowfiz allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧.", "Mi sto preparando a partire per una missione della Siege Brigade. Sarà lunga, e devo rifornire Jetsteam di provviste per un mese. Allora, mentre Steelgrill lavora al mio carro armato, puoi andare a caccia per me?\n\nMi servono pellicce per i giacigli e carne di cinghiale da mangiare. La carne la prendi dai cinghiali e le pellicce dagli orsi... li trovi entrambi nei campi innevati a sud della Tana Selvaggia.", "I preparativi procedono bene. Come va la caccia?", "Per la barba di Magni, ne hai fatta di caccia!! Grazie, {name}.", 0x9298abb1, 0x763455c2, 0x6304c52d, 0xf79f8e14, 0xf15f9d6d, "....." },
  [318] = { nil, "Procurati un barilotto di Evershine da Rejold Barleybrew a ⟦Brewnall Village=Borgo Luppolo⟧.", "Rejold Barleybrew fa esperimenti con le sue birre. Alcune sono buone, altre cattive, e alcune... be', alcune stenderebbero chiunque tranne il più robusto dei nani.\n\nVive a ⟦Brewnall Village=Borgo Luppolo⟧, a ovest di Kharanos, e una delle sue bevande, l'Evershine, è proprio quella che voglio. Mi aiuterà a tenermi al caldo sulla strada gelida.\n\nE... quella benedetta roba brucia così forte che posso buttarla nella fornace di Jetsteam per avere un'esplosione di potenza! Questo trucchetto mi ha tirato fuori da più di un guaio.", nil, "Bellowfiz vuole un po' del mio Evershine? Mm... va bene.", 0xab586d5c, 0xcb9ca884, 0x9b9623a7, nil, 0x0bdd12f0, "e..m." },
  [319] = { "Un favore in cambio di Evershine", "Uccidi 6 Ice Claw Bear, 8 Elder Crag Boar e 8 Snow Leopard, poi torna da Rejold Barleybrew a ⟦Brewnall Village=Borgo Luppolo⟧.", "Ho un barile di Evershine a portata di mano, ma... puoi farmi un favore? A Borgo Luppolo servirebbe una mano contro gli animali selvatici che vagano per le nevi qui intorno. A volte si avvicinano troppo.\n\nNon abbiamo paura di questi orsi, felini e cinghiali (nessun nano che si rispetti ne avrebbe), ma se tu potessi occuparti di quelle bestie per noi, avremmo più tempo per i nostri lavori e le nostre birre.", "Ti sei occupat<o/a> di quegli animali selvatici?", "Grazie, {name}. Sarà bello lavorare ai nostri mestieri senza sentire tanti ringhi e grugniti fuori dal villaggio.", 0x46ebb913, 0xe3630b84, 0xe551b5b9, 0x8630896b, 0x1e4bad26, "....." },
  [320] = { "Ritorno da Bellowfiz", "Consegna il barile di Evershine al pilota Bellowfiz allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧.", "Ecco il tuo barile di Evershine, {name}. E grazie ancora per la caccia di prima.", "Hai preso quell'Evershine?", "Sì, andrà benissimo. Credo che aprirò subito una bottiglia per assaggiarla...", 0xb3dbad35, 0x289b7cd5, 0x0fbc74dc, 0x8ef21aef, 0xf157f980, "....." },
  [321] = { "Ferro della Forgia della Luce", "Perquisisci il relitto della Flying Osprey nelle ⟦Wetlands=Paludi Grigie⟧.", "I relitti al largo di questa costa sono ciò che resta della sventurata Terza Flotta di Kul'Tiras, incendiata e affondata dai draghi rossi durante l'ultima Grande Guerra.\n\nLa Flotta veniva da Lordaeron, ma con lei c'era anche una nave da guerra elfica, la Flying Osprey. Trasportava un carico di ferro della Forgia della Luce e si era unita alla Terza Flotta per avere protezione. Ironia della sorte, è affondata per mano degli stessi draghi...\n\nBasta con la storia. Il relitto della Flying Osprey si trova a sud del ⟦Menethil Harbor=Porto di Menethil⟧. Se lì trovi il ferro della Forgia della Luce, portamelo.", nil, "Questo forziere è fradicio e ha le assi rotte. Molti segni di artigli ne sfregiano l'interno e l'esterno... come se dei murloc ci avessero frugato dentro e ne avessero rubato il tesoro.\n\nMa nascosto in fondo al forziere c'è un solo ⟦Lightforge Ingot=Lingotto della Forgia della Luce⟧. Purtroppo ne serviranno molti altri per avere abbastanza metallo da forgiare un'arma.", 0x2c43f553, 0x90913df9, 0x4f73f4fe, nil, 0x43d7effb, "...m." },
  [322] = { "Un'arma benedetta", "Porta la ⟦Crate of Lightforge Ingots=Cassa di Lingotti della Forgia della Luce⟧ a Grimand Elmore, a ⟦Stormwind=Roccavento⟧.", "Nel Dwarven District di ⟦Stormwind=Roccavento⟧ c'è un Fabbro d'Armi nanico che sa lavorare il ferro della Forgia della Luce. Si chiama Grimand Elmore.\n\nHo messo il ferro che hai trovato in una cassa. Portala a Grimand e raccontagli la tua storia. Sono sicuro che vorrà aiutare chi è impegnato in una missione come la tua e ti forgerà un'arma... un'arma che farà preoccupare perfino Morbent Fel!", "Come posso mettere la mia arte al tuo servizio, {class}?", "Che storia, la tua. E ferro della Forgia della Luce! Sono anni che non lavoro un metallo simile. Sarà un onore forgiarlo di nuovo. E dovrai tornare da me più tardi a raccontarmi della tua battaglia contro il negromante.\n\nMa non corriamo troppo. Prima, la tua arma contro Morbent Fel...", 0xc00e26ec, 0xfe21b562, 0x8155f944, 0xbc274cdc, 0xcdab21ec, "....." },
  [323] = { "La prova del tuo valore", "Uccidi 15 Skeletal Raider, 3 Skeletal Healer e 3 Skeletal Warder, poi torna da Sven.", "Morbent Fel è un negromante, alleato dei cavalieri oscuri. Vorrei metterti contro il potere di Morbent Fel, ma non ti manderò contro quel vile demonio senza prima conoscere la tua forza.\n\nMi hai già dimostrato il tuo coraggio, ma se vuoi davvero affrontare il negromante, ora devi dimostrare la tua abilità contro i suoi servitori.", "Combatti con tenacia, {name}. E non disperare, perché la disperazione è l'arma più potente del male.", "La tua abilità in combattimento, {name}, è fuori discussione. La tua determinazione potrebbe ancora condurci fino alla fine di Morbent Fel!", 0x2b69e0a3, 0xe93db108, 0xa4fe1361, 0x3028a831, 0x850f6fbf, "....." },
  [324] = { "I lingotti perduti", "Raccogli 5 Lingotto della Forgia della Luce, poi torna da Glorin Steelbrow nelle ⟦Wetlands=Paludi Grigie⟧.", "Hai preso l'unico lingotto della Forgia della Luce rimasto nel forziere fradicio: è chiaro che i murloc hanno rubato il resto. Da' la caccia ai predoni murloc vicino al relitto della Flying Osprey per recuperare il ferro della Forgia della Luce perduto.", "Hai trovato il ferro della Forgia della Luce che ti serve?", "Ah, li hai trovati! Ora battiamo questo ferro della Forgia della Luce e ricaviamone qualcosa di utile, eh?", 0xbad55a3a, 0x3e3da78f, 0x3c29b98a, 0x0a6e75bf, 0x67c1cb55, "....." },
  [325] = { "Armi in pugno", "Porta l'⟦Morbent's Bane=Anatema di Morbent⟧ a Sven, a ⟦Duskwood=Boscovespro⟧.", "Ecco l'arma contro il demone di cui mi hai parlato. Sei pront<o/a>, {name}. Buona fortuna, e non vedo l'ora di sentire il racconto della tua gloria!", "Salve, {name}. Non sei stat<o/a> via molto, ma vedo nei tuoi occhi un fuoco che prima non c'era.", "Ah, questa sarà efficace contro il demone Morbent Fel! Ben fatto!\n\nSei pront<o/a>. Morbent Fel cadrà.", 0x87f2ec41, 0xcc976788, 0xd24c2a78, 0xc11cc698, 0xad511684, "....." },
  [332] = { "Pubblicità di un'enoteca", "Va' all'enoteca Gallina Winery e porta a Suzetta Gallina il ⟦Wine Ticket=Buono per il Vino⟧ per avere una bottiglia di vino in omaggio.", "Se parli di vino con qualcuno, allora sai che noi Gallina vendiamo il miglior vino di ⟦Stormwind=Roccavento⟧. E non siamo lontani: siamo sempre nel ⟦Trade District=Quartiere del Commercio⟧, lungo gli splendidi canali della città.\n\nEcco, prendi questo volantino. Portalo a mia sorella Suzetta, nel nostro negozio, e avrai in omaggio una bottiglia del nostro famoso pinot nero. Non te ne pentirai!", "Salve e benvenut<o/a>, <signore/signora>. Hai già assaggiato uno dei nostri vini pregiati?", "Ah, quindi hai visto Renato? Bene, eccoti servit<o/a>, <signore/signora>. Una bottiglia del nostro pinot nero speciale. Non troverai niente di simile in tutta Azeroth!", 0xbef51e47, 0xa087845e, 0x1a55a490, 0x057eda77, 0xb3727db1, ".....", nil, nil, nil, 0x894606fa, 0xbccda04d },
  [333] = { "Rifornimenti per Harlan", "Va' alla Canal Tailor Shop e porta a Rema Schneider la ⟦Cloth Request=Richiesta di Stoffa⟧ di Harlan Bagley.", "Ultimamente gli affari vanno a gonfie vele. Sembra che tutti comprino armature e abiti robusti. Quasi si aspettassero una stagione fredda e dura...\n\nMa queste sono preoccupazioni per il futuro. Quello che mi preoccupa oggi è che sto finendo gli abiti a maglia da vendere. Mi serve un altro carico dal nostro fornitore.\n\nSe potessi portare questa richiesta a Rema Schneider, alla Canal Tailor and Fit Shop, te ne sarei davvero grato.", "Porti notizie dal signor Bagley?", "Qui dice che gli affari di Harlan vanno a gonfie vele. È una buona notizia, ma mi chiedo perché la gente abbia bisogno di tutte quelle armature. Non ho sentito parlare di guerra aperta... c'è qualcosa che i nobili non ci dicono?\n\nBeh, grazie per avermi portato la richiesta. Ecco il tuo compenso, e farò in modo che Harlan riceva le sue forniture.", 0xb45daef4, 0xe2e2a078, 0x90d86eed, 0xacbdeec7, 0x6c92f110, "....." },
  [334] = { "Un pacco per Thurman", "Va' da Larson Clothiers, nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧, e consegna a Thurman Schneider il suo Sewing Kit.", "Mio figlio Thurman è apprendista da Larson Clothiers, nel Quartiere dei Maghi. Oggi andava di fretta e ha dimenticato forbici e aghi. So che <un/una> {class} in gamba come te avrà compiti importanti da sbrigare, ma senza i suoi attrezzi Thurman non può fare il suo lavoro da apprendista!\n\nTi prego, {name}. Puoi portare a mio figlio il suo kit da cucito? Larson Clothiers è uno dei due negozi di abiti del Quartiere dei Maghi: è quello più all'interno, vicino alla Torre del Mago.", "Sei qui per comprare dei vestiti?", "Oh, maledizione! Pensavo che dimenticare il kit mi avrebbe liberato dal lavoro. Adesso mi sa che dovrò aiutare i Larson con il cucito...\n\nVabbè. Il divertimento verrà dopo, immagino.", 0x2f63edc3, 0x271cf18d, 0xdd0e9c55, 0x50590106, 0x82df6d32, "....." },
  [335] = { "Una nobile bevanda", "Zardeth the Black Claw vuole che tu gli porti una ⟦Tear of Tilloa=Lacrima di Tilloa⟧ da ⟦Darkshire=Borgoscuro⟧ e una ⟦Musquash Root=Radice Muschiata⟧ dalle ⟦Wetlands=Paludi Grigie⟧.", "Lord Wishock sta creando un bel trambusto nella House of Nobles. È venuto a sapere del nostro piccolo \"locale\" quaggiù e sta facendo pressioni per un'indagine completa. Ho un piano per tenere Wishock \"occupato\", ma mi servirà il tuo aiuto.\n\nNel Garden of Stalvan, alla periferia di ⟦Darkshire=Borgoscuro⟧, cresce un fiore. Questo piccolo fiore bianco è noto come ⟦Tear of Tilloa=Lacrima di Tilloa⟧. Mi servirà anche una ⟦Musquash Root=Radice Muschiata⟧, che si trova solo ai piedi delle cascate, molto più in basso della ⟦Stonewrought Dam=Diga di Pietrasalda⟧, nelle ⟦Wetlands=Paludi Grigie⟧.", "Presto Wishock raccoglierà abbastanza sostegno da crearci un sacco di guai. Sei riuscit<o/a> a ottenere la ⟦Tear of Tilloa=Lacrima di Tilloa⟧ o la ⟦Musquash Root=Radice Muschiata⟧?", "Eccellente! Questi sono davvero ottimi campioni!", 0xb74eb85e, 0x62942fae, 0xe7ffff8f, 0xcd7a22de, 0x7e0ff13b, "....." },
  [336] = { "Una nobile bevanda", "Porta la ⟦Black Claw Stout=Birra Scura Graffionero⟧ a lord Wishock nella Hall of Petitioners.", "Lord Wishock, come tutti gli uomini, ha le sue debolezze. La sua è la passione per i liquori. L'ipocrisia è sbalorditiva. Quello sciocco banale passa le giornate a cercare di far chiudere la nostra piccola \"taverna\", mentre le notti le passa al piano di sopra, accumulando un conto che non paga mai. Be', vediamo se gli piace questa bevanda speciale che ho preparato per lui: la Birra Scura Graffionero. È bella forte, {name}.\n\nPortagliela e vedi se gli piace. Molto probabilmente quel vecchio sciocco gironzola nella Hall of Petitioners.", "Non vedi che sono occupato? Le mie parole devono essere ascoltate! Sono molto importante per il futuro di questo Regno!\n\nOh... cos'hai lì? Sembra proprio una bevanda rinfrescante...", "Ah, grazie per avermi portato questa birra scura dall'aspetto squisito, serv<o/a>. Ecco un rame per te. Ora sparisci e lasciami godere la mia bevanda!", 0xb74eb85e, 0x53f90ba6, 0xda7b4013, 0x1b629e3f, 0x43acc741, "....." },
  [337] = { "⟦An Old History Book=Antico Libro di Storia⟧", "Restituisci il libro «La storia di ⟦Stormwind=Roccavento⟧» alla Biblioteca di ⟦Stormwind=Roccavento⟧.", "Anche se la copertina di questo libro è rovinata da graffi e incrostata di fango, sul dorso si legge ancora il titolo «La storia di ⟦Stormwind=Roccavento⟧». Aprendolo, sulla prima pagina si vede chiaramente il timbro della Biblioteca di ⟦Stormwind=Roccavento⟧.\n\nSembra che qualcuno abbia preso in prestito questo libro e non l'abbia mai restituito...", "Oh! Cos'è quel vecchio libro che hai lì? Posso vederlo??", "Oh, cielo! Questo libro non stava su questi scaffali da prima della ricostruzione di ⟦Stormwind=Roccavento⟧, anni fa. Andrà restaurato, naturalmente, è in pessime condizioni, ma sarei onorata di collocarlo nella nostra collezione di libri rari.\n\nGrazie, <signore/signora>. Accetta questo come compenso per aver restituito il libro!", 0x71dc094a, 0x1883e731, 0x53cae2d4, 0xf9cb11cb, 0x48ec99b2, ".....", nil, nil, nil, nil, 0x26f2965a },
  [343] = { "Un discorso sulla forza", "Va' alla Biblioteca Reale, nel Castello di ⟦Stormwind=Roccavento⟧, e parla con Milton Sheaf. Potrà trovarti il libro di metallurgia che serve a fratello Kristoff per il suo discorso.", "Terrò un discorso sulla Forza dello Spirito e vorrei citare alcuni passi di un particolare libro di metallurgia: «Tensioni d'Acciaio». Una copia di questo libro dovrebbe trovarsi nella Biblioteca Reale, all'interno del Castello di ⟦Stormwind=Roccavento⟧. Puoi recuperarla per me? Se sì, che le benedizioni della Luce siano con te!\n\nLa Biblioteca Reale è molto grande, ma il bibliotecario capo, Milton Sheaf, conosce ogni scaffale come fosse suo figlio. Parla con lui, ti troverà il libro.", nil, "Metallurgia? Ah sì, abbiamo molti libri sull'argomento, e siamo felici di aiutare fratello Kristoff con il suo discorso! Ora... qual era il libro che serviva al buon fratello?", 0x2aad28e2, 0x5b41f90b, 0xdb30b559, nil, 0xcfbcf25b, "...m." },
  [344] = { "Fratello Paxton", "Parla con fratello Paxton nell'⟦Northshire Abbey=Abbazia della Contea del Nord⟧.", "«Tensioni d'Acciaio»? Sì, conosco il libro. Davvero ottimo, scritto qualche decennio fa dal minatore nanico Margulf Blaggon. Passò gran parte della sua vita nelle profondità delle montagne di Khaz Modan, a scavare minerale. Un tipo sveglio!\n\nMa dov'ero rimasto? Ah sì, «Tensioni d'Acciaio»! Temo che il libro sia stato trasferito all'⟦Northshire Abbey=Abbazia della Contea del Nord⟧. Il custode della biblioteca dell'abbazia, fratello Paxton, voleva farne una copia per i suoi scaffali.\n\nMa è stato mesi fa. Chissà perché ci sta mettendo tanto...", nil, "Il signor Sheaf si chiede dove sia il suo libro? Be', è un tantino imbarazzante. Il libro ce l'ho io, ma sto ancora facendo la mia copia e non sono del tutto pronto a restituire l'originale!", 0x757cdd99, 0xed902b3e, 0x5c81c1f5, nil, 0x65a09975, "...m." },
  [345] = { "Scorte d'inchiostro", "Parla con il caposquadra Oslow a ⟦Lakeshire=Borgolago⟧ e chiedigli del ⟦Iron Ore=Minerale di Ferro⟧ di Rethban.", "Volevo finire la mia copia di «Tensioni d'Acciaio», ma...\n\nVedi, l'inchiostro per i libri che copio lo preparo io. È una mia ricetta: non cola, non sbava e asciuga molto in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi la copiatura, e non ho avuto modo di prepararne dell'altro!\n\nPer farne ancora mi serve il ⟦Iron Ore=Minerale di Ferro⟧ di Rethban delle ⟦Redridge Mountains=Montagne Crestarossa⟧. Di solito me lo fornisce il caposquadra Oslow, a ⟦Lakeshire=Borgolago⟧.", nil, "Ti serve cosa?? Forse non l'hai notato, ma siamo impegnati a rafforzare le difese di Borgolago e a riparare i danni dei recenti attacchi degli orchi. Se ti serve ⟦Iron Ore=Minerale di Ferro⟧ di Rethban, dovrai procurartelo da te!", 0x6436fa89, 0x9f82018f, 0xf8e115c5, nil, 0x6eaa5bf6, "...m." },
  [346] = { "Ritorno da Kristoff", "Torna da fratello Kristoff in Cathedral Square. Consegnagli il libro «Tensioni d'Acciaio».", "Ora che ho finito di copiare il libro, ecco l'originale di «Tensioni d'Acciaio». Grazie per la pazienza, e se vedi Milton, digli per favore che mi dispiace per il lungo ritardo.", "Sei riuscit<o/a> a trovare il libro?", "È proprio quello! Grazie, {name}. Che la Luce risplenda luminosa sul tuo corpo e sul tuo spirito!", 0x7914bcc7, 0xaffc7d2d, 0xa9d0a831, 0xf44efc87, 0xcfcb4f09, "....." },
  [347] = { "⟦Rethban Ore=Minerale di Rethban⟧", "Raccogli 5 carichi di ⟦Rethban Ore=Minerale di Rethban⟧ e portali a fratello Paxton nella biblioteca della ⟦Northshire=Contea del Nord⟧.", "Il ⟦Rethban Ore=Minerale di Rethban⟧ prende il nome dall'uomo che lo trovò per primo, Bart Rethban. Una volta fuso non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che alcuni scrivani usano per le loro tinture. Si trova nelle ⟦Rethban Caverns=Caverne di Rethban⟧, a nord di qui.\n\nDi solito ne abbiamo un po' in magazzino, ma siamo troppo impegnati a prepararci agli attacchi degli orchi per raccoglierne. E poi... ora nelle ⟦Rethban Caverns=Caverne di Rethban⟧ vivono gli gnoll di ⟦Redridge=Crestarossa⟧, e i loro Drudger raccolgono il minerale per conto loro.\n\nQuindi, se te ne serve, dovrai procurartelo da te.", "Hai il ⟦Rethban Ore=Minerale di Rethban⟧?", "Oh, splendido! Posso usare questo minerale per fare la mia tintura e poi finire di copiare «Tensioni d'Acciaio».\n\nGrazie, {name}!", 0x1452bc02, 0x66b7c48d, 0xcc491e42, 0xd2e294d7, 0x1dd5b437, "....." },
  [353] = { "La consegna per Stormpike", "Consegna il ⟦Package for Stormpike=Pacco per Piccatonante⟧ al montanaro Stormpike, a Loch Modan.", "Gli Stormpike sono un clan nanico rispettato, e sono noti per i loro gusti raffinati ed esigenti. Non c'è da stupirsi, quindi, che Gringer Stormpike, un montanaro di ⟦Ironforge=Forgiardente⟧, mi abbia commissionato un'arma.\n\nL'arma è pronta, ma... il montanaro Stormpike è lontano, nel lontano Loch Modan. Se hai in programma di viaggiare verso nord, potresti consegnargli questo pacco?\n\nNel suo ultimo messaggio, il montanaro Stormpike diceva di essere di stanza alla torre di guardia settentrionale di Loch Modan.", "Vieni fin da ⟦Stormwind=Roccavento⟧? Ho sentito che laggiù, nelle terre degli umani, la situazione si fa rischiosa, con briganti e orchi in giro. Il posto perfetto per un {class} che voglia dimostrare quanto vale!", "Ah! Allora Grimand ha finalmente finito la mia ascia! Non vedo l'ora di provarla su qualche trogg e coboldo!\n\nGrazie mille, {name}. Hai fatto molta strada per questa consegna. Ecco qualche moneta per il disturbo.", 0x8e577b92, 0xd5f60077, 0xab2b7ebb, 0xae7f0689, 0x2aedd325, "....." },
  [354] = { "Lutti in famiglia", "Porta i ⟦Gregor's Remains=Resti di Gregor⟧, i ⟦Nissa's Remains=Resti di Nissa⟧ e i ⟦Thurman's Remains=Resti di Thurman⟧ a Coleman Farthing, a Brill.", "La famiglia Agamand era la più prospera delle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Lavoravo nei loro mulini... prima della Piaga.\n\nQuando arrivò il Flagello, gli Agamand fortificarono la loro dimora e convinsero chi era al loro servizio a restare e aiutarli a difenderla. Fummo degli sciocchi, ma almeno sciocchi leali.\n\nGli Agamand, nella loro superbia, ci condannarono alla non morte. E ora sono servitori del Flagello!\n\nServi i Reietti sconfiggendo gli Agamand caduti preda della Piaga. Servi me portandomi i loro resti.", "Hai i resti degli Agamand? Quelle bestie maledette sono finalmente distrutte?", "La vendetta ha un sapore dolce, non credi? Quando hai distrutto gli Agamand, hai colto in loro qualche traccia di libero arbitrio? Lo spero. Spero che abbiano conosciuto la paura prima di essere annientati.\n\nÈ una speranza sciocca, lo so. Ma è una speranza che coltivo comunque.", 0x1206b2d7, 0x2456ccd8, 0x1a5741cd, 0x9da96eaf, 0x39237f36, "....." },
  [355] = { "Parla con Sevren", "Parla con il magistrato Sevren, a Brill.", "Mi hai dato i resti degli Agamand e hai soddisfatto la mia sete di vendetta. Ma i ⟦Agamand Mills=Mulini degli Agamand⟧ sono una minaccia per tutti i Reietti, non solo per me.\n\nHo parlato delle tue imprese contro gli Agamand al magistrato Sevren, e lui desidera parlarti.", nil, "Coleman parla bene di te, {name}, e racconta delle tue fortunate incursioni nei ⟦Agamand Mills=Mulini degli Agamand⟧.\n\nI Reietti hanno di nuovo bisogno dei tuoi talenti...", 0x54128fb3, 0xe10a8192, 0xbcf3fe44, nil, 0x4c5c4fc7, "...m." },
  [356] = { "Pattuglia di retroguardia", "Uccidi 8 Bleeding Horror e 8 Wandering Spirit, poi torna a fare rapporto a Linnea, al suo accampamento.", "I difensori della ⟦The Bulwark=Granbarricata⟧, che proteggono Tirisfal dalle ⟦Plaguelands=Terre Infette⟧, sono sempre all'erta. Ma a volte qualche creatura del Flagello riesce a sfuggire loro.\n\nIl nostro successo alla ⟦The Bulwark=Granbarricata⟧ dipende dal combattere su un solo fronte: non possiamo permettere un attacco alle spalle, né che la linea di rifornimento dei nostri difensori venga tagliata.\n\nAiuta la ⟦The Bulwark=Granbarricata⟧. Pattuglia verso est e uccidi ogni creatura del Flagello che trovi. Impegnati soprattutto alla ⟦Balnir Farmstead=Cascina dei Balnir⟧, a est. È diventata un rifugio per gli intrusi del Flagello.", "Hai un rapporto sulla tua pattuglia?", "Molto bene. I tuoi sforzi aiutano molto a tenere a bada il Flagello. Manderò un encomio al mio superiore, l'esecutore Zygand.", 0x889b08c3, 0x17b31481, 0x10a80db8, 0x7f3fa30a, 0xe62772cd, "....." },
  [357] = { "L'identità del lich", "Porta il grimorio del lich a Bethor Iceshard a ⟦Undercity=Sepulcra⟧.", "Sull'isola del ⟦Brightwater Lake=Lago di Acqualucente⟧, a nord, vive un lich. Pur essendo un Reietto dotato di libero arbitrio, crede che ogni altro Non Morto sia uno schiavo del Flagello e fa attaccare dai suoi servitori chiunque gli si avvicini.\n\nMa poiché è un Reietto, la Regina lo vorrà. E se è esperto di negromanzia, il suo sapere sarebbe... molto utile per noi.\n\nPer scoprire la sua identità e i suoi talenti devo vedere il suo grimorio. Intrufolati nel suo accampamento, prendilo e torna da me.", "{name}, ti sei procurat<o/a> il libro?", "Molto bene, {name}. Studierò questo libro e scoprirò l'identità di quel lich. Hai servito bene la tua Regina.\n\n<Bethor apre il libro e ne fissa intensamente le pagine luminose...>\n\nSorprendente! Il libro che hai recuperato appartiene nientemeno che a Gunther Arcanus!\n\nIn vita Gunther era un abile negromante; lui e io eravamo amici e compagni d'armi, prima della Piaga. E a giudicare dal suo libro, nella morte è diventato ancora più potente.\n\nLe sue abilità ci sarebbero di grande aiuto.", 0x77f697ac, 0x3216aabc, 0x0c4b7d62, 0x7639f1e5, 0x63fb2df0, "....." },
  [358] = { "Profanatori di tombe", "Uccidi i Rot Hide Graverobber e i Rot Hide Mongrel.\n\nPorta 8 Icore per Imbalsamazioni al magistrato Sevren a Brill.", "Le Mass Graves, a sud-ovest del ⟦Garren's Haunt=Covo di Garren⟧, più a nord, furono scavate per accogliere il... notevole... numero di morti che Tirisfal subì quando arrivò la Piaga.\n\nFinora i corpi in queste fosse sono stati risparmiati dalla non morte, ma ora il Flagello manda gli gnoll Rot Hide a raccogliere i cadaveri per rinforzare le sue armate. Non possiamo permetterlo!\n\nIl tuo compito è duplice: uccidi i Rot Hide alle Mass Grave e al ⟦Garren's Haunt=Covo di Garren⟧, e raccogli da loro l'⟦Embalming Ichor=Icore per Imbalsamazioni⟧ che dà loro la vita.", "Il tuo compito è concluso? Hai distrutto quelle specie di cani e li hai prosciugati del loro icore?", "Ottimo lavoro, {name}. Il Flagello si sbaglia se crede di poter usare quei cadaveri contro di noi, e il fluido che hai raccolto dagli schiavi Rot Hide sarà studiato dai nostri speziali. Potrebbe nascondere segreti da usare contro di loro.\n\nCome ho detto, ben fatto. Ma la nostra lotta continua, e il conflitto ti offrirà di certo altre occasioni per dimostrare il tuo valore ai Reietti.", 0xb5a1b5e8, 0x31835064, 0xdaef0d93, 0x150b25ca, 0xf3d4d59b, "....." },
  [359] = { "Doveri dei Reietti", "Parla con la Guardia della Morte Linnea.", "Mi serve un rapporto aggiornato dal nostro posto di guardia della Guardia della Morte, a est.\n\nDevo sapere se altre forze del Flagello sono sgusciate oltre la ⟦The Bulwark=Granbarricata⟧ e sono entrate a Tirisfal. La sorveglianza sul confine con le ⟦Plaguelands=Terre Infette⟧ va mantenuta: non possiamo permettere al Flagello di rafforzare la sua presenza qui!\n\nSegui la strada verso sud, poi al bivio prendi a est fino al posto di guardia. Parla con la Guardia della Morte Linnea. Ha le informazioni che mi servono.", nil, "Il magistrato Sevren vuole un rapporto? Molto bene: i difensori della ⟦The Bulwark=Granbarricata⟧ tengono a bada la maggior parte del Flagello, ma ogni tanto qualcuno riesce a passare.\n\nAbbiamo notato sporadiche attività del Flagello a est di questo posto, concentrate intorno alla ⟦Balnir Farmstead=Cascina dei Balnir⟧.", 0xd084bae8, 0x01a29751, 0x62158f5e, nil, 0x24304d48, "...m." },
  [360] = { "Ritorno dal magistrato", "Torna dal magistrato Sevren a Brill.", "Ora torna dal magistrato Sevren con le informazioni che ti ho dato. Le vorrà al più presto, quindi sii rapid<o/a>.\n\nE se sulla via del ritorno incontri qualche creatura del Flagello, abbattila: non possiamo lasciarle vagare indisturbate per le nostre terre.", nil, "È preoccupante sapere che il Flagello riesce a passare oltre la Granbarricata. Il Re dei Lich e i suoi servitori non danno tregua con i loro assalti.\n\nMa non cederemo. Non ci prenderà di nuovo!", 0x12884385, 0x92c7d7d0, 0x9c00db70, nil, 0x421c5bd4, "...m." },
  [361] = { "Una lettera mai consegnata", "Trova Yvette Farthing e consegnale la lettera di Thurman Agamand.", "È una lettera scritta da Thurman, il figlio maggiore di Gregor Agamand. È indirizzata a una certa Yvette Farthing, ma non sembra esserle mai arrivata...", "Sì?", "Oh... mio povero Thurman! L'ho supplicato di lasciare i ⟦Agamand Mills=Mulini degli Agamand⟧ con me e mio padre, ma la sua lealtà verso la famiglia era troppo forte! E lo sapevo! Lo sapevo che Brand voleva fargli del male!! Oh, maledetta questa Piaga, e il Flagello!\n\n<Il volto di Yvette si distende e si fa gelido.>\n\nMa i rimpianti sono per i deboli. Da Reietta, ho nuovi obiettivi e l'amore non è tra questi. Ti ringrazio per avermi consegnato questa lettera, perché mi ero chiesta cosa fosse successo al mio amore di un tempo.\n\nMa quella vita è finita. Per sempre.", 0x5e10b1e4, 0xc4999128, 0xe925a4ce, 0x0c07a888, 0x85cd25fb, "....." },
  [362] = { "I mulini infestati", "Uccidi Devlin Agamand e porta i ⟦Devlin's Remains=Resti di Devlin⟧ a Coleman Farthing, a Brill.", "Devlin Agamand era il minore dei due figli della famiglia Agamand, e in vita i due non avrebbero potuto essere più diversi. Thurman era alto e mite, mentre il fratello minore era debole e aveva la lingua tagliente.\n\nQuando i ⟦Agamand Mills=Mulini degli Agamand⟧ caddero sotto la Piaga, non mi sorprese sapere che Devlin aveva ceduto in fretta. Il suo farneticare folle si sente ancora vicino alla strada che porta ai ⟦Agamand Mills=Mulini degli Agamand⟧.\n\nSto raccogliendo i resti degli Agamand e voglio il povero Devlin. Trovalo, distruggilo e portami le sue ossa.", "Hai trovato Devlin?", "Grazie. Le ossa di Devlin faranno una bella figura sulla mia mensola del camino.\n\nSe il mio cuore freddo può trovare un po' di calore, è nel sapere che gli Agamand sono distrutti. Hanno tradito me e la mia famiglia quando è arrivata la Piaga: ora giuro che schiaccerò i loro resti sotto il mio tallone!", 0xa79aec83, 0xffa9100d, 0x1441dcb8, 0x4fefbbb4, 0x9ac1d49a, "....." },
  [363] = { "Un brusco risveglio", "Parla con il Sacerdote dell'Ombra Sarvis.", "Era ora che ti svegliassi. Stavamo per gettarti nel fuoco con gli altri, ma a quanto pare ce l'hai fatta.\n\nIo sono Mordo, il custode della cripta di ⟦Deathknell=Albamorta⟧. E tu non sei più schiav<o/a> del Re dei Lich.\n\nParla con il Sacerdote dell'Ombra Sarvis, nella cappella ai piedi della collina: ti dirà altro di ciò che devi sapere.", nil, "Un altro morto che cammina, eh? Dev'essere stato un bel colpo, risvegliarsi nella cripta con solo il freddo e Mordo ad accoglierti...\n\nVedo la confusione sul tuo volto. Lascia che provi a spiegarti la nostra... situazione.\n\nSiamo stati liberati dal controllo del Re dei Lich dalla nostra nuova guida, Lady Sylvanas. La Dama Oscura ci guida nella guerra contro l'odiato Flagello e contro gli ultimi baluardi dell'umanità, che ci braccano a ogni passo.", 0xe51cefc8, 0xcd2051a8, 0x4ee64e18, nil, 0x3dd91702, "...m." },
  [364] = { "I senza mente", "Il Sacerdote dell'Ombra Sarvis vuole che tu uccida 8 Mindless Zombie e 8 Wretched Zombie.", "Noi Reietti siamo in guerra contro l'esercito del Flagello del Re dei Lich: armate di non morti risvegliate con la negromanzia, bestie immonde del nord e spettri tormentati.\n\nLa parte settentrionale del villaggio è stata invasa dai Senza Mente, e vanno distrutti. Distruggili senza pietà, anche se un tempo erano nostri fratelli e sorelle. I Caduti non sono altro che schiavi del Re dei Lich.", "Non andrai lontano in questa nuova vita se non riesci a uccidere nemmeno il più debole degli zombi, {name}. Non tornare finché non avrai un successo da riferire.", "È un peccato che il Flagello non possa essere portato dalla nostra parte: il suo gran numero ci sarebbe utile nelle battaglie a venire.\n\nMa non si unirà a noi, quindi non abbiamo altra scelta che distruggerlo.", 0x662772dd, 0x2c117b14, 0x3bac79ef, 0x22709411, 0x7b9bd914, "....." },
  [365] = { "Campi del dolore", "Ruba 10 zucche dalla fattoria a ovest, appena a nord di ⟦Deathknell=Albamorta⟧, e portale allo speziale Johaan a Brill.", "Che abbiamo qui? Sembri un {class} alle prime armi. Se speri di dimostrare il tuo valore alla Dama Oscura, devi imparare le usanze dei Reietti.\n\nA ovest troverai una fattoria. Gli umani infestano la terra come la muffa un cadavere in putrefazione. E, peggio ancora, la ⟦Scarlet Crusade=Crociata Scarlatta⟧ pattuglia i dintorni dalla sua torre. Dai una lezione a quella feccia e ruba 10 delle loro preziose zucche.\n\nQuando ne avrai 10, portale allo speziale Johaan a Brill.", "La Guardia della Morte Simmer mi ha fatto sapere che mi avresti procurato dei reagenti di cui ho molto bisogno. Sei già <riuscito/riuscita> a raccogliere 10 zucche, {name}?", "Hai eseguito bene i tuoi ordini, giovane {class}. Ti stai dimostrando una vera risorsa per l'esercito della Dama Oscura.", 0x2932f488, 0xf53c96c2, 0xf89b6106, 0x73105245, 0x0e4e9168, "....." },
  [366] = { "La restituzione del libro", "Restituisci il ⟦Gunther's Spellbook=Grimorio di Gunther⟧ al suo proprietario, sull'isola dell'⟦Gunther's Retreat=Asilo di Gunther⟧.", "Tanto tempo fa, Gunther e io, insieme a Thule Ravenclaw, oggi negromante del Flagello, eravamo amici e studenti del Kirin Tor, una società di maghi di Dalaran.\n\nGunther e io cademmo entrambi vittime della Piaga, ma pensavo che fosse rimasto morto o che fosse stato risvegliato tra le file del Re dei Lich. È bello sapere che è libero.\n\nDobbiamo averlo con noi. Ho lanciato sul suo libro un incantesimo che, quando lo vedrà, gli mostrerà che anch'io sono libero dal Re dei Lich. Saputo questo, spero che si unisca a noi.", "I tuoi padroni sono degli sciocchi a mandarti qui, perché non sarò mai più uno schiavo del Flagello!", "Il mio libro?!? Allora eri tu <il/la> <ladro/ladra> che l'ha rubato!\n\nMa... cos'è questo nuovo incantesimo su di esso... Bethor? È a Lordaeron?\n\nSe esiste ancora, forse anche lui è sfuggito alla presa del Re dei Lich...", 0x67addb26, 0x1ef4863d, 0x9d95752a, 0x03c4c134, 0xc9995e3f, "....." },
  [367] = { "Una nuova piaga", "Lo speziale Johaan, nella città di Brill, vuole che tu raccolga 5 fiale di ⟦Darkhound Blood=Sangue di Segugio Oscuro⟧.", "Lady Sylvanas ha fatto appello alla Royal Apothecary Society. La Dama Oscura crede che il nostro sapere, unito alla magia appena scoperta, sarà la chiave per la fine di Arthas. Ci ha sfidati a creare una nuova piaga, una piaga più letale di qualunque malattia di Azeroth. Questo nuovo morbo porterà alla rovina l'esercito del Flagello di Arthas.\n\nI miei studi indicano che il sangue delle bestie potrebbe essere la chiave. Portami 5 fiale di Sangue di Segugio Oscuro, così potrò verificare la mia teoria.", "Hai già raccolto 5 fiale di Sangue di Segugio Oscuro, {name}? Il tempo stringe!", "Hai fatto un buon lavoro, {name}, e ti ringrazio per il tuo impegno.", 0x4012ba5a, 0x09ffaa51, 0x368f3ad3, 0xef4e8ff0, 0x60911425, "....." },
  [368] = { "Una nuova piaga", "Lo speziale Johaan della città di Brill ha bisogno di 5 Vile Fin Scale dei murloc delle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Mentre raccoglievi campioni per me, i miei esperimenti mi hanno fatto capire che serviranno altri reagenti perché questa nuova malattia si diffonda come si deve. Avvelenare qualche povero disgraziato è un gioco da ragazzi. Infestare un mondo intero si rivela un po' più complicato.\n\nMi serviranno 5 Vile Fin Scale dai murloc dei dintorni. Troverai quelle creature lungo la costa, a nord o a ovest.", "{name}, sei riuscit<o/a> a ottenere 5 Vile Fin Scale dai murloc?", "Le scaglie sono perfette, {name}. Proprio ciò che mi serviva per questo intruglio.", 0x4012ba5a, 0x909fd9c6, 0xf43a2021, 0xbd3e5279, 0x795f8256, "....." },
  [369] = { "Una nuova piaga", "Lo speziale Johaan, nel villaggio di Brill, vuole che tu gli porti 4 campioni di veleno di un Vicious Night Web Spider.", "Mentre eri fuori a raccogliere, ho trovato in uno dei miei tomi un vecchio testo secondo cui un'antica piaga sterminò migliaia di vittime innocenti. In seguito si scoprì che l'agente letale della piaga si conservava nel veleno dei Night Web Spider.\n\nPortami un po' di veleno di un Vicious Night Web Spider per completare questo esperimento. Voglio vedere se l'elemento contagioso del veleno funziona con il mio nuovo intruglio. Si dice che quei ragni si trovino nella parte orientale delle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Hai già un po' di veleno di un Vicious Night Web Spider, {name}? È l'ultimo componente che mi serve per mettere alla prova il mio esperimento.", "Ah, questo veleno andrà benissimo, {name}. Tutto il resto è già stato aggiunto al mio intruglio e fatto bollire. Finalmente sono pronto a provare questo nuovo agente letale!", 0x4012ba5a, 0x71928e3a, 0x9ecb3ade, 0xf0a5e0b1, 0x20e13a3f, "....." },
  [370] = { "In guerra con la ⟦Scarlet Crusade=Crociata Scarlatta⟧", "L'esecutore Zygand di Brill vuole che tu uccida il capitano Perrine, 3 Scarlet Zealot e 3 Scarlet Missionary.", "I documenti strategici dell'esecutore Arren contengono tutti i dettagli che ci servono per estirpare dalle nostre terre l'infestazione umana. Secondo queste informazioni, la ⟦Scarlet Crusade=Crociata Scarlatta⟧ ha assegnato il capitano Perrine e una brigata alla torre in rovina a sud-ovest di Brill.\n\nUccidi Perrine insieme a 3 fanatici e 3 missionari e fai rapporto da me.", "Giovane {class}, non dovresti perdere tempo qui a Brill quando il tuo popolo ha bisogno che tu combatta per la sua causa. Ora prendi le armi e va' a sud-ovest, alla torre in rovina, e uccidi il capitano Perrine insieme a 3 Scarlet Zealot e 3 Scarlet Missionary. Condurremo la ⟦Scarlet Crusade=Crociata Scarlatta⟧ alla rovina come bestiame al macello.", "La morte del capitano Perrine farà senz'altro piacere alla Dama Oscura. Hai compiuto bene il tuo dovere, {class}.", 0x5aa72e8b, 0xdbeebcd7, 0xc41776f5, 0xa5c40f43, 0xe3a971de, "....." },
  [371] = { "In guerra con la ⟦Scarlet Crusade=Crociata Scarlatta⟧", "L'esecutore Zygand di Brill ti ha incaricato di uccidere il capitano Vachon e 5 Scarlet Friar.", "Siamo ancora in guerra e la ⟦Scarlet Crusade=Crociata Scarlatta⟧ si fa sempre più forte. Il rapporto che mi ha mandato l'esecutore Arren dice che i crociati scarlatti compiono razzie partendo dalla torre in rovina nel sud-est di Tirisfal, vicino alla ⟦Balnir Farmstead=Cascina dei Balnir⟧, al comando del capitano Vachon.\n\nUccidi Vachon e 5 Scarlet Friar. Sarà un colpo devastante per la Crociata!", "Vedo che sei <tornato/tornata>, ma il tuo compito non è concluso. Forse ti sta bene che dei semplici umani intralcino il piano della Dama Oscura? O forse saprai rispondere alla chiamata del dovere e uccidere il capitano Vachon e la sua banda di Scarlet Friar!", "La morte del capitano Vachon rallenterà parecchio l'avanzata della Crociata Scarlatta a Tirisfal. Ma altre minacce incombono.", 0x5aa72e8b, 0x230145b6, 0x8d2df557, 0xed1a74cc, 0x0d6cd08c, "....." },
  [372] = { "In guerra con la ⟦Scarlet Crusade=Crociata Scarlatta⟧", "L'esecutore Zygand, nel villaggio di Brill, vuole che tu assassini il capitano Melrache e le sue due guardie del corpo.", "I crociati scarlatti fanno incursioni dalla torre in rovina nel nord delle Radure di Tirisfal, oltre il ⟦Faol's Rest=Sepolcro di Faol⟧. Secondo le nostre informazioni, a capo di questa banda malvagia c'è uno spietato comandante, il capitano Melrache.\n\nOra ti affido una missione speciale e pericolosa. Uccidi Melrache e le sue due guardie del corpo, nel nome della Dama Oscura.", "Non hai ancora fatto il tuo dovere, {class}. Non possiamo sperare di realizzare il piano della Dama Oscura con la ⟦Scarlet Crusade=Crociata Scarlatta⟧ che tormenta i nostri soldati. Dai loro la morte e compi il tuo dovere verso Sylvanas!", "Hai fatto un lavoro eccellente, {class}. Con combattenti spietati come te che conquistano nel nome dei Reietti, la nostra razza è un passo più vicina a sconfiggere Arthas una volta per tutte. Ho un buon presentimento su di te, <compagno/compagna>.", 0x5aa72e8b, 0x16e2b772, 0x9d736921, 0x721d38b8, 0x06825bc6, "....." },
  [373] = { "La lettera mai spedita", "Consegna la ⟦Letter to the City Architect=Lettera per l'Architetto Cittadino⟧ a Baros Alexston, a ⟦Stormwind=Roccavento⟧.", "Frugando addosso a Edwin VanCleef, trovi, tra le altre cose, una lettera mai spedita. È indirizzata a Baros Alexston, Architetto Cittadino di ⟦Stormwind=Roccavento⟧, Municipio, Cathedral Square.\n\nSembra scritta e sigillata di recente.", "Sì? Posso aiutarti in qualcosa?", "Edwin VanCleef, dici? Mi aspetterei piuttosto una lettera dalla mia defunta nonna... Quindi l'hai ucciso? Perdona se te lo dico, ma sono alquanto sorpreso. In gioventù era un combattente senza pari. Vediamo che cosa sente il bisogno di scrivermi dopo tanti anni.\n\n<Baros scorre la lettera.>\n\nEdwin... vedo che gli anni non ti hanno cambiato affatto: idealista come sempre, e romantico. Non gli importa chi ferisce, {name}. La vendetta l'ha consumato. Ma d'altronde non sono sicuro di poterlo biasimare.", 0xaf33b2fe, 0xb7077b54, 0x4d9722a9, 0x5bf43657, 0x5b678cae, "....." },
  [374] = { "Prova di morte", "Porta 10 Scarlet Insignia Ring alla Guardia della Morte Burgess a Brill.", "L'esecutore Zygand mi dice che sei <andato/andata> in giro a uccidere Crociati Scarlatti. Le ⟦Tirisfal Glades=Radure di Tirisfal⟧ ne brulicano.\n\nVarimathras, luogotenente della Dama Oscura, provvede di persona a far sì che la feccia di Azeroth, la razza umana, venga spazzata nell'oblio. Qui nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧ affrontiamo una genia di umani particolarmente fastidiosa: la ⟦Scarlet Crusade=Crociata Scarlatta⟧.\n\nVa' e porta l'offensiva contro la ⟦Scarlet Crusade=Crociata Scarlatta⟧, {class}. Riportami 10 Scarlet Insignia Ring come prova della tua lealtà a Varimathras e alla Dama Oscura.", "Hai già raccolto 10 Scarlet Insignia Ring, {class}?", "Varimathras sarebbe fiero. Servi bene i tuoi capi, {class}.", 0x921e8463, 0xb39a505d, 0xed4d1fa3, 0x22053211, 0x6b185a16, "....." },
  [375] = { "Il gelo della morte", "Porta cinque Duskbat Pelt e un po' di ⟦Coarse Thread=Filo Grezzo⟧ a Gretchen Dedmar a Brill.", "Fa così freddo, ora. La Piaga della Non Morte mi striscia nelle vene come un serpente gelido. Presto lo Stato Senza Mente mi raggiungerà. Ma nessun destino segnato mi impedirà di servire la nostra Dama Oscura. Quando giunse la chiamata, cucii sacchi per i caduti del possente esercito di Sylvanas.\n\nOra le mani mi tremano per il gelo. Se mi portassi cinque Duskbat Pelt e un po' di ⟦Coarse Thread=Filo Grezzo⟧, potrei cucirmi una coperta. Aiutami, {name}, così potrò continuare a servire la causa.", "Hai già cinque Duskbat Pelt e un po' di ⟦Coarse Thread=Filo Grezzo⟧, {name}?", "Apprezzo i tuoi sforzi, {name}. Che Sylvanas possa riconoscere un giorno il tuo coraggio. . . .", 0x7e5206c9, 0x896b7787, 0xe96a4151, 0x22b2c2d6, 0x788b9dba, "....." },
  [376] = { "I dannati", "La novizia Elreth ha bisogno di 6 Scavenger Paw e 6 Duskbat Wing.", "Tra i miei compiti c'è curare i nostri guerrieri feriti, cucire armature e vestiti e aiutare il Sacerdote dell'Ombra Sarvis in qualunque altra cosa gli serva.\n\nA quanto vedo, anche tu finirai al suo servizio... a dare la caccia ai Senza Mente, se lo conosco bene. Be', se vuoi restare tutto d'un pezzo, e non ho dubbi che tu lo voglia, forse posso aiutarti. Mi stanno finendo zampe e ali: se me ne porti un po', ti troverò un'armatura. A sud troverai un bel po' di lupi e pipistrelli.", "Cerca di non farti male finché non ti avrò procurato un'armatura.", "Grazie, {name}. Questa armatura dovrebbe esserti d'aiuto.\n\nSperiamo che ti serva meglio di quanto sia servita all'ultimo che l'ha indossata...", 0x0d5c3a64, 0xeac65110, 0x95813e5f, 0xa9195c35, 0x1cb90e7e, "....." },
  [377] = { "Delitto e castigo", "Il consigliere Millstipe di ⟦Darkshire=Borgoscuro⟧ vuole che tu gli porti la mano di Dextren Ward.", "Come se l'abbandono degli abitanti di ⟦Duskwood=Boscovespro⟧ non bastasse, ora la House of Nobles sputa in faccia al Consiglio di ⟦Darkshire=Borgoscuro⟧ decidendo di imprigionare Dextren Ward a ⟦Stormwind=Roccavento⟧ invece di decapitare quel furfante, come voleva la sentenza di lord Ebonlocke.\n\nWard è stato sorpreso a vendere i corpi del cimitero a Morbent Fel, un crimine punibile con la morte. Eppure ⟦Stormwind=Roccavento⟧ reclama Ward come suo prigioniero.\n\nAssassina Ward nelle ⟦Stockade=Segrete di Roccavento⟧, portami la sua mano e ti ricompenserò.", "Finché a un profanatore di morti come Dextren Ward sarà permesso di vivere, la giustizia resterà tradita. Torna da me quando la condanna a morte di lord Ebonlocke sarà eseguita su quel profanatore, Ward. Daremo alle famiglie dei defunti la pace che meritano e, meglio ancora, manderemo un messaggio chiaro alla House of Nobles di ⟦Stormwind=Roccavento⟧.", "Allora Dextren Ward ha finalmente pagato per i suoi crimini contro l'umanità? Bene, che sparisca quella feccia, dico io. E alla tua salute, amico mio! Non solo hai dato alle famiglie dei defunti la pace che meritano, ma hai anche mandato un messaggio eloquente a quei burocrati corrotti della House of Nobles. ⟦Stormwind=Roccavento⟧ deve rispondere ai bisogni della gente di ⟦Duskwood=Boscovespro⟧, o ci libereremo della sua tirannia.", 0xd8baf022, 0x6846295b, 0x8a0de614, 0xc306418b, 0x3d4fa9be, "....." },
  [378] = { "Una furia profonda", "Motley Garmason vuole che gli porti la testa di Kam Deepfury a Dun Modr.", "Hai dimostrato la tua lealtà a re Magni, {class}. E il tuo odio per quella feccia dei ⟦Dark Iron=Ferroscuro⟧ è grande quanto il mio.\n\nC'è un compito che vorrei portare a termine di persona, ma l'onore mi obbliga a restare con Longbraid. Roggo, però, ha raccolto informazioni che provano che Kam Deepfury ha preso parte alla congiura dell'attacco al ⟦Thandol Span=Viadotto di Thandol⟧. È per i piani di Deepfury che Longbraid ha perso i suoi familiari.\n\nDeepfury è trattenuto per ragioni politiche nelle ⟦Stockade=Segrete di Roccavento⟧. Lo voglio morto, {name}. Per Longbraid! Portami la sua testa!", "Non lascerò che la stupida burocrazia umana si intrometta nelle faccende dei nani, {name}. È provato che Kam Deepfury ha preso parte alla congiura dell'attacco al ⟦Thandol Span=Viadotto di Thandol⟧. La brava gente di re Magni ha perso la vita per l'inganno di Deepfury. Agli umani forse sta bene lasciar marcire Deepfury nelle ⟦The Stockade=Segrete di Roccavento⟧, ma io non dormirò sonni tranquilli finché Deepfury non sarà morto.", "Così Kam Deepfury ha finalmente provato cosa vuol dire trovarsi dall'altra parte della Morte? Bene. Se lo merita, quel codardo, feccia dei ⟦Dark Iron=Ferroscuro⟧. Hai fatto bene, {class}. Le vittime dell'attacco al ⟦Thandol Span=Viadotto di Thandol⟧ non erano che vittime in un mondo dilaniato da guerre e disordini. Le loro famiglie avranno la pace di sapere che Deepfury ha ricevuto la punizione che meritava. La morte del fratello di Longbraid è stata vendicata.", 0x1158c5af, 0x54c0df47, 0xcec43aea, 0xfee1b4d9, 0x53eb2770, "....." },
  [380] = { "⟦Night Web's Hollow=Valle Telanera⟧", "L'esecutore Arren vuole che tu uccida 10 Young Night Web Spider e 8 Night Web Spider.", "Una delle nostre sfide più grandi è procurarci le risorse naturali che ci servono per sopravvivere. L'oro scarseggiava perfino all'apice del potere dell'Alleanza.\n\nA nord-ovest c'è una miniera d'oro invasa dai ragni. L'oro di quella miniera ci serve, ma non possiamo certo prenderlo finché quei ragni ci strisciano dentro. Non ho molti uomini da dedicare al compito, quindi dovremo procedere poco alla volta.\n\nVa' lassù e vedi cosa puoi fare per noi, {name}.", "Attent<o/a> al veleno dei ragni, {name}. Se senti un bruciore acuto, faresti bene a fartelo controllare.", "Mm, be', è un inizio. Ci vorranno settimane o mesi per ripulire del tutto l'infestazione. Dopo dovremo scendere laggiù con delle torce per bruciare le ragnatele.\n\nHai fatto bene il tuo dovere, {name}: sono certo di poter trovare qualcos'altro da farti fare.", 0xf4d863e7, 0xb5ac7fa7, 0x89530ddc, 0xaad01ead, 0x9c201e46, "....." },
  [381] = { "La ⟦Scarlet Crusade=Crociata Scarlatta⟧", "Porta all'esecutore Arren 12 Scarlet Armband presi agli Scarlet Convert e agli Scarlet Initiate.", "Ti farà piacere sapere che nella miniera sembriamo fare progressi, in buona parte grazie ai tuoi sforzi. Ora possiamo rivolgere lo sguardo ad altre faccende.\n\nI miei esploratori riferiscono che un distaccamento della ⟦Scarlet Crusade=Crociata Scarlatta⟧ sta allestendo un accampamento a sud-est di qui. La ⟦Scarlet Crusade=Crociata Scarlatta⟧ è un'organizzazione spregevole che ci dà la caccia, e non si fermerà finché ogni non morto, che appartenga al Flagello del Re dei Lich o no, non sarà distrutto. Dobbiamo colpire per primi!\n\nStai in guardia: il loro zelo empio li rende avversari pericolosi.", "Quegli stolti... Si mandano allegramente nelle loro stesse tombe.", "Se solo dessero ascolto alla ragione, eh, {name}? Magari potremmo farli sedere per un ragionevole dibattito... ah!\n\nStolti accecati dalla Luce.", 0xe44fe888, 0x315fed01, 0x9254889b, 0x7a95f60a, 0xefabbf0e, "....." },
  [382] = { "Il messaggero rosso", "Uccidi Meven Korgal, il messaggero, all'accampamento dei crociati, poi riporta all'esecutore Arren qualunque informazione trovi.", "Secondo i rapporti dei miei superiori a Brill, un agente della ⟦Scarlet Crusade=Crociata Scarlatta⟧ è partito dal ⟦Scarlet Monastery=Monastero Scarlatto⟧ ed è stato mandato qui ad ⟦Deathknell=Albamorta⟧. Stando ai rapporti, il messaggero porta con sé informazioni importanti. Non ho altri dettagli, ma qualunque cosa sia, dobbiamo averla!\n\nSei la persona più qualificata che posso mandare, {name}. Trova quel messaggero e portami tutte le informazioni che riesci a trovare.", "Come procede la tua missione, {name}?", "Mm... Vediamo cos'hai trovato...\n\n<Comincia a frugare tra i documenti che hai recuperato.>\n\nNotizie delle loro imprese contro di noi... Inutili. Rapporti di esplorazione... Nuovi ordini: \"Continuare a costruire un accampamento vicino alla città in rovina...\" Niente che non sapessimo già... Ah, e questo cos'è? Una mappa con le posizioni di alcuni loro comandanti e agenti sul campo! Questa possiamo usarla.", 0xcc6b9441, 0xdf601388, 0x24feade3, 0x04bcf357, 0x99d645bd, "....." },
  [383] = { "Informazioni vitali", "Consegna i ⟦Scarlet Crusade Documents=Documenti della Crociata Scarlatta⟧ all'esecutore Zygand a Brill.", "Questi andranno portati al mio superiore, l'esecutore Zygand, a Brill. Con queste informazioni potremo infliggere un colpo decisivo alla ⟦Scarlet Crusade=Crociata Scarlatta⟧. I tuoi servigi qui ad ⟦Deathknell=Albamorta⟧ sono stati utili, ma mi serve qualcuno che li consegni a Zygand, e credo che lui saprà trovarti incarichi più adatti.\n\nPrendi la strada che esce da ⟦Deathknell=Albamorta⟧ verso nord. Poco dopo essere entrat<o/a> nella Tirisfal vera e propria, arriverai a un incrocio. Prendi la diramazione a est e continua verso est. Lungo la strada passerai accanto al ⟦Cold Hearth Manor=Maniero Cuorduro⟧.", "Sì, che cosa vuoi?", "Sì, ottimo. Hai fatto bene a procurarti queste informazioni, {name}. Mm... i nomi degli ufficiali nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧...\n\nImmagina il colpo che potremmo infliggere al morale di quei maledetti fanatici se uccidessimo i loro capi con un solo, rapido attacco.", 0x2ab93219, 0x3476f839, 0x22c8ce98, 0xba88a72c, 0x95a7a867, "....." },
  [384] = { "⟦Beer Basted Boar Ribs=Costolette di Cinghiale alla Birra⟧", "Ragnar Thunderbrew a Kharanos vuole 6 Crag Boar Rib e un boccale di ⟦Rhapsody Malt=Birra Rapsodia⟧.", "Niente piace ai clienti della mia taverna più delle ⟦Beer Basted Boar Ribs=Costolette di Cinghiale alla Birra⟧! L'unico problema è che il cacciatore della zona che mi portava le provviste si è arruolato nell'esercito del re per dare una mano nella guerra sul fronte dell'⟦Alliance=Alleanza⟧.\n\nForse puoi aiutarmi tu? Se mi porti sei costolette di cinghiale delle rupi e una ⟦Rhapsody Malt=Birra Rapsodia⟧ dalla taverna qui, ti darò la ricetta di famiglia delle mie famose ⟦Beer Basted Boar Ribs=Costolette di Cinghiale alla Birra⟧, per non parlare di un assaggio gratis! Il segreto è nella Birra!", "Mi serviranno sei costolette di cinghiale delle rupi e un boccale di ⟦Rhapsody Malt=Birra Rapsodia⟧, {name}.", "La Birra è fermentata, i Cinghiali son spacciati\n\nE prima che sia tutto fatto e detto\n\nCi batteremo per il primo assaggio\n\nDi queste gustose ⟦Beer Basted Boar Ribs=Costolette di Cinghiale alla Birra⟧!", 0x56bf3780, 0x848a85be, 0xacc6d110, 0xe5dfc379, 0x3d02ca9a, "....." },
  [385] = { "Caccia ai crocolischi", "Procura 5 pezzi di ⟦Crocolisk Meat=Carne di Crocolisco⟧ e 6 Crocolisk Skin per Marek Ironheart al ⟦Farstrider Lodge=Padiglione Lungopasso⟧.", "Molti cacciatori vengono a Loch Modan per dare la caccia ai nostri famosi crocolischi. Ci sono sempre mercanti che cercano pelli di crocolisco per farne vestiti o armature, e c'è anche chi ne apprezza il sapore della carne.\n\nNe facciamo un po' di commercio, ma non molto, perché i crocolischi sono feroci e si sono trincerati sulle isole del lago. Ma non lasciarti scoraggiare: lottare con le fauci di quelle bestie è un'esperienza unica.\n\nPensa che una volta...", "Ti ho mai raccontato di quella volta che per poco non ci rimettevo la mano con uno di quei crocolischi? Era una bestiaccia, con denti come coltelli. Ma sono stato fortunato... Gli ho bloccato le mascelle con il mio coltello. Quel coltello ce l'ho ancora, qui da qualche parte...", "Bene bene, questi che hai raccolto sono esemplari eccellenti, {name}. Bei soldi per materiali di prima qualità, poco ma sicuro.", 0x08c77bcd, 0x39f97603, 0x43d56489, 0x6cc0be27, 0x469a4235, "....." },
  [386] = { "Chi la fa l'aspetti...", "Porta la testa di Targorr the Dread alla guardia Berton, a ⟦Lakeshire=Borgolago⟧.", "Targorr the Dread servì sotto Gath'Ilzogg come boia supremo. I suoi metodi erano spietati, perfino per uno sporco orco. Uomini che avevano combattuto con coraggio per difendere il Regno venivano torturati per suo capriccio. Ora è rinchiuso nelle ⟦The Stockade=Segrete di Roccavento⟧, condannato a morte. Eppure qualcosa non va. Uno dei nobili burocrati ha sospeso la sua esecuzione. Sono sicuro che c'è sotto qualche sporco gioco.\n\nMetti fine alla vita di Targorr the Dread, {name}. Va' alle ⟦The Stockade=Segrete di Roccavento⟧ e decapitalo prima che ci giochino qualche brutto tiro.", "Sei già stat<o/a> a ⟦Stormwind=Roccavento⟧, alle ⟦The Stockade=Segrete di Roccavento⟧? Temo che l'inganno che ha tenuto in vita Targorr the Dread così a lungo finirà per ridargli la libertà. È stato condannato a morte, {name}, non a fare da pedina politica per il capriccio di un nobile.", "Targorr the Dread ha finalmente incontrato il suo destino. Per quanto mi riguarda, sono lieto di sapere che quella bestia ora conosce la stretta spietata della Morte. Hai fatto bene, {name}. A volte la giustizia più vera si trova solo fuori dalle aule di tribunale e oltre lo sguardo offuscato della politica.", 0x985b5c1d, 0x0bd13fa2, 0x9d18b187, 0x4b424f22, 0x4701141d, "....." },
  [387] = { "Sedare la rivolta", "Il direttore Thelwater di ⟦Stormwind=Roccavento⟧ vuole che tu uccida 10 Defias Prisoner, 8 Defias Convict e 8 Defias Insurgent nelle ⟦The Stockade=Segrete di Roccavento⟧.", "La rivolta va sedata! Mi serve il tuo aiuto. Se si viene a sapere che la prigione è in mano ai detenuti, perderò il posto! Se c'è mai stato un caso di sabotaggio, è questo. Ma ora l'importante è costringere questi prigionieri alla resa, per la sicurezza di ⟦Stormwind=Roccavento⟧.\n\nLa pena per l'insurrezione è la morte. Uccidi un po' di questi delinquenti! Così le cose dovrebbero tornare sotto controllo.", "Le ⟦The Stockade=Segrete di Roccavento⟧ sono ancora in mano ai rivoltosi! Bisogna mostrare a questi ratti Defias che le loro azioni non saranno tollerate. Ora torna laggiù e fai vedere un po' di forza!", "Ti sei battut<o/a> con valore nelle ⟦The Stockade=Segrete di Roccavento⟧, {name}. È evidente che questo problema è più grande di entrambi. Ma hai agito bene, e per questo ti sono grato.", 0x577b3efe, 0x537853f9, 0xb27b21dc, 0x07128f06, 0x7f65d9bb, "....." },
  [388] = { "Il colore del sangue", "Nikova Raskol di ⟦Stormwind=Roccavento⟧ vuole che tu raccolga 10 Bandana di Lana Rossa.", "L'amarezza mi scorre nelle vene come un fiume gelido. Mio nipote, Mac, era un così bravo ragazzo. Aveva appena 14 anni. Quando l'esercito fu mandato al fronte, Mac prese le armi per difendere la città. Era una guardia nelle ⟦The Stockade=Segrete di Roccavento⟧, dove è rinchiusa la banda dei Defias. Mac rimproverò alcuni prigionieri che strappavano le loro coperte di lana per farne sciarpe, un simbolo della loro banda. Per questo Mac fu pugnalato alle spalle.\n\nVoglio vendetta. Portami 10 delle loro preziose bandane di lana. Hanno il colore del sangue.", "Vedo che sei tornat<o/a>, {class}. Hai già raccolto 10 Red Wool Bandana da quella feccia dei Defias nelle ⟦The Stockade=Segrete di Roccavento⟧?", "Dunque il mio Mac è morto per queste bandane, sudici simboli di corruzione? Che spreco. Che tragico sacrificio.\n\nMa ahimè, non posso tornare indietro nel tempo. Sappi solo, {name}, che con le tue azioni hai reso giustizia alla mia famiglia.", 0x309b5224, 0x731de4a6, 0x75502eb1, 0x94db022c, 0x3ca7de8a, "....." },
  [389] = { nil, "Parla con il direttore Thelwater nelle ⟦Stockade=Segrete di Roccavento⟧.", "VanCleef e io eravamo membri della Gilda dei Tagliapietre. Il nostro compito principale era ricostruire ⟦Stormwind=Roccavento⟧ dopo la guerra.\n\nQuando finimmo il lavoro, fummo truffati. I nobili si rifiutarono di pagarci. Ad alcuni dei tagliapietre più anziani furono offerti incarichi governativi, ma VanCleef rifiutò per lealtà verso tutti i tagliapietre. Guidò una rivolta e lasciò la città, giurando vendetta.\n\nIl suo luogotenente, Bazil Thredd, potrebbe saperne di più sui piani di VanCleef. È tenuto prigioniero nelle ⟦Stockade=Segrete di Roccavento⟧.", nil, "Che cosa vuoi, in nome della Luce? Non vedi che qui abbiamo una crisi?\n\nBazil Thredd?! Perché mai vorresti parlare con quel bastardo? Come faccio a sapere che non sei <uno/una> dei suoi compari, venut<o/a> a dar man forte alla sua maledetta rivolta? Se tutte quelle dannate celle non fossero aperte, potrei sbatterti in una per un po'!", 0x49a42307, 0x9f1dfef8, 0xcad99174, nil, 0x275f421d, "e..m." },
  [391] = { "Rivolta nelle ⟦The Stockade=Segrete di Roccavento⟧", "Uccidi Bazil Thredd e porta la sua testa al direttore Thelwater, alle ⟦Stockade=Segrete di Roccavento⟧.", "Mettiamo subito le cose in chiaro, {name}: io non mi fido di te. Ma, con la situazione com'è, probabilmente non farai alcuna differenza.\n\nQuindi funziona così: scendi laggiù e fa' la tua chiacchierata con Thredd. Se stai davvero dalla nostra parte, uccidilo e portami la sua testa a lavoro finito. E se si scopre che stai dalla sua parte, e non esci... quando ti troveremo, morirai insieme al resto di quei vermi.", "O mi porti la testa di Thredd, o mi prendo la tua. Chiaro, {name}?", "Senza Thredd a guidarli, si spera che le rivolte siano più facili da contenere. Vedremo.\n\nDevo dire che dopo mezz'ora non mi aspettavo proprio che saresti uscit<o/a>, ma a quanto pare ti ho giudicat<o/a> male.\n\nImmagino, quindi, che tu non abbia ricavato da lui molte informazioni utili? Ma io so un paio di cose sulle attività di Thredd che potrebbero interessarti.", 0x8d19e31c, 0x1cb86e24, 0xa2b8b189, 0xb08a569e, 0x6178e7e9, "....." },
  [392] = { "Lo strano visitatore", "Porta la ⟦Sealed Description of Thredd's Visitor=Descrizione Sigillata del Visitatore di Thredd⟧ a Baros Alexston, a ⟦Stormwind=Roccavento⟧.", "Nei primi anni di prigionia, Thredd non ha mai ricevuto visite. Pensavo che non servisse più alla Fratellanza e che quindi l'avessero abbandonato.\n\nComunque, qualche mese fa tutto è cambiato: ha cominciato a ricevere visite regolari... una, forse due volte a settimana. Era un tipo strano, di quelli silenziosi. Avevo i miei sospetti, ma i suoi documenti erano tutti in regola.\n\nSecondo i documenti si chiamava Maelik; ecco la sua descrizione. Non credo che verrà più a trovare Thredd.", "Sì, {name}? Che cosa hai scoperto?", "Mm. Maelik? No, il nome non mi dice niente, e nemmeno questa descrizione. Ma potrebbe essere chiunque! Un ex Tagliapietre, uno della ⟦Defias Brotherhood=Fratellanza dei Defias⟧... Però, se è così ben introdotto come dice Thelwater, forse qualcun altro potrebbe riconoscerlo. Fammi pensare.", 0x35a2f6f1, 0xdb51b853, 0x0cbcac0d, 0x2a96cc90, 0x473d9a09, "....." },
  [393] = { "L'ombra del passato", "Porta la ⟦Sealed Description of Thredd's Visitor=Descrizione Sigillata del Visitatore di Thredd⟧ al maestro Mathias Shaw, a ⟦Stormwind=Roccavento⟧.", "Non ne ho proprio idea, {name}. C'è qualcun altro che potrebbe aiutarti, e guarda caso mi deve un favore per... be', lasciamo perdere. Il maestro Mathias Shaw dell'⟦SI:7=IR:7⟧ si trova nella caserma di Old Town. Shaw tiene d'occhio quasi tutti gli affari loschi o sottobanco della città.\n\nSe qualcuno lo sa, è lui.", "Salute. In che cosa posso esserti utile, {class}?", "Cosa? Che cos'è questo? Sì, credo di sapere chi è quest'uomo, ma il suo nome non è Maelik. Gli assassini hanno molti nomi e molte maschere, e se ne liberano quando non servono più. Un altro pseudonimo noto di quest'uomo è Marzon; ma di certo neanche quello è il suo vero nome.\n\nIn ogni caso, è un assassino e so parecchie cose su di lui.\n\nAl momento Marzon è al soldo di lord Gregor Lescovar, un nobile dalla reputazione losca, persino considerando la corruzione della nobiltà di ⟦Stormwind=Roccavento⟧.", 0x57046a0a, 0x20fa1c0c, 0x29c82d75, 0x3a5dbaf1, 0x224c7373, "....." },
  [397] = { "Ci hai servito bene", "Parla con Zggi, il servitore di Zardeth the Blackclaw, per ricevere la tua ricompensa.", "Ho sentito che a lord Wishock è piaciuta la sua bevanda.\n\nCi hai servito bene, {name}. Gli stregoni di ⟦Stormwind=Roccavento⟧ potranno praticare le nostre arti indisturbati, grazie a te. Per i tuoi sforzi ho preparato un dono speciale. Parla con il mio servitore, Zggi, e ricevi la tua ricompensa.", nil, "Padrone dice dare dono a {name}. Zggi vuole tenere bel dono ma Zggi sa che non deve tradire Padrone.", 0xeaaf884a, 0x441331ba, 0x5147d5ea, nil, 0xa9142260, "...m." },
  [398] = { "RICERCATO: Maggot Eye", "Uccidi Maggot Eye e porta la sua zampa all'esecutore Zygand, a Brill, per avere una ricompensa.", "Ricercato: Maggot Eye!\n\nBestia immonda persino per gli standard degli gnoll, Maggot Eye è stato condannato a morte per i suoi crimini contro i Reietti. Questo spregevole furfante ruba cadaveri da destinare all'esercito del Re dei Lich. Maggot Eye è stato visto l'ultima volta mentre saccheggiava le terre vicino al ⟦Garren's Haunt=Covo di Garren⟧, a nord di Brill.\n\nCon il presente avviso, la città di Brill offre una ricompensa all'anima capace che saprà eseguire la condanna. A esecuzione avvenuta, mostra all'esecutore Zygand la zampa del furfante.\n\nLa pietà è per i deboli.", "Sì?", "Le malefatte di Maggot Eye sono state finalmente vendicate. Forse il tuo coraggio manderà un messaggio chiaro a chi vuole fare del male alla nostra gente. A nome della città di Brill, ti ringrazio, {name}.", 0x655d68ed, 0x0869dc49, 0x04ae2b05, 0x0c07a888, 0xe8743f8e, "....." },
  [399] = { "Umili inizi", "Va' alla casa di Baros Alexston nelle ⟦Westfall=Marche Occidentali⟧ e cerca la sua bussola, poi riportagliela in Cathedral Square, a ⟦Stormwind=Roccavento⟧.", "Mi sembra passata un'eternità da quando ero un ragazzo e lavoravo alla fattoria nelle ⟦Westfall=Marche Occidentali⟧. Dicono che non si può più tornare indietro, ed è vero. Nel mio caso doppiamente vero: la casa della mia famiglia è stata bruciata e occupata dai ladri.\n\nHo parlato con mio padre della sorte di alcune delle mie cose, tra cui la mia prima bussola. Non è riuscito a salvarle. Però dice che dovrebbero essere nascoste da qualche parte nella fattoria.\n\nTroverai la ⟦Alexston Farmstead=Cascina degli Alexston⟧ a ovest di ⟦Sentinel Hill=Guardiacolle⟧. Potresti andare a recuperarla per me?", "{name}! Hai avuto fortuna?", "Oh, grazie, {name}! Non mi serve a nulla in pratica, ma il valore affettivo... Inutile dirlo, grazie per avermela portata... e a rischio della tua incolumità, per non parlare del tempo che ti è servito per scendere fino alle ⟦Westfall=Marche Occidentali⟧. Hai la mia gratitudine: accetta questo come segno del mio ringraziamento.", 0xe3c50bf4, 0xf6990729, 0x3d3b2003, 0x92e1e141, 0x3dfe9061, "....." },
  [400] = { "Attrezzi per Steelgrill", "Consegna gli ⟦Steelgrill's Tools=Attrezzi di Grigliafredda⟧ a Beldin Steelgrill.", "Beldin Steelgrill gestisce l'officina meccanica del posto ed è il miglior tecnico di macchine d'assedio che ci sia! Però non ha pietà dei suoi attrezzi. Giuro che rompe più chiavi ad arco voltaico di quante riusciamo a fornirgliene!\n\nAbbiamo appena preparato il suo ultimo ordine di attrezzi. Se glielo consegni, sono sicuro che ti ricompenserà per il disturbo.\n\nLa sua officina, lo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧, è appena a nord-est di Kharanos. Ed è un ritrovo per i piloti veterani di macchine d'assedio, quindi tieni le orecchie aperte: potrebbero capitarti delle occasioni.", "Mm? Mi sembri un po' giovane per essere un pilota di macchine d'assedio. Ma non importa... hai qualcosa da riparare?\n\nBe', prendi il numero e mettiti comod<o/a>. Sto lavorando a un paio di macchine proprio ora e non avrò tempo per un altro lavoro per almeno qualche giorno.\n\nO forse eri qui per qualcos'altro...?", "Hai i miei attrezzi? Ben fatto, <ragazzo/ragazza>, ben fatto! Ho rotto il mio ultimo cricchetto a zanna un'ora fa e me ne serve uno per finire le riparazioni alla macchina d'assedio del pilota Stonegear. Hai fatto una buona cosa a trascinare qui quegli attrezzi, {name}.\n\nEcco, prendi queste monete per il tuo aiuto.", 0x872f52ba, 0xc5e776cd, 0x841b2028, 0x849bd1d2, 0xfbff9b36, ".....", nil, nil, nil, nil, 0x7de665ab },
  [401] = { "Aspetta che Sirra finisca", "Aspetta un momento, poi parla di nuovo con Sirra Von'Indi.", "Ho quasi finito di tradurre quel biglietto. Se torni tra qualche istante dovrei aver finito.", nil, "Ecco fatto. È tradotto...\n\n<L'aria si fa pesante, come se una spessa tenda nera calasse sulla terra...>", 0xec04092d, 0xa17cff08, 0x5bacacc5, nil, 0x16c781dc, "...m." },
  [403] = { "Barile Thunderbrew sorvegliato", nil, nil, nil, "Questo barile di birra è sorvegliato da Jarven Thunderbrew. Finché lui è in cantina, nessun barile può essere toccato.", 0xdf09604e, nil, nil, nil, 0x33af4f29, ".mmm." },
  [404] = { "Un compito putrido", "Porta 7 Putrid Claw alla Guardia della Morte Dillinger a Brill.", "Il Flagello si è infiltrato nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧ e ha infestato la zona a ovest di Brill, vicino al vecchio ponte.\n\nVa' laggiù e respingi i morti putrescenti e i cadaveri devastati che trovi. Spargi le loro ossa e riportami i loro artigli putridi: le Guardie della Morte ti ricompenseranno.", "Hai portato a termine il compito che ti ho affidato? Hai quegli artigli putridi?", "Ben fatto. Mi dispiace non essere stato lì a vederti ridurre quei non morti in poltiglia putrescente!", 0x2b4ec308, 0xfb2bd54c, 0x62cd09e5, 0x245a4768, 0x4519c29e, "....." },
  [405] = { "Il lich prodigo", "Presenta gli ⟦Sevren's Orders=Ordini di Sevren⟧ a Bethor Iceshard a ⟦Undercity=Sepulcra⟧.", "Bethor Iceshard, un mago potente e di alto rango a ⟦Undercity=Sepulcra⟧, a sud, mi ordina di mandargli un agente di provato valore contro il Flagello. Tu, {name}, sarai quell'agente.\n\nPresenta questi ordini a Bethor. Lui ti istruirà sulla tua missione. Non ne conosco i dettagli, ma riguarda il reclutamento di un lich ribelle. E sarà pericolosa.\n\nQuindi preparati, {class}. Non devi fallire.\n\nTroverai Bethor nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "Saluti. O non sai chi sono, o i tuoi affari con me sono urgenti.\n\nPerché se nessuna delle due cose fosse vera, non saresti così sciocc<o/a> da disturbarmi...", "Ah, sei l'agente mandato dal magistrato Sevren. Allora sì, i tuoi affari con me sono di importanza cruciale.\n\nConfido che Sevren abbia trovato qualcuno adatto al mio compito... ma vedremo.", 0xfee82a33, 0x956051d7, 0xf7ee88d1, 0xc24b95f7, 0x878ffdc4, "....." },
  [407] = { "Campi del dolore", "Porta la ⟦Laced Pumpkin=Zucca Corrotta⟧ al Captured Scarlet Zealot rinchiuso nella cantina della taverna Gallow's End.", "Zucche innocue, vero? O almeno così sembra. Se vogliamo respingere l'avanzata di Arthas dal Nord e l'infestazione umana dal Sud, dobbiamo cominciare a sfruttare tutto il potenziale del nostro dono della non morte.\n\nCon un po' d'ingegno, una semplice zucca diventa un agente della nostra Dama Oscura. Questa zucca, corretta con la mia ultima formula, si rivelerà una vera delizia.\n\nUn altro Scarlet Zealot è stato catturato ed è rinchiuso nella cantina della taverna Gallow's End. Porta questa zucca a quello stolto.", "Sta' lontano, creatura immonda e sacrilega! Che la Luce mi protegga! La ⟦Scarlet Crusade=Crociata Scarlatta⟧ libererà Azeroth dalla tua. . .\n\n. . .oh, aspetta. È cibo per me? Ho così fame. . .", "Per la Luce! Finalmente del cibo! Dolce, dolce zucca. . . .", 0x2932f488, 0x3ae020ed, 0x5fbf4409, 0x590d0a08, 0x95632aa4, "....." },
  [408] = { "La cripta di famiglia", "Uccidi 8 Wailing Ancestor e 8 Rotting Ancestor.\n\nUccidi il capitano Dargol e porta il suo teschio al magistrato Sevren a Brill.", "La zona dei ⟦Agamand Mills=Mulini degli Agamand⟧ è diventata una testa di ponte del Flagello. Il loro punto più forte è la ⟦Agamand Family Crypt=Cripta degli Agamand⟧, dove ha posto il suo quartier generale il loro capo militare locale, uno scheletro chiamato capitano Dargol. Con la negromanzia ha risvegliato gli antenati degli Agamand e intende usarli contro di noi.\n\nNon possiamo permetterlo, e tu devi fermarlo. Raggiungi la ⟦Agamand Family Crypt=Cripta degli Agamand⟧ e sconfiggi gli antenati risvegliati degli Agamand.\n\nE portami il teschio del capitano Dargol.", "Il tempo è un lusso che non abbiamo, {name}. A ogni ora che passa, la presa del Flagello sulle ⟦Tirisfal Glades=Radure di Tirisfal⟧ si fa più salda.", "Le tue azioni hanno inferto un duro colpo al Flagello. E la tua vittoria non passerà inosservata: né ai Reietti, né ai nostri nemici.\n\nContinua la lotta come facciamo tutti, {name}, e un giorno scacceremo da Azeroth persino il Re dei Lich in persona!", 0x66f94b22, 0x78a7f290, 0x657d58bb, 0x07b8e1b4, 0xaacae948, "....." },
  [409] = { "Prova di lealtà", "Procurati una ⟦Candle of Beckoning=Candela del Richiamo⟧.\n\nEvoca Lillith Nefara e uccidila.\n\nTorna da Gunther sulla sua isola.", "Dici di non essere sottomess<o/a> alla volontà del Re dei Lich, e l'incantesimo che Bethor ha posto sul mio libro lo conferma. Ma prima di crederti devo avere la prova che sei nemic<o/a> del Flagello.\n\nAppena al largo della costa meridionale di quest'isola c'è un vecchio altare insanguinato. Lo usa una potente agente del Flagello, Lillith Nefara.\n\nPrendi una ⟦Candle of Beckoning=Candela del Richiamo⟧ da questa cassa. Accendila sull'altare e Lillith si risveglierà. Distruggi Lillith e crederò che tu sia nemic<o/a> del Re dei Lich.", "Attendo la prova della tua lealtà, {class}.", "Hai sconfitto Lillith Nefara, dimostrando di essere nemic<o/a> del Flagello. Incredibile.\n\nCredevo di essere l'unico Non Morto dotato di libero arbitrio, ma tu mi hai mostrato che ce ne sono altri che hanno spezzato il dominio del Re dei Lich.", 0xa4c93d97, 0x4be8db40, 0x7384925c, 0x4e450c0a, 0x42a35ea1, "....." },
  [410] = { "L'ombra dormiente", nil, nil, "È un tavolo vecchio, malridotto e macchiato di sangue.", "Posi la ⟦Candle of Beckoning=Candela del Richiamo⟧ sul tavolo e la accendi...", 0x860cba69, nil, nil, 0x6926ebe0, 0x9a85d915, ".mm.." },
  [411] = { "Il ritorno del lich prodigo", "Porta la ⟦Nether Gem=Gemma Fatua⟧ a Bethor Iceshard, a ⟦Undercity=Sepulcra⟧.", "Porta questa ⟦Nether Gem=Gemma Fatua⟧ al mio vecchio compagno Bethor. Ci permetterà di comunicare... e ho molto da dirgli.", "Hai restituito il libro di Gunther? Ha risposto?", "L'hai convinto a unirsi a noi! Hai compiuto una grande impresa per i Reietti, {name}. La Dama Oscura ne sarà informata.", 0xaea9b7a4, 0xfa36d7fb, 0x4d641943, 0x9d276ad6, 0xa985ef55, "....." },
  [412] = { "Operazione Recombobulation", "Porta a Razzle Sprysprocket, a Kharanos, 8 Restabilization Cog e 8 Gyromechanic Gear.", "Da un'analisi più approfondita della situazione di Gnomeregan, risulterebbe che non solo non siamo riusciti a sterminare i trogg, ma abbiamo anche trasformato gran parte della razza gnomica in orribili gnomi lebbrosi, senza cervello e malvagi.\n\nOzzie e io intendiamo invertire l'orribile effetto lebbroso con la nostra ultima invenzione: il Recombobulator. La macchina è quasi finita, ma abbiamo un disperato bisogno di Restabilization Cog e Gyromechanic Gear. Recuperane un po' dagli gnomi lebbrosi davanti all'ingresso di Gnomeregan.", "Il Recombobulator sarà in funzione non appena avremo abbastanza Restabilization Cog e Gyromechanic Gear.", "Questi Gyromechanic Gear e Restabilization Cog sono perfettamente conformi agli schemi di Ozzie per il Dispositivo di Recombobulation. Appena avrò aggiunto un po' di idrolubrificante ai pistoni a combustione interna, regolato il cricco-a-manovella e aumentato la viscosità del gel di elettrogomma, la razza gnomica sarà come nuova.", 0xeb51823c, 0x9967013a, 0x65cd1925, 0x5da233c7, 0xc3725696, "....." },
  [413] = { "⟦Shimmer Stout=Scura Brillante⟧", "Porta il ⟦Barrel of Shimmer Stout=Barile di Scura Brillante⟧ al montanaro Barleybrew.", "Vorrei che mio fratello Wellart assaggiasse la mia nuova ⟦Shimmer Stout=Scura Brillante⟧. È un montanaro di stanza nella torre di guardia meridionale, una delle due torri sul confine con Loch Modan.\n\nNon sarà un birraio come il resto di noi Barleybrew, ma adora bere e so che questa gli piacerà.\n\nPuoi portargli questo ⟦Barrel of Shimmer Stout=Barile di Scura Brillante⟧ da parte mia?", "Salve, {class}! E cosa ti porta fin quassù?\n\nQualcosa di emozionante, spero. Sono giorni che non faccio una bella zuffa, e questo barile di birra è quasi asciutto...", "<Il montanaro Barleybrew assaggia la ⟦Shimmer Stout=Scura Brillante⟧...>\n\nOh. Accidenti! Questa roba ti fa proprio brillare gli occhi. Mi sembra di vedere al buio!", 0xb36fea29, 0x8e29116f, 0xc2c58cab, 0xb59d2e44, 0xe387b846, "....." },
  [414] = { "Birra scura per Kadrell", "Porta la ⟦Cask of Shimmer Stout=Cassa di Scura Brillante⟧ al montanaro Kadrell.", "Ho bevuto ancora un po' di quella ⟦Shimmer Stout=Scura Brillante⟧ che ha fatto mio fratello: è roba fantastica! Voglio che la assaggi un altro montanaro. Si chiama Kadrell e di solito pattuglia la strada che attraversa Thelsamar, a Loch Modan.\n\nPer arrivare a Thelsamar, va' a sud-est attraverso la galleria, poi gira a nord-est dove il sentiero si apre in una strada. Segui quella strada dritto fino a Thelsamar.\n\nDai al montanaro Kadrell questa cassa di ⟦Shimmer Stout=Scura Brillante⟧ e senti che ne pensa!", "Salute a te, {class}, e benvenut<o/a> a Thelsamar!", "Ora, fammi assaggiare...\n\nPer la barba di Magni! Questa roba fa girare la testa! E alleggerisce anche le gambe.\n\nMi sembra di poter volare!", 0xd20ea02e, 0xeed35031, 0x40ac0d91, 0xffeabd23, 0x91b650e9, "....." },
  [415] = { "La nuova birra di Rejold", "Parla con Rejold Barleybrew.", "Rejold Barleybrew, a ⟦Brewnall Village=Borgo Luppolo⟧, ha chiesto di te.\n\nVuole parlarti di una nuova bevanda che sta preparando... ha detto qualcosa sul fatto che l'hai aiutato. Forse ti conviene tornare a ⟦Brewnall Village=Borgo Luppolo⟧ e sentire cos'ha da dire.\n\nPotrebbe scapparci qualche bevuta gratis...", nil, "{name}! Ti ricordi quella Shimmerweed che mi hai portato? Be', l'ho usata in un paio di ricette su cui sto lavorando, e una è venuta benissimo!\n\nEcco, assaggiala e dimmi cosa ne pensi...", 0xe805c4ca, 0x2b9ce38c, 0x1d773d33, nil, 0xb5fafd9a, "...m." },
  [416] = { "Caccia ai ratti", "Porta 12 Tunnel Rat Ear al montanaro Kadrell, a Thelsamar.", "Abbiamo un vero problema di infestazione a ovest. I coboldi Tunnel Rat si sono insediati sulle colline, scavando tane e insozzando la nostra terra con la loro sporcizia!\n\nVogliamo che siano eliminati. Dagli la caccia, portami le loro orecchie e guadagnati la taglia.\n\nTrovi i coboldi Tunnel Rat e le loro tane a ovest di Thelsamar, sparse lungo il fianco della montagna.", "Salute a te, {name}. Come va la caccia ai ratti?", "Puah! Quando ho chiesto quelle orecchie non immaginavo che puzzassero così tanto!\n\nEcco la tua ricompensa, {name}. Ben fatto.", 0x63070b4c, 0x45c146d7, 0x5b4e949e, 0x46cea726, 0x1e9a33db, "....." },
  [417] = { "La vendetta di un pilota", "Uccidi Mangeclaw.\n\nPorta il suo ⟦Mangy Claw=Artiglio Bianco⟧ e il ⟦Hildelve's Journal=Diario di Hildelve⟧ al pilota Hammerfoot.", "Nel suo diario Hildelve ha scritto di essere stato attaccato da Mangeclaw, un «enorme orso ⟦Ice Claw=Artiglio di Ghiaccio⟧». Riuscì a scacciare la bestia, ma non prima che lo dilaniasse ferocemente.\n\nA giudicare dallo stato del corpo di Hildelve, Mangeclaw deve essere tornato in seguito e averlo ucciso.\n\nTuttavia, nel suo diario Hildelve ha scritto il suo unico, ultimo desiderio:\n\nVendetta contro Mangeclaw.", "Salve, {name}. Hai notizie del mio amico Hildelve?", "Sono brutte notizie, perché Hildelve era un buon amico. E vorrei essere stato lì con te quando hai trovato quella bestia, Mangeclaw!\n\nGrazie, {name}. La tua impresa sarà ricordata dai piloti della Brigata d'Assedio di ⟦Ironforge=Forgiardente⟧.", 0xc8a157ff, 0xfc8ba3ba, 0x36d8afa5, 0x86e8914d, 0x2e3d6b6c, "....." },
  [418] = { "Sanguinacci di Thelsamar", "Porta 3 pezzi di ⟦Bear Meat=Carne d'Orso⟧, 3 ⟦Boar Intestines=Intestino di Cinghiale⟧ e 3 ⟦Spider Ichor=Icore di Ragno⟧ a Vidra Hearthstove, a Thelsamar.", "Qui a Thelsamar le pance vuote non mancano mai: bambini che entrano ed escono di corsa, operai degli scavi che arrivano dopo una dura giornata di lavoro. Siamo famosi per i nostri sanguinacci, immagino che tu non li abbia mai assaggiati?\n\nNo? Be', da queste parti il pasto bisogna guadagnarselo, e non pensare di fare eccezione solo perché sei <un/una> {class} <raffinato/raffinata>.\n\nMi servono carne d'orso, intestino di cinghiale per il budello e icore di ragno per insaporire. Procurami un po' di queste cose e lascia la cucina a Vidra!", "Sono pronta a mettermi ai fornelli: hai gli ingredienti per me?", "Credimi, sembra molto più difficile di quanto appaia, ma...\n\nOh, non ho mai conosciuto nessuno che si interessasse tanto a come si fanno le salsicce, ma ti darò la ricetta, non si sa mai. Ecco qua, e mi raccomando, mangiale fresche!", 0xa87d8ad8, 0x3da74c62, 0x0fbff557, 0x6090d9ed, 0x9a0355ae, "....." },
  [419] = { "Il pilota scomparso", "Trova il pilota Hildelve.", "Il mio amico e collega pilota di macchine d'assedio, Mori Hildelve, si è perso tra le colline. Cercavamo un minerale raro che serve per una polvere esplosiva di alta qualità e, durante le ricerche, lui ha guidato la sua macchina su per una collina ripida e l'ha sfasciata!\n\nSempre convinto che il minerale fosse su queste montagne, Hildelve mi ha incaricato di sorvegliare le nostre macchine mentre lui proseguiva a piedi.\n\nSono passati giorni e di notte ho sentito dei ringhi bestiali tra le colline. Mori è un osso duro, ma sono preoccupato.\n\nTi prego, {name}. Trovalo.", nil, "Ecco il cadavere di un nano: dilaniato, congelato e ripulito fino all'osso dagli spazzini di montagna. Stretto in mano ha un libro con gli appunti scarabocchiati di Mori Hildelve. E addosso, ancora in ottime condizioni, porta un Brigadier's Vest.\n\nQuesta scena raccapricciante dev'essere il luogo dove il pilota della macchina d'assedio ha trovato la sua fine.", 0x7f8b701c, 0x19886134, 0x7506a7ac, nil, 0x78eadffd, "...m." },
  [420] = { "Le osservazioni di Senir", "Consegna il rapporto di Grelin a Senir Whitebeard, a Kharanos.", "I trogg del tunnel sono estremamente ostili e non hanno esitato ad attaccare chi lo attraversa. Ma tu sembri abbastanza robust<o/a>, quindi dovresti cavartela.\n\nIndicazioni? Se vai a parlare con Senir, lo trovi a Kharanos.\n\nAttraversa il tunnel e, quando sbuchi dall'altra parte, continua a seguire la strada: ti porterà dritto a Kharanos.", "Come va? Ti va di bere qualcosa con me, magari? Con questo freddo non c'è molto altro da fare.", "Cos'è questo? Ah, il rapporto di mio fratello. Mm...\n\nGli avevo detto di andarci piano con il nome del re, ma non mi ha dato retta. Poco male, suppongo, anche se di sicuro farà arruffare qualche piuma al Senato. Non che non fossero piume da arruffare! Ah!\n\nComunque, immagino che questo significhi che dovrei mandare anch'io il mio rapporto a ⟦Ironforge=Forgiardente⟧, ma devo ammettere che sono un po' indietro. Maledetto freddo.\n\nPiù tardi dovrei avere del lavoro per te, se ti interessa.", 0x034f6959, 0xd1c8fc65, 0x507d5ef4, 0xd802ec21, 0xf5afd554, "....." },
  [421] = { "Dimostra il tuo valore", "Dalar Dawnweaver, presso la ⟦Sepulcher=Mausolea⟧, vuole che tu uccida 5 Moonrage Whitescalp.", "Lady Sylvanas ha incaricato Varimathras di conquistare le terre degli umani e dei nani a sud.\n\nMa quello stolto di Arugal, ciarlatano di Dalaran e ora bestia maledetta del ⟦Shadowfang Keep=Forte di Zannascura⟧, ha lasciato che la sua magia sconsiderata devastasse la roccaforte strategica della ⟦Silverpine Forest=Selva Pinargento⟧.\n\nMi serve qualcuno esperto nell'arte del combattimento che mi aiuti a rimediare al disastro di Arugal. Dimostrami il tuo valore uccidendo 5 Moonrage Whitescalp. Quelle bestie miserabili si trovano spesso appena fuori dalla strada, giù per la collina.", "Se vuoi dimostrarmi il tuo valore, devi uccidere 5 Moonrage Whitescalp. Porta a termine questo compito e farò in modo che la tua abilità venga impiegata in incarichi più degni.", "Mi hai servito bene, {class}. Per me è evidente che sarai un valido aiuto mentre mi preparo a liberare la ⟦Silverpine Forest=Selva Pinargento⟧ dalla maledizione di Arugal.", 0x4165cc3c, 0xa3af291f, 0xc69e0e06, 0x78467694, 0x2fbdf2d6, "....." },
  [422] = { "La follia di Arugal", "Recupera il ⟦Remedy of Arugal=Rimedio di Arugal⟧ per Dalar Dawnweaver, alla ⟦Sepulcher=Mausolea⟧.", "Come Arugal sia stato accettato nel Kirin Tor è un mistero per me. Le sue conoscenze arcane parevano trasparenti come un ninnolo di vetro soffiato.\n\nOra ciò che conta è scoprire esattamente quale magia abbia usato Arugal, così da poterla rivolgere contro di lui e assicurare la ⟦Silverpine Forest=Selva Pinargento⟧ alla Dama Oscura.\n\nArugal soggiornò dapprima nella fattoria di grano appena a nord del ponte. Uno degli ⟦Deathstalkers=Inseguitori della Morte⟧ ha riferito di aver visto alcuni libri di incantesimi, ma non è riuscito a recuperarli. Recupera per me da quei libri l'incantesimo intitolato ⟦Remedy of Arugal=Rimedio di Arugal⟧.", "Prima di sapere con cosa abbiamo a che fare, {class}, devo studiare l'incantesimo noto come ⟦Remedy of Arugal=Rimedio di Arugal⟧. Portamelo subito, o sarò costretto a trovarmi un servitore degno.", "È proprio l'incantesimo che cercavo, {class}. Se la tua dedizione alla causa della Dama Oscura resterà incrollabile, scoprirai di avere un bel futuro tra i Reietti.", 0x93f7323d, 0x13790612, 0x0abc03a5, 0x8be8400a, 0x953bc065, "....." },
  [423] = { "La follia di Arugal", "Porta 6 Glutton Shackle e 3 Darksoul Shackle a Dalar Dawnweaver, alla ⟦Sepulcher=Mausolea⟧.", "Dopo aver esaminato il lavoro di Arugal, i miei peggiori sospetti sono stati confermati. Quel vecchio ciarlatano non era degno di pulire i pitali a Dalaran, figuriamoci di rappresentare il Kirin Tor nella sua ora più buia. Stolti!\n\nArugal usava oggetti incantati per rafforzare la sua magia debole. Devo esaminare questi oggetti di persona. Va' e uccidi Moonrage Glutton e Moonrage Darksoul finché non avrai raccolto abbastanza delle loro manette incantate per le mie ricerche. Quelle creature immonde sono state viste a nord e a est.", "Mi servono 6 Glutton Shackle e 3 Darksoul Shackle prima di poter valutare la situazione e trovare una soluzione definitiva per Arugal. Ora fa' quanto ti ho chiesto e uccidi Moonrage Glutton e Moonrage Darksoul finché non avrai ciò che mi serve.", "Spero di riuscire a ricavare abbastanza energia da un campione così limitato. Forse avrei dovuto farti prendere più manette.\n\nComunque, hai dimostrato grande abilità nel raccoglierle, {class}.", 0x93f7323d, 0xd7d800f3, 0x1e48bc9c, 0x5a525c19, 0x264fea1f, "....." },
  [424] = { "La follia di Arugal", "Uccidi Grimson the Pale e porta la sua testa a Dalar Dawnweaver, alla ⟦Sepulcher=Mausolea⟧.", "Mi ci vorrà davvero più tempo del previsto per svelare gli oscuri segreti degli incantesimi che usava Arugal.\n\nNel frattempo, però, devo chiederti di occuparti di un piccolo problema scoperto dai nostri Darkstalker. Pare che Arugal abbia lasciato dilagare la sua magia fino all'⟦Deep Elem Mine=Abisso di Elem⟧, la miniera tra le colline a sud-est.\n\nLa miniera sarebbe una risorsa preziosa per l'avanzata di Varimathras.\n\nVoglio che tu decapiti il caposquadra corrotto della miniera, Grimson the Pale. Con la sua morte, la miniera sarà nostra.", "Grimson the Pale è stato ucciso? Varimathras non sarà contento se ignoriamo i suoi ordini.", "Eccellente. La miniera fornirà risorse superbe alle nostre forze mentre ci espandiamo in tutta ⟦Silverpine=Pinargento⟧ e nel resto di Azeroth.", 0x93f7323d, 0xa3cab538, 0x20158451, 0x4d00d6bf, 0xabedee59, "....." },
  [425] = { nil, "Uccidi Ivar the Foul e porta la ⟦Ivar's Head=Testa di Ivar⟧ a Rane Yorick, all'Ivar Patch.", "Mio fratello Quinn e io avevamo il compito di perlustrare la ⟦Silverpine Forest=Selva Pinargento⟧ e fare rapporto all'alto esecutore Hadrec. Ma non siamo andati lontano: mentre attraversavamo questa fattoria siamo stati attaccati dal ghoul Ivar the Foul.\n\nSiamo sfuggiti a Ivar, ma lui ha sbranato Quinn per bene. Si sta riprendendo grazie alla pozione che gli hai dato, ma Ivar potrebbe tornare prima che Quinn guarisca.\n\nUccidi Ivar, così Quinn avrà il tempo di rimettersi. Di solito Ivar sta nel granaio laggiù, in attesa che io abbassi la guardia.", "Hai ucciso Ivar the Foul? Se non vuoi farlo per me e mio fratello, fallo per i Reietti.", "Ah, grazie. Hai la mia gratitudine, {name}.\n\nE ti includerò nel rapporto che farò ai miei superiori.", 0xd4799367, 0x19bd6f46, 0x3025cc30, 0x30e68483, 0x37affe37, "e...." },
  [426] = { "I mulini invasi", "Raccogli 5 Notched Rib e 3 Blackened Skull, poi torna dalla Guardia della Morte Dillinger a Brill.", "Il Flagello sta cercando di stabilire una base ai ⟦Agamand Mills=Mulini degli Agamand⟧. Se ci riesce, potrà lanciare altri attacchi dentro Tirisfal.\n\nGli ordini sono stati dati. Il Flagello ai Mulini va distrutto.\n\nVa' ai Mulini. Raccogli Notched Rib dai Rattlecage Soldier e dai Cracked Skull Soldier, e Blackened Skull dai Darkeye Bonecaster.\n\nPer raggiungere i Mulini segui la strada verso ovest. Dopo aver attraversato il ponte, al bivio successivo prendi a nord e continua sempre verso nord. Quando vedrai i mulini a vento, la battaglia avrà inizio.", "Le nostre battaglie contro il Flagello continuano, {name}. Fa' la tua parte e ricaccia quei maledetti non morti senza mente nelle ⟦Plaguelands=Terre Infette⟧!", "I tuoi sforzi in guerra si fanno sentire tra noi, {name}. Non ti ringrazierò per aver fatto ciò che è necessario, ma la Guardia della Morte di Tirisfal ricorderà il tuo nome.", 0xf1b26f58, 0x6633a1b4, 0x3c638478, 0xd0a18bbd, 0x4238abe0, "....." },
  [427] = { "In guerra con la ⟦Scarlet Crusade=Crociata Scarlatta⟧", "L'esecutore Zygand di Brill vuole che tu uccida 10 Scarlet Warrior.", "I documenti forniti dall'esecutore Arren sono proprio la svolta che ci serviva nella battaglia contro la miserabile ⟦Scarlet Crusade=Crociata Scarlatta⟧. Ora conosciamo le loro posizioni esatte in tutte le ⟦Tirisfal Glades=Radure di Tirisfal⟧.\n\nMa la Guardia della Morte ha preoccupazioni più grandi. L'esercito del Re dei Lich cresce di numero ogni notte. Ci serve qualcuno con \"iniziativa\" come te per mandare nella tomba la ⟦Scarlet Crusade=Crociata Scarlatta⟧.\n\nDimostrami di essere in grado di servire la Dama Oscura: va' a ovest, alla torre oltre la ⟦Solliden Farmstead=Cascina dei Solliden⟧, e uccidi 10 Scarlet Warrior.", "Se vuoi dimostrare il tuo valore alla Dama Oscura, uccidi 10 Scarlet Warrior, {class}.", "Eccellente, {class}. La tua abilità nell'arte del combattimento è innegabile.", 0x5aa72e8b, 0x6e2fd180, 0x4814c47e, 0x8852c390, 0x35635107, "....." },
  [428] = { "⟦Deathstalkers=Inseguitori della Morte⟧ dispersi", "Trova gli ⟦Deathstalkers=Inseguitori della Morte⟧ Quinn e Rane Yorick.", "Un paio di settimane fa due dei nostri ⟦Deathstalkers=Inseguitori della Morte⟧, Rane e Quinn Yorick, sono stati mandati in ricognizione nel nord di Selva ⟦Silverpine=Pinargento⟧. Da allora non abbiamo più avuto loro notizie.\n\nPotrebbero essere caduti vittime del Flagello, ma se è così voglio averne conferma. Trova questi ⟦Deathstalkers=Inseguitori della Morte⟧.\n\nIl loro primo obiettivo era perlustrare le fattorie nel nord di Selva ⟦Silverpine=Pinargento⟧. Comincia le ricerche da lì.", nil, "Ci hai trovati! E appena in tempo...", 0x8d08680c, 0xde9b51c9, 0x0e702215, nil, 0x7b7112cf, "...m." },
  [429] = { "Cuori selvaggi", "Raccogli 3 cuori di worg scoloriti e portali allo speziale Renferrel, alla ⟦Sepulcher=Mausolea⟧.", "Mio fratello Quinn è stato ferito gravemente dal ghoul Ivar the Foul, e non so se guarirà come si deve senza un aiuto alchemico. Non sono una speziale, ma so che i nostri speziali possono preparare pozioni curative dai cuori scoloriti dei worg.\n\nRaccogli quei cuori e portali allo speziale Renferrel, alla ⟦Sepulcher=Mausolea⟧, a sud. Poi torna qui con la pozione.\n\nTroverai molti worg tra qui e il ⟦Malden's Orchard=Frutteto di Malden⟧, a est.", "Ho poco tempo, {class}: la Dama Oscura mi ha affidato un compito gravoso.", "<Renferrel prende i cuori.>\n\nÈ preoccupante sapere che i nostri ⟦Deathstalkers=Inseguitori della Morte⟧ hanno fallito la loro missione.\n\nSperiamo che questi fallimenti siano rari.\n\nTi darò la pozione tra un momento, ma ecco la sua ricetta: se quegli ⟦Deathstalkers=Inseguitori della Morte⟧ dovessero avere bisogno di aiuto in futuro, forse potrai darglielo tu.", 0x46265aa8, 0x468e1442, 0x0b973e29, 0xe2c1ed4b, 0x14750494, "....." },
  [430] = { "Ritorno da Quinn", "Porta la pozione di Quinn a Quinn Yorick, all'Ivar Patch, a nord della ⟦Sepulcher=Mausolea⟧.", "Ecco la pozione che aiuterà Quinn Yorick a riprendersi.\n\nOra, se vuoi scusarmi, ho un lavoro molto importante da portare avanti...", "Mia sorella mi ha detto che sei qui per aiutarci. È vero?", "<Quinn prende la pozione e la beve.>\n\nSì, sento che fa effetto. Presto potrò rimettermi in viaggio.\n\nMi hai fatto un grande favore, {name}.", 0xf0dc2596, 0xed042c3f, 0x57f627f0, 0xf2d24222, 0xc5dd8287, "....." },
  [431] = { "Candele del Richiamo", nil, nil, nil, "Prendi una delle candele e la metti nella sacca.", 0xb1929f4a, nil, nil, nil, 0x2a34be75, ".mmm." },
  [432] = { "Quei maledetti trogg!", "Uccidi 6 Rockjaw Skullthumper per il caposquadra Stonebrow, alla cava di Gol'Bolar.", "Quei trogg, che la Luce li fulmini, mi stanno riducendo il cantiere a un rottame! Guarda lì, un altro barile di polvere che salta!\n\nOhhh, quanto vorrei scendere laggiù e tirare il collo a ognuno di quei mingherlini! Li voglio ammazzare tutti!\n\nNon può far bene alla salute, tutto questo stress e tutta questa rabbia... Cosa mi hanno lasciato? Niente!\n\nLi ammazzerei io stesso, ma la mia mira non è più quella di una volta! Va' tu nella cava e fai fuori un po' di quei luridi bastardi! Ti pagherò! Basta che li fai soffrire, che li ammazzi!", "Mi fa infuriare! Grrr...", "Be', così mi sento un po' meglio...\n\nMa non sarò contento finché non saranno morti tutti! Tutti quanti!", 0xa38a8583, 0x68645f8e, 0xd7fa5983, 0xcd9b49ca, 0xda5abbb8, "....." },
  [433] = { "Al servizio pubblico", "Uccidi 10 Rockjaw Bonesnapper per il senatore Mehr Stonehallow, alla cava di Gol'Bolar.", "Come membro del Senato e della ⟦Explorers' League=Lega degli Esploratori⟧, mi sono fatto carico di questa parte dell'infestazione di trogg che ha colpito le nostre terre.\n\nDi certo hanno devastato la cava di Gol'Bolar, e senza motivo. Mentre scavavamo in profondità nella terra, sono sbucati fuori in massa, distruggendo la nostra attrezzatura e cacciando via i minatori. Non ci resta che sterminarli tutti, ricostruire e tornare al lavoro.\n\nSe mi aiuti con i trogg, ti ricompenserò volentieri per il tuo tempo.", "Se riusciamo a scacciare i trogg dalla cava di Gol'Bolar, sarà il primo dei tanti passi che dovremo compiere per liberarci di questa minaccia.", "È un inizio. Speriamo di poterne approfittare e di mandare qualche montanaro a mettere in sicurezza la zona. Poi potremo cominciare a ripristinare le nostre infrastrutture e far tornare i minatori al lavoro.\n\nGrazie per il tuo aiuto, {name}.", 0x23152624, 0x8332d369, 0xdd9ed5fb, 0xf528dd76, 0xc92f32fa, "....." },
  [435] = { "Scortare Erland", "Scorta Erland in mezzo ai lupi fino a Rane Yorick.", "I lupi là fuori non se ne vanno, e mi guardano con occhi cattivi ogni volta che metto piede fuori da quella porta. Devono essere davvero affamati, se pensano che valga la pena mangiarmi.\n\nDevo fare rapporto alla mia compagna di squadra, Rane Yorick degli Inseguitori della Morte. E per raggiungere Rane mi servirà aiuto contro quei lupi.\n\nTi prego, scortami! E là fuori ci sono un sacco di lupi, quindi avremo più possibilità se hai degli amici che possono darci una mano...", "Sii breve, ti prego. Il pericolo è ovunque e non possiamo restare fermi a chiacchierare.", "Grazie per l'aiuto, {name}. Temevo che Erland fosse stato sopraffatto dai pericoli di ⟦Silverpine=Pinargento⟧. Grazie a te, vedo che non è così.", 0xd56111cc, 0x1d0e5dcf, 0x938665ef, 0xff823412, 0xaae0989d, "....." },
  [436] = { "Lo scavo di Ironband", "Parla con l'esploratore Fellhew.", "Il prospettore Ironband dirige lo scavo di antiche rovine a est del lago. Ultimamente i suoi progressi sono lenti, specie considerando tutte le provviste che gli abbiamo mandato.\n\nIronband è un nano robusto e onesto che bada ai risultati, e questo mi fa temere che ci siano forze che lavorano contro di lui.\n\nVa' allo scavo di Ironband e parla con Magmar Fellhew. Si occupa dei dettagli del sito e saprà perché i lavori rallentano.\n\nPer raggiungere lo scavo, aggira la punta meridionale del lago, poi dirigiti a est.", nil, "Jern vuole sapere perché i lavori rallentano, eh?\n\nIronband sta preparando il suo ultimo rapporto con tutti i dettagli, ma una cosa posso dirtela io:\n\nSono i trogg!!", 0x2c4f5a39, 0x18791172, 0x721d5d65, nil, 0x7334fe2a, "...m." },
  [437] = { "L'Agro dei Morti", "Uccidi gli gnoll Rot Hide all'Agro dei Morti.\n\nQuando compare Nightlash, uccidila.\n\nPorta l'⟦Essence of Nightlash=Essenza di Sferanotte⟧ all'alto esecutore Hadrec, alla ⟦Sepulcher=Mausolea⟧.", "I primi rapporti dei nostri esploratori su ⟦Silverpine=Pinargento⟧ indicano che i Rot Hide hanno una base in una vecchia fattoria a nord, l'Agro dei Morti. Abbiamo lanciato contro di loro piccoli attacchi, ma ogni volta ricevono rinforzi dalla banshee Nightlash, che con la sua magia mette in rotta le nostre forze.\n\nVogliamo che Nightlash venga distrutta.\n\nVa' all'Agro dei Morti e attacca i Rot Hide. Se non vedi Nightlash, uccidi i Rot Hide finché non compare, poi sconfiggila.\n\nLa sua essenza si ridurrà in polvere. Portami quella polvere come prova.", "Hai sconfitto Nightlash, {name}? Il nostro successo contro i Rot Hide dipende dalla sua distruzione!", "Ho saputo della tua riuscita incursione contro i Rot Hide, {name}, e questa essenza è la prova della morte di Nightlash.\n\nOggi il Flagello ha perso terreno. Il tuo valore per i Reietti cresce.", 0x19a0e0e1, 0x94c5883b, 0xcad784a9, 0x0ae8e887, 0xfa2a4b70, "....." },
  [438] = { "Il traghetto decrepito", "Raggiungi il traghetto decrepito.\n\nScopri perché il Flagello si trova lì.", "{name}, abbiamo scoperto un nuovo covo del Flagello: il traghetto decrepito. Il traghetto si trova a est della ⟦Sepulcher=Mausolea⟧ ed è pattugliato da numerosi Rot Hide e altri non morti.\n\nDev'esserci un motivo se il Flagello occupa la zona. Va' al traghetto decrepito e scopri perché il Flagello si trova lì.", nil, "In questa barca è ammucchiata una pila di cadaveri avvolti in bende. E guardando a est oltre il ⟦Lordamere Lake=Lago Lordamere⟧, si scorge un molo dall'altra parte, sull'⟦Fenris Isle=Isola di Fenris⟧.\n\nIl destino dei cadaveri dev'essere legato all'⟦Fenris Isle=Isola di Fenris⟧.", 0x97530730, 0xbfa7d2d4, 0x8d58e9c8, nil, 0xe0ee0465, "...m." },
  [439] = { "Indizi sui Rot Hide", "Porta l'⟦Deliah's Ring=Anello di Deliah⟧ all'alto esecutore Hadrec, alla ⟦Sepulcher=Mausolea⟧.", "Tra i cadaveri sporge una mano, senza bende. È la mano di una donna, butterata dalla pestilenza ma relativamente fresca.\n\nAl dito c'è un anello. Sfilandolo ed esaminandolo, scopri un'incisione:\n\n«Per Deliah»", "{name}. Sei tornat<o/a>, quindi immagino che le tue indagini abbiano dato frutto?", "Dici che questo anello lo portava una donna uccisa di recente?\n\nL'unico posto qui vicino da cui potrebbe venire un corpo simile sono le fosse comuni di Tirisfal. Gli gnoll Rot Hide devono portare quei cadaveri all'⟦Fenris Isle=Isola di Fenris⟧!", 0x289840ab, 0xd59dacd7, 0x784cd106, 0x6fc0f68a, 0xde42ded4, "....." },
  [440] = { "L'anello inciso", "Porta l'⟦Deliah's Ring=Anello di Deliah⟧ al magistrato Sevren a Brill.", "Se vuoi trovare il marito o l'amato che ha dato a Deliah il suo anello... allora parla con il magistrato Sevren a Brill. Dovrebbe avere i registri dei decessi recenti e, con un po' di fortuna, potrà scoprire chi sia Deliah.\n\nMa non ci spererei. Chiunque le abbia dato l'anello è probabilmente morto. O, se è un non morto, probabilmente di Deliah non gli importa più nulla.", "Salve, {name}. Cosa ti riporta a Brill?", "Una certa Deliah viveva a Brill, non molto tempo fa. È stata sepolta nella fossa comune, ma se quello che dici è vero, gli gnoll Rot Hide devono aver rubato il suo corpo e averlo portato a ⟦Silverpine=Pinargento⟧.\n\nI Rot Hide, come tutto il Flagello, vanno distrutti. Confido che tu stia facendo il necessario perché accada.", 0x9c594b06, 0x3b544afb, 0x37390a55, 0x8f05840a, 0x92cc36a4, "....." },
  [441] = { "Raleigh e ⟦Undercity=Sepulcra⟧", "Porta l'⟦Deliah's Ring=Anello di Deliah⟧ a Raleigh.", "Deliah aveva un marito, Raleigh, che ora vive a ⟦Undercity=Sepulcra⟧. Se la Deliah che viveva a Brill è quella a cui apparteneva questo anello, Raleigh lo saprà.\n\nRaleigh si trova nel ⟦Trade Quarter=Quartiere del Commercio⟧ di ⟦Undercity=Sepulcra⟧.", "Ci conosciamo?", "Sì, questo anello era di mia moglie. Il suo destino è stato quello di tutti coloro che non riescono a sopravvivere a questi tempi duri. Non provo nulla per la sua morte, né per la storia che racconti sul rapimento del suo corpo.\n\nSentimenti simili si sono raffreddati in me da tempo. Ma un desiderio arde ancora nel mio cuore morto, {name}.\n\nIl desiderio di vendetta.", 0xf2f8becb, 0x2a2120e4, 0x68a8bdd5, 0x879570ca, 0xc3ca1109, "....." },
  [442] = { "Assalto all'⟦Fenris Isle=Isola di Fenris⟧", "Porta la ⟦Thule's Head=Testa di Thule⟧ all'alto esecutore Hadrec, alla ⟦Sepulcher=Mausolea⟧.", "È giunto il momento di assaltare la roccaforte del Flagello a ⟦Silverpine=Pinargento⟧: l'⟦Fenris Isle=Isola di Fenris⟧.\n\nDevi tornare sull'isola e distruggere Thule Ravenclaw. Voglio la sua testa!\n\nQuesta missione è tanto pericolosa quanto vitale, {name}. Non devi fallire.", "Non possiamo permettere che il Flagello resti a ⟦Silverpine=Pinargento⟧, {name}. Torna da me quando avrai la prova della morte di Thule.", "La morte di Thule Ravenclaw non è stata cosa da poco, {name}. Renferrel mi dice che le energie liberate quando hai distrutto Thule si sono avvertite persino alla ⟦Sepulcher=Mausolea⟧.\n\nLe tue azioni risuonano tra le file dei Reietti. Il tuo valore per noi cresce.", 0x8c0400d6, 0x90739e69, 0xcc5d4db1, 0xeecb06e8, 0x3df470a5, "....." },
  [443] = { "⟦Rot Hide Ichor=Icore di Pellemarcia⟧", "Porta 8 bottiglie di Icore di Pellemarcia allo speziale Renferrel alla ⟦Sepulcher=Mausolea⟧.", "Prima di lanciare un assalto all'⟦Fenris Isle=Isola di Fenris⟧, dobbiamo scoprire chi c'è dietro gli gnoll Pellemarcia. I nostri speziali credono che la loro origine stia nello strano fluido che scorre nei loro corpi.\n\nVa' all'⟦Fenris Isle=Isola di Fenris⟧, a est del Decrepit Ferry, e raccogli l'icore di Pellemarcia dagli gnoll che trovi laggiù. Portalo allo speziale Renferrel, di stanza fuori dalla ⟦Sepulcher=Mausolea⟧.", "Hai l'icore di Pellemarcia, {name}?", "Molto bene. Questo icore ci aiuterà a capire la natura dei Pellemarcia e potrebbe mostrarci il loro punto debole...\n\n...se ne hanno uno.", 0x90b269c6, 0xd63f7b63, 0xdc2829eb, 0xac2920ec, 0xf7c5204c, "....." },
  [444] = { "Le origini dei Pellemarcia", "Porta l'⟦Sample Ichor=Icore Campione⟧ a Bethor Iceshard a ⟦Undercity=Sepulcra⟧.", "Ho ridotto l'icore che mi hai portato e l'ho separato nei suoi componenti di base. Le mie scoperte non sono definitive, ma ho stabilito che nella sua creazione sono state usate magie da stregone e negromantiche.\n\nMentre continuo a studiare l'icore, voglio che tu ne porti un campione a Bethor Iceshard, a ⟦Undercity=Sepulcra⟧. Bethor non è uno speziale, ma la sua conoscenza della magia potrebbe aiutare a svelare il mistero dei Pellemarcia.\n\nVa'. Troverai Bethor nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "I miei studi richiedono grande concentrazione. Spero quindi che la tua visita non sia frivola.", "Questa sostanza è intrisa di potenti incantesimi, alcuni dei quali non vedevo da tanto, tantissimo tempo...\n\nUn momento... devo invocare un incantesimo di divinazione...", 0xd15f0da4, 0xdd620190, 0xb0943b84, 0xf5eccafc, 0xa52b889f, "....." },
  [445] = { "Una consegna per ⟦Silverpine Forest=Selva Pinargento⟧", "Porta i risultati dello speziale Johaan allo speziale Renferrel, a ⟦Silverpine Forest=Selva Pinargento⟧.", "Il tempo è un lusso che non è concesso a chi di noi è al servizio di Lady Sylvanas. Ormai dovresti saperlo.\n\nCome membro della Royal Apothecary Society, è mio dovere condividere il mio sapere con i colleghi, affinché i nostri sforzi comuni possano un giorno dare alla Dama Oscura la Nuova Piaga che tanto desidera.\n\nPorta questi risultati allo speziale Renferrel, di stanza alla ⟦The Sepulcher=Mausolea⟧, a ⟦Silverpine Forest=Selva Pinargento⟧. Da Brill segui le strade verso sud. Da ⟦Undercity=Sepulcra⟧, dirigiti a sud-ovest.", "Che affari hai con me, {class}?", "Ah, che gentile lo speziale Johaan a mandare le sue ricerche. Con tutte le novità qui a ⟦Silverpine=Pinargento⟧, mi ero quasi dimenticato dei risultati che arrivano da Lordaeron e dalle ⟦Tirisfal Glades=Radure di Tirisfal⟧. A proposito, devo spedire presto quei campioni alla Necropolis.\n\nMa perdona le mie divagazioni. Prolunga il tuo soggiorno a ⟦Silverpine=Pinargento⟧, {name}. Ci farebbe comodo qui <un/una> {class} in gamba come te.", 0x2e8b0154, 0x1c9b0cbd, 0xb9cda9ec, 0x3e97b540, 0x3ac792af, "....." },
  [446] = { nil, "Porta la ⟦Bethor's Scroll=Pergamena di Bethor⟧ allo speziale Renferrel, alla ⟦Sepulcher=Mausolea⟧, a ⟦Silverpine=Pinargento⟧.", "Questo icore è stato creato da un mio vecchio collega: Thule Ravenclaw. Prima della grande guerra era un mago giovane e promettente, ma quando il Re dei Lich salì al potere tradì i suoi confratelli e si alleò con il Flagello.\n\nNon sapevo che fosse ancora vivo, né che guidasse i Rot Hide nelle loro incursioni contro di noi!\n\nConosco molti dei suoi incantesimi e posso aiutare a preparare una pozione per contrastarli. Porta questa pergamena allo speziale Renferrel. Contiene le formule necessarie per la pozione.", "Salute, {name}. Cos'aveva da dire Bethor?", "Questa pergamena è intrisa di una magia potente. Non ho mai usato forze simili in una pozione... sarà una miscela potente, e dovrebbe esserti molto utile se attaccherai Thule nella sua roccaforte sull'⟦Fenris Isle=Isola di Fenris⟧.", 0x57daa6c7, 0x59967169, 0x042f5571, 0x8927eab0, 0x7025b4ee, "e...." },
  [447] = { "Una ricetta per la morte", "Raccogli 6 Grizzled Bear Heart e 6 campioni di ⟦Skittering Blood=Sangue Brulicante⟧ e consegnali al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "Le forze di Arthas sono soverchianti. Ma con una Nuova Piaga potremmo sradicare una volta per tutte sia l'esercito del Flagello sia l'infestazione Umana.\n\nI miei studi hanno dimostrato che il sangue di ragno, unito a una tossina ricavata dal cuore di un orso grigio, dà un elisir mortale. Raccogli campioni dai ragni dello Skittering Dark, a nord-ovest, e dagli orsi che vagano per la ⟦Silverpine Forest=Selva Pinargento⟧. Consegna i reagenti al maestro speziale Faranell della Royal Apothecary Society, a ⟦Undercity=Sepulcra⟧.", "Salve, {class}. Che affari hai con la Royal Apothecary Society?", "Che gentile lo speziale Renferrel a mandarti da me, {name}. Questi campioni si riveleranno davvero utili alla causa. Comincerò subito a studiarne le proprietà tossiche e contaminanti.", 0x9bd96087, 0x208db28d, 0x5edf7be6, 0x15bc577b, 0x367733d6, "....." },
  [448] = { "Rapporto a Hadrec", "Fai rapporto all'alto esecutore Hadrec, alla ⟦Sepulcher=Mausolea⟧.", "Prima di lanciare un assalto all'⟦Fenris Isle=Isola di Fenris⟧, fai rapporto all'alto esecutore Hadrec. Potrebbe avere altre informazioni o l'equipaggiamento che ti servirà.", nil, "Se ciò che dice Bethor è vero, Thule Ravenclaw è una forza da affrontare, e da affrontare presto.\n\nPer aiutarti in questo compito, puoi prendere qualcosa dal nostro arsenale...", 0x844a69cf, 0x65ab3030, 0xbcd0c567, nil, 0x5fbf7280, "...m." },
  [449] = { "Il rapporto degli ⟦Deathstalkers=Inseguitori della Morte⟧", "Porta il ⟦Deathstalker Report=Rapporto sugli Inseguitori della Morte⟧ all'esecutore supremo Hadrec, alla ⟦Sepulcher=Mausolea⟧.", "Anche se le ferite di Quinn stanno guarendo, voglio far arrivare il nostro rapporto all'esecutore supremo Hadrec il prima possibile. Contiene informazioni vitali per l'occupazione di ⟦Silverpine=Pinargento⟧ da parte dei Reietti.", "Hai scoperto che fine hanno fatto gli ⟦Deathstalkers=Inseguitori della Morte⟧?", "Non avevo previsto una presenza del Flagello come quella che abbiamo visto nella ⟦Silverpine Forest=Selva Pinargento⟧, né le difficoltà che i nostri ⟦Deathstalkers=Inseguitori della Morte⟧ hanno incontrato nelle loro ricognizioni.\n\nIl tuo aiuto ai nostri ⟦Deathstalkers=Inseguitori della Morte⟧ è stato prezioso, {name}. E riceverai un encomio.", 0x18ffce2e, 0x519228b9, 0xe630f60f, 0xdc68e1b5, 0x036c5730, "....." },
  [450] = { "Una ricetta per la morte", "Recupera il diario dello speziale Berard a ⟦Pyrewood Village=Rovonero⟧ e portalo allo speziale Renferrel, alla ⟦Sepulcher=Mausolea⟧.", "Puoi rendere un altro servizio alla Royal Apothecary Society, {name}.\n\nQuando Arugal ha scagliato la sua magia maledetta sulla foresta, ha colpito uno dei nostri membri più promettenti, lo speziale Berard. Ora che è un servo senza mente di Arugal, Berard non ci serve più a nulla. Le sue scoperte, però, potrebbero rivelarsi preziose. Stava studiando un'antica pestilenza che secoli fa sterminò tutte le creature acquatiche del Lake Lordamere.\n\nRecupera il ⟦Berard's Journal=Diario di Berard⟧ dal suo studio nella locanda di ⟦Pyrewood Village=Rovonero⟧ e portalo allo speziale Renferrel.", "Vedo che sei tornat<o/a>, {name}.", "Il diario dello speziale Berard! Sei davvero coraggios<o/a>, {name}. Ora vediamo cosa stava combinando Berard prima di impazzire...", 0x9bd96087, 0x995d38e8, 0xd129f3dd, 0x28eec3e3, 0x3b144e17, "....." },
  [451] = { "Una ricetta per la morte", "Porta 6 campioni di ⟦Lake Creeper Moss=Muschio di Camminatore dei Laghi⟧, 6 campioni di ⟦Lake Skulker Moss=Muschio di Furtivo dei Laghi⟧ e un ⟦Hardened Tumor=Tumore Indurito⟧ al maestro speziale Faranell a ⟦Undercity=Sepulcra⟧.", "Secondo il ⟦Berard's Journal=Diario di Berard⟧, il muschio dei Lake Skulker e dei Lake Creeper potrebbe rivelarsi utile per la nostra ricerca di una nuova piaga. Quelle bestie vivono sulle isole di Lake Lordamere, a est.\n\nMenziona anche un rarissimo ⟦Hardened Tumor=Tumore Indurito⟧ che ha scoperto su un murloc Vile Fin. A quanto pare il tumore è così raro che Berard è riuscito a procurarsene solo uno.\n\nRaccogli dei campioni del muschio e il raro ⟦Hardened Tumor=Tumore Indurito⟧ e portali al maestro speziale Faranell a ⟦Undercity=Sepulcra⟧.", "Che cosa ti riporta a ⟦Undercity=Sepulcra⟧, {name}?", "Che duro colpo per la Royal Apothecary Society perdere Berard. Ma grazie al tuo impegno e alle diligenti ricerche dello speziale Renferrel, gli studi di Berard serviranno ancora alla causa della Dama Oscura.\n\nSiamo sul punto di ottenere qualcosa di grande, {name}. Se non fossi così abile nell'arte del combattimento, cercherei di reclutarti nella Society.", 0x9bd96087, 0xd477e1df, 0x2254fe23, 0x09a6dc7b, 0x41deeb73, "....." },
  [452] = { "Imboscata a Rovonero", "Aiuta l'inseguitrice della Morte Faerleia a uccidere il Pyrewood Council.", "Sei arrivat<o/a> appena in tempo, {name}!\n\nIl Pyrewood Council tornerà da un momento all'altro. Arugal ha altre faccende di cui occuparsi nella fortezza. Usa il Consiglio come semplici marionette per tenere sotto controllo i servi senza mente di Rovonero. Ma credo che, senza la guida del Pyrewood Council, i figli di Arugal si rivolteranno contro il loro padrone.\n\nNon posso affrontarli tutti da sola. Ho bisogno del tuo aiuto. Insieme possiamo annientare il Consiglio, per Lady Sylvanas.", nil, "Hai combattuto come <un/una> <vero/vera> <discepolo/discepola> della Dama Oscura, {name}. Con il consiglio morto, forse riusciremo a prendere il controllo di questa città una volta per tutte e a cacciare Arugal dal ⟦Shadowfang Keep=Forte di Zannascura⟧. Ti saluto!", 0x2e010a83, 0xc67918a7, 0xf4516ba5, nil, 0x04404ce2, "...m." },
  [453] = { "Sulle tracce della figura misteriosa", "Trova la figura misteriosa. I tuoi indizi:\n\nNon è originario di ⟦Darkshire=Borgoscuro⟧.\n\nÈ un tipo nervoso e agitato.\n\nHa lasciato ⟦Darkshire=Borgoscuro⟧ dirigendosi a ovest.", "Buona fortuna, {name}. Spero che tu trovi quel tizio, e spero che tu lo trovi vivo.\n\nSe ha lasciato la sicurezza di ⟦Darkshire=Borgoscuro⟧, potrebbe finire preda delle belve selvatiche.", "Chi sei?? Lasciami in pace!", "<Jitters sospira...>\n\nSì, sono io l'autore di quel libro. Alla fine mi hai trovato, eh?\n\nBe', se hai letto quel diario... allora sai solo metà della storia!", 0x2ae0c829, 0xd39bd401, 0x2c24a350, 0x9d47818e, 0x344ae3ba, "....." },
  [454] = { "Dopo l'imboscata", "Parla con Miran.", "Prima di questa... faccenda, trasportavamo i barili di polvere avanti e indietro a più riprese. Ora dobbiamo dividerci il lavoro: Miran porta i barili e io sorveglio gli altri.\n\nNon mi sento tranquillo a lasciare che Miran trasporti da solo il resto del carico. Quando è pronto a partire, magari potresti scortarlo nel suo prossimo viaggio?", nil, "Salve, {class}.\n\nSarai tu a scortarmi al sito di scavo? Mi fa piacere saperlo... Dopo Saean e i suoi tirapiedi, chissà cos'altro hanno in serbo i Ferroscuro?\n\nComunque, lasciami fare gli ultimi controlli. Parlami di nuovo quando sei pront<o/a> a partire.", 0x2d57ae65, 0xb4a1fd8d, 0x4806532e, nil, 0x7d1ab5fb, "...m." },
  [455] = { "La traversata di Algaz", "Attraversa Dun Algaz.\n\nUccidi 8 Dragonmaw Scout e 6 Dragonmaw Grunt.\n\nPresentati a Valstag Ironjaw, a ⟦Menethil Harbor=Porto di Menethil⟧.", "Gli orchi del clan delle Fauci di Drago hanno un rifugio nelle ⟦Wetlands=Paludi Grigie⟧. E ora si sono spinti fino a Dun Algaz! Non possiamo lasciare che mantengano una posizione qui, o Loch Modan resterà tagliato fuori da ⟦Menethil Harbor=Porto di Menethil⟧, il nostro porto e la nostra roccaforte nelle ⟦Wetlands=Paludi Grigie⟧.\n\nApriti un varco attraverso Dun Algaz fino alle ⟦Wetlands=Paludi Grigie⟧ e, già che ci sei, uccidi qualche orco! Fai rapporto a Valstag Ironjaw, a ⟦Menethil Harbor=Porto di Menethil⟧.\n\nMenethil si trova oltre Dun Algaz: segui la strada verso nord, poi prendi a ovest al bivio.\n\nContiamo su di te, {name}. Non fallire.", "Vieni da Loch Modan? Com'è la situazione con gli orchi alla ⟦Algaz Gate=Porta di Algaz⟧?", "Il tuo rapporto è pieno di cattive notizie!\n\nVedo che le Fauci di Drago stanno avanzando in forze verso Algaz. Di solito se ne stanno nascoste sulle colline. Cosa le abbia spinte a riversarsi su Algaz è ancora un mistero...\n\nGrazie, {name}. E probabilmente avremo bisogno del tuo aiuto per occuparci di questi orchi.", 0x3a6441ba, 0x8925dac0, 0x2bd879fc, 0xadb75063, 0xcd00a06e, "....." },
  [456] = { "L'equilibrio della natura", "Uccidi 7 Young Nightsaber e 4 Young Thistle Boar e torna dal conservatore Ilthalaine.", "Salute, {name}. Sono il conservatore Ilthalaine. Il mio compito a ⟦Shadowglen=Vallombra⟧ è assicurarmi che l'equilibrio della natura sia mantenuto.\n\nQuest'anno le piogge di primavera sono state particolarmente abbondanti, e così alcune bestie della foresta hanno prosperato mentre altre hanno sofferto.\n\nPurtroppo i Nightsaber e i Thistle Boar sono diventati troppo numerosi. ⟦Shadowglen=Vallombra⟧ può produrre solo una certa quantità di cibo per le bestie. Va', giovane {class}, e sfoltisci i cinghiali e i felini, così che l'armonia della natura sia preservata.", "C'è ancora del lavoro da fare, {name}. Torna da me quando avrai sfoltito i Nightsaber e i Thistle Boar.", "Hai svolto bene i tuoi compiti, {name}.", 0x2cefa7e3, 0x57f2ad93, 0x2ca7f2af, 0x1bb3c7c9, 0xb4a95be9, "....." },
  [457] = { "L'equilibrio della natura", "Il conservatore Ilthalaine ha bisogno che tu uccida 7 Mangy Nightsaber e 7 Thistle Boar.", "Sfoltire le creature più giovani qui a ⟦Shadowglen=Vallombra⟧ è stato un buon inizio, {name}, ma c'è ancora del lavoro da fare.\n\nLe risorse della foresta si esauriranno troppo in fretta se il problema non viene affrontato. Uccidere le bestie della natura è un male necessario per il bene di tutti coloro che condividono questa terra. Addentrati nella foresta e abbatti i Mangy Nightsaber e i Thistle Boar in nome dell'equilibrio.", "Il tuo compito non è ancora finito, {name}. Torna da me quando avrai ucciso 8 Mangy Nightsaber e 8 Thistle Boar.", "Hai dimostrato bene la tua dedizione alla natura, {name}. <Un/Una> giovane {class} come te ha un futuro promettente.", 0x2cefa7e3, 0xc9b080bf, 0x37d9d1de, 0xe2130366, 0x943085ad, "....." },
  [458] = { "La protettrice dei boschi", "Cerca la driade chiamata Tarindrella.", "Grazie al cielo sei qui, {class}. Strane notizie mi sono giunte attraverso i sussurri degli spiriti della foresta.\n\nLa misteriosa protettrice dei boschi, Tarindrella, è tornata a ⟦Shadowglen=Vallombra⟧. Da anni la presenza della driade non si avvertiva nelle foreste di Kalimdor. Se ha fatto ritorno in questa terra, di certo qualcosa non va.\n\nCerca Tarindrella e scopri quali faccende la portano nel nostro bosco. Una delle ⟦Sentinels=Sentinelle⟧ ha riferito di averla vista a sud-ovest di Aldrassil.", nil, "Vedo che mi hai trovata, giovane {race}. Melithar è un druido saggio, ad averti mandato da me. Ma hai ancora molto da imparare. So che quelli della tua razza amano i libri. Prendine uno, ti prego, per approfondire la tua istruzione.", 0x89f0da3a, 0x7d2d6e81, 0xa893a5da, nil, 0x8298799d, "...m." },
  [459] = { "La protettrice dei boschi", "Raccogli 8 ⟦Fel Moss=Vilmuschio⟧ e portali a Tarindrella.", "Qualcosa di malvagio si sta preparando nelle foreste di Teldrassil. Guarda bene verso le colline dove un tempo vivevano i pacifici mezzorsi. Hanno abbandonato le loro case e si stanno radunando sotto il nome di tribù dei ⟦Gnarlpine=Mordipigna⟧.\n\nSolo la corruzione del malvagio ⟦Fel Moss=Vilmuschio⟧ potrebbe causare una simile trasformazione. I grell e i grellkin hanno infestato la zona e minacciano gli abitanti di ⟦Shadowglen=Vallombra⟧.\n\nAffronta questi grell e grellkin, {name}, e scopri se sono davvero caduti sotto l'incantesimo del malvagio ⟦Fel Moss=Vilmuschio⟧.", "Conferma i miei sospetti, {name}. Portami 8 ⟦Fel Moss=Vilmuschio⟧.", "Il tuo servizio alle creature di ⟦Shadowglen=Vallombra⟧ merita una ricompensa, {name}.\n\nHai però confermato i miei timori. Se i grell sono stati contaminati dal ⟦Fel Moss=Vilmuschio⟧, si può solo immaginare che cosa ne sia stato della tribù di mezzorsi ⟦Gnarlpine=Mordipigna⟧ che un tempo viveva qui.\n\nSe ti troverai a Dolanaar, abile {class}, cerca il saggio druido Athridas Bearmantle. Condivide la nostra preoccupazione per il benessere della foresta.", 0x89f0da3a, 0x26033e95, 0xd7bf71e4, 0x048ee8f1, 0x503e2cc2, "....." },
  [460] = { "Riposa in pezzi", "Porta la ⟦Alaric's Head=Testa di Alaric⟧ alla sua tomba.", "Non sembri un Pellemarcia. Bene. Avevo perso ogni speranza...\n\nMi chiamo Alaric, e un tempo ero il primo servitore e la guardia del corpo di Thule. Usò la sua magia per \"proteggermi\" dalla piaga dei non morti, ma il suo incantesimo mi diede invece una non vita da cui non posso fuggire. E dopo aver creato i maledetti gnoll Pellemarcia, Thule mi decapitò... e diede la mia testa agli gnoll come giocattolo!\n\nTi prego, portami dal mio corpo. Credo che gli gnoll l'abbiano sepolto qui a ⟦Fenris Keep=Forte Fenris⟧, vicino alla stalla, in una tomba senza nome.", "Questa tomba è stata scavata in fretta.", "Grazie, {name}. Temevo che gli gnoll avessero distrutto il mio corpo. È bello sapere che non l'hanno fatto.", 0xbaedcb62, 0x793129d1, 0xb3b726d1, 0x8c9b8322, 0x3b9cc0ec, "....." },
  [461] = { "La nicchia nascosta", "Porta Alaric all'alcova nascosta.", "Conosco una nicchia nascosta all'interno del forte che custodisce un oggetto caro a Thule e ai suoi vecchi colleghi. Contiene anche qualcosa che potrebbe esserti utile. Portami là!\n\nL'alcova si trova nella torre sud-occidentale del forte, dietro uno scaffale impolverato.\n\nPrendi il mio corpo, ma lascia stare i miei stivali. Tanto non mi sono mai andati bene...", "È questo il posto! Portami più vicino...", "Ecco fatto, è aperta. Lasciami qui. Ho passato i giorni migliori della mia vita in questo forte, e il pensiero di riposare fra le sue mura mi conforta.\n\nAssicurati di chiudere bene l'alcova: non voglio che quei Rot Hide mi trovino.\n\nAh, e prendi questo. Te lo sei meritato.", 0xa99e0958, 0x096624be, 0x5066a675, 0x42a11c2d, 0xa6ae72db, "....." },
  [463] = { "Il Greenwarden", "Trova il Greenwarden.", "Hai sentito parlare del Greenwarden? Non starai mica cercando lui, vero? Be', se è così sei fuori di testa, ma chi sono io per impedire a uno sciocco di andare incontro alla propria morte?\n\nSe cerchi quella bestia, ho sentito dire che sta nella palude, a est della strada, dove si biforca verso Dun Modr. Si aggira lì tra i coccodrilli... e peggio!\n\nE lascia qui i tuoi soldi. Dove vai non ti serviranno... e non vorrai che il vecchio Greenie si scheggi un dente sul tuo oro mentre ti stacca in due con un morso, no?", nil, "Le radici e le felci parlano bene di te, piccol<o/a>. Anche se ho molti nomi, rispondo solo a pochi. Ma tu puoi chiamarmi Rethiel.\n\nE ora ascolta... perché queste terre piangono per ferite purulente, e io ti incarico di guarirle.", 0xfb7098bf, 0xbe0cd27c, 0x6f613338, nil, 0xf9cd436c, "...m.", nil, nil, 0x65c7375f, nil, nil },
  [464] = { "Stendardi di guerra", "Porta 8 Stendardo di Guerra delle Fauci di Drago al capitano Stoutfist.", "Il clan di orchi delle Fauci di Drago fu quasi annientato alla fine della Seconda Guerra, dopo aver perso il controllo dei suoi draghi rossi addomesticati. I draghi non erano affatto contenti dei loro vecchi padroni e diedero una caccia spietata alle Fauci di Drago. I pochi sopravvissuti fuggirono da Grim Batol e si rifugiarono sulle montagne a est degli Scavi di Whelgar.\n\nOra hanno ripreso forza e hanno un accampamento a nord-est di Menethil.\n\nVogliamo che tu attacchi quell'accampamento. Raccogli i loro stendardi di guerra e portameli come prova.", "Hai attaccato l'accampamento delle Fauci di Drago?", "Ben combattuto, {name}. Le Fauci di Drago non sono più la minaccia di quando avevano i draghi, ma restano avversari feroci.\n\nLe Fauci di Drago sono guidate da Nek'rosh, figlio di Nekros, che anni fa era il capo delle Fauci di Drago. Nekros usò una potente magia per domare i draghi rossi, ma quando quella magia lo tradì... i draghi non ne furono affatto contenti.\n\nNekros fu ucciso, e suo figlio ha giurato vendetta contro i draghi che gli uccisero il padre.", 0x342e9831, 0xfebb6d1b, 0x31e6e5db, 0x6eddf078, 0xb005d6c1, "....." },
  [466] = { "Alla ricerca dell'incendicite", "Porta 6 carichi di ⟦Incendicite Ore=Minerale di Incendicite⟧ al pilota Stonegear a Dun Morogh.", "Ho sentito che nelle ⟦Wetlands=Paludi Grigie⟧, in una grotta a nordovest della ⟦Algaz Gate=Porta di Algaz⟧, hanno trovato un minerale raro, l'incendicite. L'incendicite è roba instabile e difficile da usare senza saltare in aria, ma sono sicuro che, fusa nel modo giusto, potrebbe dare proiettili da cannone dalla potenza devastante!\n\nPortami del minerale di incendicite e troverò qualcuno abbastanza coraggioso da sperimentarlo.\n\nAh, e per estrarre quel minerale da un filone ti servirà l'abilità in Estrazione. Se non ce l'hai, allora... porta in quella grotta un amico che ce l'abbia!", "Dov'è quel minerale, {name}?!", "Hai il minerale! Ben fatto, {name}! Lo farò lavorare subito da qualcuno. Speriamo che non salti in aria!", 0x469ffcbc, 0x3c97991b, 0x5e710ce5, 0x46a9e54f, 0x6a8505d0, "....." },
  [467] = { "La ricerca di Stonegear", "Parla con il pilota Stonegear.", "Il pilota Stonegear adora il suo mezzo d'assedio, come ogni pilota che si rispetti! Ed è sempre ansioso di trovare nuovi modi per aumentare la potenza di fuoco del suo carro!\n\nHa sentito parlare di un minerale raro e cerca qualcuno che glielo vada a scovare. Se ti prudono i piedi, trova Stonegear allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧, nel Dun Morogh, e senti cosa vuole.", nil, "Ciao, {name}. Sei qui per il compito che ho da affidare, eh? Fa piacere vedere <un/una> giovane {race} come te a cui il sangue ribolle all'idea dell'avventura!", 0xbf72506c, 0x71b54a38, 0x914d3b00, nil, 0x768a05c1, "...m." },
  [468] = { "A rapporto dal montanaro Rockgar", "Parla con il montanaro Rockgar.", "Il montanaro Rockgar cerca volontari per una missione attraverso Dun Algaz, fino alle ⟦Wetlands=Paludi Grigie⟧.\n\nSe vuoi bagnarti gli stivali in quella contea fradicia a nord, parla con Rockgar a Dun Algaz. Dun Algaz si trova a nord lungo la strada, oltre la torre di guardia.", nil, "Salve, {class}! Sei qui per la missione di ricognizione, vero? Benissimo!\n\nSpero che il tuo equipaggiamento sia in buone condizioni, perché questa missione di «ricognizione» si è trasformata in qualcosa di più sporco...", 0xaca33545, 0x25296a5b, 0x8f51853a, nil, 0xf66d3152, "...m." },
  [469] = { "Consegna quotidiana", "Consegna il ⟦Bundle of Crocolisk Skins=Mucchio di Pelli di Crocolisco⟧ a James Halloran, il conciatore, a ⟦Menethil Harbor=Porto di Menethil⟧.", "Salute, <viaggiatore/viaggiatrice>!\n\nNon è che per caso stai andando dalle parti di Menethil? Se no, ti consiglio di fermarti lì: è un buon posto per comprare merci e perfino per farsi una pinta e rilassarsi.\n\nOra, se per caso vai proprio da quella parte, ti dispiacerebbe portare questo mucchio di pelli di crocolisco a James Halloran, il conciatore?\n\nLo farei io, ma ultimamente mia moglie è piuttosto di cattivo umore, e vorrei rimandare il più possibile il momento di affrontarla.", "Salve, {class}. Posso interessarti a un paio di stivali? Magari qualche pelle conciata di fresco?", "Mmh, questo è da parte di Einar, giusto? È quasi una settimana che non mi consegna le pelli di persona. Senza dubbio qualche screzio con la moglie!\n\nForse manderò mia moglie a parlare con Sida, prima o poi...", 0x4ccc1397, 0x32b2e18d, 0xd17d7bf3, 0x65e51f86, 0xbde24237, "....." },
  [470] = { "Frugando nella melma", "Una delle melme del ⟦Ironbeard's Tomb=Sepolcro di Barbaferrea⟧ ha la borsa di Sida: recuperala e riportagliela al ⟦Menethil Harbor=Porto di Menethil⟧.", "Durante la mia visita settimanale al ⟦Ironbeard's Tomb=Sepolcro di Barbaferrea⟧ mi hanno attaccata delle orribili melme gocciolanti! Naturalmente, sono andata nel panico.\n\nHo lanciato la borsa contro una di loro, ma non è servito a niente! La melma l'ha risucchiata e basta... Per fortuna, mi ha dato il tempo di scappare.\n\nIl brutto è che ho davvero bisogno di ciò che c'era nella borsa!\n\nNon so contro quale melma l'ho lanciata: sembravano tutte uguali! Il ⟦Ironbeard's Tomb=Sepolcro di Barbaferrea⟧ è a nord-est di qui, vicino a Dun Modr. Grazie mille!", "Hai trovato la mia borsa?", "Oh, grazie, {name}! Temevo che fosse perduta per sempre!\n\n<Svuota in fretta per terra il contenuto della borsa coperta di melma, poi lo raccoglie.>\n\nMm, a me non serve più a molto, ma dagli una lavata e sono sicura che potrai farne buon uso.", 0x775c3dbd, 0xca612179, 0xa1442cd7, 0xffefe4fa, 0xf927327c, "....." },
  [471] = { "I doveri dell'apprendista", "Raccogli 6 Pelle di Crocolisco Gigante e portale a James Halloran, a ⟦Menethil Harbor=Porto di Menethil⟧.", "Ho mandato il mio apprendista nelle paludi a scuoiare qualcuno dei nostri famosi crocolischi giganti delle ⟦Wetlands=Paludi Grigie⟧. Quando non è tornato, sono andato a cercarlo... Diciamo solo che non è stato un bello spettacolo.\n\nLa levatrice dice che potrebbe cavarsela, ma nel frattempo a me servono ancora le pelli!\n\n...Se ti va di uccidere qualcun altro di quei bestioni, non avrei niente in contrario, dopo quello che hanno fatto. Troverai i coccodrilli a nord, risalendo la costa, oltre le capanne dei murloc.", "Il mio apprendista è come un figlio per me. Sarà dura per lui vivere con una gamba sola.\n\nAh, {name}, come va? Hai le mie pelli?", "Mmm... Non è che ti interesserebbe diventare il mio apprendista, vero?\n\nAh! No, sto scherzando. Tanto per cominciare, sei troppo vecchi<o/a>. E poi, a guardarti, si direbbe che tu abbia altre ambizioni nella vita. Comunque, queste che mi hai procurato sono ottime pelli, e saprò farne buon uso.", 0x574671c8, 0xeda0e52b, 0xb121762e, 0xfe757fb5, 0x2c27a8df, "....." },
  [472] = { "La caduta di Dun Modr", "Cerca Longbraid nei pressi della città di Dun Modr.", "Dun Modr è caduta in mano ai ⟦Dark Iron Dwarves=Nani Ferroscuro⟧!\n\nLe mie ferite sono gravi, {class}. Quasi tutto il reggimento è stato ucciso! Quei bruti ⟦Dark Iron=Ferroscuro⟧ ci hanno attaccati prima che potessimo riorganizzarci dopo l'imboscata al ⟦Thandol Span=Viadotto di Thandol⟧.\n\nIl nostro capo, Longbraid, ha suonato il corno della ritirata. Mentre lasciavamo la città, un'ascia vagante mi ha colpito alla schiena. Poi è stato tutto buio.\n\nMi sono risvegliato qui a Menethil, ma temo per i miei compagni. In me arde ancora la speranza. Forse Longbraid è ancora vivo! Vedi se riesci a trovarlo vicino a Dun Modr, {race}!", nil, "Quale <coraggioso/coraggiosa> {class} manda notizie da Menethil? Ah, {name}, ti chiamano.\n\nPorti speranza in una situazione senza speranza. È davvero una buona notizia che il giovane Harlo sia sopravvissuto. Durante la fuga ha ricevuto una ferita grave. Abbiamo avuto appena il tempo di mandarlo via in groppa all'unico destriero sopravvissuto del reggimento.\n\nMa ora ci troviamo in una situazione pericolosa. Dun Modr è caduta e siamo solo l'ombra del grande reggimento che eravamo un tempo.", 0x2480801e, 0x9ccb757d, 0xd17a7577, nil, 0x4bca7f5e, "...m." },
  [473] = { "Rapporto al capitano Stoutfist", "Parla con il capitano Stoutfist.", "{name}. Il clan di orchi delle Fauci di Drago sta mostrando la sua forza non solo ad Algaz.\n\nIl capitano Stoutfist ha chiesto di parlare con chi è disposto a offrire aiuto contro questi orchi. È dentro la fortezza, nella sala di guerra.", nil, "{name}. Valstag mi ha informato dei tuoi successi passati contro gli orchi delle Fauci di Drago a Dun Algaz. Sei <un/una> {race} di valore.\n\nE ho un compito per te.", 0x738d103f, 0x4a1d9b30, 0x08a06865, nil, 0x4b813de0, "...m." },
  [475] = { "Una brezza inquietante", "Cerca Gaerolas Talvethren a ⟦Starbreeze Village=Brezzastella⟧.", "Una brezza inquietante soffia attraverso la foresta.\n\nGaerolas Talvethren è il Grande Custode dei Druids of the Talon in letargo nell'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧. Il suo compito, come protettore prescelto dei Dormienti, è garantire la loro sicurezza, perché il loro patto con Ysera continui a essere rispettato.\n\nMa le notizie di Gaerolas ora tardano e io comincio a preoccuparmi. Viaggia a est fino a ⟦Starbreeze Village=Brezzastella⟧ e riportami un rapporto di Gaerolas, così potrò mettere a tacere le mie preoccupazioni, sapendo che i miei fratelli sognanti dormono al sicuro.", nil, "Siano ringraziati gli spiriti della foresta, sei qui! Sapevo che Athridas avrebbe avvertito il pericolo e mandato aiuto.", 0x42437c5a, 0x464394e4, 0xaf4e302f, nil, 0x78e5478b, "...m." },
  [476] = { "La corruzione dei ⟦Gnarlpine=Mordipigna⟧", "Torna da Athridas Bearmantle a Dolanaar.", "La tribù dei ⟦Gnarlpine=Mordipigna⟧ è stata corrotta!\n\nI mezzorsi, un tempo pacifici, si sono rivoltati contro i protettori della foresta. Mi hanno teso un'imboscata mentre partivo per l'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧ e poi hanno saccheggiato ⟦Starbreeze Village=Brezzastella⟧. Ursal the Mauler, il loro capo, usa i poteri malvagi del ⟦Fel Moss=Vilmuschio⟧ per farli impazzire.\n\nSono troppo ferito per tornare da Athridas a portargli questa grave notizia. Il compito spetta a te, giovane {class}. Possiamo solo sperare che i ⟦Gnarlpine=Mordipigna⟧ impazziti non abbiano ancora raggiunto Ban'ethil!", nil, "Per le stelle! Questo è davvero molto inquietante!", 0x333dcbf7, 0xc82e6f6a, 0xda446a65, nil, 0x5e5ae3c1, "...m." },
  [477] = { "Valichi di confine", "Recupera il contenuto di una delle casse dei maghi di Dalaran. Troverai ⟦Pyrewood Village=Rovonero⟧ a sud.", "Come forse sai, la città di ⟦Ambermill=Mulino d'Ambra⟧ resta un focolaio di opposizione umana, soprattutto grazie al sostegno che riceve dai maghi di Dalaran.\n\nNon so quale sia il loro piano, ma se mostrano interesse per un villaggio sperduto come ⟦Ambermill=Mulino d'Ambra⟧, deve avere un'importanza maggiore.\n\nStanno spedendo casse su casse da ⟦Hillsbrad=Colletorto⟧ con i carri. Molte di quelle provviste finiscono in un piccolo accampamento a nord di ⟦Pyrewood Village=Rovonero⟧. Recupera il contenuto di una cassa e portamelo.", nil, "<Forzando il coperchio della cassa, trovi un assortimento di oggetti imballati con cura. In cima c'è un fascio di mappe ingiallite dal tempo, che sembrano raffigurare la ⟦Silverpine Forest=Selva Pinargento⟧ e altre parti del Lordaeron occidentale.\n\nSotto le mappe c'è un pendente magico dall'aria misteriosa.>", 0x2ab2002c, 0x34ecda45, 0x7b469157, nil, 0x18486046, "...m." },
  [478] = { "Mappe e rune", "Porta lo strano pendente al Sacerdote dell'Ombra Allister, alla ⟦Sepulcher=Mausolea⟧.", "<Togli in fretta il pendente dalla cassa e rimetti a posto il coperchio.>", "Hai scoperto qualcosa di utile, {name}?", "Mappe e questo... pendente, eh? Interessante.\n\nÈ evidente che i maghi di Dalaran si interessano a ⟦Ambermill=Mulino d'Ambra⟧ per qualche motivo, ma il loro scopo mi resta ancora oscuro.\n\nForse Dalar saprà qualcosa del loro uso.", 0xf6f2bae9, 0xf8e14cc9, 0xd8e2db76, 0x27f9af48, 0xb86a9652, "....." },
  [479] = { "Indagini a ⟦Ambermill=Mulino d'Ambra⟧", "Procurati 8 Dalaran Pendant per il Sacerdote dell'Ombra Allister, alla ⟦Sepulcher=Mausolea⟧.", "Dalar sta cercando di individuare la fonte degli incantesimi dei maghi. Per ora dobbiamo rallentare i loro progressi in ogni modo possibile...\n\nGli evocatori, i maghi e i protettori portano di certo i pendenti. Strappaglieli e recuperali.\n\nPrendi la strada principale verso sud e poi la diramazione a est per ⟦Ambermill=Mulino d'Ambra⟧.", "Dobbiamo sbrigarci: i loro piani non devono realizzarsi, o rischiamo di perdere il controllo della ⟦Silverpine Forest=Selva Pinargento⟧.", "Dalar ha scoperto che la tessitura è a buon punto, nonostante la battuta d'arresto.\n\nUn mago di grande potere sta guidando l'energia magica. Va fermato in fretta.", 0x8bd36624, 0x6146c2b3, 0xd0b38a65, 0x9b61e2ce, 0x2b98fa69, "....." },
  [480] = { "Il tessitore", "Uccidi l'arcimago di Dalaran, poi recupera il suo bastone per il sacerdote dell'Ombra Allister alla ⟦Sepulcher=Mausolea⟧.", "Un arcimago di grande potere sta sovrintendendo alla riattivazione del nodo di energia tellurica. Visti i progressi che hanno fatto, la nostra unica speranza di fermarli è ucciderlo. Non sarà facile: di sicuro è protetto da molti altri maghi e guardiani.\n\nDevi andare, e devi eliminarlo in fretta. Quando sarà morto, recuperami il suo bastone. Ora va'.", "Presto, il tempo stringe, {name}!", "La magia dei maghi si dissolve e le energie telluriche si assopiscono. I tuoi sforzi hanno dato frutto, {name}: abbiamo inferto un duro colpo ai nostri nemici e agli arroganti maghi di Dalaran.\n\nDobbiamo però restare vigili, sapendo che quella fonte di energia è così vicina... Bisogna fare piani per il futuro.", 0xfccb2595, 0x7a833cf6, 0xe5cf22a6, 0x94847aa9, 0x16a486ed, "....." },
  [481] = { "L'analisi di Dalar", "Porta il pendente inciso di rune a Dalar Dawnweaver, alla ⟦Sepulcher=Mausolea⟧.", "Porta il pendente a Dalar Dawnweaver: forse lui potrà fare luce sui piani dei maghi.", "Sì, {class}? Che c'è?", "Interessante: altre macchinazioni del Kirin Tor, a quanto pare. Questo è un manufatto potente. Era usato spesso dai potenti maghi del Kirin Tor per incanalare energie magiche.\n\nIl fatto che ne stiano portando così tanti a ⟦Ambermill=Mulino d'Ambra⟧ indica che hanno in corso un progetto di una certa portata.\n\nVedrò se riesco a penetrare i loro scudi e a scoprire le loro intenzioni.", 0xd8838416, 0x06e6855e, 0x728cbfa3, 0xcc36545e, 0x3d8d2712, "....." },
  [482] = { "Le intenzioni di Dalaran", "Parla con il Sacerdote dell'Ombra Allister, alla ⟦Sepulcher=Mausolea⟧.", "Ma certo! Come ho potuto dimenticarlo?\n\nMulino d'Ambra era uno dei luoghi segnalati dal Kirin Tor, perché ospita un nodo di energia tellurica dormiente. I maghi devono avere in mente di riattivare il nodo e usarne le energie per uno scopo più grande.\n\nNon possiamo permetterlo...\n\nServirà una gran quantità di potere per attivare le energie telluriche della zona: possiamo rallentarli sottraendo i pendenti ai maghi.\n\nRiferisci queste informazioni ad Allister, deciderà lui come agire.", nil, "Brutte notizie mi porti, {name}. Se Dalar ha ragione, e non ho motivo di credere il contrario, dobbiamo muoverci in fretta.\n\nDevo consultarmi con lui sul nostro piano d'attacco. Nel frattempo, però, dovremo rallentare i loro progressi.", 0x058d0862, 0x399d30b9, 0xe7b56a1e, nil, 0xb93463a9, "...m." },
  [483] = { "Le Relics of Wakening", "Recupera le Relics of Wakening e portale ad Athridas Bearmantle, a Dolanaar.", "Sono stati visti degli invasori ⟦Gnarlpine=Mordipigna⟧ devastare l'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧, a ovest.\n\nI druidi addormentati resteranno intrappolati per l'eternità nel ⟦Emerald Dream=Sogno di Smeraldo⟧, ignari del loro destino, se non li aiutiamo. Il delicato rituale di ibernazione non può essere interrotto senza le Relics of Wakening.\n\nRaggiungi l'Eremo e recupera il ⟦Raven Claw Talisman=Talismano Artiglio del Corvo⟧, la ⟦Black Feather Quill=Piuma Nera⟧, lo ⟦Sapphire of Sky=Zaffiro del Cielo⟧ e la ⟦Rune of Nesting=Runa della Nidificazione⟧. I druidi li custodiscono in forzieri sacri. Riportali a me e preparerò il rituale del risveglio.", "{name}, i Druids of the Talon rapiti resteranno intrappolati per sempre nel ⟦Emerald Dream=Sogno di Smeraldo⟧ se non recuperiamo le Relics of Wakening dall'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧, a ovest.\n\nOgni minuto di ritardo avvicina di un passo il loro destino alla dannazione eterna.", "Ci sei riuscit<o/a>, giovane {class}! Ben fatto. E appena in tempo, aggiungerei.", 0x269464e3, 0x956f3a24, 0x3fcb2591, 0xa4a2f2fb, 0x69323857, "....." },
  [484] = { "Pelli di crocolisco giovane", "Procura $N1 Pelle di Crocolisco Giovane per James Halloran a ⟦Menethil Harbor=Porto di Menethil⟧.", "Sono James Halloran, il conciatore. Le mie pelli di crocolisco conciate sono ricercate ovunque, e i carichi partono via nave verso porti di tutto il mondo.\n\nHai conosciuto Einar? È uno dei cacciatori che mi portano pelli di crocolisco.\n\nSono un po' a corto delle pelli più morbide, quelle dei crocolischi giovani.\n\nVisto che le scorte scarseggiano, ti pagherò profumatamente per una partita di pelli. Trovi i crocolischi giovani nelle acque appena fuori città.", "{name}, giusto? Hai le mie pelli?", "Bel lavoro, {name}. La qualità di queste pelli è superba. Dovrò metterle in concia il prima possibile. Oh, ma prima di farlo, c'è un altro lavoro da sbrigare di cui penso tu possa occuparti.", 0xade45334, 0x2f1b74bf, 0xe4e1e7f0, 0x268e2dce, 0x1944bc7f, "....." },
  [486] = { nil, "Uccidi Ursal the Mauler e torna da Athridas Bearmantle, a Dolanaar.", "Ora è giunto il momento di salvare i Druids of the Talon. Se falliamo adesso, {name}, resteranno per sempre perduti nel sonno.\n\nPreparerò le Relics of Wakening e celebrerò il rituale. Perché la mia opera abbia effetto, la bestia maledetta responsabile di questa orribile situazione deve essere uccisa. Solo allora il rituale sarà completo.\n\nÈ stato Ursal the Mauler a interferire con la vocazione dei nostri fratelli, ed è Ursal the Mauler che ora deve pagare perché siano liberati. Raggiungi l'⟦Gnarlpine Hold=Accampamento dei Mordipigna⟧, a sud-ovest, e uccidilo.", "I nostri fratelli non potranno essere risvegliati finché Ursal the Mauler non sarà ucciso, {name}.", "{name}, ti sei dimostrat<o/a> <un/una> {class} davvero degn<o/a> e capace. Un {race} che segue la via dell'onore con la tua sicurezza troverà di certo grande gloria in questo mondo.\n\nChe gli spiriti della foresta ti proteggano ovunque ti portino i tuoi viaggi.", 0xb9e1d498, 0xa1727d4c, 0x3474dc51, 0xd8fc3fa7, 0x6273f6f3, "e...." },
  [487] = { "La strada per Darnassus", "Uccidi 6 Gnarlpine Ambusher e torna dalla sentinella Amara Nightwalker, fuori da Dolanaar.", "La strada per Darnassus va tenuta sicura. I viaggiatori diretti da Dolanaar a Darnassus riferiscono di attacchi spietati da parte dei mezzorsi corrotti della tribù ⟦Gnarlpine=Mordipigna⟧.\n\nOgni giorno notizie importanti e merci viaggiano da e per Darnassus lungo questa strada. Non possiamo permetterci che una banda di selvaggi senza legge terrorizzi la gente.\n\nPrendi le armi in nome della foresta sacra, {class}. La loro tana si trova da qualche parte sotto questo punto d'osservazione. Uccidi 6 di questi Gnarlpine Ambusher e fai rapporto da me.", "La strada non è ancora sicura, {class}. Va' e uccidi 6 Gnarlpine Ambusher, poi torna da me.", "Hai servito bene la brava gente di Dolanaar e di Darnassus, <valoroso/valorosa> {class}. Come membro delle Sentinelle di Teldrassil, rendo onore ai tuoi sforzi.", 0x02e02bee, 0x82c785f5, 0x0083a597, 0x0910083a, 0x48dc3b9e, "....." },
  [488] = { "Agli ordini di Zenn", "Porta a Zenn Foulhoof, fuori da Dolanaar, 3 Nightsaber Fang, 3 Strigid Owl Feather e 3 pezzi di ⟦Webwood Spider Silk=Seta di Ragno Telalegno⟧.", "Desideros<o/a> di lavorare, vedo. Per tua fortuna non passa giorno senza che io desideri un {class} alle prime armi che esegua i miei ordini.\n\nVedi, {name}, posso renderti molto felice e procurarti cose che non hai mai nemmeno sognato di avere. Ma perché accada devi portarmi certi oggetti.\n\nI miei affari nella foresta richiedono spesso certi... reagenti. Procurami 3 Nightsaber Fang, 3 Strigid Owl Feather e 3 pezzi di ⟦Webwood Spider Silk=Seta di Ragno Telalegno⟧.\n\nChe resti il nostro piccolo segreto, {race}.", "Sei stat<o/a> un'ape operosa, {name}? Aspettavo che mi portassi quello che mi serve.", "Ah ah! Ben fatto davvero.\n\nChi avrebbe mai detto che io, Zenn Foulhoof, avrei avuto un {race} ai miei ordini? Di certo non io! Ma così va il mondo... questo nostro amato mondo è pieno di sorprese.\n\nTre evviva per gli ingenui e i creduloni!", 0x3c90fdc2, 0x717fc8a2, 0xccae3948, 0xb7e65c4d, 0x8c124f4e, "....." },
  [489] = { "Cerca la redenzione!", "Raccogli 3 Fel Cone e dalle a Zenn Foulhoof, fuori Dolanaar.", "Il Council of the Forest ha saputo che hai aiutato Zenn Foulhoof. Quel satiro è un nemico della foresta. Come {race}, dovresti sapere che non si profana la foresta uccidendo le creature della Natura.\n\nDevi riscattarti agli occhi del Council, se vuoi restare <amico/amica> di Teldrassil.\n\nDai una lezione a Foulhoof e sarai <redento/redenta>. I Fel Cone sono semi corrotti che cadono dagli alberi. Emettono sbuffi di fumo verde.\n\nDanne qualcuno a Foulhoof. Penserà che tu gli abbia portato uno spuntino innocuo.", "Cos'hai per me, {name}? Uno spuntino delizioso, suppongo?", "Ah, che {race} adorabile! Sapevo che mi saresti <tornato/tornata> utile!", 0x713743b3, 0x0ce5bdd5, 0x26b28abb, 0x2249cbce, 0x33294b57, "....." },
  [490] = { "Taglia: mezzorsi ⟦Gnarlpine=Mordipigna⟧", "Shayla Nightbreeze, sulla strada fuori Darnassus, vuole che tu le porti $N1 Gnarlpine Fang.", "Per ordine tassativo delle ⟦Sentinels=Sentinelle⟧, istituisco una taglia sui ⟦Gnarlpine=Mordipigna⟧. Non sono più amici della foresta. La corruzione li ha resi minacce senza senno per il nostro popolo e per le creature della radura.\n\nCome stabilito, sarai <ricompensato/ricompensata> per aver liberato Teldrassil dalla minaccia dei mezzorsi. Portami le loro zanne come prova delle tue gesta.\n\nTroverai i mezzorsi concentrati nella ⟦Ban'ethil Hollow=Vallata di Ban'ethil⟧, a ovest di Dolanaar e a sud della strada, e a ⟦Starbreeze Village=Brezzastella⟧, a est.", "Teldrassil non può prosperare se la corruzione contamina la terra. Caccia i ⟦Gnarlpine=Mordipigna⟧ da questa foresta, una volta per tutte.", "Hai servito bene, {name}. Sarai <ricompensato/ricompensata> per il tuo contributo.", 0x15504232, 0x7d8799e1, 0x356c46a1, 0xe87d5faf, 0xd1d90b14, "....." },
  [491] = { "Una bacchetta per Bethor", "Porta la ⟦Woven Wand=Bacchetta Intrecciata⟧ a Bethor Iceshard, nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "Thule una volta mi raccontò che, molto tempo fa, lui e due colleghi crearono una bacchetta magica, intrecciando insieme le bacchette da apprendista che ciascun mago possedeva. Quella bacchetta era il simbolo della loro amicizia e, sebbene Thule finì per disprezzarla, non riuscì a separarsene, né poteva lasciarla agli altri. Così rubò la bacchetta e la nascose a ⟦Fenris Keep=Forte Fenris⟧.\n\nEcco. Porta la bacchetta a Bethor Iceshard, uno dei vecchi amici di Thule. Sono sicuro che la vorrà.", "{name}. Hai sconfitto Thule Ravenclaw?", "...che cos'è questa? Thule aveva la nostra ⟦Woven Wand=Bacchetta Intrecciata⟧? Pensavo fosse andata perduta quando la nostra amicizia si spezzò e lui si schierò con il Re dei Lich!\n\nNon deve averne invocato il potere, altrimenti l'avrei percepito. Ed è un bene che non l'abbia usata...\n\nÈ un ritrovamento straordinario. Hai la mia gratitudine, {name}, e sarai ricompensat<o/a>.", 0x45c93402, 0xe42d61cc, 0x20d403d4, 0x1b246f8d, 0x117496a2, "....." },
  [492] = { "Una nuova piaga", "Porta il Johaan's Special Drink al montanaro prigioniero.", "Secondo la Guardia della Morte, è appena stato catturato un altro di quegli sciocchi montanari nanici. Alla Guardia della Morte piace usare la cantina della Gallows End Tavern come cella, finché i prigionieri non possono essere sistemati «come si deve».\n\nPerché non vai a vedere come il montanaro prigioniero gradisce questa bevanda speciale che ho preparato per lui? Contiene un sottile assaggio di ciò che la Dama Oscura ha in serbo per il resto di Azeroth.", "Se avessi il mio fidato fucile, saresti già <morto/morta>, {class}. Aspetta solo che arrivi la Steam Tank Brigade a salvarmi!", "Ah, finalmente da bere. Di sicuro non è una ⟦Rhapsody Malt=Birra Rapsodia⟧, ma a questo punto prendo qualsiasi cosa pur di bagnarmi il becco.", 0x4012ba5a, 0x46e5d67b, 0xb19d0a59, 0xe2d8db78, 0x7a7546f8, "....." },
  [493] = { "Viaggio alle ⟦Hillsbrad Foothills=Alture di Colletorto⟧", "Consegna le scoperte dello speziale Renferrel allo speziale Lydon, nel villaggio del ⟦Tarren Mill=Mulino di Tarren⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.", "La Royal Apothecary Society è sottoposta a un'enorme pressione da parte della Dama Oscura per sviluppare una Nuova Piaga. Lavoriamo con diligenza e abbiamo fatto molti progressi. Crediamo che il successo arriverà molto più in fretta se condividiamo le informazioni all'interno della Society.\n\nPer questo voglio che tu consegni le mie ultime scoperte allo speziale Lydon al ⟦Tarren Mill=Mulino di Tarren⟧, un piccolo villaggio annidato nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Sarà un lungo viaggio.\n\nDirigiti a sud e resta sulle strade. Segui attentamente i cartelli!", "Hai qualcosa per me?", "Ah, eccellente. Lo speziale Renferrel ha tutta la mia stima. Non vedo l'ora di studiare il suo lavoro.", 0x49f62cad, 0x59f23d5b, 0xa20ad1d6, 0xa03be4c2, 0x77090878, "....." },
  [494] = { "È ora di colpire", "Raggiungi il ⟦Tarren Mill=Mulino di Tarren⟧ e consegna il messaggio dell'inseguitore della Morte Lesh all'alta esecutrice Darthalia.", "Taci e presta attenzione, {class}.\n\nSono stato mandato in questa posizione per sorvegliare il villaggio di ⟦Hillsbrad=Colletorto⟧. La mia è una missione di ricognizione. È fondamentale che tu porti subito un messaggio all'alta esecutrice Darthalia, al ⟦Tarren Mill=Mulino di Tarren⟧. Falle sapere che io, l'⟦Deathstalker=Inseguitore della Morte⟧ Lesh, invio il seguente messaggio:\n\n«Il grido del corvo da occidente chiama.»\n\nSegui la strada verso est e fai molta attenzione ai cartelli. Ora sbrigati! Corri al ⟦Tarren Mill=Mulino di Tarren⟧, e con urgenza, aggiungerei!", nil, "«Il grido del corvo da occidente chiama»?\n\nNotizie eccellenti! ⟦Hillsbrad=Colletorto⟧ è matura per l'attacco. Ora possiamo mettere in atto il nostro piano di distruzione. Varimathras ne sarà compiaciuto.", 0x21fbe6c8, 0xdc490290, 0xf2a72a87, nil, 0x6d384f87, "...m." },
  [496] = { "⟦Elixir of Suffering=Elisir della Sofferenza⟧", "Lo speziale Lydon del ⟦Tarren Mill=Mulino di Tarren⟧ vuole 10 Lingua d'Orso Grigio e un po' di ⟦Creeper Ichor=Icore di Camminatore⟧.", "Ah, un'altra giornata penosa al ⟦Tarren Mill=Mulino di Tarren⟧. Tutta quest'aria pulita mi mette di pessimo umore, {name}.\n\nPrima riusciremo ad appestare gli umani di qui, meglio sarà. Sto conducendo studi approfonditi su possibili agenti letali da usare nei miei intrugli, ma non ho il tempo di raccoglierli tutti.\n\nSe vuoi renderti utile, procurami quanto segue: 10 lingue d'orso grigio e il rarissimo e introvabile ⟦Creeper Ichor=Icore di Camminatore⟧. Troverai sia gli orsi sia i camminatori appena fuori ⟦Tarren Mill=Mulino di Tarren⟧.", "Vedo che sei <tornato/tornata>. Spero che tu sia <riuscito/riuscita> a raccogliere gli agenti che mi servono. Un'altra giornata senza morte mi metterebbe di un umore così cupo.", "Questi campioni sono perfetti. Ebbene, {name}, sei <riuscito/riuscita> a portarmi un barlume di gioia in un'altra giornata miserabile. I tuoi sforzi sono apprezzati.", 0x146268e0, 0x3d995aa2, 0x9dac60ff, 0x87a55b6f, 0x524140e5, "....." },
  [498] = { "Il salvataggio", "Krusk, al ⟦Tarren Mill=Mulino di Tarren⟧, ha bisogno che tu liberi Drull e Tog'thar da ⟦Durnholde Keep=Forte Durnholde⟧.", "Io e altri guerrieri siamo stati mandati dal Capoguerra a recuperare un oggetto da Durnholde e a indagare su questa cosiddetta ⟦Syndicate=Lega dei Tagliagole⟧.\n\nSiamo andati a Durnholde a dare un'occhiata, ma un gran numero di umani ci ha colti di sorpresa. Abbiamo combattuto con coraggio, ma erano troppi e ci hanno sconfitti. Hanno fatto prigionieri alcuni di noi, ma io sono riuscito a scappare.\n\nDurnholde è appena a sud-est di qui, oltre il fiume. Tengono prigionieri Drull e Tog'thar: devi andare a liberarli.", "Devi sbrigarti, {class}. Rabbrividisco al pensiero di cosa gli umani potrebbero fare a Drull e Tog'thar.", "Così gli umani pensavano di fare schiavi i nostri guerrieri, eh? Gliela faremo vedere noi!\n\nSembra che abbiano portato Gol'dir, il nostro capo, in un altro luogo. Dobbiamo trovarlo e liberarlo. Ma per ora non abbiamo idea di dove sia...\n\nQuando avremo una pista, te lo farò sapere di sicuro, {name}.", 0x159a2ed8, 0xe459be02, 0x1f8bc674, 0x1fba2d2c, 0x9e396e8f, "....." },
  [499] = { "⟦Elixir of Suffering=Elisir della Sofferenza⟧", "Dai a Umpi l'⟦Elixir of Suffering=Elisir della Sofferenza⟧.", "Mi basterà un attimo per mescolare questi componenti in quello che ho battezzato ⟦Elixir of Suffering=Elisir della Sofferenza⟧.\n\nEcco fatto! Ah, niente rallegra una giornata cupa su queste colline miserabili come portare un po' di sofferenza nel mondo.\n\nVediamo se la nostra pozioncina ha avuto l'effetto desiderato.\n\nDa' al mio assistente Umpi un assaggio di ciò che la Dama Oscura ha in serbo sia per gli umani sia per il Flagello.", "Cra!", "Gracc!", 0x146268e0, 0xa4579478, 0x84f92d8f, 0xcffd874e, 0xb3b43e90, "....." },
  [501] = { "⟦Elixir of Pain=Elisir del Dolore⟧", "Porta 10 fiale di ⟦Mountain Lion Blood=Sangue di Puma⟧ allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Oh, {name}... a ⟦Hillsbrad=Colletorto⟧ i fiori sbocciano e l'aria è così fresca e frizzante. Non posso fare a meno di crogiolarmi nella miseria di tutto questo. Guardo fuori dalla mia finestra sudicia e sogno il giorno in cui la nostra Nuova Piaga porterà a questo mondo la morte che merita.\n\nPer quanto mi piacerebbe passare la giornata a rimuginare, il dovere verso la Dama Oscura mi chiama. Mi aiuti? Le mie ricerche mi portano a credere di poter preparare uno splendido intruglio di morte con il sangue di un puma. Portamene un po' e ci divertiremo.", "Mi ricordo di te, {name}. Dovevi aiutarmi a preparare il mio ultimo elisir. Mi serve quel sangue prima di poter portare la mia speciale miseria agli abitanti di ⟦Hillsbrad=Colletorto⟧.", "Raccolta superba, {name}.", 0x5f95556d, 0xae81b3e0, 0xb6ac6284, 0x514bdf87, 0xa3c56c40, "....." },
  [502] = { "⟦Elixir of Pain=Elisir del Dolore⟧", "Fai bere l'⟦Elixir of Pain=Elisir del Dolore⟧ a Stanley.", "Ah, niente come l'odore del sangue fresco sulle colline!\n\nOra ci aggiungiamo un pizzico di questo e un po' di quello, e che il vero divertimento abbia inizio! Ciò che ho creato con questo sangue mi piace chiamarlo ⟦Elixir of Pain=Elisir del Dolore⟧. Se i miei calcoli sono giusti, questo intruglio potrebbe essere l'inizio di qualcosa di molto bello per Lady Sylvanas. Ma ci serve una prova.\n\nPorta questo elisir alla fattoria settentrionale dei ⟦Hillsbrad Fields=Campi di Colletorto⟧, a sud-ovest. Vediamo se a Stanley, il cagnolino del contadino Ray, piace questo «bocconcino».", "Bau?", "Versi un po' di elisir nella mano e lo tieni davanti alla bocca di Stanley.", 0x5f95556d, 0x21d6f5d9, 0x37c4b112, 0x0625e132, 0xa319b98f, "....." },
  [509] = { "Elisir dell'agonia", "Porta 6 Mudsnout Blossoms allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Un altro giorno, un altro elisir da preparare. Se dipendesse da me, lascerei che quei patetici umani e il Flagello se la sbrighino tra loro. Sembrano già decisi a sterminarsi a vicenda.\n\nAhimè, la nostra Dama Oscura vuole accelerare un pochino le cose, quindi perché non passare queste giornate macabre spargendo un po' di morte e malattia per le terre?\n\nEcco il piano, {name}: va' alla ⟦Nethander Stead=Cascina dei Nethander⟧, a sud del ⟦Tarren Mill=Mulino di Tarren⟧ e a est del fiume e di ⟦Southshore=Riva del Sud⟧. Raccogli nel campo 6 Mudsnout Blossoms per il mio prossimo elisir.", "Novità dalla ⟦Nethander Stead=Cascina dei Nethander⟧?", "Ah, l'orribile tanfo dei Mudsnout Blossoms. Almeno quei sudici gnoll servono a qualcosa.", 0xe2ec6d44, 0x700181da, 0x77bb60d3, 0x593338b4, 0xdc0fce28, "....." },
  [511] = { "⟦Encrypted Letter=Lettera Codificata⟧", "Porta la ⟦Encrypted Letter=Lettera Codificata⟧ al custode della sapienza Dibbs a ⟦Southshore=Riva del Sud⟧.", "Una delle lettere su questo tavolo è cifrata e incomprensibile.", "Sì, <signore/signora>? Hai qualche affare da sbrigare con me?", "Che cos'è questo? Aspetta un momento... fammi dare un'occhiata più da vicino.\n\n...\n\nMm, non ho mai visto prima questa forma di cifratura, ma devo ammettere che le mie conoscenze in materia non sono affatto complete.", 0x5eef0cde, 0x3d22b12c, 0x9592e003, 0x3282ae20, 0x132ef96b, ".....", nil, nil, nil, 0xc3a055e5, nil },
  [513] = { "Elisir dell'agonia", "Porta il ⟦Mudsnout Composite=Composto di Grugnobrago⟧ al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "Proprio quando pensavo che un altro giorno sarebbe passato senza alcuna gioia, mi hai portato quei meravigliosi Mudsnout Blossoms.\n\nPrima li ridurrò in un composto raffinato. Poi servirà che il maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧, vi applichi il suo colloide di decomposizione, e allora saremo pronti per un bel divertimento!\n\nEcco, prendi questo ⟦Mudsnout Composite=Composto di Grugnobrago⟧ e portalo subito al maestro Faranell, {name}.", "Non vedi che sono occupato, {class}? La Dama Oscura pretende una nuova piaga prima che l'avanzata del Flagello da Nordania ci travolga. E con la minaccia umana che preme da sud, il tempo diventa la mia risorsa più preziosa. Spero che sia importante!", "Ti manda lo speziale Lydon? Ah, perché non l'hai detto subito!\n\nNonostante il suo carattere cupo, lo speziale Lydon è uno dei nostri membri più devoti e capaci.\n\nQuel brav'uomo manda del ⟦Mudsnout Composite=Composto di Grugnobrago⟧! Ora so cosa sta combinando il nostro amico a ⟦Hillsbrad=Colletorto⟧. E mi piace il suo modo di pensare. La Dama Oscura sarebbe molto colpita dai progressi che sta facendo verso la nuova piaga.", 0xe2ec6d44, 0xcaf9ff53, 0xf69b73d7, 0x0e29bf6f, 0xe69dc47d, "....." },
  [515] = { "Elisir dell'agonia", "Porta la ⟦Mudsnout Mixture=Mistura di Grugnobrago⟧, uno Strong Troll's Blood Elixir, 5 Scaglia di Liscaguzza e 5 Occhio di Pinnalacera allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Un composto di Grugnobrago? Assolutamente geniale! Perché non ci ho pensato io?\n\nLascia che aggiunga il mio colloide della decomposizione a questo intruglio diabolico.\n\nPer attivare gli agenti contaminanti in questa mistura di Grugnobrago, Lydon avrà bisogno di un potente elisir di sangue di troll, oltre ad alcune scaglie di Liscaguzza e occhi di Pinnalacera dalla costa meridionale di ⟦Hillsbrad=Colletorto⟧. Saprà cosa fare quando gli avrai procurato tutti i reagenti. E quanto sono impaziente di sapere come andrà il suo esperimento!", "Che piacere rivederti, {name}. Mi stavo annoiando terribilmente qui. Nient'altro di divertente da fare se non avvelenare e infettare Umpi e rianimarla... ancora e ancora e ancora.\n\nCom'è andato il viaggio a ⟦Undercity=Sepulcra⟧? Hai avuto la fortuna di massacrare qualche umano lungo la strada?", "L'eccitazione per questo esperimento mi dà alla testa! Mi sei stat<o/a> di grande aiuto, {name}. Insieme diffonderemo morte e malattia in questa terra!", 0xe2ec6d44, 0x58f2a802, 0xbe1e2231, 0x3acc338b, 0xd2c3fdb4, "....." },
  [516] = { "⟦Beren's Peril=Grotta di Beren⟧", "Trova la ⟦Beren's Peril=Grotta di Beren⟧, poi uccidi 6 Ravenclaw Drudger e 6 Ravenclaw Guardian e torna dal sacerdote dell'ombra Allister alla ⟦Sepulcher=Mausolea⟧.", "Mi è giunta notizia che un gruppo di non morti si è rintanato per preparare un attacco contro di noi. Con questa informazione possiamo ribaltare la situazione e attaccarli per primi, stroncando sul nascere il loro piccolo piano.\n\nPurtroppo le mie informazioni sono frammentarie, a dir poco. Pare che si nascondano in un luogo noto come ⟦Beren's Peril=Grotta di Beren⟧. Il punto esatto è sconosciuto, ma sembra trattarsi di una grotta tra le colline, vicino a un gruppo di maghi di Dalaran.\n\nConfido nella tua intraprendenza. Trovali ed eliminali.", "Hai già trovato la loro base, {name}? Il tempo stringe!", "Se i nostri esploratori e agenti continueranno a procurarci informazioni preziose come questa, in un attimo cacceremo dalle nostre terre il Flagello del Re dei Lich.", 0x26401209, 0xd52db9a2, 0x9be2b48b, 0xf891aa7c, 0x98b12fce, "....." },
  [517] = { "Elisir dell'agonia", "Porta un Barile di Sbronzaforte allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Questo nuovo elisir è finalmente pronto per essere provato. Ma perché sprecare una peste perfettamente valida e altamente contagiosa su una semplice rana o un cane? Divertiamoci sul serio, nel nome di Lady Sylvanas.\n\nScendi a Dun Garok. Conosci la caserma dove zampettano quei piccoli nani schifosi. Rubami un barile della loro Sbronzaforte. Quando avrò quel barile, io e te faremo una bella festa, {name}.", "A volte mi annoio così tanto qui al ⟦Tarren Mill=Mulino di Tarren⟧ che apro il barattolo di formaldeide e lascio che quel delizioso aroma si diffonda nell'aria. Però rende Umpi un po' nervosa.\n\nAllora, sei riuscit<o/a> a prendere un barile dai nani? Giuro che se devo fissare questo elisir letale per un altro giorno senza usarlo su qualcuno mi metto a urlare.", "Finalmente! Ora siamo pronti all'azione!", 0xe2ec6d44, 0x1dc458cd, 0x248bb624, 0x765bfcc6, 0x2d05d391, "....." },
  [524] = { "Elisir dell'agonia", "Metti il ⟦Tainted Keg=Barile Avvelenato⟧ sul tappeto per i contadini prigionieri.", "Qui accanto le Guardie della Morte tengono in ostaggio alcuni contadini catturati. L'alta esecutrice Darthalia sospettava che uno degli strateghi militari di ⟦Stormwind=Roccavento⟧ si nascondesse tra loro. A quanto pare, quel tizio dell'esercito è stato trovato morto nelle ⟦Plaguelands=Terre Infette⟧ la notte scorsa. Darthalia, che pensa sempre a me, ha deciso di lasciare i prigionieri a mia disposizione.\n\nDirei che è ora di dare una festa a quei contadini. Sembra un gran bel divertimento!\n\nMetti questo barile avvelenato sul tappeto nella loro stanza. Birra appestata per tutti!", "Un odore di muffa sale dal tappeto.", "Appoggi il barile avvelenato sul tappeto polveroso.", 0xe2ec6d44, 0x0e0d8bc9, 0xc0bb2da8, 0xed0af003, 0xbb8b8f70, "....." },
  [526] = { "Lingotti della Forgia della Luce", "Raccogli 5 Lingotto della Forgia della Luce, poi torna da Glorin Steelbrow nelle ⟦Wetlands=Paludi Grigie⟧.", "Avrai anche trovato un lingotto della Forgia della Luce in quel forziere, ma non basta per forgiare niente di decente!\n\nDovresti tornare laggiù a cercarne altri. Forse i murloc intorno a quel relitto ne hanno addosso qualcuno.", "Hai trovato il ferro della Forgia della Luce che ti serve?", "Ah, li hai trovati! Ora battiamo questo ferro della Forgia della Luce e ricaviamone qualcosa di utile, eh?", 0x104fcb9a, 0x2c181b7a, 0xa9406e02, 0x0a6e75bf, 0x67c1cb55, "....." },
  [527] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", "Uccidi 6 Hillsbrad Farmhand, 6 Hillsbrad Farmer, il contadino Ray e il contadino Getz, poi fai rapporto a Darthalia al ⟦Tarren Mill=Mulino di Tarren⟧.", "Sull'attenti quando ti rivolgi a me, {class}.\n\nSono agli ordini diretti di Varimathras. Il nostro compito è contenere l'infestazione umana finché i nostri speziali non avranno sviluppato la nuova piaga.\n\nLe nostre informazioni ci portano a credere che la città di ⟦Hillsbrad=Colletorto⟧ sia vulnerabile a un attacco. Il tuo primo incarico mira a colpire le loro scorte di cibo e le loro infrastrutture.\n\nVa' a ovest. Razzia le fattorie più settentrionali dei ⟦Hillsbrad Fields=Campi di Colletorto⟧. E assicurati che anche i proprietari terrieri, il contadino Ray e il contadino Getz, vengano giustiziati.", "In qualità di alta esecutrice del ⟦Tarren Mill=Mulino di Tarren⟧, agli ordini diretti di Varimathras e della Dama Oscura, sei tenut<o/a> a eseguire i miei ordini.\n\nForse prendi alla leggera questa guerra contro l'⟦Alliance=Alleanza⟧? Se è così, dovrei decapitarti qui e ora. Altrimenti, va' a ovest fino alla città di ⟦Hillsbrad=Colletorto⟧ e combatti contro gli umani, come ti è stato ordinato.\n\nPuoi andare.", "Riposo, {class}. Vedo che sei tornat<o/a> dalla battaglia. Le mie fonti mi dicono che te la sei cavata bene sul fronte di ⟦Hillsbrad=Colletorto⟧.", 0x55e77d88, 0xfc0ccebc, 0x01474ce8, 0x54542e09, 0x60bb143c, "....." },
  [528] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", "Uccidi 15 Hillsbrad Peasant e fai rapporto a Darthalia al ⟦Tarren Mill=Mulino di Tarren⟧.", "La notizia dell'attacco alle fattorie del nord ha seminato il panico fra la gente del paese. Eccellente.\n\nI nostri ⟦Deathstalkers=Inseguitori della Morte⟧ riferiscono di contadini in fuga verso i campi nel sud di ⟦Hillsbrad=Colletorto⟧. Quegli sciocchi credono di potersi nascondere nei frutteti e sfuggire al loro destino.\n\nDimostra che si sbagliano, {name}. Torna ai ⟦Hillsbrad Fields=Campi di Colletorto⟧ e stana i contadini rintanati. Falli a pezzi in nome della nostra Dama Oscura.\n\nVa'!", "Hai i tuoi ordini, {class}. Smettila di bighellonare qui al ⟦Tarren Mill=Mulino di Tarren⟧ quando c'è da fare altrove.", "La morsa della morte si stringe attorno al paese di ⟦Hillsbrad=Colletorto⟧. La battaglia procede bene.", 0x55e77d88, 0x62654585, 0x6ef14919, 0xb73cd769, 0x51097f22, "....." },
  [529] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", "Uccidi il fabbro Verringtan e 4 Hillsbrad Apprentice Blacksmith.\n\nRecupera un carico di ferro e torna a fare rapporto a Darthalia, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Gli umani di ⟦Hillsbrad=Colletorto⟧ oppongono una resistenza inaspettata. Pare che il problema sia che la popolazione viene armata dal fabbro del posto. Dobbiamo tagliare tutte le linee di rifornimento.\n\nLa tua missione sarà giustiziare il fabbro Verringtan. Uccidi anche i suoi apprendisti. Già che ci sei, porta indietro un carico di ferro dalle loro scorte. Le provviste ci torneranno utili quando avremo finito di conquistare ⟦Hillsbrad=Colletorto⟧ e cominceremo a radere al suolo ⟦Southshore=Riva del Sud⟧.", "Sei riuscit<o/a> a eseguire gli ordini, {class}? Ti sei sbarazzat<o/a> di Verringtan e dei suoi assistenti? E dov'è quel carico di ferro?", "Missione compiuta, {class}. E portata a termine con notevole abilità, aggiungerei.", 0x55e77d88, 0x1e161d1d, 0x8ad21433, 0x0e58073f, 0xf288501a, "....." },
  [530] = { "La vendetta di un marito", "Uccidi Valdred Moray.\n\nPorta le sue mani a Raleigh Andrean a ⟦Undercity=Sepulcra⟧.", "Valdred, un tempo mio caro amico, è stato l'assassino di mia moglie. Anche se sono incapace di provare dolore, desidero ardentemente vendetta. Se ucciderai Valdred e mi porterai le sue mani maledette, ti ricompenserò.\n\nL'ultima volta ho sentito che si trovava al Greymane Wall, nel sud di ⟦Silverpine=Pinargento⟧, nel tentativo di fuggire nel regno di Gilneas.", "Hai quelle mani, {name}?", "Ah, bene. Queste mani hanno ucciso mia moglie, Deliah. La vendetta per il suo omicidio era il mio unico pensiero, e tu sei <stato/stata> lo strumento di quella vendetta.\n\nEcco, prendi l'anello che mi hai riportato prima. Deliah è morta per me da così tanto tempo che il suo anello è un gingillo che non mi importa più conservare. Terrò invece queste mani, in ricordo del tradimento del mio amico.", 0x8a3e9a99, 0xdb158509, 0x99016295, 0x6375afcb, 0x8105cc0e, "....." },
  [531] = { "La vendetta di Vyrin", "Porta la testa di Ol' Sooty a Vyrin Swiftwind al ⟦Farstrider Lodge=Padiglione Lungopasso⟧.", "Per la Luce! Non portare cose simili nel Padiglione... è antigienico, indicibile, anti... anti... antigienico!\n\nPortalo via di qui, vuoi? Nessuno vuole vedere il tuo piccolo trofeo insanguinato, davvero!", "Ottimo lavoro, {name}! Gliel'abbiamo fatta vedere! Ecco, dammi la testa e me ne occupo io.", "Grazie per avermi aiutato con il mio piccolo piano, {name}. Erano mesi che morivo dalla voglia di vendicarmi di quel ragazzino borioso e pieno di sé, e direi che abbiamo fatto proprio un bel lavoro! Ecco, prendi questo, te lo sei <guadagnato/guadagnata>.", 0xeb8bf51a, 0xcafffbbe, 0x90fd33a0, 0x31f709f1, 0x2e24ea10, "....." },
  [532] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", "Uccidi il magistrato Burnside e 5 Hillsbrad Councilman. Distruggi la Hillsbrad Proclamation. Ruba il ⟦Hillsbrad Town Registry=Registro della Città di Colletorto⟧. Poi torna a fare rapporto a Darthalia, al ⟦Tarren Mill=Mulino di Tarren⟧.", "La città di ⟦Hillsbrad=Colletorto⟧ è allo sbando e crediamo che cadrà presto. Dobbiamo però restare spietati finché quella feccia umana non sarà spazzata via dalle colline per l'eternità.\n\nNonostante le perdite schiaccianti, gli umani si stringono attorno ai loro capi e continuano a combattere. Dobbiamo eliminare il loro capo, il magistrato Burnside, e anche il consiglio cittadino. Distruggi anche il loro venerato documento politico, la Hillsbrad Proclamation. E già che ci sei, ruba il registro della città.", "Che notizie porti?", "La notizia delle tue glorie a ⟦Hillsbrad=Colletorto⟧ ha viaggiato in fretta. Hai fatto bene, {class}.", 0x55e77d88, 0xfbca56f2, 0x7f196303, 0x52f31234, 0xc73dc98a, "....." },
  [536] = { "Giù lungo la costa", "Uccidi 10 Torn Fin Tidehunter e 10 Torn Fin Oracle per il tenente Farren Orinelle a ⟦Southshore=Riva del Sud⟧.", "Trasferito dalla guardia cittadina di ⟦Stormwind=Roccavento⟧ a ⟦Southshore=Riva del Sud⟧, un villaggio che a vederlo andrebbe abbandonato... Puzza di porto giorno e notte.\n\nPer non parlare del vecchio Redpath... Vuole che mi occupi dei murloc. Ah!\n\nRiesco a malapena a trovare la forza di andare fino ai branchi di quei pesci troppo cresciuti lungo la ⟦Western Strand=Riva Occidentale⟧. Se ci andassi tu al posto mio e te ne occupassi, te ne sarei grato.", "Un'altra birra, per favore, l'ultima sembra proprio sparita!\n\nLuce, quanto ancora dovrò restare bloccato quaggiù?\n\nOh, sei tu, {name}. Hai già ucciso quei murloc?", "Spero che basti a convincere Redpath che ho... ah!... eseguito i suoi ordini e liberato ⟦Southshore=Riva del Sud⟧ dalla terribile e orribile minaccia dei temuti murloc! Perché non potrebbe esserci male più grande della furia dei pesci troppo cresciuti!", 0x89675618, 0x07796c70, 0x0ee219d7, 0x9449d897, 0x06ffe0e5, "....." },
  [539] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", "Uccidi il caposquadra Bonds e 10 Hillsbrad Miner, poi fai rapporto a Darthalia al ⟦Tarren Mill=Mulino di Tarren⟧.", "Il ⟦Hillsbrad Town Registry=Registro della Città di Colletorto⟧ indica che l'Azureload Mine è sotto il controllo dell'⟦Alliance=Alleanza⟧. Inoltre, la miniera è una fonte primaria di minerale di ferro per le armerie dell'⟦Alliance=Alleanza⟧.\n\nAnche se abbiamo inferto un colpo decisivo alla città di ⟦Hillsbrad=Colletorto⟧, l'⟦Alliance=Alleanza⟧ continua a sostenere e a proteggere con fervore l'Azureload Mine.\n\nLa miniera si trova a sud di ⟦Hillsbrad=Colletorto⟧. Va' laggiù e uccidi il caposquadra, un umano di nome Bonds. Uccidi anche i suoi minatori. Sarà un messaggio chiaro per l'⟦Alliance=Alleanza⟧.", "Avevi l'ordine diretto di attaccare l'Azureload Mine. Spero che tu abbia una buona ragione per startene a bighellonare al ⟦Tarren Mill=Mulino di Tarren⟧, o ti farò decapitare per tradimento.", "La Dama Oscura sarà lieta di sapere che ha una nuova miniera con cui armare i suoi soldati.", 0x55e77d88, 0xc2e921ef, 0x69cc7e83, 0xa393de25, 0x3d6e86cd, "....." },
  [541] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", "Raggiungi Dun Garok e uccidi 10 montanari, 8 fucilieri, 4 sacerdoti e il capitano Ironhill, poi fai rapporto a Darthalia al ⟦Tarren Mill=Mulino di Tarren⟧.", "Nani che aiutano gli umani? Maledette piccole bestie schifose.\n\nMetteremo alla prova la forza della cosiddetta ⟦Alliance=Alleanza⟧. Vedremo quanta voglia avranno quei piccoli sbatticaviglie di aiutare gli umani, una volta assaggiata la nostra ira. Sappiamo esattamente dove si trova la loro roccaforte in questo territorio.\n\nHanno costruito una caserma nel sud-est di ⟦Hillsbrad=Colletorto⟧, lungo il ⟦Thoradin's Wall=Muro di Thoradin⟧, chiamata Dun Garok. La missione finale di questa battaglia è assediare Dun Garok, {class}. Il capitano Ironhill, il loro capo, deve morire.", "Dun Garok si rivela un ostacolo troppo grande per te, {class}? E io che pensavo ti fossi fatt<o/a> valere con onore a ⟦Hillsbrad=Colletorto⟧.\n\nSe non sei all'altezza della missione che ti è stata affidata, troverò qualcun altro che sappia ottenere risultati migliori. Quanto a te, be', sono certa che la Dama Oscura abbia sempre bisogno di altri becchini nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Le tue azioni sul campo di battaglia meritano i più alti elogi.", 0x55e77d88, 0x75d9b9d1, 0xe1c4c546, 0xb8469e41, 0x1f838ead, "....." },
  [546] = { "Souvenir di morte", "La guardia della morte Samsa del ⟦Tarren Mill=Mulino di Tarren⟧ vuole 30 Teschio Umano di ⟦Hillsbrad=Colletorto⟧.", "Ho sentito che Darthalia ti ha arruolat<o/a> per muovere guerra agli umani di ⟦Hillsbrad=Colletorto⟧. Che invidia...\n\nMentre tu te la spassi, a massacrare umani, saccheggiare il paese e terrorizzare innocenti, io sono bloccato qui di guardia al ⟦Tarren Mill=Mulino di Tarren⟧.\n\nForse avrai pietà di una vecchia Guardia della Morte come me? Vedi, colleziono teschi umani. E tu combatterai gli umani ancora per parecchio. Nel corso della tua lunga battaglia, portami 30 teschi e ne varrà la pena.", "Allora <il/la> <fortunato/fortunata> {name} è tornat<o/a>? Quanti umani hai massacrato oggi? Centinaia, spero!\n\nHai qualche teschio per me?", "Teschi preziosi! Bellissimi! Come promesso, ti devo una ricompensa, {name}!", 0x91bf9c63, 0x7816dbda, 0xae66bd6b, 0xe44cd7fa, 0xddaefa3e, "....." },
  [547] = { "⟦Humbert's Sword=Spada di Humbert⟧", "Recupera la spada della Guardia della Morte Humbert a Dun Garok e riportagliela al ⟦Tarren Mill=Mulino di Tarren⟧.", "L'alta esecutrice Darthalia mi ha mandato a sorvegliare Dun Garok da lontano. Avevo piantato il campo appena fuori vista. Ma quando è arrivato il mattino e dovevo far bollire l'acqua, mi sono allontanato a raccogliere legna da ardere.\n\nQuando sono tornato al campo, ho scoperto che il mio equipaggiamento era sparito.\n\nA quanto pare alcuni esploratori nani di Dun Garok erano passati di lì e se l'erano portato via. Mi serve la mia spada! Se riesci a recuperarmela, te ne sarò davvero grato. Ci sono così tanti nani laggiù... sarà piuttosto difficile trovare il piccolo ladro schifoso che l'ha rubata.", "Sei riuscit<o/a> a recuperare la mia spada, {name}? L'alta esecutrice Darthalia mi appenderà alle travi se scopre la mia sbadataggine.", "L'hai trovata!\n\nAh, mi sento di nuovo completo con la mia preziosa spada in mano. Grazie mille!", 0xd3a84f58, 0xb320d0f8, 0x90ba6ec9, 0x4cd630db, 0xe5687dbb, "....." },
  [549] = { "RICERCATI: membri della ⟦Syndicate=Lega dei Tagliagole⟧", "Uccidi 10 Syndicate Rogue e 10 Syndicate Watchman. Torna dall'alta esecutrice Darthalia al ⟦Tarren Mill=Mulino di Tarren⟧ per la ricompensa.", "Per autorità di Lady Sylvanas, tutti i membri dell'organizzazione nota come ⟦Syndicate=Lega dei Tagliagole⟧ sono ricercati morti. Chi verrà preso in custodia o fatto prigioniero sarà giustiziato sommariamente. Al momento risulta che si stiano radunando tra le rovine di ⟦Durnholde Keep=Forte Durnholde⟧, a sud-est del ⟦Tarren Mill=Mulino di Tarren⟧.\n\nUna lauta ricompensa attende chiunque porti le prove delle proprie gesta all'alta esecutrice Darthalia.", "Non hai niente di meglio da fare che startene qui davanti a me, {class}? In qualità di alta esecutrice, ho faccende più urgenti che fissare la tua faccia putrefatta.", "Eccellente, {class}. Di questo passo, la piaga della ⟦Syndicate=Lega dei Tagliagole⟧ sarà estirpata da queste terre in un attimo.", 0x4dfa905a, 0xc376c3eb, 0x3bff7ff9, 0x273b2f3d, 0x5f04d0d8, "....." },
  [550] = { "La battaglia di ⟦Hillsbrad=Colletorto⟧", nil, nil, nil, nil, 0x55e77d88, nil, nil, nil, nil, ".mmmm" },
  [567] = { "Pericolosi!", "L'alta esecutrice Darthalia del ⟦Tarren Mill=Mulino di Tarren⟧ offre una taglia sull'impiegato Horrace Whitesteed, sul cittadino Wilkes, sul minatore Hackett e sul contadino Kalaba.", "Pericolosi!\n\nI seguenti umani di ⟦Hillsbrad=Colletorto⟧ sono stati dichiarati pericolosi e su di loro l'alta esecutrice Darthalia ha posto una taglia:\n\nL'impiegato Horrace Whitesteed. Ricercato per l'omicidio della Guardia della Morte Toma.\n\nIl cittadino Wilkes. Ricercato per l'omicidio dello speziale Eli.\n\nIl minatore Hackett. Ricercato per l'omicidio dell'⟦Deathstalker=Inseguitore della Morte⟧ Fry.\n\nIl contadino Kalaba. Ricercato per l'imboscata ai rifornimenti provenienti da ⟦Undercity=Sepulcra⟧.\n\nTutti questi nemici sono nascosti e sarà difficile trovarli. Una ricompensa sarà concessa alla notizia della loro morte.", "Sì?", "Sei <un/una> ver<o/a> cacciat<ore/rice> di taglie, {class}. Ben fatto.", 0x97aa3e60, 0x29cc4353, 0x59dd6751, 0x0c07a888, 0x49ccbea2, "....." },
  [579] = { "La biblioteca di ⟦Stormwind=Roccavento⟧", nil, nil, "Re Anduin ha dato grande importanza al sapere, e per questo ha stanziato fondi per mettere a disposizione del pubblico copie di vari tomi e scritti. È molto semplice. Tu mi porti un buono della biblioteca e io ti do una copia di uno dei libri disponibili.", "Qualcuno di questi titoli ti interessa, {name}?", 0x308ed743, nil, nil, 0xccf61e18, 0x71324ab5, ".mm.." },
  [583] = { "Benvenuti nella giungla", "Parla con Hemet Nesingwary.", "Benvenut<o/a> a Rovotorto!\n\nForse non lo sai, ma quel nano laggiù è il solo e unico Hemet Nesingwary, celebre eroe di guerra dell'⟦Alliance=Alleanza⟧ e maestro cacciatore di selvaggina grossa. Non è tipo da accogliere estranei nel suo accampamento, ma tu sembri averne viste parecchie ai tuoi tempi, {class}.\n\nEssendo anche lui un veterano di molte battaglie, il maestro Nesingwary ha un debole per gli altri eroi.\n\nVa' a parlargli. Magari può darti qualche consiglio di caccia.", nil, "Molto lieto di fare la tua conoscenza, {name}. Era un pezzo che non vedevo <un/una> {class} da queste parti.\n\nMi sono unito a questa spedizione per un solo scopo: cacciare una bestia grande e sfuggente. Visto che sei una specie di eroe, sono disposto a lasciarti partecipare alla caccia, ma prima devi dimostrare il tuo valore.\n\nTi insegnerò l'arte di uccidere i raptor. Ajeck ti addestrerà nella caccia alla tigre. E sir Erlgadin è un maestro nel seguire le tracce delle pantere.\n\nDimostra la tua abilità e ti farò partecipare alla grande caccia.", 0x9ad92ef3, 0x56561224, 0x1e3f2560, nil, 0x9f389bf6, "...m." },
  [590] = { "L'affare di un furfante", "Sconfiggi Calvin Montague ad ⟦Deathknell=Albamorta⟧.", "Cosa?\n\nCOSA?!\n\nVuoi dei soldi? Non ti devo nessun soldo.\n\nLettera? Quale lettera? Oh, vuoi fare a botte, allora? D'accordo, amico... facciamola finita! Devo dei soldi a te, figurati...", nil, "Incredibile! Che abilità!\n\nPensavo che saresti stat<o/a> una preda facile, {name}. Mi hai conciato per bene, eh.\n\nEcco le monete che ti avevo promesso... non quante avevo detto, ma è colpa mia che ti ho mentito fin dall'inizio.", 0x824c6911, 0x6ebdfe04, 0xcf0d4d70, nil, 0xfe24a85d, "...m." },
  [637] = { "⟦Sully Balloo's Letter=Lettera di Sully Balloo⟧", "Consegna la ⟦Sully Balloo's Letter=Lettera di Sully Balloo⟧ a Sara Balloo.", "La busta, fradicia e malconcia per la guerra, ti si disfa tra le mani, lasciandoti in pugno alcune pagine di una lettera scritta con cura minuziosa.\n\nLa lettera è indirizzata a una certa signora Sara Balloo di ⟦Ironforge=Forgiardente⟧ e comincia così: «Mia cara Sara...»", "Sembri aver viaggiato molto lontano e aver visto molti tormenti ai tuoi tempi, {class}. I tempi in cui viviamo mettono a dura prova l'anima. Che notizie mi porti, ora?", "Dici di aver visto il mio Sully intrappolato sotto le acque gelide? Dimmi che non è vero!\n\nFammi leggere cosa ha scritto...", 0x16ea5dcb, 0xe1099d7a, 0x1cae80a2, 0xde03d404, 0x83ce737d, "....." },
  [647] = { "⟦MacKreel's Moonshine=Torcibudella di MacKreel⟧", "Porta il ⟦MacKreel's Moonshine=Torcibudella di MacKreel⟧ al mastro birraio Bilger a ⟦Southshore=Riva del Sud⟧.", "Ieri sera ho mandato giù parecchio del buon vecchio Torcibudella! Longbraid mi farebbe la pelle se sapesse che sono svenuto durante il mio turno di guardia.\n\nLa zucca mi fa un male cane. Mi è sembrato che mi passasse sopra un'intera brigata di macchine d'assedio, con tutto quel rombo.\n\nOh, accidenti, guarda che ore sono! Ho promesso al mastro birraio Bilger di ⟦Southshore=Riva del Sud⟧ che avrei saldato il mio debito mandandogli un po' di Torcibudella.\n\nMa mancano solo 15 minuti alla scadenza! Portagli questa partita, ti va? E sbrigati!", "Che novità mi porti, {race}?", "Ah, niente come il ⟦MacKreel's Moonshine=Torcibudella di MacKreel⟧ del buon Foggy per scaldarti in una giornata frizzante! E io che pensavo che quel furfantello sarebbe stato di nuovo in ritardo con i conti. Grazie, amico! Grazie mille davvero!", 0x888fda51, 0x674a14d5, 0x270bf03c, 0x35f07d1b, 0x31b8acb8, "....." },
  [683] = { "⟦Sara Balloo's Plea=Supplica di Sara Balloo⟧", "Porta il biglietto di Sara Balloo a re Magni Bronzebeard di ⟦Ironforge=Forgiardente⟧.", "{name}, ho solo una piccola richiesta da farti.\n\nPorta questo biglietto che ho preparato al nostro grande sovrano di ⟦Ironforge=Forgiardente⟧, re Magni Bronzebeard. È un compito modesto da chiedere a qualcuno come te, che finora ha dimostrato grande valore per la causa dell'⟦Alliance=Alleanza⟧.\n\nPresentarmi al re nel mio stato di dolore non gioverebbe alla mia causa. Lo capirai di certo.", "Dunque sei tu {name}, {class}? La notizia del tuo contributo all'⟦Alliance=Alleanza⟧ è arrivata piuttosto lontano, sai?\n\nPer quale faccenda ti presenti al mio cospetto, oggi?", "Mi basterà un momento per leggere questa lettera...", 0x35db5c7b, 0x521be7bf, 0x77136a52, 0xffa93ce4, 0xbff31da8, "....." },
  [686] = { "Il tributo di un re", "Re Magni Bronzebeard vuole che tu parli con il gran capomastro Marblesten.", "Non mi aspetto che nani di buon cuore come la signora Balloo capiscano perché le atrocità della guerra vadano sopportate per il bene superiore del nostro popolo. La perdita di suo marito, e la perdita di ogni nano che combatte in nome dell'⟦Alliance=Alleanza⟧, mi pesa sull'anima.\n\nNon posso riportare suo marito indietro dalla ⟦Twisting Nether=Distorsione Fatua⟧, ma posso rendergli omaggio.\n\nCommissionerò un monumento in memoria di Sully Balloo, che sarà costruito dal gran capomastro Mablesten.\n\nMandagli subito notizia, {class}. Sarai tu il custode della mia volontà.", nil, "Allora ti ha mandato re Magni Bronzebeard in persona?\n\nPerbacco! Dev'essere una cosa importante!", 0x82e28c92, 0x6fdcb316, 0xbf80acf9, nil, 0x8fe6a7ae, "...m." },
  [689] = { "Il tributo di un re", nil, nil, nil, nil, 0x82e28c92, nil, nil, nil, nil, ".mmmm" },
  [700] = { "Il tributo di un re", nil, nil, nil, nil, 0x82e28c92, nil, nil, nil, nil, ".mmmm" },
  [729] = { "Il prospettore distratto", "Va' a sud e controlla come sta il prospettore Remtravel.", "Che onore è stato quando mastro Greywhisker mi ha assegnata a lavorare sotto la guida del grande prospettore Remtravel. All'accademia di ⟦Ironforge=Forgiardente⟧ tutti conoscevano le grandi scoperte di Remtravel.\n\nMa il prospettore è piuttosto... ehm... ignaro... di ciò che lo circonda.\n\nAvevamo scoperto le prove di una grande civiltà. Orribili golem sono sbucati dal terreno e hanno invaso il sito. Remtravel non sembrava essersene accorto. Io sono corsa ad Auberdine a cercare aiuto.\n\nTi prego, va' a sud e controlla se il prospettore sta bene!", nil, "Hollee, sei tu? Mi serve una mano a scalpellare questa pietra. Passami la spazzola per la pietra, mi pare di vedere qualcosa.\n\nEhi, tu non sei Hollee! Per caso hai visto la mia spazzola per la pietra?\n\nLascia perdere! Ho promesso alla Lega che avrei spedito il fossile misterioso che ho trovato. Dov'è finita Hollee?\n\nC'è così tanto lavoro da fare! Allora, dov'è quel fossile misterioso... e la mia spazzola... e Hollee...\n\nE tu chi sei... non importa, purché tu sia qui per aiutare.\n\nFammi sapere quando sei <pronto/pronta> a cominciare le ricerche.", 0xb9653d3d, 0xfae33a52, 0x15681a9a, nil, 0x1419b23f, "...m." },
  [730] = { "Guai a ⟦Darkshore=Rivafosca⟧?", "Va' ad Auberdine e cerca tracce della squadra di scavo dei nani.", "Che bello vedere un {class} che si interessa alle grandi meraviglie archeologiche del nostro mondo.\n\nSpesso i nostri amici dell'⟦Alliance=Alleanza⟧ liquidano il nostro lavoro come un semplice passatempo. Ma molti non si rendono conto che le recenti scoperte a Khaz Modan hanno dimostrato che una forza grande e potente minaccia tutta Azeroth, da Lordaeron a Kalimdor.\n\nSono molto preoccupato per la squadra che ho mandato a ⟦Darkshore=Rivafosca⟧. Non manda notizie da settimane.\n\nVa' ad Auberdine e cerca un indizio su dove si trovino.", nil, "Sono così contento che l'archeologo capo Greywhisker ci abbia mandato a chiamare...", 0x267580f4, 0x8039f2c6, 0xcf3329d9, nil, 0xa8b5955b, "...m." },
  [731] = { "Il prospettore distratto", "Proteggi il prospettore Remtravel mentre cerca il fossile misterioso, poi torna dall'archeologa Hollee ad Auberdine.", "Dunque, Hollee... ah già, tu non sei Hollee. Dov'è Hollee?\n\nBah, non è questo il punto. Dobbiamo trovare quella spazzola per la pietra... cioè, il fossile misterioso! Dobbiamo trovare quel fossile. La ⟦Explorers' League=Lega degli Esploratori⟧ di Darnassus vorrà qualche prova di ciò che ho fatto.\n\nFammi sapere quando sei <pronto/pronta> e daremo la caccia a quella spazzola.... cioè, al fossile! Troveremo qualcosa di scritto per accontentare la Lega.\n\nAllora, sei <pronto/pronta>?", "Il prospettore è vivo?", "Siano ringraziate le stelle, il prospettore Remtravel è salvo! Te l'avevo detto che era distratto. Non riesco a credere che abbia insistito per restare laggiù con tutte quelle orribili creature in agguato.", 0xb9653d3d, 0x700580fd, 0xf5e66d39, 0x7c063599, 0x6e9a29da, "....." },
  [741] = { "Il prospettore distratto", "Porta il fossile misterioso all'archeologo capo Greywhisker a Darnassus.", "Quindi il prospettore vuole spedire il fossile misterioso alla ⟦Explorers' League=Lega degli Esploratori⟧ di Darnassus? Non me la sento di lasciare ⟦Darkshore=Rivafosca⟧ senza di lui.\n\nEcco, {name}, consegna il fossile misterioso all'archeologo capo Greywhisker a Darnassus.", "Cosa posso fare per te, {race}?", "Oh, cielo! Solo il prospettore Remtravel poteva fare una scoperta simile!", 0xb9653d3d, 0x4673c264, 0x9261fce9, 0x99c037c7, 0x5249d78d, "....." },
  [742] = { "La caccia di ⟦Ashenvale=Valtetra⟧", "Parla con Senani Thunderheart all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "Attenzione, giovani avventurieri! Le terre selvagge di ⟦Ashenvale=Valtetra⟧ vi attendono!\n\nL'⟦Horde=Orda⟧ si è insediata saldamente nelle terre a nord delle ⟦Barrens=Savane⟧. I nostri due avamposti, l'⟦Splintertree Post=Avamposto di Troncorotto⟧ e l'avamposto della ⟦Zoram Strand=Spiaggia di Zoram⟧, si battono per portare gloria all'⟦Horde=Orda⟧! Chi vuole mettersi alla prova dovrebbe cercare una guida laggiù. Da segnalare: Senani Thunderheart, all'⟦Splintertree Post=Avamposto di Troncorotto⟧, direttamente a nord delle ⟦Barrens=Savane⟧, cerca avventurieri disposti a partecipare a una grande caccia a ⟦Ashenvale=Valtetra⟧!", nil, "Benvenut<o/a> nella nuova frontiera, {name}. ⟦Ashenvale=Valtetra⟧ è una terra di opportunità, dove un giovane {class} come te può trovare infinite occasioni per dimostrare il proprio valore. Dai un'occhiata all'avamposto e non mancare di spingerti fino alla ⟦Zoram Strand=Spiaggia di Zoram⟧, dove l'⟦Horde=Orda⟧ ha un altro avamposto.\n\nLa tua presenza qui mi dice che sei <venuto/venuta> per saperne di più sulla caccia. Ascolta bene, e ti dirò volentieri ciò che devi sapere.", 0x1bf465b8, 0x0a003978, 0x7489a1c6, nil, 0xedbc036b, "...m." },
  [743] = { "I pericoli delle Windfury", "Porta 8 Windfury Talon a Ruul Eagletalon al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Grazie per aver trovato il tempo di parlare con me, {name}. Sono Ruul, guerriero e maestro.\n\nHai ormai raggiunto l'età in cui devi prepararti alle tue prove, se vuoi avventurarti molto più lontano da Mulgore.\n\nSe desideri mettere alla prova la tua forza, comincia cercando le arpie Windfury a sud-est. Si annidano lungo i fianchi della montagna, lontano dalla strada.\n\nSono tra i nostri nemici naturali qui a Mulgore e saranno un buon metro del tuo valore.", "Le Windfury sono nemiche letali. La loro forza in battaglia è pari soltanto alla loro fame di carne fresca.", "Hai fatto bene, {name}. Sembri ben <preparato/preparata> per proseguire il viaggio. Che il vento sia sempre alle tue spalle.", 0xd4a11af3, 0x3e4caa58, 0x8d790d6c, 0x82a0757c, 0xdd9e3807, "....." },
  [744] = { "Preparativi per la cerimonia", "Raccogli 6 Azure Feather e 6 Bronze Feather e portale a Eyahn Eagletalon, a ⟦Thunder Bluff=Picco del Tuono⟧.", "{name}, mio fratello comparirà presto davanti al capo Bloodhoof, ed è un onore per me preparare il suo copricapo.\n\nVorrei chiederti un favore mentre finisco di conciare queste strisce di cuoio. Non ho il tempo di trovare abbastanza piume, e mi chiedevo: potresti raccoglierne altre per me?\n\nTroverai piume della misura giusta sulle arpie che vivono molto a nord e a nord-ovest di ⟦Thunder Bluff=Picco del Tuono⟧. Mi servono solo 6 piume azzurre e 6 bronzee per completare il disegno.", "Questo copricapo sarà di certo un dono meraviglioso per mio fratello.", "Grazie per il tuo aiuto, {name}.\n\nIl mio ruolo nella cerimonia di mio fratello è quasi concluso. Consegnargli il copricapo e assistere alla cerimonia è tutto ciò che il mio dovere mi chiede.", 0x4e130e80, 0xf38f39b5, 0xea0f1c58, 0xc2f8f6ff, 0xb9642dba, "....." },
  [745] = { "Condividere la terra", "Uccidi 10 Palemane Tanner, 8 Palemane Skinner e 5 Palemane Poacher, poi torna da Baine Bloodhoof al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "{name}, sono molti i conflitti che feriscono questa terra. Spero che tu non debba assistere a tanti di essi quanti ne ho visti io. Eppure ce n'è uno che ti chiederei di affrontare. Ti darà un'idea di quanto possa essere terribile per la terra anche una piccola minaccia, se non la si tiene a freno.\n\nGli gnoll Palemane si sono stabiliti a sud del Villaggio di Zoccolo Sanguinario e in una grotta a ovest. Disprezzano i nostri tentativi di comunicare con loro e massacrano senza freno la fauna di Mulgore.\n\nLe parole non sono più la risposta.", "Se i Palemane avessero rispettato di più la terra e i suoi abitanti, questo conflitto non sarebbe mai scoppiato.", "{name}, è un bene che tu abbia preso sul serio il mio compito. Il rispetto per la terra e per le sue creature è importante. La morte e la vita sono un cerchio... una necessità. L'una non può esistere senza l'altra. Prenditi del tempo per riflettere su questo e fa' in modo di non dimenticarlo mai.", 0x26ffc744, 0xb5d17a3e, 0x8fb09aaf, 0x31c8332b, 0xe7331b89, "....." },
  [746] = { "Scavi nanici", "Raccogli 5 Prospector's Pick.\n\nA una forgia, frantuma i Prospector's Pick per ottenere degli ⟦Broken Tools=Utensili Rotti⟧.\n\nPorta 5 ⟦Broken Tools=Utensili Rotti⟧ a Baine Bloodhoof al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Ci sono dei nani che stanno preparando uno scavo a nord-ovest. Credono che la terra nasconda dei segreti, ed è vero, ma svuotare e profanare la terra non è il modo di apprenderne gli insegnamenti.\n\nRaccogli gli attrezzi da scavo dei nani, frantumali e torna da me con gli attrezzi rotti dei nani.\n\nPuoi frantumare gli attrezzi a una forgia. Ne troverai una a ⟦Thunder Bluff=Picco del Tuono⟧, ma qualsiasi forgia andrà bene, persino una all'accampamento dei nani.", "Salve, {name}. Hai gli ⟦Broken Tools=Utensili Rotti⟧? Gli scavi dei nani faranno infuriare i kodo di Mulgore. Questa profanazione va fermata!", "Grazie, {name}. Questo calmerà le bestie di Mulgore. E, se gli spiriti vorranno, insegnerà ai nani che svuotare la terra non è la via della conoscenza.", 0x2946e68d, 0x36dfb8c2, 0xa41c26a0, 0x4f307216, 0x360e92d2, "....." },
  [747] = { "Inizia la caccia", "Grull Hawkwind, al ⟦Camp Narache=Campo Narache⟧, vuole che tu gli porti 7 Plainstrider Feather e 7 pezzi di ⟦Plainstrider Meat=Carne di Zampalunga delle Pianure⟧.", "Hai un'aria promettente e saprai dimostrare il tuo valore alla tribù. Forse un giorno non lontano sarai accolt<o/a> nella grande città di ⟦Thunder Bluff=Picco del Tuono⟧. Ma prima dovrai dimostrare il tuo valore a mio padre, il capo Hawkwind.\n\nQui sulla ⟦Red Cloud Mesa=Mesa Nuvola Rossa⟧ andiamo fieri della nostra abilità nella caccia. I tauren cacciano per necessità e per sport. Le nostre scorte di carne si sono ridotte e ci servono piume per gli abiti. Caccia i Plainstrider qui vicino e dimostra il tuo valore rifornendo il villaggio.", "Procurare carne e piume alla tribù è il primo passo per dimostrare il tuo valore come <cacciatore/cacciatrice> davanti al capo.", "I tauren di Narache ti ringraziano, {name}. Sei molto promettente.", 0xc3235e62, 0x93fdc57c, 0x019bcbf5, 0x30e02e4f, 0x5501c907, "....." },
  [748] = { "Acqua avvelenata", "Porta 6 Prairie Wolf Paw e 4 Plainstrider Talon a Mull Thunderhorn, a Bloodhoof.", "I goblin e i loro servi hanno contaminato i nostri sacri pozzi! Non possiamo permetterlo.\n\nPer purificare ogni pozzo devo creare un totem purificatore, poi tu dovrai portare il totem al pozzo ed eseguire un rituale di purificazione.\n\nPer prima cosa creeremo un totem purificatore per il ⟦Winterhoof Water Well=Pozzo degli Zoccolo Artico⟧. Per farlo, la terra deve offrirci il suo aiuto. Caccia i lupi della prateria per le loro zampe e i corripiana adulti per i loro artigli. Si trovano a sud-ovest.\n\nTorna da me con le zampe e gli artigli, {name}.", "Hai le zampe e gli artigli, {name}?", "Hai fatto bene, {name}. Prenderò questi e legherò il loro potere a un totem purificatore.", 0xb8a26047, 0x2a8356cb, 0x70184bd0, 0x559f8cc7, 0x89b71023, "....." },
  [749] = { "La ⟦Ravaged Caravan=Carovana Depredata⟧", "Morin Cloudstalker vuole che tu esamini il contenuto di una cassa di provviste alla ⟦Ravaged Caravan=Carovana Depredata⟧.", "Qualche giorno fa abbiamo trovato una carovana della S.P.R. & Co. che viaggiava sotto scorta sulla riva settentrionale del ⟦Stonebull Lake=Lago Toro di Pietra⟧. Avevamo perso due dei nostri in una battaglia precedente, così non abbiamo esitato ad attaccare e devastare la carovana.\n\nAbbiamo lasciato lì le loro casse di provviste, pensando che le nostre torce avrebbero distrutto qualunque cosa di valore, ma visto che vicino ai carri bruciati sono stati avvistati dei recuperatori della S.P.R. & Co., forse ci sbagliavamo.\n\nForse potresti andare alla carovana ed esaminare il contenuto delle casse.", nil, "Su ogni lato della cassa è impresso il marchio della Divisione Mineraria della S.P.R. & Co. Alcune note scritte con cura sul fianco della cassa indicano che il contenuto deve essere lavorato in uno dei loro impianti centrali.", 0xa500e769, 0x913fbdf4, 0xb6364b39, nil, 0x336db033, "...m." },
  [750] = { "La caccia continua", "Grull Hawkwind, a ⟦Camp Narache=Campo Narache⟧, vuole che tu gli porti 10 Mountain Cougar Pelt.", "Un tauren esperto nell'arte della caccia sa che la sua preda non è un semplice trofeo. Le bestie delle pianure ci danno di che sopravvivere. Farai una buona impressione sugli anziani se riuscirai a riportare delle pregiatissime pellicce di puma di montagna. Troverai quelle bestie in agguato sulle colline a sud.\n\nI nostri figli hanno bisogno di vestiti e le nostre tende vanno rammendate.", "Se porterai pellicce per la tribù, riferirò a mio padre, il capo Hawkwind, delle tue generose azioni.", "I tauren di Narache ti ringraziano per queste provviste, {name}. Con la tua abilità nell'arte della caccia, un giorno sarai di certo venerat<o/a> a ⟦Thunder Bluff=Picco del Tuono⟧.", 0x841a4863, 0x8102d1fe, 0x243dac7e, 0x6c46fb68, 0xe19931e6, "....." },
  [751] = { "La ⟦Ravaged Caravan=Carovana Depredata⟧", "Riporta i ⟦Venture Co. Documents=Documenti della S.P.R. & Co.⟧ a Morin Cloudstalker, vicino al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Sollevando il coperchio scopri un assortimento ben stipato di minerali grezzi, un'ulteriore prova delle operazioni minerarie della S.P.R. & Co. a Mulgore. Sopra i minerali trovi un fascio di carte strettamente legato, e lo prendi.\n\nSu tra le colline a est riesci a malapena a sentire rumori di lavoro e vedi del fumo levarsi da un grande fuoco.", "Salute, {name}. Hai scoperto qualcosa di nuovo sui piani e le operazioni della S.P.R. & Co. nella nostra terra?\n\nSe intendono sfruttare le nostre terre come hanno fatto con altre, gli Outrunner non ci metteranno molto a porvi fine.", "Sembra proprio che la S.P.R. & Co. stia cercando di derubarci delle nostre risorse naturali. È bene saperlo con certezza, e ora, a quanto pare, dobbiamo fare qualcosa al riguardo.", 0xa500e769, 0x0e721958, 0x275bb1a2, 0xca60a30e, 0xcb7fd24f, "....." },
  [752] = { "Un compito umile", "Il capo Hawkwind vuole che tu cerchi sua madre vicino al pozzo a sud-est del ⟦Camp Narache=Campo Narache⟧.", "Tutti i membri della tribù partecipano all'armonia della vita. Viviamo insieme e lavoriamo insieme.\n\nL'impegno che abbiamo gli uni verso gli altri porta con sé una grande responsabilità. Ora ti chiedo un compito umile.\n\nStamattina mia madre è andata a prendere l'acqua al pozzo a sud-est di Narache. È passato parecchio tempo ormai. Potresti andare a vedere come sta, mentre io mi occupo delle questioni della tribù?", nil, "Hai fatto tutta questa strada solo per aiutare una vecchia? Ma guarda, sei proprio una perla! Ecco, prendi uno di questi manuali di addestramento, così potrai imparare a dare il tuo contributo alla comunità.", 0x565c8400, 0xb6c07f5c, 0x22266d02, nil, 0x69499cdf, "...m." },
  [753] = { "Un compito umile", "Prendi una ⟦Water Pitcher=Brocca d'Acqua⟧ dal pozzo.\n\nRiporta la brocca al capo Hawkwind a ⟦Camp Narache=Campo Narache⟧, a nord-ovest del pozzo.", "Ho percorso molti sentieri nella vita e queste vecchie gambe non hanno più il vigore di un tempo. Posso ancora svolgere i miei doveri verso la tribù. A volte, a una vecchia serve solo un po' più di tempo per portare a termine un compito.\n\nMa tu hai l'aria di un {class} entusiasta. Mettiamo alla prova un po' di quel vigore giovanile. Prendi una brocca d'acqua dal pozzo e portala a mio figlio, il capo, a ⟦Camp Narache=Campo Narache⟧.\n\nRicorda che anche il compito più umile può guadagnarsi il riconoscimento degli anziani.", "Hai l'aria di chi torna dalle pianure. Hai notizie della Grande Madre Hawkwind?", "Vedo che hai riportato questa brocca su richiesta della Grande Madre.\n\nLa tua disponibilità ad aiutare gli altri e a provvedere ai tauren di ⟦Camp Narache=Campo Narache⟧ mi fa credere che un giorno renderai fiera la tribù a ⟦Thunder Bluff=Picco del Tuono⟧.", 0x565c8400, 0x6368490a, 0xf72e32dd, 0xeb66c85e, 0x2178cc89, "....." },
  [754] = { "La purificazione degli ⟦Winterhoof=Zoccolo Artico⟧", "Usa il ⟦Winterhoof Cleansing Totem=Totem Purificatore degli Zoccolo Artico⟧ al ⟦Winterhoof Water Well=Pozzo degli Zoccolo Artico⟧, poi torna da Mull Thunderhorn.", "Ho creato il totem per purificare il ⟦Winterhoof Water Well=Pozzo degli Zoccolo Artico⟧. Ora devi portarlo al pozzo ed eseguire un rituale di purificazione. Lo troverai a sud-est, sorvegliato da goblin immondi!\n\nNon sarà un compito facile, ma devi portarlo a termine se vogliamo usare di nuovo le sue acque.\n\nChe la fortuna ti accompagni, {name}.", "Non indugiare, {name}. La contaminazione del Pozzo degli ⟦Winterhoof=Zoccolo Artico⟧ deve essere eliminata!", "La notizia della tua impresa mi è giunta pochi istanti fa: già le bestie vicino al pozzo vi bevono avidamente.\n\nHai fatto una grande cosa per la terra, {name}. E hai fatto una grande cosa per il popolo dei Tauren.", 0xcc5edaf5, 0x89a6b62d, 0x3c9c3742, 0x5c381be6, 0xc389e962, "....." },
  [755] = { "I riti della Madre Terra", "Raggiungi il veggente Graytongue, che vive sulle colline subito a sud di ⟦Camp Narache=Campo Narache⟧.", "La tua disponibilità a svolgere un compito umile per i tauren di Narache e il tuo desiderio di imparare sono qualità nobili, {name}. Credo che un giorno a ⟦Thunder Bluff=Picco del Tuono⟧ sarai acclamat<o/a> come un grande {class}.\n\nPrima, però, dovrai affrontare i Riti della Madre Terra, che sono tre.\n\nLa prima prova è il Rito della Forza. Raggiungi il veggente Graytongue e digli che ti manda il capo Hawkwind.\n\nTroverai la dimora del veggente subito a sud di ⟦Camp Narache=Campo Narache⟧, nascosta tra le colline.", nil, "Ti manda il capo Hawkwind? Intraprendere i Riti della Madre Terra non è un compito da poco...", 0x7df8fef9, 0xe288069f, 0x91bed61c, nil, 0x4cd10b4a, "...m." },
  [756] = { "Il totem dei ⟦Thunderhorn=Corno Tonante⟧", "Porta 6 ⟦Stalker Claws=Artiglio di Inseguitore⟧ e 6 ⟦Cougar Claws=Artiglio di Puma⟧ a Mull Thunderhorn.", "Per creare il ⟦Thunderhorn Cleansing Totem=Totem Purificatore dei Corno Tonante⟧, devi raccogliere gli artigli dei predatori delle pianure di Mulgore. Caccia gli inseguitori della prateria per i loro artigli e i puma delle pianure per i loro artigli, poi torna da me.\n\nTroverai gli inseguitori della prateria e i puma delle pianure a est e a ovest.", "{name}, hai gli artigli che ti ho mandato a raccogliere? Il ⟦Thunderhorn Water Well=Pozzo dei Corno Tonante⟧ è sempre più contaminato a ogni ora che passa!", "Grazie, {name}. La purezza con cui queste bestie cacciano è essenziale per creare il prossimo totem purificatore.\n\nI goblin non impareranno mai la differenza tra lottare contro la terra e vivere in armonia con essa.", 0xe8309f4d, 0xbc8ba1fb, 0x53c6b880, 0xe827177e, 0x710f55bc, "....." },
  [757] = { "Il Rito della Forza", "Uccidi i ⟦Bristleback=Mantotergo⟧ nella ⟦Brambleblade Ravine=Depressione di Rovoaguzzo⟧ e porta 12 Bristleback Belt al capo Hawkwind a ⟦Camp Narache=Campo Narache⟧.", "I Riti della Madre Terra sono i passi che un giovane tauren deve compiere per guadagnarsi il rispetto a ⟦Thunder Bluff=Picco del Tuono⟧.\n\nPer prima cosa devi superare il Rito della Forza. In questa prova devi dimostrare il tuo coraggio uccidendo i nemici della tribù.\n\nI Mantotergo della ⟦Brambleblade Ravine=Depressione di Rovoaguzzo⟧, a est, stanno invadendo le terre della nostra tribù. Tendono imboscate ai nostri gruppi di caccia e col buio derubano il villaggio.\n\nMostra il tuo valore uccidendo questi furfanti e torna dal capo a ⟦Camp Narache=Campo Narache⟧ con le loro cinture come prova delle tue imprese.", "Hai completato il Rito della Forza, {name}? Mi serve una prova del tuo valore contro i nemici della nostra tribù, i Mantotergo.", "Hai superato la prima prova dei Riti della Madre Terra. La tribù sarà fiera di te.", 0xf671573e, 0xfccb1ae7, 0x910b75e2, 0x9c7434f5, 0x73f2fc7f, "....." },
  [758] = { "La purificazione dei ⟦Thunderhorn=Corno Tonante⟧", "Usa il ⟦Thunderhorn Cleansing Totem=Totem Purificatore dei Corno Tonante⟧ al ⟦Thunderhorn Water Well=Pozzo dei Corno Tonante⟧, poi torna da Mull.", "Il totem è pronto, {name}. E ancora una volta, spetta a te compiere il rituale di purificazione.\n\nVa' al ⟦Thunderhorn Water Well=Pozzo dei Corno Tonante⟧, a nord del villaggio, e usa il ⟦Thunderhorn Cleansing Totem=Totem Purificatore dei Corno Tonante⟧ nel tuo rituale. Fatto questo, torna da me.\n\nChe gli spiriti ti guidino.", "Il ⟦Thunderhorn Water Well=Pozzo dei Corno Tonante⟧ è ancora contaminato, {name}. Ti prego, devi compiere il rituale!", "Gli antenati del clan dei ⟦Thunderhorn=Corno Tonante⟧ mi hanno parlato in sogno, lodandoti per ciò che hai fatto vicino al loro pozzo.\n\nIn segno di gratitudine, desiderano darti questo...", 0x58669439, 0xdd2b0e6c, 0x3a75f7e9, 0x4f9e2854, 0x1f3f8b27, "....." },
  [759] = { "Il totem dei Manto Selvaggio", "Porta 8 Denti di Lupo Alfa a Mull Thunderhorn, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Rimane un solo pozzo da purificare, quello che porta il nome del clan dei Manto Selvaggio. Perché le sue acque tornino pure, la terra deve offrire i denti di un predatore feroce, il lupo alfa della prateria. Trova gli alfa a nord, poi torna da me quando avrai finito la caccia.\n\nGli alfa si aggirano spesso ai piedi della nostra possente città, ⟦Thunder Bluff=Picco del Tuono⟧.", "{name}. Hai i denti che ti ho chiesto?", "Molto bene, {name}. Sento il sacrificio della terra in questa offerta, e il mio spirito si gonfia di tristezza, e di orgoglio.", 0x31b3fafd, 0xc6a6a863, 0xd7b8ed1e, 0x8617acfb, 0xb1d9bbda, "....." },
  [760] = { "La purificazione dei Manto Selvaggio", "Usa il ⟦Wildmane Cleansing Totem=Totem Purificatore dei Manto Selvaggio⟧ al ⟦Wildmane Water Well=Pozzo dei Manto Selvaggio⟧, poi torna da Mull Thunderhorn.", "Gli spiriti parlano di come hai purificato i pozzi degli ⟦Winterhoof=Zoccolo Artico⟧ e dei ⟦Thunderhorn=Corno Tonante⟧, giovane {name}. Il totem dei Manto Selvaggio è pronto, e ti attende l'ultimo compito.\n\nIl ⟦Wildmane Water Well=Pozzo dei Manto Selvaggio⟧ si trova a nord di ⟦Thunder Bluff=Picco del Tuono⟧. Compi il rituale! Guarisci la terra dai veleni dei goblin! Che l'acqua torni a scorrere limpida!", "L'ultimo pozzo è ancora fetido e velenoso, {name}. Non devi indugiare!", "Ce l'hai fatta. Hai purificato i pozzi e guarito la nostra terra. Il Villaggio di Zoccolo Sanguinario ti è grato, {name}.\n\nChe il vento sussurri le tue gesta per cento stagioni, e che le acque di Mulgore restino pure per sempre.", 0xef853d46, 0xe1ef1416, 0xe826c668, 0xf89fe265, 0x2756872c, "....." },
  [761] = { "Caccia agli swoop", "Porta 8 Trophy Swoop Quill a Harken Windtotem al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Lo swoop è un uccello astuto, difficile da trovare e da cacciare. Una collezione di penne di swoop è, per un cacciatore, un segno di ingegno e determinazione.\n\nSe sei <disposto/disposta> ad accettare questo compito, addentrati nelle pianure e caccia gli swoop.\n\nPortami le loro penne e porta onore al tuo clan.\n\nGli swoop si trovano ovunque a Mulgore, ma devi avere l'occhio acuto per scorgerli e gli zoccoli rapidi per prenderli.", "Hai trovato gli swoop, {name}? Hai le loro penne?", "So che raccogliere queste penne non è stato un compito facile, {name}. Così facendo, dimostri di essere un {class} di valore. È un bene averti al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", 0x94bab1f1, 0x29a14ae0, 0x91563b63, 0xa8ba17e3, 0x1264b4dd, "....." },
  [763] = { "I riti della Madre Terra", "Porta il ⟦Totem of Hawkwind=Totem dei Vento Agile⟧ a Baine Bloodhoof, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Segui la strada che esce dal ⟦Camp Narache=Campo Narache⟧.", "Per proseguire con i Riti della Madre Terra devi superare altre due prove. È tempo che tu allarghi la tua esperienza, {name}.\n\nRecati al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ e cerca il capo, Baine Bloodhoof, figlio di Cairne. Lì potrai continuare il tuo viaggio e guadagnarti l'approvazione degli anziani di ⟦Thunder Bluff=Picco del Tuono⟧.\n\nPorta questo totem a Baine. Riconoscerà i miei intagli e ti aiuterà nel tuo cammino.\n\nSegui la strada che esce dal ⟦Camp Narache=Campo Narache⟧ e viaggia in fretta. Non deviare, o ti perderai.", "Cosa ti porta al mio villaggio, {class}?", "Notizie dal mio buon amico, il capo Hawkwind! Ah, dai suoi intagli vedo che sei di una stirpe speciale.", 0x7df8fef9, 0x03e6da03, 0xfd5f3bae, 0x4f49dc5c, 0xf9a3f2f5, "....." },
  [764] = { "La S.P.R. & Co.", "Uccidi 14 Venture Co. Worker e 6 Venture Co. Supervisor per Morin Cloudstalker, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Questo spiega l'aumento di dipendenti e attrezzature della S.P.R. & Co. che abbiamo visto a Mulgore. Quei goblin... la loro compagnia si sta espandendo troppo in fretta per il loro stesso bene. Come si suol dire, mostra qualcosa a un goblin e sentirai il tintinnio della bilancia.\n\nPiccole creature avide, ecco cosa sono. Purtroppo per i loro affari, noi tauren non possiamo permettere che operino nelle nostre terre. Va' alla loro miniera, a nord-est della carovana devastata, e manda loro un messaggio.", "Alla S.P.R. & Co. sono stati negati i diritti di estrazione qui a Mulgore, ma a quanto pare non accettano un no come risposta. Noi tauren, però, non siamo tipi da tante parole, e abbiamo altri modi per far arrivare il nostro messaggio.", "Non credo che quel segnale si possa fraintendere o ignorare, eh? La S.P.R. & Co. saprà che non deve prendere alla leggera i tauren, né essere tanto arrogante da credere che le lasceremmo rubare senza protestare le risorse naturali che ci circondano.", 0xf2993d30, 0xd5d4a54b, 0xf3734121, 0x13728f08, 0xfaa63db1, "....." },
  [765] = { "Il sovrintendente Fizsprocket", "Uccidi il sovrintendente Fizsprocket e porta il suo blocco appunti a Morin Cloudstalker, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Secondo i documenti che hai recuperato dalla carovana, la S.P.R. & Co. ha ideato molti piani per cacciarci dalle nostre terre, così da avere mano libera nel saccheggiarle.\n\nIl punto a cui sono disposti ad abbassarsi pur di raggiungere i loro scopi mi disgusta e mi sconvolge. Voglio morta la mente dietro questi piani. Si chiama sovrintendente Fizsprocket: lo troverai alla miniera della S.P.R. & Co., a est della carovana devastata. Portami il suo blocco appunti, vedremo se ne ricaviamo qualcosa di utile.", "Ribollo di rabbia al pensiero delle atrocità che la S.P.R. & Co. è disposta a commettere contro di noi in nome del profitto.", "La mia rabbia si placa un poco alla notizia che quel furfante di Fizsprocket è morto. Esaminerò i suoi effetti personali e vedrò se ci sono altre informazioni su cosa ha in programma la S.P.R. & Co. per il futuro. Grazie per il tuo impegno, {name}.", 0x189f219c, 0x173e8cc7, 0x334998bc, 0x10cf1ff1, 0x9ad50194, "....." },
  [766] = { nil, "Porta un ⟦Prairie Wolf Heart=Cuore di Lupo della Prateria⟧, un ⟦Flatland Cougar Femur=Femore di Puma delle Pianure⟧, una ⟦Plainstrider Scale=Scaglia di Zampalunga delle Pianure⟧ e uno ⟦Swoop Gizzard=Stomaco dell'Avvoltoio⟧ a Maur Raincaller al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Mio nonno mi raccontava delle sue battaglie con uno zampalunga di nome Mazzranache. Mi parlava dei suoi demoniaci occhi rossi, dei suoi artigli affilati come rasoi e del suo morso velenoso.\n\nIl destino ha voluto che, mentre attraversavo le pianure, lo incontrassi, e mi ha strappato un brutto morso dalla spalla. Era terribile come lo descriveva mio nonno. Mi serviranno alcune parti di animali difficili da trovare per ripulire l'infezione del morso: un cuore di lupo, un femore di puma, una scaglia di zampalunga delle pianure e uno stomaco di avvoltoio.\n\nFa' presto, il tempo stringe.", "La febbre peggiora e la mia mente scivola in incubi deliranti... Avrei dovuto sapere che non sarei riuscito a tener testa a una bestia che nemmeno mio nonno era riuscito a sconfiggere...\n\nHai gli ingredienti per il rimedio? Temo che se non ripulisco presto l'infezione, sarà la mia morte.", "Ah, grazie, {name}. Con gli oggetti che mi hai portato potrò preparare il rimedio che mi serve per fermare l'infezione e, alla fine, guarirla del tutto. Ti devo la vita.\n\nMa non dimenticherò mai quel verso stridulo quando Mazzranache mi piombò addosso, quel lampo di colori mentre il suo becco calava su di me...\n\nSta' in guardia durante i tuoi viaggi.", 0xc53484ac, 0xc072894f, 0x179b5a29, 0x03b0363b, 0x1f60bcdb, "e...." },
  [767] = { "Il Rito della Visione", "Parla con Zarlman Two-Moons al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Il Rito della Visione, uno dei Riti della Madre Terra, ti aiuterà a guadagnarti il rispetto degli anziani di ⟦Thunder Bluff=Picco del Tuono⟧.\n\nIl nostro popolo ha imparato che la terra è la nostra fonte di sostentamento più sacra. Per prendere parte alla visione rituale, devi parlare con la guida spirituale del villaggio, Zarlman Two-Moons.", nil, "Sentivo che saresti <venuto/venuta> da me, {class}. Riconosco sempre chi cerca di superare i Riti della Madre Terra.", 0x41285dc9, 0x38d9ca06, 0x991d2c64, nil, 0xb19dcd8c, "...m." },
  [768] = { "Raccolta di cuoio", "Porta 12 pezzi di ⟦Light Leather=Cuoio Leggero⟧ a Veren Tallstrider a ⟦Thunder Bluff=Picco del Tuono⟧.", "Salve, giovane. Hai un luccichio negli occhi; vedo che non vedi l'ora di tornare a cacciare nelle pianure. Che tu possa portare onore al tuo clan!\n\nLavoro le pelli delle bestie e ne ricavo vestiti e armature per la gente di ⟦Thunder Bluff=Picco del Tuono⟧.\n\nSe vai a caccia di bestie e mi porti le loro pelli, preparerò qualcosa per te.", "Ciao di nuovo. Sei andat<o/a> a caccia? Hai delle pelli per me?", "Ah, sono pezzi molto belli. Ne verranno ottimi articoli di cuoio.\n\nEcco, {name}. Prendi questo in cambio...", 0x20df24d4, 0xf2d8885d, 0x1d87caf8, 0xa3f0a992, 0xec223580, "....." },
  [769] = { "⟦Kodo Hide Bag=Sacca di Pelle di Kodo⟧", "Porta 4 pezzi di ⟦Light Leather=Cuoio Leggero⟧ e 4 rocchetti di ⟦Coarse Thread=Filo Grezzo⟧ a Veren Tallstrider, a ⟦Thunder Bluff=Picco del Tuono⟧.", "I kodo di Mulgore sono forti e robusti, qualità molto rispettate tra noi. Se sei espert<o/a> nella lavorazione del cuoio e vuoi imparare a creare una ⟦Kodo Hide Bag=Sacca di Pelle di Kodo⟧, portami i materiali per il mio mestiere.\n\nFallo, e condividerò con te il mio sapere.", "Hai i miei materiali, {name}?", "Ah, bene. Grazie, {name}. Il mio cuore si gonfia d'orgoglio nel vedere giovani interessati all'arte della lavorazione del cuoio.", 0x2a31f358, 0x65e5965b, 0xd979157c, 0x934db7b4, 0x4f7e5b87, "....." },
  [770] = { "Il ⟦Demon Scarred Cloak=Manto Straziato dal Demone⟧", "Trova qualcuno che sappia qualcosa di Ghost Howl.", "La pelle logora di Ghost Howl porta ancora una ferita terribile, ricevuta nelle battaglie del lupo contro la Legione Infuocata.\n\nForse qualcuno al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ vorrà sapere della fine di Ghost Howl...", nil, "Stento a credere ai miei vecchi occhi! Hai sconfitto il grande lupo Ghost Howl? Ti guardo con rinnovato rispetto, giovane {class}. Sei <un/una> <cacciatore/cacciatrice> di straordinaria abilità!\n\nLascia che ti offra qualcosa. I miei giorni di caccia sono finiti, ma sarei onorato se usassi una delle mie armi nelle tue cacce.\n\nChe colpisca sempre nel segno e ti porti fama.\n\nE speriamo che lo spirito di Ghost Howl abbia finalmente trovato pace.", 0x2d2eee90, 0x9ee101a3, 0x7f4824a7, nil, 0x1cb5a6d0, "...m." },
  [771] = { "Il Rito della Visione", "Raccogli 2 Well Stone e 2 Ambercorn e riportali a Zarlman Two-Moons al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Per superare il Rito della Visione, devi raccogliere i reagenti necessari a preparare l'⟦Water of the Seers=Acqua dei Veggenti⟧.\n\nMi serviranno delle pietre di pozzo, che si trovano intorno ai pozzi d'acqua di Mulgore. A queste unirò le Ambercorn, che cadono sotto i possenti alberi della nostra terra.\n\nQuesti reagenti contengono elementi magici e, una volta preparati e consumati davanti al fuoco tribale, ti faranno incontrare una visione. Seguila, e ti condurrà alla prossima tappa di questa sacra missione.", "Quando avrai raccolto abbastanza pietre di pozzo intorno ai pozzi d'acqua e Ambercorn sotto gli alberi, preparerò per te l'⟦Water of the Seers=Acqua dei Veggenti⟧.", "Vedo che hai imparato a raccogliere dalla nostra terra sacra, {name}. Mi basterà un istante per preparare l'⟦Water of the Seers=Acqua dei Veggenti⟧.", 0x41285dc9, 0x59131882, 0x498db071, 0x381db944, 0x0d3c4b06, "....." },
  [772] = { "Il Rito della Visione", "Bevi l'⟦Water of the Seers=Acqua dei Veggenti⟧ davanti al fuoco tribale del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ e segui la visione quando appare.", "Ora ti consegno l'⟦Water of the Seers=Acqua dei Veggenti⟧.\n\nQuando sarai <pronto/pronta>, bevi le acque vicino al fuoco tribale. Dopo averle ingerite, ci vorrà qualche istante prima che la visione si materializzi davanti al fuoco.\n\nA quel punto starà a te seguirla verso il tuo destino....", nil, "Non temere, {name}. Hai superato il Rito della Visione.", 0x41285dc9, 0x703cb80a, 0x5c9c801d, nil, 0x1330e907, "...m." },
  [773] = { "Il Rito della Saggezza", "Recati ai ⟦Red Rocks=Massi Rossi⟧, a est di ⟦Thunder Bluff=Picco del Tuono⟧, e parla con lo ⟦Ancestral Spirit=Spirito Ancestrale⟧.", "Per essere accettat<o/a> dagli anziani di ⟦Thunder Bluff=Picco del Tuono⟧, ora devi completare il Rito della Saggezza.\n\nOra che hai superato il Rito della Visione, gli spiriti ancestrali dei ⟦Red Rocks=Massi Rossi⟧ ti concederanno la benedizione dei nostri antenati. Solo chi ha bevuto l'Acqua dei Veggenti può riceverla.\n\nRecati a est di ⟦Thunder Bluff=Picco del Tuono⟧, ai ⟦Red Rocks=Massi Rossi⟧, e cerca lo ⟦Ancestral Spirit=Spirito Ancestrale⟧, {name}.", nil, "Hai mostrato grande diligenza nel tuo desiderio di superare i Riti della Madre Terra, {name}.\n\nNoi, gli Spiriti Ancestrali, rappresentiamo i possenti tauren che diedero coraggiosamente la vita per fondare e proteggere la nostra grande città di ⟦Thunder Bluff=Picco del Tuono⟧. Con questo, affido a te il dovere di quella protezione.\n\nHai superato il Rito della Saggezza, giovane {class}. Entra a ⟦Thunder Bluff=Picco del Tuono⟧ con orgoglio.", 0x3cab5a3b, 0xba53b13d, 0xeee894d8, nil, 0x6d5525a9, "...m." },
  [775] = { "Viaggio a ⟦Thunder Bluff=Picco del Tuono⟧", "Parla con Cairne Bloodhoof a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ora godrai di grande rispetto nella nostra grande città. Ogni {race} che si dimostri all'altezza di completare i Riti della Madre Terra si guadagna questo onore.\n\nPer la tua ultima missione, cerca il nostro nobile capo, Cairne Bloodhoof, che dimora in cima alla mesa più alta di ⟦Thunder Bluff=Picco del Tuono⟧.", nil, "Salute, giovane {class}. Vedo che hai trovato la strada fino alla mia soglia.", 0xdcd33962, 0x0ea57d96, 0x9394ae56, nil, 0xc4ed687f, "...m." },
  [776] = { "I riti della Madre Terra", "Cairne Bloodhoof, a ⟦Thunder Bluff=Picco del Tuono⟧, vuole che tu gli porti il ⟦Horn of Arra'chea=Corno Arra'chea⟧.", "Hai superato i Riti della Madre Terra e ti sei <guadagnato/guadagnata> un posto a ⟦Thunder Bluff=Picco del Tuono⟧.\n\nMa per mantenere il posto che hai tanto faticato a ottenere, devi continuare a dimostrare il tuo valore alla tua gente.\n\nSiamo cacciatori, {name}. Giù a Mulgore c'è un possente kodo di nome Arra'chea. Mostrami la tua abilità nel seguire le tracce e nel cacciare portandomi il ⟦Horn of Arra'chea=Corno Arra'chea⟧.", "Hai già trovato Arra'chea?", "Ben fatto! Un'ottima preda.\n\nManderò una squadra a recuperare la carcassa, così potremo prenderne la pelle e la carne.\n\nHai compiuto una grande impresa per la tua gente, {name}.", 0x7df8fef9, 0x661646b6, 0x721576c2, 0xc2995de7, 0x6d0429c3, "....." },
  [780] = { "I Battleboar", "Grull Hawkwind, a ⟦Camp Narache=Campo Narache⟧, vuole che tu uccida dei Battleboar e riporti 8 Battleboar Snout e 8 Battleboar Flank.", "I Battleboar della ⟦Brambleblade Ravine=Depressione di Rovoaguzzo⟧, a est, stanno invadendo i terreni di caccia della nostra tribù. Li addestrano alla ferocia i ⟦Bristleback=Mantotergo⟧, i verrospini con cui siamo in guerra.\n\nVa' e uccidi quelle creature immonde, e riporta dei musi e dei costati, così potremo preparare uno stufato per i nostri piccoli.", "I Battleboar sono sempre più aggressivi. Hai mandato loro un messaggio chiaro e riportato qualche muso e costato?", "Eccellente. Con questi ingredienti verrà fuori un ottimo stufato, e la perdita di quei cinghiali dovrebbe essere una bella lezione per quei vili Mantotergo.", 0x378fb934, 0xee3fc884, 0xa5153aa4, 0xd39bd801, 0x1977a494, "....." },
  [781] = { "Attacco a ⟦Camp Narache=Campo Narache⟧", "Porta i ⟦Bristleback Attack Plans=Piani d'Attacco dei Mantotergo⟧ al capo Hawkwind a ⟦Camp Narache=Campo Narache⟧.", "Dopo aver esaminato con attenzione la mappa, ti rendi conto di aver scoperto i piani del capoguerra dei ⟦Bristleback=Mantotergo⟧ per un lungo assedio a ⟦Camp Narache=Campo Narache⟧.\n\nDi certo il capo Hawkwind vorrà avere queste informazioni!", "Hai l'aria preoccupata, {name}. Che notizie porti?", "Questo è davvero allarmante! Ma con queste informazioni possiamo chiamare i nostri fratelli del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ ad aiutarci a sventare l'attacco. Hai salvato la vita a molti tauren, {name}.", 0xb52d084e, 0xe65805d4, 0xe823abd6, 0x979a42f3, 0xe5c852a9, "....." },
  [783] = { "Una minaccia interna", "Parla con il maresciallo McBride.", "Spero che tu abbia stretto bene la cintura, giovane {class}, perché qui nella ⟦Northshire=Contea del Nord⟧ c'è del lavoro da fare.\n\nE non parlo di lavori nei campi.\n\nLe guardie di ⟦Stormwind=Roccavento⟧ faticano a mantenere la pace, con tanti di noi in terre lontane e tante minacce che incombono. Per questo chiediamo l'aiuto di chiunque sia disposto a difendere la propria casa. E la propria alleanza.\n\nSe sei qui per rispondere alla chiamata, parla con il mio superiore, il maresciallo McBride. È nell'abbazia, alle mie spalle.", nil, "Ah, bene. Un altro volontario. Ne arrivano tanti di questi tempi.\n\nSpero che bastino.\n\nLe terre degli umani sono minacciate dall'esterno, e gran parte delle nostre forze è stata mandata lontano. Questo, a sua volta, permette a gruppi corrotti e senza legge di prosperare entro i nostri confini.\n\nCombattiamo una battaglia su molti fronti, {name}. Preparati a una lunga campagna.", 0x5dfca6f5, 0x4ec936be, 0x0ab5d4f4, nil, 0x031c7505, "...m." },
  [784] = { "Sconfiggere i traditori", "Uccidi 10 Kul Tiras Sailor, 8 Kul Tiras Marine e il tenente Benedict, poi torna da Gar'Thok a ⟦Razor Hill=Tranciacolle⟧.", "Guidati dall'ammiraglio Proudmoore, gli umani di Kul Tiras hanno invaso il Durotar, violando il patto che il Capoguerra aveva stretto con Jaina Proudmoore per sconfiggere Archimonde anni fa.\n\nL'aggressione umana fu respinta e il ⟦Tiragarde Keep=Forte di Tiragarde⟧ cadde. Ma di recente le riserve dell'ammiraglio, guidate dal tenente Benedict, hanno ripreso il forte e minacciano di nuovo la nostra patria. Questi umani non hanno alcun rispetto per la diplomazia.\n\nDimostra il tuo onore: viaggia a sud fino al ⟦Tiragarde Keep=Forte di Tiragarde⟧ ed elimina gli invasori umani.", "Hai i tuoi ordini, {name}. La sicurezza del Durotar è in pericolo. Porta a termine il compito che hai davanti o china il capo per la vergogna.\n\nMostra il tuo onore e sconfiggi gli umani del ⟦Tiragarde Keep=Forte di Tiragarde⟧.", "La notizia del tuo coraggio corre veloce, {class}. Le storie della tua vittoria al ⟦Tiragarde Keep=Forte di Tiragarde⟧ saranno celebrate a Orgrimmar.", 0x61203c69, 0x154583f4, 0x582379ba, 0x9292d6eb, 0xd22b726e, "....." },
  [785] = { "Un'⟦Alliance=Alleanza⟧ strategica", "Cerca Lar Prowltusk sul fianco occidentale del ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Thrall è un capo davvero saggio e nobile. La sua tenacia sul campo di battaglia è pari soltanto al suo tatto diplomatico.\n\nI ⟦Darkspear Trolls=Troll Lanciascura⟧ si sono dimostrati alleati preziosi per la stirpe degli orchi. Per lealtà e onore abbiamo stretto con loro un patto di protezione.\n\nIl Capoguerra ha ordinato di assicurarci che i nostri amici ⟦Darkspear=Lanciascura⟧ del ⟦Sen'jin Village=Villaggio di Sen'jin⟧ non corrano pericoli diretti. Uno dei loro esploratori più fidati, Lar Prowltusk, sorveglia attentamente il loro fianco occidentale.\n\nCerca Lar e aiutalo come serve.", nil, nil, 0xf723c36b, 0xf3d70985, 0x1c00d4e5, nil, nil, "...mm" },
  [786] = { "Fermare l'aggressione dei Kolkar", "Lar Prowltusk, fuori dal ⟦Sen'jin Village=Villaggio di Sen'jin⟧, vuole che tu distrugga i 3 piani d'attacco custoditi a Kolkar Crag.", "Abbassa la voce, {class}. I centauri Kolkar sono appena oltre la cresta a ovest, a Kolkar Crag.\n\nIeri notte, mentre erano fuori a razziare, mi sono intrufolato nel loro villaggio e ho scoperto che quelle bestie schifose hanno pianificato un attacco in tre fasi contro i troll e gli orchi di Durotar.\n\nNon possiamo permettere che la loro invasione vada in porto. Forse tu puoi raccogliere la forza necessaria per infiltrarti a Kolkar Crag e distruggere i loro piani d'attacco.\n\nL'ultima volta che li ho visti, li avevano divisi fra tre dei loro capi.", "I centauri si sono rivelati un fastidio costante per l'⟦Horde=Orda⟧. Le loro intenzioni di assediare la nostra terra non possono essere tollerate.", "L'⟦Horde=Orda⟧ prevarrebbe di certo se i centauri Kolkar attaccassero. Ma impedendo un simile attacco, abbiamo risparmiato ai nostri possenti guerrieri un inutile spargimento di sangue.\n\nE com'è vero che c'è sabbia nel deserto di Tanaris, sappiamo che altro sangue sarà versato prima che questi tempi difficili finiscano.\n\nHai servito bene il tuo popolo, {class}.", 0xb1c3cfee, 0x456bae15, 0x42ae48a2, 0x6f511eae, 0xe654120a, "....." },
  [787] = { "La nuova ⟦Horde=Orda⟧", "Fai rapporto a Gornek nell'Antro del Tirocinio.", "Throm'ka, {class}. Sono Eitrigg, incaricato da Thrall di sovrintendere all'addestramento delle reclute.\n\nL'⟦Horde=Orda⟧ non è più quella di un tempo. Ci fu un periodo in cui lasciai l'⟦Horde=Orda⟧, disilluso dalla crescente influenza delle pedine della Legione Infuocata, assetate di potere. Durante il mio esilio fui fatto prigioniero da un gruppo di umani, ma il Capoguerra mi salvò. Quando sentii la sua visione di un'⟦Horde=Orda⟧ libera dall'influenza demoniaca e guidata dagli sciamani, tornai.\n\nGornek ti darà altre istruzioni.", nil, "Un'altra recluta di Eitrigg, eh?\n\nSiamo messi proprio male, se questo è il meglio che l'⟦Horde=Orda⟧ sa produrre. Non importa. Quando riterremo che tu sia pront<o/a> a lasciare la Valle, sarai <un/una> fier<o/a> <guerriero/guerriera> dell'⟦Horde=Orda⟧.", 0x1b8f33fb, 0xfeeb0bec, 0x360ecd22, nil, 0x73610f14, "...m." },
  [788] = { "Primi denti", "Uccidi 10 Mottled Boar, poi torna da Gornek all'Antro del Tirocinio.", "Per prima cosa dovrai metterti un po' di forza nella schiena. Potrei mandarti nelle ⟦Barrens=Savane⟧ a cacciare kodo ma, beh, a dirla tutta, ci sei più utile viv<o/a> che mort<o/a>.\n\nCredo che troverai degli avversari alla tua altezza nei Mottled Boar, qui a nord.", "Spero che tu non sia tornat<o/a> per convincermi di aver portato a termine il tuo compito, {name}. No, certo che no. Avrei una stima migliore di te.", "Mmm, niente male, {name}. Ma non montarti la testa... nella tua carriera affronterai avversari più duri dei cinghiali.\n\nComunque hai dimostrato il tuo valore, e la tua prossima prova sarà contro un avversario molto più pericoloso, quindi ti servirà un po' di protezione in più.", 0xd952680c, 0xe879ed8f, 0xbc4c97b2, 0x33c5034a, 0x0851ec59, "....." },
  [789] = { "Il pungiglione dello scorpide", "Procura 10 Coda di ⟦Scorpid=Scorpide⟧ Lavoratore per Gornek, nell'Antro del Tirocinio.", "Guerrieri possenti e goffi novellini sono caduti allo stesso modo sotto il pungiglione velenoso dello scorpide. Troverai molti scorpidi a nord-ovest di qui. Portami dieci delle loro code come prova della tua abilità in battaglia.\n\nL'antidoto per la loro puntura si ricava proprio dal veleno estratto dai loro pungiglioni. Ne teniamo grandi scorte a portata di mano per curare i giovani impetuosi come te...\n\nMa sono sicuro che non ne avrai bisogno, vero?", "Il carapace di uno scorpide non è così spesso da fermare la forza di un guerriero determinato. Colpisci con forza e senza esitare, e gli scorpidi si dimostreranno prede facili.", "C'è una lezione importante che devi trarre dalla lotta contro gli scorpidi. L'avversario più piccolo come quello più grande può comunque condurti alla rovina. In un combattimento feroce, qualsiasi cosa può causare la tua caduta.\n\nNon ho altro da insegnarti, {name}. Hai fatto bene, e seguirò i tuoi progressi con interesse.", 0xa7461cce, 0x3563df4d, 0x9f27737c, 0xe82bc356, 0xd139b0d4, "....." },
  [790] = { nil, "Uccidi Sarkoth e riporta la sua chela a Hana'zua.", "{class}! Pensavo che sarei morto qui senza che nessuno lo sapesse. Mentre cacciavo gli scorpidi della Valle, mi sono imbattuto in uno dall'aria particolarmente feroce. Mi ci sono scagliato contro e sono riuscito a infliggergli un colpo tremendo alla chela, prima che si chiudesse sulla mia gamba.\n\nPerò non mi aspettavo il pungiglione: è calato e mi è penetrato nel petto, lacerandomi la carne e facendomi sanguinare. Ti prego, devi uccidere lo scorpide al posto mio! Il mio onore deve essere difeso! L'ho combattuto sull'altopiano a sud.", "Ahhh... mio padre diceva sempre che non avrei mai combinato granché, e ora, steso sotto un albero mentre la vita mi abbandona, temo proprio che avesse ragione.\n\nAlmeno vorrei morire sapendo che il mio ultimo nemico giace morto.", "Il mio colpo non è bastato a ucciderlo, ma vedere il danno che gli ho inflitto mi dà una piccola dose di orgoglio. Quella piccola dose sarà tutto ciò che avrò per sostenermi se morirò, e sotto questa luce, il breve elenco delle imprese della mia vita mi riempie di rabbia.", 0xc29f8f29, 0xed33aa8a, 0xabbb648b, 0x3647febb, 0x59471209, "e...." },
  [791] = { "Fai la tua parte", "Furl Scornbrow, nella torre di guardia di ⟦Razor Hill=Tranciacolle⟧, vuole 8 ⟦Canvas Scraps=Brandelli di Canovaccio⟧.", "L'età mi ha reso inutile in battaglia. Ora mi rendo utile in altri modi.\n\nDa questo punto d'osservazione sorveglio l'arrivo di invasori. Man mano che qui la nostra forza cresce, mi ritrovo a suonare il corno d'allarme sempre meno.\n\nPer passare il tempo fabbrico oggetti per aiutare i guerrieri più giovani e capaci a difendere la nostra patria.\n\nPer te posso fabbricare una borsa per i tuoi averi. Se un oggetto del genere ti è utile, portami un po' di tela, un materiale comune tra gli umani e i centauri.", "Ho combattuto con orgoglio al fianco del Capoguerra quando queste terre furono conquistate. Le cicatrici della battaglia segnano la mia pelle.\n\nL'onore dell'⟦Horde=Orda⟧ è stato difeso anche grazie alla mia ascia e al mio grido di battaglia durante la sconfitta di Archimonde, quando, per necessità, fu stretta l'empia alleanza con gli umani e gli elfi.\n\nMa il mio ruolo di sentinella e fornitore mi ha dato un nuovo senso del mio valore.", "Eccellente, {name}. Qualunque {class} che si rispetti troverà di certo un uso per questa borsa sul campo di battaglia.\n\nOnoro il tuo vigore e la tua disponibilità a morire nel nome dell'⟦Horde=Orda⟧!", 0xf3916378, 0xacb97dc1, 0x620d5ba2, 0xca1b14ce, 0x6227d388, "....." },
  [792] = { "Famigli vili", "Uccidi 12 Vile Familiar.\n\nTorna da Zureetha Fargaze, fuori dall'Antro del Tirocinio.", "Confido che la ⟦Valley of Trials=Valle delle Sfide⟧ ti insegnerà molto, giovane {class}.\n\nSono stata mandata nella Valle per guidarti, ma qui ho scoperto una corruzione che si diffonde...\n\nUn gruppo che si fa chiamare ⟦Burning Blade=Lame Ardenti⟧ ha una congrega qui nella ⟦Valley of Trials=Valle delle Sfide⟧. Si nascondono in una caverna a nord-est, e i loro Vile Familiar sono usciti dall'imboccatura per seminare il caos.\n\nCome primo compito contro le ⟦Burning Blade=Lame Ardenti⟧, ti chiedo di sconfiggere questi famigli. Uccidine molti e, se sopravvivi, torna da me.", "Per metterti alla prova contro le ⟦Burning Blade=Lame Ardenti⟧, devi prima sconfiggere i loro Vile Familiar. Torna da me quando l'avrai fatto.", "Hai fatto bene, {name}.\n\nAnche se i Vile Familiar erano solo semplici famigli al servizio dei poteri più oscuri delle ⟦Burning Blade=Lame Ardenti⟧, il tuo successo contro di loro preannuncia imprese più grandi.", 0x8ce65439, 0xcd4c8281, 0x88673f1b, 0xa51a267d, 0x83d0b880, "....." },
  [794] = { "⟦Burning Blade Medallion=Medaglione delle Lame Ardenti⟧", "Porta il ⟦Burning Blade Medallion=Medaglione delle Lame Ardenti⟧ a Zureetha Fargaze, fuori dall'⟦The Den=Antro del Tirocinio⟧.", "Grazie alle mie divinazioni vedo che un oggetto di potere si nasconde nel profondo del ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧, sorvegliato da bestie e magia nera.\n\nSi chiama ⟦Burning Blade Medallion=Medaglione delle Lame Ardenti⟧, e il tuo prossimo compito è trovarlo e portarlo via dal covo.\n\nMa stai in guardia, perché il medaglione potrebbe essere in mano a un agente delle ⟦Burning Blade=Lame Ardenti⟧, e in tal caso il suo potere sarebbe superiore a quello dei famigli che hai già affrontato.\n\nVa', {name}. Troverai il covo in una grotta, a nord-ovest.", "Hai portato a termine il tuo compito, {name}? Hai il ⟦Burning Blade Medallion=Medaglione delle Lame Ardenti⟧?", "L'hai recuperato! Ben fatto!\n\nI tuoi sforzi nel ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧ sono fondamentali per estirpare questo culto dalla ⟦Valley of Trials=Valle delle Sfide⟧. Ma temo che abbiano mire più ampie sulla nostra terra.\n\nNon abbiamo ancora visto la loro fine.", 0xd7a9ded1, 0x0d382153, 0xb70542ce, 0x8771c5c2, 0x7c8c1f1c, "....." },
  [804] = { nil, "Riferisci a Gornek, all'Antro del Tirocinio, la difficile situazione di Hana'zua.", "Vedere ciò che hai fatto per me mi tempra il cuore. Non posso cadere così facilmente! Devo resistere!\n\nMa resta il fatto che non posso tornare all'Antro del Tirocinio senza aiuto. Ti prego, {name}, torna all'Antro del Tirocinio e racconta a Gornek della mia situazione. Forse lui può aiutarmi.", nil, "Dalla tua descrizione della bestia, credo che tu stia parlando di Sarkoth! Non c'è da stupirsi che Hana'zua ne sia stato sopraffatto. Gli manderemo subito aiuto: non preoccuparti più della situazione di Hana'zua.\n\nTuttavia devo dire che sono molto colpito nel sapere che hai dato la morte a Sarkoth. È un'impresa di cui andare fier<o/a>, {name}. E il fatto che tu abbia combattuto per l'onore di uno sconosciuto, mentre altri compiti ti tenevano occupat<o/a>, accresce il tuo stesso onore.", 0xc29f8f29, 0xafd8ceaf, 0x6faf13ea, nil, 0xc5de3e04, "e..m." },
  [805] = { "Rapporto al ⟦Sen'jin Village=Villaggio di Sen'jin⟧", "Parla con il maestro Gadrin al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Le tue prove contro le ⟦Burning Blade=Lame Ardenti⟧ sono concluse... qui nella Valle. Ma voglio che tu riferisca ciò che hai scoperto.\n\nVa' al villaggio troll di Sen'jin e cerca il maestro Gadrin. Il ⟦Sen'jin Village=Villaggio di Sen'jin⟧ si trova a est, fuori dalla valle, poi a destra al bivio.\n\nParla a Gadrin delle ⟦Burning Blade=Lame Ardenti⟧ e digli che hanno raggiunto la ⟦Valley of Trials=Valle delle Sfide⟧. Scopri da lui se sono già arrivate a Sen'jin.\n\nVa', {name}, e sii rapid<o/a>. Temo che il male trovato nel ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧ sia solo il presagio di una minaccia più grande...", nil, "Mm... il tuo rapporto arriva in un brutto momento. Le ⟦Burning Blade=Lame Ardenti⟧ non si sono viste qui a Sen'jin, ma il loro male ha messo radici al largo della costa, sulle ⟦Echo Isles=Isole dell'Eco⟧.\n\nGli orchi sono amici dei ⟦Darkspear Trolls=Troll Lanciascura⟧. Amici d'onore. Noi vogliamo aiutare gli orchi, ma... anche noi abbiamo bisogno di aiuto.", 0x3a372a4c, 0x0c77979e, 0x0bbd2c9e, nil, 0xda50f16d, "...m." },
  [806] = { "Tempeste oscure", "Porta l'⟦Fizzle's Claw=Artiglio di Fizzle⟧ a Orgnil Soulscar, a ⟦Razor Hill=Tranciacolle⟧.", "Non possiamo permettere che le ⟦Burning Blade=Lame Ardenti⟧ mettano piede in Durotar! Dobbiamo distruggerle prima che il loro male si diffonda!\n\nHo condotto le mie indagini e ho scoperto che uno stregone delle ⟦Burning Blade=Lame Ardenti⟧, il goblin Fizzle Darkstorm, si è accampato nella ⟦Thunder Ridge=Fossa del Tuono⟧, a nord-ovest. Lì lui e i suoi tirapiedi cultisti seminano il caos.\n\nTrova Fizzle, sconfiggilo e portami il suo artiglio morto!", "Hai trovato Fizzle, {name}? Lui e il resto delle ⟦Burning Blade=Lame Ardenti⟧ vanno spazzati via dalle nostre terre!", "Aha! L'hai preso!\n\nFai onore al tuo clan, {name}. E grazie a te Durotar si è liberata di un altro agente del male.", 0x2402e200, 0x7fa60fc3, 0x7cc19661, 0x20286f9c, 0x3cc1d2bc, "....." },
  [808] = { "Il ⟦Minshina's Skull=Teschio di Minshina⟧", "Recupera il teschio di Minshina dal cerchio del potere sulle ⟦Echo Isles=Isole dell'Eco⟧.\n\nPortalo al maestro Gadrin, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Sento la voce di mio fratello, Minshina, che mi chiama nei sogni.\n\nÈ stato preso da Zalazane, lo stregone delle ⟦Echo Isles=Isole dell'Eco⟧, a est. Ed è morto.\n\nMa la morte non è libertà per mio fratello. Lo spirito di Minshina è stato imprigionato nel suo stesso teschio dalla magia di Zalazane. Nei sogni lo vedo insieme ad altri teschi, in un cerchio del potere sulla più grande delle ⟦Echo Isles=Isole dell'Eco⟧. Finché resterà lì, l'anima di mio fratello sarà dannata.\n\nTi prego, {name}. Trova il cerchio e recupera il teschio di Minshina. Portalo a me.\n\nLiberalo!", "Hai il teschio di mio fratello, {name}? È finalmente libero?", "Grazie, {name}. Hai salvato Minshina. Hai liberato lo spirito di mio fratello dalla schiavitù!", 0xdcd76bb7, 0x55625a18, 0xd5b48458, 0xbf95ade1, 0x4cdebc60, "....." },
  [809] = { nil, "Parla con Ak'Zeloth nelle ⟦Barrens=Savane⟧.", "Dall'ultima grande guerra, quando la Legione Infuocata fu sconfitta, ho cercato le fonti della corruzione demoniaca nella società degli orchi. Il collare che mi hai portato conferma i miei timori.\n\nAppartiene alle ⟦Burning Blade=Lame Ardenti⟧, un culto che si raccoglie attorno a un oggetto dal potere demoniaco. Si chiama Demon Seed e si trova nelle ⟦Barrens=Savane⟧, in cima al ⟦Dreadmist Peak=Picco di Brumafunesta⟧. Va distrutto!\n\nVa' al ⟦Far Watch Post=Presidio Lungosguardo⟧, al confine occidentale delle ⟦Barrens=Savane⟧, e parla con il mio assistente, Ak'Zeloth. Ti darà altre indicazioni.", nil, "Neeru vuole che il Demon Seed venga distrutto, eh? Strano...\n\nE sia. Se desidera che il seme sparisca, allora ti dirò come rimuoverlo.", 0xc03c9820, 0xc0c2c1e8, 0x8b606564, nil, 0x8f364e63, "e..m." },
  [812] = { "Serve una cura", "Trova Kor'ghan a Orgrimmar e procurati l'⟦Venomtail Antidote=Antidoto ai Codavenefica⟧. Poi porta l'antidoto a Rhinag, vicino al confine nord-occidentale di Durotar.", "{name}... arrivi al momento giusto. Spero solo di poter lodare anche la tua rapidità.\n\nSono stato imprudente mentre combattevo alcuni Codavenefica qui vicino, e uno di loro mi ha punto in profondità. Sento il suo veleno che mi indebolisce anche adesso, mentre parliamo. Di questo passo mi resta forse un'ora di vita. Ma se voglio farcela mi serve il tuo aiuto...\n\nKor'ghan, a Orgrimmar, sa come preparare l'antidoto. Trovalo... e sbrigati, {name}. Non resisterò ancora a lungo. Dovrebbe essere nel Cleft of Shadow.", "Quasi quasi sono contento di non poter tornare a Sen'jin in questo stato. Verrei di sicuro deriso per la mia debolezza e la mia stupidità.", "{name}, mi hai salvato la vita. Grazie.\n\nTi prego, prendi questo; spero che almeno ti sia utile nei tuoi viaggi, se non a farti guadagnare qualche moneta. Da quel che dici, non lo userò tanto presto. Kor'ghan mi farà passare per altri suoi rituali finché non avrò dimostrato il mio valore. Altri cinghiali da ammazzare, altre code di scorpide da raccogliere... <sospira>", 0xac00d112, 0x6effbb1f, 0x4c6dedad, 0x018eb78e, 0x5fe8b88a, "....." },
  [813] = { "In cerca dell'antidoto", "Porta 4 Venomtail Poison Sac a Kor'ghan, a Orgrimmar.", "I Codavenefica sono tra gli scorpidi più letali di Durotar. Rhinag è stato imprudente a cacciarli senza portarsi dietro un po' di antidoto, ma in questo momento una ramanzina è l'ultima cosa di cui ha bisogno.\n\nPortami qualche sacca di veleno dei Codavenefica che si trovano vicino all'ingresso di Orgrimmar e preparerò un antidoto per lui.\n\nAffrettati, {name}. Uno dei nostri ha bisogno del tuo aiuto.", "Ricorda: qualunque creatura tu cacci, faresti bene a studiarla e a capirne il comportamento. Saperlo potrebbe salvarti la vita.", "Ecco l'antidoto, {name}. Portalo a Rhinag appena puoi, e fai attenzione.", 0xf085941f, 0xbfb9abac, 0x76075c6a, 0xf792b3ad, 0x5339c8f3, "....." },
  [815] = { "Rompere qualche uovo", "Porta 3 Taillasher Egg al cuoco Torka a ⟦Razor Hill=Tranciacolle⟧.", "Bah! Quasi dimenticavo che devo preparare la colazione.\n\n{name}, datti una mossa e portami delle uova di taillasher. Me ne servono almeno tre se voglio averne abbastanza per il pasto di domani.\n\nI Bloodtalon Taillasher sanno essere feroci e il più delle volte difendono le loro uova fino alla morte. A volte seppelliscono le uova troppo in profondità per poterle dissotterrare senza rischi, ma se vai alle ⟦Echo Isles=Isole dell'Eco⟧, a sud-est del ⟦Sen'jin Village=Villaggio di Sen'jin⟧, di solito le trovi sparse per tutte quelle isole.", "Colazione, pranzo, cena! Chi se ne importa di che pasto si tratta? Qualcuno deve comunque cucinarlo... cioè io!", "Sarai anche debole, ma almeno non sei <imbranato/imbranata>, {name}.\n\nTieni, prendi questo e levati di torno. Ho da cucinare.", 0x5872ab42, 0x6e4abc1b, 0xb26fb94f, 0x9f710600, 0x85e91f1f, "....." },
  [816] = { "Perduto ma non dimenticato", "Porta un segno della sorte di Kron a Misha Tor'kren, alla fattoria a nord-ovest di ⟦Razor Hill=Tranciacolle⟧.", "{name}, ti prego, puoi aiutarmi? Mio figlio Kron è andato a caccia giorni fa e non è ancora tornato. È andato a ovest, verso le ⟦Barrens=Savane⟧, a cacciare crocolischi lungo il ⟦Southfury River=Fiume Furialunga⟧. Temo il peggio.\n\nPer quanto fosse forte, il suo orgoglio testardo lo ha sempre cacciato nei guai. L'avevo avvertito che i crocolischi erano potenti e feroci. Si è arrabbiato e se n'è andato furioso.\n\nSe non riesci a trovarlo, portami almeno un segno della sua sorte... anche se dovessi aprire lo stomaco di ogni crocolisco sulle rive del Furialunga.", "Prego che Kron torni da me, ma sono quasi certa di conoscere già la sua sorte.", "Oh, figlio mio... il mio bellissimo figlio.\n\nNon sapendo che fine avesse fatto, mi sono tormentata da quando è partito. Ora che so cosa è successo, forse potrò finalmente cominciare a piangerlo.\n\nGrazie, {name}. Ti prego, prendi questo. Volevo regalarlo a Kron quando fosse tornato vittorioso. Ora che so che è morto, non sopporto di guardarlo.", 0xdc0dedea, 0xcc865ae2, 0xb2b27950, 0xe760bb38, 0xf0b43d80, "....." },
  [817] = { "Prede utili", "Porta 4 Durotar Tiger Fur a Vel'rin Fang al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Molte delle pelli che usiamo vengono dalle tigri di Durotar, {name}. Coperte, armature, tende: ci sono tantissimi motivi per cui cacciamo queste bestie, e altrettanti per cui allo stesso tempo le lasciamo prosperare.\n\nÈ giunto il momento di sfoltire il branco, per così dire. Noi cresciamo di numero e i nostri bisogni cominciano a superare le scorte. Mi servono altre pelli se devo preparare beni adatti per la nostra gente.\n\nPortami 4 pellicce di tigre di Durotar e ti ricompenserò. Le trovi sulle isole a sud di qui.", "Ricordo la mia prima caccia alla tigre, {name}. Scelsi di cacciare sulla più grande delle ⟦Echo Isles=Isole dell'Eco⟧ e rimasi perfettamente immobile all'ombra del fogliame per quasi un giorno intero... a osservare... ad aspettare.\n\nAvevo i muscoli tesi e mi preparavo a colpire. Fu una delle mie più grandi vittorie, quando quella tigre finalmente abboccò.", "Mi fa piacere, {name}. Grazie al tuo aiuto, la nostra gente sarà protetta e non patirà il freddo al cambio delle stagioni.\n\nGrazie.", 0xe98eb762, 0xc04aa178, 0x87d30384, 0x79595368, 0x849219dc, "....." },
  [818] = { "Uno spirito solvente", "Porta 4 Intact Makrura Eye e 8 fiale di ⟦Crawler Mucus=Muco di Crostaceo⟧ al maestro Vornal al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Anche se i miei occhi mi tradiscono, ci vedo ancora abbastanza bene. Sempre più spesso devo affidarmi alle mie arti alchemiche per aiutarmi con magie che un tempo mi venivano facili. Ma mi rifiuto di prendere un apprendista: nessun troll o orco abbastanza degno si è mai fatto avanti.\n\nSei all'altezza? Sì, certo che lo sei... certo che credi di esserlo.\n\nMi servono alcune cose. Me le procuri?\n\nMi servono occhi di makrura intatti e fiale di Muco di Crostaceo. Li puoi trovare su qualunque makrura o crostaceo del Durotar. Ci riparleremo presto.", "Il tempo è la vera prova della tua forza e della tua volontà. Perdi la pazienza o cedi alla debolezza, e il tuo vero io si rivelerà.", "Ben fatto, giovane... davvero ben fatto.", 0x0560be8b, 0x00d040ad, 0x16d40dbf, 0xc4a472af, 0xd20355b6, "....." },
  [819] = { "⟦Chen's Empty Keg=Barile di Chen Vuoto⟧", "Trova qualcuno che sappia qualcosa del ⟦Chen's Empty Keg=Barile di Chen Vuoto⟧.", "Una piccola targhetta su una delle estremità del barile recita:\n\n\"Chen Stormstout -\n\nChe il tuo spirito si elevi, e che tu sappia sempre elevare lo spirito.\"", "Sì?", "Ma guarda un po'...\n\nQuesto era uno dei barili di Chen Stormstout. Ha viaggiato con Rexxar tanto tempo fa. Non lo vedo né ne sento parlare da un'era di kodo. Ti ringrazio di avermelo portato, {name}.", 0xc395691b, 0x99cbd4a8, 0xab7a0060, 0x0c07a888, 0x7257e695, "....." },
  [821] = { "⟦Chen's Empty Keg=Barile di Chen Vuoto⟧", "Porta 5 Savannah Lion Tusk, 5 Plainstrider Kidney e 1 ⟦Thunder Lizard Horn=Corno di Sauro del Tuono⟧ al mastro birraio Drohn, a ⟦Ratchet=Porto Paranco⟧.", "Ti va di assaggiare la birra che porta il nome di Chen? Ahh, la stormstout è una birra possente. Chen ha insegnato la ricetta al mio maestro, e il mio maestro l'ha tramandata a me. Avrò bisogno che tu mi procuri un po' di cose, ma una cosa te la posso dire: ne vale la botta.\n\nPortami 5 zanne di leone della savana da qualsiasi leone della savana, 5 reni di corripiana da qualsiasi corripiana e 1 corno di sauro del tuono da qualsiasi specie di sauro del tuono. Dovrebbe bastare.\n\nTroverai questi ingredienti in tutte le ⟦Barrens=Savane⟧.", "Come procede la ricerca?", "Ahah... Non pensavo che avrei mai più preparato questa roba.\n\nMi hai risvegliato una gran nostalgia, {name}. Mi ricorda un po' l'ultima volta che ho fatto una cotta di birra trogg. Grazie. I ricordi mi scaldano lo stomaco.", 0xc395691b, 0x7c727806, 0x88214860, 0xdbae01bb, 0x59d50b70, "....." },
  [822] = { "⟦Chen's Empty Keg=Barile di Chen Vuoto⟧", "Porta 5 Lightning Gland, 1 ⟦Thunderhawk Saliva Gland=Ghiandola di Saliva di Falco del Tuono⟧ e 1 ⟦Kodo Liver=Fegato di Kodo⟧ al mastro birraio Drohn a ⟦Ratchet=Porto Paranco⟧.", "Roba buona, quella stormstout, eh?\n\nHo un'altra ricetta che ho imparato da Chen. Ti interessa? Non ci vorrà molto a prepararla, e potrebbe esserti utile se hai intenzione di avventurarti ancora.\n\nPortami 5 ghiandole del fulmine da qualsiasi stormhide, 1 ghiandola di saliva di falco del tuono dai greater thunderhawk e un fegato di kodo da uno qualsiasi dei kodo delle ⟦Barrens=Savane⟧.\n\nCome ti ho detto, questa roba picchia duro: è la birra dei trogg di cui ti avevo parlato.", "Ti stai dando da fare a trovare quegli ingredienti, {name}?", "Ah ah! Sapevo che non avresti resistito a un po' di questa birra. Torna quando vuoi se ne desideri ancora, {name}. Basta che mi porti altri ingredienti come quelli che ti ho fatto raccogliere.", 0xc395691b, 0xb481c111, 0xeda85af3, 0x3344caba, 0xa4ba152c, "....." },
  [823] = { "Rapporto a Orgnil", "Parla con Orgnil Soulscar a ⟦Razor Hill=Tranciacolle⟧.", "Qui al ⟦Sen'jin Village=Villaggio di Sen'jin⟧ abbiamo anche noi i nostri guai, e ti ringraziamo per il tuo aiuto. Ma le notizie che porti sulle ⟦Burning Blade=Lame Ardenti⟧ potrebbero essere un problema per tutti.\n\nA ⟦Razor Hill=Tranciacolle⟧ c'è un orco di stanza, Orgnil Soulscar, che protegge il Durotar da mali come le ⟦Burning Blade=Lame Ardenti⟧! Va' da Orgnil e raccontagli la nostra situazione, e anche le notizie che porti dalla ⟦Valley of Trials=Valle delle Sfide⟧. Vorrà saperle.\n\n⟦Razor Hill=Tranciacolle⟧ si trova a nord.", nil, "Sì? Hai qualcosa da riferire? Allora, sentiamo!", 0x8fb77557, 0xf5ac1ba5, 0xef556d0f, nil, 0xf17219be, "...m." },
  [824] = { "Je'neu dell'Earthen Ring", "Porta il ⟦Befouled Water Globe=Globo d'Acqua Contaminata⟧ a Je'neu Sancrea, all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, a ⟦Ashenvale=Valtetra⟧.", "L'Earthen Ring è un gruppo sciamanico dedito allo studio e alla salvaguardia degli elementi. Hanno dimenticato più cose su vecchi dei folli, leggende antiche e antiche tradizioni di quante la maggior parte degli studiosi ne saprà mai.\n\nPer tua fortuna, conosco qualcuno dell'Earthen Ring qui a ⟦Ashenvale=Valtetra⟧. Va' all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, sulla costa della ⟦Zoram Strand=Spiaggia di Zoram⟧, e mostra a Je'neu Sancrea ciò che hai trovato. Se c'è qualcuno che può capire l'importanza di quel globo, è lui.", "Ah, salve. Passo molto tempo a studiare l'acqua, anzi tutti gli elementi, tanto che a volte non mi accorgo nemmeno delle persone intorno a me.\n\nPosso aiutarti in qualche modo?", "Questo globo... è davvero inquietante. Molti degli elementali più potenti ricevono il loro potere e la loro energia attraverso congegni come questo. Trovarne uno quasi intatto è una cosa; trovarlo così contaminato è un'altra.\n\nFarò in modo che questo globo venga studiato a dovere dall'Earthen Ring. Forse riusciremo a mettere fine a questa corruzione degli elementi. Ti prego, accetta questo come giusto compenso per aver portato il globo all'attenzione dell'Earthen Ring.", 0x6802f11f, 0xaff53a21, 0x31e82842, 0x21696c42, 0xc008b860, "....." },
  [825] = { "Dal relitto....", "Gar'Thok di ⟦Razor Hill=Tranciacolle⟧ vuole che tu recuperi 3 ⟦Gnomish Tools=Attrezzi Gnomeschi⟧ dal relitto al largo della costa.", "Uno dei miei esploratori più attenti mi riferisce che il relitto della flotta di Proudmoore si trova ancora al largo della costa di Durotar, poco a est del ⟦Tiragarde Keep=Forte di Tiragarde⟧.\n\nNon è un segreto che gli umani, alleati con quelle piccole e ripugnanti creature chiamate gnomi, abbiano una conoscenza avanzata della meccanica. Dobbiamo comprendere a fondo tutti i nostri potenziali nemici. E anche il nostro popolo trarrà beneficio da queste nuove conoscenze.\n\nNuota tra i relitti, {name}, e recuperami gli attrezzi dell'⟦Alliance=Alleanza⟧.", "Una volta capito come gli umani fanno funzionare i loro strani macchinari, avremo maggiori possibilità di sconfiggerli nelle battaglie future.\n\nCon le nuove conoscenze acquisite, l'⟦Horde=Orda⟧ non potrà che diventare più forte.", "La tua missione di recupero è stata un successo, {class}. Mi assicurerò che questi attrezzi arrivino a Orgrimmar con la prossima carovana.\n\nBen fatto.", 0x181930de, 0x5b5b3e7f, 0xfad72992, 0x11689c03, 0xdacdadb7, "....." },
  [826] = { nil, "Sconfiggi Zalazane.\n\nUccidi 8 Voodoo Troll e 8 Hexed Troll.\n\nPorta la ⟦Zalazane's Head=Testa di Zalazane⟧ a Gadrin.", "Lo stregone Zalazane dimora sulle ⟦Echo Isles=Isole dell'Eco⟧, a est. Sono le isole che un tempo chiamavamo casa.\n\nDa lì manda i suoi troll sulla terraferma, a maledire la nostra gente e a trascinarne altri sotto il suo dominio.\n\nVa fermato.\n\nSconfiggi Zalazane e i suoi servitori, troll ⟦Darkspear=Lanciascura⟧ ormai perduti per noi. Portami la sua testa e saprò che il suo regno di malvagità è finito.", "Zalazane è stato sconfitto, {name}?", "Ora che Zalazane non c'è più, la nostra tribù può di nuovo dormire in pace.\n\nGrazie, {name}. La tribù dei ⟦Darkspear=Lanciascura⟧ ti deve molto. Se soffri di qualche malanno, va' dal mio assistente Bom'bay, alle mie spalle. Il suo vudù è potente...", 0x489251bd, 0xe01a8eac, 0x24710aa2, 0xb7a847c3, 0xd30e272c, "e...." },
  [827] = { "⟦Skull Rock=Roccia del Teschio⟧", "Raccogli i Searing Collar dai cultisti della ⟦Skull Rock=Roccia del Teschio⟧.\n\nPortali a Margoz, al suo accampamento.", "{name}. Le ⟦Burning Blade=Lame Ardenti⟧ hanno infestato la grotta a est di Orgrimmar nota come ⟦Skull Rock=Roccia del Teschio⟧. Lì dentro celebrano rituali immondi e si bruciano la carne con i Searing Collar.\n\nCredo che, indossando questi collari, i cultisti si sintonizzino con il potere demoniaco. Ma per averne conferma devo studiarne una raccolta.\n\nVa' alla ⟦Skull Rock=Roccia del Teschio⟧ e raccogli i Searing Collar dai cultisti che trovi lì. Portameli e ne svelerò i segreti.", "Sei già entrat<o/a> nella ⟦Skull Rock=Roccia del Teschio⟧, {name}? Hai i Searing Collar?", "Bene. In questi collari si nasconde il segreto delle ⟦Burning Blade=Lame Ardenti⟧. E io lo svelerò...", 0x729f9f48, 0x54e6be8b, 0xff788f72, 0x6798c34d, 0x0a7d203c, "....." },
  [828] = { nil, "Parla con Margoz.", "Uno dei nostri sciamani, Margoz, sa di più sulla corruzione delle ⟦Burning Blade=Lame Ardenti⟧. Parla di una grotta tra le montagne chiamata ⟦Skull Rock=Roccia del Teschio⟧, proprio alle porte di Orgrimmar!, che dà rifugio a una grossa banda di cultisti delle ⟦Burning Blade=Lame Ardenti⟧.\n\nPrima di andare alla ⟦Skull Rock=Roccia del Teschio⟧, parla con Margoz. È saggio e i suoi consigli sono preziosi.\n\nÈ accampato a nord-est, tra la costa e la ⟦Drygulch Ravine=Gola di Fossosecco⟧.\n\nSegui i suoi consigli ma, qualunque cosa dica Margoz, {name}, voglio comunque che tu schiacci quei cultisti!", nil, "Benvenut<o/a>, {name}. Mi è giunta notizia del tuo arrivo e delle tue imprese in Durotar.\n\nSei <un/una> {class} di abilità e fama crescenti.\n\nResta sulla via pura e il tuo futuro sarà davvero grande.", 0x5cde94d6, 0x93909fb0, 0xb5d1aee2, nil, 0x6bc52b40, "e..m." },
  [829] = { nil, "Porta un ⟦Example Collar=Collare Campione⟧ a Neeru Fireblade, a Orgrimmar.", "I Searing Collar che mi hai portato sono strumenti demoniaci potenti. Scoprirne l'origine, temo, va oltre le mie capacità di sciamano. Ci servirà uno stregone per studiarli.\n\nPorta un Searing Collar a Neeru Fireblade. Benché sia uno stregone abile, sostiene di usare i suoi poteri per contrastare i demoni e afferma che le sue ricerche sull'occulto sono innocue. Vero o falso che sia, potremmo aver bisogno del suo aiuto contro il culto demoniaco in Durotar.\n\nTroverai Neeru a Orgrimmar, nel Cleft of Shadow.", "I miei più umili saluti, {class}. Come posso aiutare <mio/mia> <fratello/sorella> {race}, oggi?", "Ah, e dove l'hai preso questo? È stato il buon Margoz di ⟦Razor Hill=Tranciacolle⟧ a mandarti da me, vero?\n\nBene, lasciami dare un'occhiata più da vicino...", 0x868b3608, 0x613e9f65, 0x05a32b33, 0x4968d4eb, 0x71421289, "e....", nil, nil, nil, 0xec476d59, nil },
  [830] = { "Gli ordini dell'ammiraglio", "Porta gli ⟦Admiral Proudmoore's Orders=Ordini dell'Ammiraglio Marefiero⟧ a Gar'Thok a ⟦Razor Hill=Tranciacolle⟧.", "Apri la busta vecchia e consunta e scopri un documento dall'aria ufficiale. Riconosci il sigillo dell'ammiraglio Proudmoore.\n\nSembra importante. Forse Gar'Thok, il comandante di ⟦Razor Hill=Tranciacolle⟧, vorrebbe avere queste informazioni.", "Hai un'aria preoccupata, {class}. Che cos'hai lì?", "Non promette niente di buono. Hai fatto bene a portare queste informazioni alla mia attenzione.", 0x4748be45, 0xfca39656, 0x9476be3c, 0x74d48d62, 0x44e2b5b8, "....." },
  [831] = { "Gli ordini dell'ammiraglio", "Consegna gli ⟦Admiral Proudmoore's Orders=Ordini dell'Ammiraglio Marefiero⟧ a Nazgrel, nella sala di Thrall a Orgrimmar.", "Degli umani non ci si può fidare. Abbiamo combattuto al loro fianco a malincuore, sapendo che un giorno ci avrebbero traditi.\n\nLa morte dell'ammiraglio Proudmoore non è bastata a fermare la sua eredità di inganni. Quella feccia umana aveva preparato bene i suoi piani prima ancora di incontrare la sua fine.\n\nA quanto pare il suo dominio non morirà nemmeno con Benedict. Chissà quanto passerà prima che le prossime ondate di uomini di Proudmoore sbarchino sulle nostre coste.\n\nDobbiamo portare subito questi ordini a Nazgrel, a Orgrimmar! Lo trovi nella sala di Thrall.", "Non vedi che sono occupato? Spero che sia una cosa urgente....", "Innumerevoli volte ho esortato il Capoguerra a non fidarsi degli umani, ma qui non è in gioco l'orgoglio personale.\n\nHai servito l'⟦Horde=Orda⟧ con onore, giovane {class}.\n\nOra scusami, devo consigliare subito Thrall su queste questioni....", 0x4748be45, 0xc9e47975, 0xe1d3b368, 0xe626e031, 0xb4d9dc76, "....." },
  [832] = { "Ombre ardenti", "Porta quest'occhio a Neeru Fireblade.", "<Delle parole emanano dal pendente e ti entrano nella mente.>\n\nGazz'uz?\n\nGazz'uz... rapporto!\n\nCorre voce che tu sia stato scoperto alla ⟦Skull Rock=Roccia del Teschio⟧. Devi prepararti a un attacco!\n\nGazz'uz, ti ordino di parlare! Parla, o farò in modo che Neeru Fireblade sappia della tua presenza, e piomberà su di te con rapida brutalità.\n\nNon mettere alla prova la tua abilità contro Neeru...\n\n... Gazz'uz, ci sei...?", "Hai qualcosa di importante da riferire. Lo percepisco dietro i tuoi occhi.", "<Esamina l'⟦Eye of Burning Shadow=Occhio dell'Ombra Ardente⟧.>\n\nInteressante. La voce che hai sentito ha fatto il mio nome? Sono noto per dare la caccia ai nemici del nostro Capoguerra, ma... è strano che abbiano indicato proprio me. Ancora più strano che i cultisti delle ⟦Burning Blade=Lame Ardenti⟧ da cui hai recuperato questo pendente abbiano un nome così simile al mio.\n\nDevo studiare questo pendente. Devo studiarlo, e devo riflettere sul significato del suo messaggio.\n\nGrazie per avermelo segnalato, {name}. Hai reso un grande servizio al tuo popolo.", 0xa1f132b7, 0x04253717, 0x935523ac, 0x8ddce38f, 0xb049c8c8, "....." },
  [833] = { "Una sepoltura sacra", "Uccidi 8 Bristleback Interloper ai ⟦Red Rocks=Massi Rossi⟧ per lo storico Raintotem.", "Solo i tauren più valorosi riposano ai ⟦Red Rocks=Massi Rossi⟧, il nostro sacro luogo di sepoltura. È un onore concesso ai grandi guerrieri che aiutarono a fondare e difendere ⟦Thunder Bluff=Picco del Tuono⟧ e a chi ha dato la vita per il bene delle proprie tribù e dei propri capi.\n\nMa pare che una minaccia immonda sia giunta sulla nostra terra sacra. Una banda di Bristleback Interloper sta devastando le tombe, e io sono troppo vecchio e stanco per scacciarli.\n\nVanno cacciati con la forza, {name}.", "I Bristleback Interloper vanno scacciati dal nostro sacro luogo di sepoltura, {name}.", "Ben fatto. Hai mandato a quei luridi Mantotergo un messaggio chiaro. Ci penseranno due volte prima di provare di nuovo a profanare questo luogo sacro.", 0xfa1ec33f, 0x980ab5b3, 0xaa8194d7, 0xf565f7ef, 0x00b23859, "....." },
  [834] = { "Venti nel deserto", "Recupera 5 Sack of Supplies e riportali a Rezlak, vicino a Orgrimmar.", "Sono Rezlak, uno dei ragazzi di Gazlowe. Il capo mi ha mandato ad aiutare gli orchi qui a Durotar. Le cose andavano bene, a parte le carovane. Non c'è verso di tenerle al sicuro! Mi complica un po' il lavoro, capisci?\n\nL'ultimo carico (avevano promesso che sarebbe arrivato!) se lo sono preso le arpie Dustwind di... dov'era... il ⟦Razorwind Canyon=Canyon Brezza Aguzza⟧?\n\nMi servono quelle provviste, o non combinerò mai niente! Segui il grande canyon verso sud: troverai la gola scavata nelle pareti, sia a ovest che a est.", "Sono bravissimo nel mio lavoro, non fraintendermi, ma questo è ridicolo! Che dovrei fare, castelli di sabbia?", "Ehi, ma guarda un po'! Ci hai riportato le provviste. Fantastico. Potrò rimettermi al lavoro appena trovo qualcuno che mi trasporti questi sacchi.", 0x59e6f1e4, 0xd2235b13, 0xa26d70ed, 0x46f47b9e, 0x61a2af2d, "....." },
  [835] = { "Proteggere le rotte", "Uccidi 12 Dustwind Savage e 8 Dustwind Storm Witch per Rezlak, vicino alla ⟦Drygulch Ravine=Gola di Fossosecco⟧.", "Una volta Gazlowe mi ha detto: «Rezlak, c'è una cosa che devi sapere nella vita: se vuoi una cosa fatta bene, fattela da solo».\n\nNon posso permettermi di perdere tutte le nostre carovane, quindi prenderò in mano la situazione. La ⟦Drygulch Ravine=Gola di Fossosecco⟧ si trova nella parte orientale del ⟦Razorwind Canyon=Canyon Brezza Aguzza⟧. Se uccidiamo tutte le arpie che ci sono, le rotte saranno sicure.\n\nOvviamente c'è un'altra cosa che Gazlowe mi ha insegnato: «Con il giusto prezzo si ottiene tutto». Allora, mi dai una mano, {name}?", "Non lo diresti da uno come il mio capo Gazlowe, ma lui sembrava sempre sapere come vanno le cose. «Non aver paura di fare quel grande passo», diceva.\n\nLe arpie non smetteranno di darci fastidio e le carovane non smetteranno di essere attaccate, a meno che non facciamo qualcosa, eh?", "Credo di poter respirare tranquillo, ora che so che le arpie non daranno più fastidio alle nostre carovane di rifornimenti. E proprio al momento giusto, anche. Ho sentito che con il prossimo carico mi mandano qualche giocattolino divertente!\n\nSei <bravo/brava> in quello che fai, {name}: dovresti cercare il mio capo a ⟦Ratchet=Porto Paranco⟧. Scommetto che avrebbe del lavoro per te.\n\nAh, e non preoccuparti, non mi sono dimenticato di pagarti per il servizio che mi hai reso.", 0xe6fd4a95, 0x888daed9, 0xd1d3c2b0, 0x27250f04, 0x8c848b09, "....." },
  [837] = { "Invasione", "Uccidi 4 Razormane Quilboar, 4 Razormane Scout, 4 Razormane Dustrunner e 4 Razormane Battleguard per Gar'Thok a ⟦Razor Hill=Tranciacolle⟧.", "Quando arrivammo, i verrospini ⟦Razormane=Chiomaguzza⟧ possedevano gran parte di queste terre e si rivelarono una spina nel fianco. Con i nostri sforzi abbiamo scacciato la maggior parte di loro, ma in alcune zone restano ben fortificati.\n\nOra però basta. Per la nostra sicurezza, non possiamo lasciare ai ⟦Razormane=Chiomaguzza⟧ alcun appiglio nelle nostre terre. I loro accampamenti si trovano a ovest di qui. Cerca i rovi e li troverai. Oggi li cacciamo da Durotar, domani, forse, da tutta Kalimdor.", "Pur avendo un po' di intelligenza e di organizzazione, continua a stupirmi che i verrospini siano riusciti a conquistare e a tenere tanto territorio a Kalimdor. Forse sono un nemico più astuto di quanto io creda...", "Farò sapere che i verrospini sono stati scacciati dalle loro tane e che le loro strutture possono essere date alle fiamme. Cacciare i ⟦Razormane=Chiomaguzza⟧ da Durotar ci avvicina a rendere del tutto sicuri i confini della nostra nuova patria.", 0x53e8500c, 0x68b41137, 0x0b4e1318, 0x86c351c6, 0xca60d2cb, "....." },
  [840] = { "Recluta dell'⟦Horde=Orda⟧", "Segui la strada occidentale da ⟦Razor Hill=Tranciacolle⟧ fino alle ⟦Barrens=Savane⟧, attraversando un ponte.\n\nFermati all'avamposto degli orchi oltre il ponte.\n\nConsegna la tua lettera di reclutamento a Kargal Battlescar, all'avamposto delle ⟦Barrens=Savane⟧.", "Mmh, sembri piuttosto forte.\n\nSenti, il mio buon amico Kargal ha bisogno di nuove reclute per il servizio nelle ⟦Barrens=Savane⟧. So che vuoi fare ciò che è giusto per l'⟦Horde=Orda⟧. Ebbene, questa è la tua occasione.\n\nPorta questa lettera di reclutamento a Kargal e vedi se te la firma.", "Che vuoi, cucciolo? Se non sei qui per arruolarti, non ho tempo per te.", "Oh, quindi ti manda Takrin? È un esploratore eccellente, non so cosa farei senza di lui.\n\nFirmerò la tua lettera di reclutamento, ma quello che ci serve davvero è qualcuno al ⟦Crossroads=Crocevia⟧.", 0x78c37e48, 0xd392b70b, 0xd4cb8337, 0xe87fe0e8, 0x6ab997b5, "....." },
  [842] = { "Arruolamento al ⟦Crossroads=Crocevia⟧", "Segui la strada occidentale dal Far Watch Outpost di Kargal.\n\nAll'incrocio a T, svolta a sinistra e segui la strada verso sud.\n\nTrova Sergra Darkthorn all'incrocio delle strade, all'interno del ⟦Crossroads=Crocevia⟧.", "Porta questa lettera di reclutamento firmata al ⟦Crossroads=Crocevia⟧.\n\nLì comanda Sergra Darkthorn, che le venga un accidente. È una sciamana odiosa che ti farà girare la testa a forza di chiacchiere prima di lasciarti fare qualcosa di utile. Thrall è convinto che abbia qualcosa di speciale, ma io non ne sono così sicuro.\n\nDovrai deciderlo da te, cucciolo...", "Bene bene bene, che abbiamo qui? Kargal mi ha ritenuta degna di un'altra recluta?", "D'accordo, {name}. Vuoi guadagnarti da vivere con l'⟦Horde=Orda⟧? Beh, qui c'è parecchio da fare, quindi ascolta bene e fai quello che ti si dice.\n\nThrall in persona ha dichiarato che le femmine dell'⟦Horde=Orda⟧ sono alla pari dei maschi, e chi si fa avanti qui nelle ⟦Barrens=Savane⟧ lo sa bene. Mancami di rispetto anche solo un poco, e conoscerai il vero dolore.", 0x0bacb2c9, 0x8da991ec, 0xc91cd247, 0x843fd0d3, 0xd77c8ad8, ".....", nil, nil, nil, nil, 0xbdf06a0d },
  [843] = { "La riconquista di Gann", "Gann Stonespire vuole che tu uccida 15 Bael'dun Excavator e 5 Bael'dun Foreman.\n\nPorta il ⟦Khazgorm's Journal=Diario di Khazgorm⟧ a Gann Stonespire.", "Percorro queste strade in solitudine.\n\nI nani di Bael Modan non mostrano alcun rispetto per la mia terra. Esplosioni orrende scavano buchi profondi nel terreno mentre macchine rumorose squarciano le colline. Le terre che un tempo davano casa e sostentamento alla mia tribù ora brulicano di nani distruttori.\n\nI tentativi di arrivare a una soluzione diplomatica sono falliti. È giunto il momento di agire con decisione.\n\nScaccia con la forza i nani dallo scavo di Bael Modan e portami il diario del loro capo, il prospettore Khazgorm.", "Molti tauren innocenti hanno perso la vita o sono stati cacciati dalla terra dei loro antenati quando sono arrivati i nani di Bael Modan. La mia terra va riconquistata!", "Khazgorm ha avuto la fine che meritava. Non provo alcun rimorso per quello sciocco. Era un infedele su queste terre.\n\nChe la sua morte serva da monito a tutti coloro che minacciano di sconvolgere il nostro modo di vivere.\n\nOra lascia che mi prenda un momento per studiare il diario del nano...", 0x5bec56d0, 0x794de9e0, 0x0fe7d066, 0xb020102d, 0x98de05b4, "....." },
  [844] = { "La minaccia dei Plainstrider", "Raccogli 7 Plainstrider Beak e portali a Sergra Darkthorn, al ⟦Crossroads=Crocevia⟧.", "La tua prima preda sarà facile.\n\nI Plainstrider a est stanno tormentando le nostre provviste di cibo e sono diventati una seccatura.\n\nAbbatti i Plainstrider e torna da me con i loro becchi.", "Hai raccolto i becchi dei Plainstrider?", "Molto bene, {name}. Senza i Plainstrider sarà più facile mantenere intatte le nostre linee di rifornimento. E spero che tu abbia imparato qualche trucco là fuori nelle ⟦Barrens=Savane⟧, perché la tua prossima preda ha un po' più di fuoco nel sangue dei Plainstrider...", 0x683b72cb, 0xd1edb7af, 0x64402915, 0x2b051ab1, 0xa5c89360, "....." },
  [845] = { "Gli zevra", "Uccidi gli Zhevra Runner per raccogliere 4 ⟦Zhevra Hooves=Zoccolo di Zevra⟧ per Sergra Darkthorn al ⟦Crossroads=Crocevia⟧.", "Gli zevra non saranno le bestie più feroci delle ⟦Barrens=Savane⟧, ma sono un tantino più coriacei degli zampalunga delle pianure. Non preoccuparti: a tempo debito ti manderemo contro prede più grosse, ma per ora devi ancora farti le ossa.\n\nCaccia gli zevra a nord e a sud e raccogli i loro zoccoli. Portameli e forse la prossima volta ti manderemo contro qualcosa di più duro.", "Quanti zevra hai ucciso?", "Non male, {name}. Quegli zevra hanno un sacco di forza nelle zampe. Un loro calcio ben assestato può mettere a sedere persino un tauren!\n\nPare che un po' di forza ce l'abbia anche tu. Sei pront<o/a> per una vera sfida?", 0x248a686f, 0x39699e5e, 0x936818e8, 0xbd0060bc, 0xa3a56f4f, "....." },
  [846] = { "La vendetta di Gann", "Gann Stonespire vuole che tu gli porti 6 fiale di Nitroglycerin, 6 fasci di ⟦Wood Pulp=Pasta di Legno⟧ e 6 campioni di ⟦Sodium Nitrate=Nitrato di Sodio⟧.", "È chiaro che il prospettore contava sugli esplosivi e su quei rumorosi veicoli per squarciare il terreno. Possiamo aspettarci che presto un nuovo caposquadra prenda il suo posto.\n\nVoglio ripagare i nani con la loro stessa moneta. Secondo questi piani, se uniamo la nitroglicerina alla pasta di legno e al nitrato di sodio possiamo creare una carica esplosiva. Si sa che i fucilieri, i soldati e gli ufficiali del forte hanno queste scorte.\n\nRaccogli questi materiali e portameli. Preparerò una carica che i nani non dimenticheranno!", "Vedo che sei tornat<o/a>, {name}.\n\nLa morte di Khazgorm potrà ritardare un po' gli scavi nelle terre dei miei antenati, ma non metterà affatto fine alla distruzione.\n\nIl forte di Bael Modan è una minaccia militare sempre più grave. Costruito per difendere gli scavi, ora è pronto anche ad attaccare.\n\nSe hai gli ingredienti che ti ho chiesto, posso preparare una carica che farà ripensare quei nani avventati a ciò che stanno facendo qui nelle ⟦Barrens=Savane⟧.", "Vedo che sei molto operos<o/a>, {class}.\n\nSenza dubbio presto avremo una sorpresa degna di quei nani.", 0x66412c95, 0x0d3d68a3, 0x01ba4a8d, 0x1b49cb26, 0x588a2555, "....." },
  [848] = { "⟦Fungal Spores=Spore Fungine⟧", "Porta 4 ⟦Fungal Spores=Spore Fungine⟧ allo speziale Helbrim, al ⟦Crossroads=Crocevia⟧.", "Le oasi delle ⟦Barrens=Savane⟧ nascondono un mistero. Dalle loro acque scorre energia vitale, che rinvigorisce le piante e le bestie che le bevono.\n\nLe rinvigorisce, e le altera.\n\nVicino a queste oasi cresce un fungo. Le sue spore hanno proprietà che noi, gli speziali di Lordaeron, troviamo utili.\n\nPortami queste spore e avrai la nostra gratitudine.", "Hai le spore, {name}? Devo mandare un preparato al mio collega a ⟦Thunder Bluff=Picco del Tuono⟧, e servono le spore...", "Ah, sì. Sono buoni esemplari. Potenti.\n\nIo sono un Reietto, e noi onoriamo i nostri contratti. Ecco la tua ricompensa, {name}.", 0xc3123519, 0x2e68d5c7, 0x797cda26, 0xd31a5bcf, 0xd9b9e642, "....." },
  [849] = { "La vendetta di Gann", "Distruggi la macchina volante di Bael Modan e torna da Gann Stonespire.", "Seguendo i piani di Khazgorm non dovrebbe essere un problema preparare una carica esplosiva.\n\nAh, ecco fatto.\n\nOra, {name}, ti affiderò un compito speciale. Prendi questo candelotto esplosivo e usalo per far saltare in aria la macchina volante di Bael Modan.\n\nLa macchina volante non è solo una parte fondamentale delle strutture del sito, ma serve anche come arma da guerra. Soprattutto, è un simbolo di potere e un insulto alla memoria della mia tribù.\n\nRendimi fiero portando a termine questa impresa eroica e sarai ricompensat<o/a>.", "Quando la macchina volante dei nani sarà distrutta, assaporerò la dolce soddisfazione della vendetta.", "Hai fatto bene, {name}! Che tu possa essere venerat<o/a> a ⟦Thunder Bluff=Picco del Tuono⟧ come difensore delle sacre terre dei tauren e campione della tribù perduta.", 0x66412c95, 0xbaa793c0, 0xa58e30a0, 0x28d6b809, 0x1f40bd4d, "....." },
  [850] = { "I capi Kolkar", "Porta la testa di Barak a Regthar Deathgate, a ovest del ⟦Crossroads=Crocevia⟧.", "I centauri tormentano i Tauren da anni. E di recente i centauri Kolkar delle ⟦Barrens=Savane⟧ sono diventati una vera minaccia. Di solito in queste terre erano disorganizzati, ma tra loro sono sorti nuovi capi. Che li radunano.\n\nPer difendere i nostri possedimenti qui, questi capi centauri vanno distrutti.\n\nPortami la testa di Barak Kodobane. È accampato vicino alle Forgotten Pools, a nord.\n\nSconfiggilo, poi torna da me.", "Salve, {name}. Hai la testa di Barak per me?", "Ben fatto, {name}. I centauri sono creature rozze e brutali, ma alcuni hanno l'ingegno e la visione per comandare. E sono i più pericolosi.\n\nBarak era uno di quei centauri. È un bene che sia morto.", 0x998b165b, 0x6a15fed3, 0x01ef16f2, 0x12beec59, 0xd9616ab0, "....." },
  [851] = { "Verog il Derviscio", "Porta la ⟦Verog's Head=Testa di Verog⟧ a Regthar Deathgate, a ovest del ⟦Crossroads=Crocevia⟧.", "Il centauro Verog il Derviscio vaga per le ⟦Barrens=Savane⟧ e sarà difficile da trovare. Ma la sua base è la tenda di comando dei centauri all'⟦Stagnant Oasis=Oasi Stagnante⟧, a sud-est. Forse è possibile attirarlo da te.\n\nVa' all'⟦Stagnant Oasis=Oasi Stagnante⟧, a sud-est, e attacca i centauri vicino alla tenda di comando. Sarà pericoloso, ma se ne uccidi abbastanza dovrebbero dare l'allarme. E Verog arriverà.\n\nPortami la sua testa e la metterò accanto a quella di Barak Kodobane.", "Hai trovato Verog, {name}?", "Molto bene. Devi aver proprio scatenato quei centauri: le nostre guardie hanno notato movimenti giù vicino all'⟦Stagnant Oasis=Oasi Stagnante⟧, probabilmente eri tu.\n\nDovresti essere fier<o/a> della tua impresa, {name}. C'è molto coraggio in te.", 0x93dab5dc, 0xa038b95d, 0x215b556f, 0x4d4ec67a, 0x8f442ada, "....." },
  [852] = { nil, "Porta la ⟦Hezrul's Head=Testa di Hezrul⟧ a Regthar Deathgate, a ovest del ⟦Crossroads=Crocevia⟧.", "Hezrul Bloodmark è il capo dei centauri Kolkar nelle ⟦Barrens=Savane⟧. È feroce, brutale e astuto. Sconfiggerlo getterebbe i Kolkar nel caos e li dividerebbe, riducendo di molto la minaccia che rappresentano per noi.\n\nQuindi uccidilo. Come per Barak e Verog, portami la ⟦Hezrul's Head=Testa di Hezrul⟧.\n\nGuida la sua gente dall'⟦Lushwater Oasis=Oasi Acquefertili⟧, a sud.", "Hezrul è stato sconfitto, {name}?", "Ti faccio i miei complimenti, {name}. Questi centauri sono indisciplinati e non sanno incanalare la loro rabbia come gli orchi, ma sono comunque feroci. Sconfiggendoli hai dimostrato il tuo valore.", 0xd41b7348, 0x1861eeb5, 0x752c7855, 0x0df82dda, 0x60d7374e, "e...." },
  [853] = { "La speziale Zamah", "Porta le ⟦Rendered Spores=Spore Trasformate⟧ alla speziale Zamah, a ⟦Thunder Bluff=Picco del Tuono⟧, prima che scada il tempo.", "Ho trasformato le spore che mi hai dato in un'emulsione. Ora devo mandarla alla mia collega, la speziale Zamah. Se gliela porterai, potrà offrirti qualcosa dalle nostre scorte di prodotti alchemici.\n\nSi trova nelle Pools of Vision, una grotta sotto gli sciamani di ⟦Thunder Bluff=Picco del Tuono⟧. Il sentiero per la grotta è ben nascosto, ma puoi trovarlo sull'⟦Spirit Rise=Altura degli Spiriti⟧.\n\nSbrigati. Questa emulsione manterrà la sua efficacia solo per poco tempo, e prima di allora va sigillata di nuovo e lavorata.", "Hai qualcosa da parte dello speziale Helbrim?", "Ah, le spore delle ⟦Barrens=Savane⟧ che Helbrim stava raccogliendo. Ha chiesto il tuo aiuto per consegnarle? Bene.\n\nE l'emulsione è ancora efficace, quindi non devi aver perso tempo nella consegna. Ben fatto, {class}.", 0xe9931e98, 0xadbbfb8e, 0xb9f2e008, 0xfa8cd725, 0xba92a449, "....." },
  [854] = { "Viaggio al ⟦Crossroads=Crocevia⟧", "Parla con Thork al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", "Avevo previsto il tuo arrivo, giovane {class}. Anche se forse non sei più così giovane.\n\nCredo sia giunto il momento che tu ti addentri in questa terra. Sento che sei destinat<o/a> a grandi cose.\n\nÈ il ⟦Crossroads=Crocevia⟧ che devi cercare, perché le nostre vite si sono intrecciate con quelle degli orchi, e loro hanno bisogno di aiuto. Prosegui lungo questa strada verso est e poi seguila a nord fino al ⟦Crossroads=Crocevia⟧. Trova Thork tra le sue mura: ha la benedizione della Madre Terra.", nil, "È bello vedere che altri nostri alleati {race} sono venuti ad aiutarci da luoghi lontani come ⟦Thunder Bluff=Picco del Tuono⟧. Ancora una volta, ti do il benvenuto.", 0xeac1fba3, 0xb2e3771c, 0xeb69f905, nil, 0xb15720f1, "...m." },
  [855] = { "⟦Centaur Bracers=Bracciali dei Centauri⟧", "Porta 15 ⟦Centaur Bracers=Bracciali dei Centauri⟧ a Regthar Deathgate, a ovest del ⟦Crossroads=Crocevia⟧.", "I Kolkar sono una minaccia per i territori che l'⟦Horde=Orda⟧ rivendica nelle ⟦Barrens=Savane⟧: dobbiamo ridurre il numero delle loro truppe. Per questo ho un incarico di taglia per te.\n\nNei territori dei Kolkar, uccidi i loro guerrieri e raccogli i Bracciali dei Centauri. Torna quando avrai un bel mucchio di bracciali e l'⟦Horde=Orda⟧ ti ricompenserà bene.", "Come va la caccia, {name}?", "Ottimo lavoro. Di sicuro hai seminato il terrore tra i centauri sopravvissuti, {name}. Se hanno un po' di buon senso, ora si calmeranno e smetteranno di avanzare.\n\nMa non credo che lo faranno, ed è un peccato.\n\nUn peccato... per loro.", 0x10ccc226, 0x914779ba, 0x96c4ff46, 0xcc975615, 0x9b2672c0, "....." },
  [857] = { "La ⟦Tear of the Moons=Lacrima delle Lune⟧", "Feegly l'Esiliato vuole che tu recuperi per lui la ⟦Tear of the Moons=Lacrima delle Lune⟧.", "Il potere era mio! Proprio nelle mie mani! E lo rivoglio! Lo rivoglio, dico!\n\nQuegli sporchi scavatori l'hanno portata alla luce... così bella, era. L'hanno chiamata ⟦Tear of the Moons=Lacrima delle Lune⟧, ed è stata la prima grande scoperta che abbiamo fatto a Bael Modan.\n\nDoveva essere mia! Mia, dico!\n\nIl generale Twinbraid è diventato geloso del potere che mi dava. L'ha chiusa a chiave nella fortezza. L'ha detta maledetta, sì! Che sciocco!\n\nAltri la volevano e dovevano essere fermati! Quel bastardo di Twinbraid mi ha cacciato.\n\nOra la rivoglio. La rivoglio, dico!", "Dov'è la ⟦Tear of the Moons=Lacrima delle Lune⟧? Mi serve subito! Mi serve, dico!", "Finalmente il potere è di nuovo mio! Mio, dico!", 0xd61e6da0, 0xece78ab3, 0x5ea4911b, 0x03264142, 0x659e8bb7, "....." },
  [858] = { "Accensione", "Prendi la ⟦Ignition Key=Chiave d'Accensione⟧ e portala a Wizzlecrank.", "Non è che ti manda Sputtervalve? Sono nei guai. Sono saltato dentro senza rendermi conto che serve una chiave per sbloccare la colonna di movimento dello shredder. Uno degli altri operatori mi ha chiesto se andava tutto bene e sono andato nel panico! Invece di dirgli che mi mancava la chiave, gli ho detto che c'era una specie di guasto meccanico.\n\nDobbiamo filarcela di qui alla svelta! Sali nella sala di controllo in cima alla torre di trivellazione: il supervisore dovrebbe avere una chiave per questo shredder.\n\nDammi una mano!", "Presto, dobbiamo andarcene prima che qualcuno si insospettisca!", "Sì, sembra proprio la chiave giusta. Fammi solo controllare di aver capito come funziona questo affare...\n\nUhm... controllo della rotazione... Questo regola velocità e stabilità... controllo fine dei movimenti del braccio. Ma guarda qui! Non posso credere che la ⟦Venture Company=S.P.R. & Co.⟧ sia riuscita a progettare qualcosa di tanto migliore del nostro. Devo riportarlo a ⟦Ratchet=Porto Paranco⟧!", 0x18e364df, 0xfd656f2e, 0xc1e7e3e9, 0xb25128ee, 0xa8725124, "....." },
  [860] = { nil, "Parla con Sergra Darkthorn al ⟦Crossroads=Crocevia⟧.", "Se vuoi percorrere la via del cacciatore, il tuo viaggio ti porta nelle ⟦Barrens=Savane⟧. Le sue bestie sono ostinate e feroci. Cacciando là imparerai molto, e il tuo spirito crescerà.\n\nParla con Sergra Darkthorn. Sarà la tua prima guida nelle ⟦Barrens=Savane⟧.\n\nSergra si trova al ⟦Crossroads=Crocevia⟧. Per raggiungerla, viaggia verso est dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ fino alle ⟦Barrens=Savane⟧, poi va' a nord dove la strada si biforca. E fa' attenzione durante il viaggio: le ⟦Barrens=Savane⟧ sono piene di pericoli per chi è impreparato e incauto.", nil, "Vuoi cacciare nelle ⟦Barrens=Savane⟧?\n\nI tuoi occhi sono ansiosi, e giovani. Non sono ancora socchiusi dal seguire le prede attraverso le aride pianure di questa terra.\n\nMa non temere. Rafforzeremo il tuo corpo e la tua mente. E ti insegneremo che cacciare non significa solo trovare e uccidere la preda.\n\nPreparati. Il tuo viaggio comincia. Ora.", 0x3c4cd152, 0x9d903e4b, 0x2ca0b448, nil, 0xd7d00470, "e..m." },
  [861] = { "La via del cacciatore", "Porta 4 Artigli di Predatore delle Pianure a Melor Stonehoof, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Hai voglia di esplorare, lo vedo. Anch'io, un tempo, avevo il desiderio di vagare...\n\nVagare, e cacciare. Perché la caccia è il più grande onore di un tauren.\n\nSe desideri davvero seguire le vie del cacciatore, Melor Stonehoof può mostrarti il cammino. Si trova a ⟦Thunder Bluff=Picco del Tuono⟧, sull'Altura dei Cacciatori.\n\nE per dimostrargli la tua abilità e la tua determinazione, portagli gli artigli dei predatori delle pianure di Mulgore. Sono robusti e astuti: prede adatte a <un/una> giovane {class} sulla via del cacciatore.", "Salute. C'è qualcosa in te che mi dice molto. Abbiamo affari da sbrigare, tu e io?", "Skorn Whitecloud è un tauren saggio. Caccia da anni e anni, e anche se il suo corpo è vecchio, il suo spirito arde con forza. È un onore averlo con noi.\n\nSe Skorn ti ha mandato da me, allora anche tu devi avere lo spirito del cacciatore. E aver raccolto questi artigli dimostra che la tua abilità sta crescendo.\n\nForse sei pronto a percorrere il cammino.", 0xccff1f61, 0xec804e9e, 0x79313340, 0x0d1a0780, 0xbc9792ef, "....." },
  [862] = { "⟦Dig Rat Stew=Stufato di Ratto di Fossa⟧", "Porta 8 Ratto di Fossa a Grub, a est del ⟦Crossroads=Crocevia⟧.", "<Un/Una> {class} come te deve avere una gran fame, qui nelle ⟦The Barrens=Savane⟧. Io muoio di fame tutto il giorno.\n\nFacciamo così: ti preparo un bello stufato. Mi servono solo un po' di ratti di fossa.\n\nPare che quei luridi nani di Bael Modan siano invasi dal piatto preferito da tutti. Allora scendi a sud fino a Bael Modan e riportami un po' di ratti di fossa.\n\nNon hai vera esperienza d'avventura finché non hai passato un po' di tempo ad ammazzare ratti! Ah!", "Hai già fatto fuori abbastanza ratti di fossa, {name}?", "Di solito non mi piace mangiare questi roditori quando sono così... così... maturi. Mi piace lasciarli marcire per qualche settimana, per tirarne fuori tutto il sapore. Ma hai l'aria così affamata.\n\nLascia che ti prepari un po' di ⟦Dig Rat Stew=Stufato di Ratto di Fossa⟧. Ah, ecco fatto.\n\nTieni!", 0xbca7d0f0, 0x58ffc2c1, 0x785ad009, 0xc5376bbd, 0xae431bb6, "....." },
  [863] = { "La fuga", "Proteggi Wizzlecrank e lo shredder goblin rubato lungo la strada verso Sputtervalve a ⟦Ratchet=Porto Paranco⟧.", "Immagino che imparerò strada facendo... Non può essere troppo difficile. Solo qualche pulsante qui e una leva o due... Allora, sei pront<o/a> a partire?", "Posso aiutarti?", "Speriamo di riuscire a ricavare qualcosa di valore dal prototipo di shredder distrutto... il mio tempo sta per scadere! Manderò subito una squadra di recupero dov'è Wizzlecrank.\n\nAh, lascia che ti dia qualcosa per il disturbo.", 0x437cedda, 0x71ada0fe, 0x646e9b5d, 0xf30770a2, 0x6d0bbb0f, "....." },
  [865] = { "Corna di raptor", "Raccogli 5 Intact Raptor Horn dai Sunscale Scytheclaw e portali a Mebok Mizzyrix a ⟦Ratchet=Porto Paranco⟧.", "I raptor delle ⟦Barrens=Savane⟧ sono più intelligenti dei raptor di altre terre. E secondo me tutta quell'intelligenza è nascosta nelle corna! Se è così, potrei macinare le loro corna e usare la polvere per fare \"bevande intelligenti\". Potrei venderle a peso d'oro!!!\n\nE tu puoi aiutarmi. Trovami delle corna di raptor intatte dai Sunscale Scytheclaw. Si aggirano nelle ⟦Barrens=Savane⟧ meridionali e nelle ⟦Barrens=Savane⟧ settentrionali, vicino al confine con ⟦Ashenvale=Valtetra⟧.", "Hai preso le corna, {name}? Con quelle farò una fortuna!", "Magnifico, le hai prese! Ora devo solo macinarle e mescolarle con un po' di vino, e...", 0x1c567a17, 0x3fc5f7ab, 0x7d0b4af6, 0x849a25eb, 0xa8f3ad03, "....." },
  [866] = { "Campioni di radici", "Porta 8 Root Sample a Mebok Mizzyrix a ⟦Ratchet=Porto Paranco⟧.", "Le erbe delle ⟦Barrens=Savane⟧ non sono proprio come quelle delle altre terre. Le loro proprietà sono quasi le stesse, ma l'acqua delle oasi di qui altera le piante: sono appena un po' diverse.\n\nVoglio studiare queste differenze... per vedere se si possono sfruttare!\n\nSe sei espert<o/a> di erbalismo, raccogli campioni di radici dalle erbe che trovi nelle ⟦Barrens=Savane⟧. Riportami questi campioni, così potrò confrontarli con le erbe di altre regioni.", "Salve, {name}. Hai preso quei campioni di radici?", "Sì sì, sono bellissimi! Farò crescere degli esemplari da queste radici e li studierò. Spero di scoprirne nuove proprietà. Proprietà nascoste e preziose...!\n\nE non preoccuparti: se ci riesco, sarai <il/la> prim<o/a> a saperlo. Perché mi servirà qualcuno che ne raccolga altri!", 0x70eb75ac, 0x4cbd0479, 0x8786eff9, 0x068cbe55, 0xf9891d3a, "....." },
  [867] = { "Arpie predatrici", "Raccogli 8 Witchwing Talon.\n\nPortali a Darsok Swiftdagger, al ⟦Crossroads=Crocevia⟧.", "Quelle maledette arpie saccheggiano le provviste delle nostre carovane da troppo tempo. È ora di tagliare qualche gola e sfoltire le loro file.\n\nHo ficcanasato intorno ai loro nidi e ho capito chi comanda chi. L'attacco più devastante distruggerà buona parte dei loro ranghi inferiori, e poi potremo risalire fino in cima.\n\nComincerai piano: elimina le Witchwing Harpy e le Witchwing Roguefeather a nord-ovest e portami 8 artigli di Witchwing. Sarà un buon inizio...", "Ne hai fatte a pezzi abbastanza? Continua a tagliare e a prendere trofei. Voglio 8 artigli di Witchwing.", "Oh, questi sono belli. Proprio belli... Ottimo lavoro, {name}. Non vedo l'ora di vedere altro del tuo lavoro in futuro.", 0x663d72ca, 0x5cbdce59, 0x4d1ddd7f, 0x89ddc918, 0x3b507229, "....." },
  [868] = { "Caccia alle uova", "Porta 12 Uovo di Silitide e l'⟦Digging Claw=Artiglio scavatore⟧ a Korran al ⟦Crossroads=Crocevia⟧.", "Ehi, {name}. Mi hanno mandato al ⟦Crossroads=Crocevia⟧ a sorvegliare la terra e a prendere nota di ciò che succede, per i miei padroni di Orgrimmar.\n\nUno degli oggetti dei miei studi sono le creature simili a insetti che stanno a sud, nel Field of Giants. Sappiamo poco di queste creature, così io mi metto d'impegno a scoprire di più. Sembrano avere un'intelligenza, più di qualsiasi animale normale.\n\nPrendi questo artiglio scavatore e raccogli alcune uova delle creature dai loro tumuli, ma fa' attenzione: se si allarmano, ti attaccano.", "Fa' attenzione alle uova che trovi, {name}. Se si rompono, non mi servono a niente.", "Mi soddisfi, {name}. Le uova e l'attrezzo. Ben fatto.\n\nE come ricompensa...", 0x53341892, 0xe0f09771, 0x770df496, 0x0869f62f, 0xaad56485, "....." },
  [869] = { "Raptor ladri", "Porta 12 Testa di Raptor a Gazrog al ⟦Crossroads=Crocevia⟧.", "Non molto tempo fa, un carico d'argento è stato rubato dalla nostra torre di guardia. Era la paga per le guardie del ⟦Crossroads=Crocevia⟧, e quell'argento lo rivogliamo.\n\nLa cosa strana è... che abbiamo preso uno dei ladri la notte stessa del furto. Ed era... un raptor! Incredibile!\n\nNon so cosa se ne facciano i raptor dell'argento. Ma non m'importa: voglio i raptor morti, così non ci derubano più!\n\nCaccia i raptor nelle ⟦Barrens=Savane⟧. Portami le loro teste!", "Hai quelle teste, {name}?", "Ti sei sbarazzat<o/a> dei raptor!\n\nGrazie, {name}. Sei un {class} di valore.", 0x99919f6b, 0x5dd97461, 0x697ca8ba, 0x1354c782, 0x69f68898, "....." },
  [870] = { "Le ⟦The Forgotten Pools=Sorgenti Dimenticate⟧", "Torna da Tonga Runetotem a riferire ciò che hai scoperto.", "Tanto tempo fa le ⟦Barrens=Savane⟧ erano un luogo rigoglioso, brulicante di vita. Ma la guerra e i cataclismi hanno devastato la terra, bruciandola e lasciandone solo un guscio arido. Così vanno le cose, e questo mi rattrista il cuore.\n\nMa negli ultimi anni nelle ⟦Barrens=Savane⟧ si sono formate nuove oasi, e la vita si risveglia. E nel profondo, noi druidi percepiamo un potere che filtra verso la superficie.\n\nDobbiamo trovarne la fonte. Recati alle Sorgenti Dimenticate, a nord-ovest del ⟦Crossroads=Crocevia⟧. Cerca nelle sue acque una fonte di potere, poi torna qui.", "Sei stat<o/a> alle Sorgenti Dimenticate, {name}? Hai trovato qualcosa?", "Hai trovato una fenditura nel terreno da cui gorgogliano dei gas? Strano. Potrebbe essere una risposta alle nostre domande, ma non possiamo ancora esserne certi.\n\nMa è un indizio. E ti sono grato di averlo trovato.", 0x050d62e3, 0x165ddbb2, 0x9c76fc51, 0x88633845, 0x18730fb7, "....." },
  [871] = { "Sventare gli attacchi", "Della tribù dei ⟦Razormane=Chiomaguzza⟧, uccidi 8 Water Seeker, 8 Thornweaver e 3 Hunter, poi torna da Thork al ⟦Crossroads=Crocevia⟧.", "Tutti i verrospini sono nostri nemici, {name}. Alcuni si rivelano solo più fastidiosi di altri.\n\nLa tribù dei ⟦Razormane=Chiomaguzza⟧ attacca le nostre linee di rifornimento da Durotar, procurandoci fastidi senza fine. Ho degli esploratori che cercano il capo di queste incursioni ma, nel frattempo, ogni perdita che riuscirai a infliggere a quei luridi uomini-maiale ci sarà d'aiuto.\n\nComincia a nord-est, verso Durotar. Le loro tane si riconoscono sempre dagli enormi rovi spinosi che spuntano dalla terra. Trovali e uccidili.", "Più ci vorrà per fermare questi attacchi, più sarà difficile rifornire la gente del ⟦Crossroads=Crocevia⟧.", "Hai fatto bene, {name}. Quei verrospini insolenti impareranno finalmente che la potenza dell'⟦Horde=Orda⟧ non si può ignorare.", 0xe58a1b32, 0xbcd27522, 0xf215e1d9, 0xe55301e3, 0x80850757, "....." },
  [872] = { "Fine dei disordini", "Uccidi 8 Razormane Geomancer, 8 Razormane Defender e Kreenig Snarlsnout.\n\nPoi porta la ⟦Kreenig Snarlsnout's Tusk=Zanna di Kreenig Grugnoringhio⟧ a Thork, al ⟦Crossroads=Crocevia⟧.", "Uno dei miei esploratori ha assistito all'attacco a una carovana proveniente da Durotar, {name}. I colpevoli sono proprio i verrospini della tribù dei ⟦Razormane=Chiomaguzza⟧. Uno di loro in particolare guida le razzie: Kreenig Snarlsnout. È stato visto a nord-est di qui, appena a sud della strada che viene da Durotar. Se vogliamo porre fine alla minaccia, Kreenig deve morire.\n\nPer essere sicuri che gli attacchi cessino, però, dico di aggiungere la beffa al danno. Uccidi Kreenig insieme ad altri della sua tribù e torna da me quando avrai la sua zanna.", "Taglia la testa al capo e scoppia il caos, {name}. Impara bene questa lezione. Ti servirà in futuro.\n\nSenza una guida i verrospini andranno allo sbando, e potremo riprenderci le ⟦Barrens=Savane⟧.", "Ben fatto, {name}. Con la morte di Kreenig, gli attacchi alle nostre carovane caleranno di sicuro.\n\nLa tua gente dovrebbe essere fiera di contarti tra i suoi.", 0x2dfad677, 0x86bafe37, 0x6671b2df, 0x8cf286c6, 0x981f6e19, "....." },
  [873] = { nil, "Porta il ⟦Heart of Isha Awak=Cuore di Isha Awak⟧ a Mahren Skyseer.", "Il grande Isha Awak è il signore di queste acque. Grande è la sua forza, e solenne il suo orgoglio. Gli umani della costa lo temono, perché ha divorato molti di loro.\n\nMa io non lo temo. Sono lieta che sia qui. È una sfida degna, e una preda d'onore.\n\nSe sei pront<o/a>, allora nuota al largo e cerca Isha Awak, la Rovina degli Abissi.\n\nIl suo spirito dimora nel suo cuore, e udirne il battito significa conoscere il proprio destino.", "Non temere le acque, {race}.", "Ora sei una cosa sola con Isha Awak, {name}. Il suo spirito è con te. Si cela nei tuoi occhi...\n\nOcchi che, un giorno, impareranno a vedere.", 0x75825093, 0x9e928276, 0xd7808914, 0x038b0db1, 0xac941e2b, "e...." },
  [874] = { nil, "Parla con Mahren Skyseer.", "Hai cacciato le bestie delle ⟦Barrens=Savane⟧. Il tuo spirito è forte. Ma un cacciatore deve essere sempre pronto. Un vero cacciatore sa braccare la preda lungo qualsiasi sentiero. Montagne e paludi non <lo/la> faranno vacillare.\n\nNemmeno il mare.\n\nTrova mia sorella, Mahren. Caccia le grandi bestie acquatiche lungo la costa. Sarà lei a insegnarti le loro abitudini.\n\nMa fa' attenzione mentre la cerchi, perché la costa delle ⟦Barrens=Savane⟧ è in mano agli umani.", nil, "Ti ha mandato mio fratello, vero? Allora devi aver dato prova di te. Se ti sei guadagnat<o/a> il rispetto di Jorn, hai anche il mio.\n\nSei pront<o/a> a proseguire lungo il sentiero del cacciatore?", 0x7d6a1f65, 0x89e7019b, 0x773a4fa6, nil, 0x7b19f815, "e..m.", nil, nil, 0xfbb5ad85, nil, nil },
  [875] = { "I luogotenenti delle arpie", "Raccogli 6 Harpy Lieutenant Ring dalle Witchwing Slayer e portali a Darsok Swiftdagger al ⟦Crossroads=Crocevia⟧.", "Ahahah, {name}. Sei tornat<o/a> per averne ancora? Bene, è quello che mi piace sentire.\n\nStavolta voglio che tu elimini alcuni luogotenenti delle arpie nelle Dry Hills. Solo le Witchwing Slayer possono essere luogotenenti, e le riconosci dagli anelli che portano. Sono una brutta banda, ma guidano alcune delle sottoposte della zona. Toglierne di mezzo 6 sarà un colpo decisivo contro il loro matriarcato.\n\nAssicurati che muoiano tra atroci sofferenze, {name}. Vogliamo che quelle sgualdrine delle arpie capiscano quanto è stupido attaccar briga con l'⟦Horde=Orda⟧.", "Hai già i 6 Harpy Lieutenant Ring? Devono pagare per i loro feroci attacchi contro l'⟦Horde=Orda⟧.", "Ottimo lavoro, amico mio. Credo che farai strada nell'⟦Horde=Orda⟧.", 0x12f29ef9, 0xab320515, 0x35e1ffee, 0x96dfd3a4, 0xd390ae4e, "....." },
  [876] = { nil, "Uccidi Serena Bloodfeather e porta la sua testa a Darsok Swiftdagger al ⟦Crossroads=Crocevia⟧.", "Te la sei cavata così bene con i luogotenenti e i sottoposti che vorrei che facessi un'ultima cosa per me.\n\nSerena Bloodfeather è la sorella di un'arpia di nome Bloodfeather che fu uccisa da Rexxar parecchio tempo fa. A quanto pare, questi attacchi alle carovane dell'⟦Horde=Orda⟧ sono la vendetta per la morte della sorella.\n\nVoglio che tu le tagli la gola e mi riporti la sua testa. Voglio metterla sulla prossima carovana che spediremo... Così quelle arpie avranno qualcosa a cui pensare.", "Non avrai niente finché non vedrò la testa di Serena.", "AH! Ben fatto, {name}! Davvero ben fatto... Non ero sicuro che fossi all'altezza del compito, ma ti sei <dimostrato/dimostrata> <un/una> ver<o/a> tagliagole. Grazie ancora per averci aiutato a soffocare l'epidemia di arpie. Ecco la tua ricompensa, usala bene.", 0x3d86ef8c, 0xbeb8b687, 0xb8e4b9ee, 0x298feb2a, 0x2279a868, "e...." },
  [877] = { "L'⟦The Stagnant Oasis=Oasi Stagnante⟧", "Dopo aver indagato sull'⟦Stagnant Oasis=Oasi Stagnante⟧, torna da Tonga al ⟦The Crossroads=Crocevia⟧.", "Come quella che hai trovato alle Forgotten Pools, potrebbero esserci fenditure anche nelle altre oasi delle ⟦Barrens=Savane⟧. Se è così, forse le fenditure sono la fonte di vita delle oasi.\n\nDobbiamo verificarlo.\n\nEcco, prendi questi semi. Sono morti e sterili, ma portali all'⟦Stagnant Oasis=Oasi Stagnante⟧, a sud-est. Se lì c'è una fenditura, metti i semi al suo interno... e osserva.", "Sei stat<o/a> all'⟦Stagnant Oasis=Oasi Stagnante⟧? C'era una fenditura sotto le sue acque?", "Le tue scoperte sono sbalorditive! I semi che ti ho dato erano secchi e morti. Qualunque cosa giaccia sotto queste oasi può creare la vita dal nulla!\n\nDobbiamo studiarla ancora...", 0xc199d9a2, 0x9257370a, 0x03931b18, 0x169e62dc, 0xcf16b2bb, "....." },
  [878] = { "Tribù in guerra", "Uccidi 6 Bristleback Water Seeker, 12 Bristleback Thornweaver e 12 Bristleback Geomancer e torna da Mangletooth al Camp Taurajo, nelle ⟦Barrens=Savane⟧.", "Devi colpire i miei nemici. <sbuffa> Devi aiutare Mangletooth e i ⟦Razormane=Chiomaguzza⟧ indebolendo i Mantotergo. Entrambe le tribù sono molto spirituali, legate alla terra e al suo potere. <sbuffa> Ci dà forza in tutte le cose... soprattutto in guerra.\n\nSe vuoi scoprire chi causa davvero tanta angoscia a Thork <sbuffa> e all'⟦Horde=Orda⟧, allora aiuta Mangletooth! Attacca i capi spirituali dei Mantotergo a nord; indeboliscili, così che i ⟦Razormane=Chiomaguzza⟧ possano sconfiggerli e dominare le ⟦Barrens=Savane⟧.", "Altre informazioni <sbuffa> per l'⟦Horde=Orda⟧ quando avrai ucciso i saggi dei Mantotergo, {race}. <sbuffa> Non un attimo prima! Mangletooth non è uno sciocco.", "Sì, sì... pieno di gioia perché finalmente <sbuffa> i ⟦Bristleback=Mantotergo⟧ conoscono il dolore della mia tribù, {race}. Così dovrei sentirmi, ma <sbuffa> non è così.\n\nTu aiuti la tua gente e loro ti onorano. Mangletooth aiuta la sua gente, e loro cosa fanno? Gli voltano le spalle. Lo dimenticano e lo lasciano marcire in gabbia!\n\nLi aiuto perfino da dietro le sbarre, e loro non mandano nessuno a salvarmi!", 0x836aed9c, 0x94f3701b, 0x53c0b5ba, 0xd1b70764, 0xb6191585, "....." },
  [879] = { "Tradimento dall'interno", "Uccidi Nak, Kuz e Lok Orcbane e porta i loro teschi a Mangletooth a Camp Taurajo, nelle ⟦Barrens=Savane⟧.", "Tre della mia tribù sono usciti dalle Gallerie di Lamaspina per guidare le razzie contro l'⟦Horde=Orda⟧, {race}. <sbuffa> Sono spietati e astuti, e se li sconfiggi, il tuo ⟦Crossroads=Crocevia⟧ e persino gran parte delle ⟦Barrens=Savane⟧ conosceranno la pace... <sbuffa> almeno dalla tribù dei ⟦Razormane=Chiomaguzza⟧. <sbuffa>\n\nNak, Kuz e Lok Orcbane sono quelli che cerchi. Si trovano molto a sud, nelle ⟦Barrens=Savane⟧. Uno lancia incantesimi, un altro è un segugio, e il loro capo, quello chiamato Orcbane, <sbuffa> è un guerriero. Uccidili, {race}, come loro hanno ucciso me.", "Come va la tua caccia, {race}? <sbuffa>\n\nThork crede di sapere la verità su chi guida le razzie contro la sua gente, <sbuffa> ma scoprirà quanto si sbaglia, se avrai successo.\n\nLa mia morte è inevitabile, ma tu hai causato grande dolore ai miei nemici, quindi Mangletooth non si pente di nulla. <sbuffa>", "Allora è fatta. Meglio che finisca così, dice Mangletooth. <sbuffa> Avrebbero dovuto <sbuffa> assicurarsi che fossi morto quando mi hanno voltato le spalle, invece di lasciarmi <sbuffa> qui in questa gabbia maledetta.\n\nTi resta un ultimo compito da portare a termine, {race}.", 0xabe2f634, 0xda62738d, 0xf3b992ae, 0x27a878f0, 0xa569522d, "....." },
  [880] = { "Creature alterate", "Porta 8 Altered Snapjaw Shell a Tonga Runetotem al ⟦Crossroads=Crocevia⟧.", "Le tue scoperte sono incredibili, {name}. Queste oasi hanno proprietà che devono venire da una fonte esterna. O forse interna.\n\nVoglio sapere in che modo queste fenditure influiscono sulle bestie che bevono l'acqua delle oasi.\n\nCaccia gli Oasis Snapjaw a Lushwater Oasis e all'Oasi Stagnante. Portami i loro gusci, così potrò esaminarli.", "Come procede la raccolta? Hai preso i gusci?", "Grazie, {name}. Studiare le bestie di una zona può dire molto sulla zona stessa. Vedremo che storia racconteranno questi gusci.\n\nAccetta la mia gratitudine per il tuo aiuto... e forse queste monete ti saranno utili. A me non servono.", 0x3ce01f92, 0x0767e054, 0x731ae9c5, 0x0218c1d5, 0x4a48aedf, "....." },
  [881] = { nil, "Porta la ⟦Echeyakee's Hide=Pelle di Echeyakee⟧ a Sergra Darkthorn al ⟦Crossroads=Crocevia⟧.", "Whitemist, Echeyakee nella lingua dei Tauren, è il re dei felini della savana. Caccia con una tale furtività che, si dice, è come una nebbia sottile e bianca sulla terra. E uccide così in fretta che le sue prede non hanno il tempo di provare paura, o dolore.\n\nI Tauren dicono che è al tempo stesso misericordia e morte.\n\nScoprirai se è vero, perché ora ti metto sulle tracce di Echeyakee. La sua tana è a nord-est del ⟦Crossroads=Crocevia⟧, tra le ossa di kodo giganti.\n\nVa'. Suona questo corno quando raggiungi la sua tana. Suona il corno, e lui verrà.", "Il grande felino ti chiama, {name}.", "Hai sconfitto Echeyakee, e anche se i suoi giorni di caccia sono finiti... il suo spirito è con te. Ti mostrerà la forza che si trova nella discrezione, e l'onore nella misericordia.\n\nIl tuo cammino è ancora lungo, {class}. Speriamo che tu lo percorra bene.", 0x8eaea284, 0x0758978b, 0x0689f2cb, 0xe0526099, 0x1b8589ca, "e...." },
  [882] = { nil, "Porta la ⟦Ishamuhale's Fang=Zanna di Ishamuhale⟧ a Jorn, a Camp Taurajo.", "Ishamuhale, Zannalancia, è il più feroce raptor squamasole delle ⟦Barrens=Savane⟧. Non caccia per sport, né per nutrirsi. Caccia perché la caccia è la sua passione. Uccide perché uccidere è nella sua natura.\n\nE tu conoscerai la sua natura, {name}, perché ora il tuo cammino segue le orme artigliate di Ishamuhale.\n\nComincia la caccia. Uccidi la sua preda preferita, uno zhevra, poi porta la carcassa all'albero morto a nord-ovest di ⟦Ratchet=Porto Paranco⟧. Ishamuhale sentirà l'odore della carcassa e ne sarà attirato.\n\nTieniti pront<o/a> quando arriverà.", "{name}, hai avuto la meglio su Ishamuhale?", "Questa zanna è solo un simbolo, ma ciò che rappresenta è profondo.\n\nLa forza di Ishamuhale è in te, {name}. Che tu possa usarla con temperanza. Questo è il tuo fardello.\n\nQuesto è il tuo onore.", 0x574078d6, 0xdcecca63, 0x4339b639, 0xd7a1f327, 0x0249d5ae, "e...." },
  [883] = { nil, "Porta lo ⟦Hoof of Lakota'mani=Zoccolo di Lakota'mani⟧ a Jorn a Camp Taurajo.", "Lo ⟦Hoof of Lakota'mani=Zoccolo di Lakota'mani⟧ è un simbolo della forza del grande kodo.", "{name}, quando ti sei <avvicinato/avvicinata> ho visto un nuovo potere nel tuo passo. Dimmi: il tuo spirito ha incontrato il grande Lakota'mani?", "Nella nostra lingua Lakota'mani è chiamato \"Scuotiterra\", e i suoi passi sono come tuono raccolto. Ora è con te, e il suo coraggio si mescola al tuo. Insieme non c'è scontro che tu non possa affrontare.\n\nCammina a testa alta, {name}. Cammina a testa alta, Scuotiterra.", 0x8a0292b4, 0x154db736, 0x9c5704ae, 0x252b2af4, 0x5e74ae0d, "e...." },
  [884] = { nil, "Porta lo ⟦Owatanka's Tailspike=Spuntone della Coda di Owatanka⟧ a Jorn, a Camp Taurajo.", "Al tocco, dallo spuntone della coda di Owatanka sprizzano scintille.", "{name}, c'è un nuovo potere dietro i tuoi occhi! Hai incontrato il possente Owatanka, non è vero?", "I tauren chiamano la lucertola del tuono Owatanka «Bluebolt», perché in lei dimora una velocità che smentisce la sua mole. Si dice che, tanto tempo fa, un fulmine colpì Bluebolt e che, nutrita dalla furia del cielo, l'energia della grande bestia sia ora senza limiti.\n\nChe la sua energia scorra in te, {name}. Perché ora tieni il passo di Owatanka.", 0x298c2ba2, 0xb83ea4ee, 0x9858e87a, 0x51bfdd6e, 0x82017096, "e...." },
  [885] = { nil, "Porta la ⟦Washte Pawne's Feather=Piuma di Washte Pawne⟧ a Jorn Skyseer a Camp Taurajo.", "La piuma di Washte Pawne fa male al tatto.", "C'è una nuova determinazione in te, {name}. Una determinazione nata dal dolore...\n\nTi pesa la morte di Washte Pawne?", "Il falco del tuono è una bestia rara delle ⟦Barrens=Savane⟧, e la sua morte può presagire grande fortuna, o grande rovina.\n\nMa Washte Pawne, chiamato «Mordispiriti» in taurahe, non può portare né l'una né l'altra... o entrambe.\n\nIl dolore che hai provato dando la caccia a Mordispiriti è la fitta che sentono tutti coloro che ottengono grandi guadagni a caro prezzo. Il bruciore che hai sentito è il dolore del rimpianto.\n\nMa vedo che l'hai superato. Hai imparato che il rimpianto si trasforma in saggezza, e che attraverso il dolore si acquista forza.\n\nHai imparato molto, {name}.", 0xcfbb9a34, 0x82aa0f1b, 0xe555fb49, 0x46451e74, 0xe53f8aad, "e...." },
  [886] = { "Le oasi delle ⟦The Barrens=Savane⟧", "Parla con Tonga Runetotem al ⟦Crossroads=Crocevia⟧.", "I druidi di ⟦Thunder Bluff=Picco del Tuono⟧ percepiscono uno strano potere che filtra nelle ⟦Barrens=Savane⟧, a est di Mulgore.\n\nTonga Runetotem è stato mandato a scoprire la fonte di questo potere, ma temiamo che avrà bisogno di aiuto.\n\nRecati nelle ⟦Barrens=Savane⟧ e parla con Tonga. Lo troverai al ⟦Crossroads=Crocevia⟧. Per arrivarci, prendi la strada verso est che esce dal Villaggio di Zoccolo Sanguinario. Entra nelle ⟦Barrens=Savane⟧, poi gira a nord dove la strada si biforca. Prosegui verso nord e troverai il ⟦Crossroads=Crocevia⟧.\n\nE non lasciare la strada, {name}, perché le ⟦Barrens=Savane⟧ sono una terra spietata.", nil, "I miei fratelli di ⟦Thunder Bluff=Picco del Tuono⟧ sono stati saggi a mandarti, giovane {class}. Il mistero delle ⟦Barrens=Savane⟧ è uno che da solo non posso svelare.\n\nCon il tuo aiuto, speriamo di trovare risposta alle nostre domande.", 0x96d3bc63, 0xcc4a44bb, 0x754621de, nil, 0xe0891962, "...m." },
  [887] = { "⟦Southsea Freebooters=Filibustieri dei Mari del Sud⟧", "Uccidi 12 Southsea Brigand e 6 Southsea Cannoneer per Gazlowe a ⟦Ratchet=Porto Paranco⟧.", "Vorrei proprio che il viceammiraglio Grezzlik facesse un lavoro migliore nel tenere i mari sicuri per le nostre navi mercantili. Con tutto l'oro che i principi mercanti hanno versato nelle flotte commerciali, mi fa imbestialire vedere tanti pirati scorrazzare a destra e a manca, assaltare le mie navi e rubare la mia merce!\n\nHo sentito che i ⟦Southsea Freebooters=Filibustieri dei Mari del Sud⟧ hanno messo su un accampamento appena a sud di qui. Sono una vera spina nel fianco e, se Grezzlik non se ne occupa, be', magari puoi aiutarmi tu a sbarazzarmene.", "Non voglio nemmeno pensare ai profitti che ho perso per colpa delle razzie dei pirati, e adesso si accampano proprio sulla porta di casa mia? La situazione sta sfuggendo di mano, Undermine deve fare qualcosa.", "Bel lavoro, <ragazzo/ragazza>. Ancora un po' di lavoro così e sarà una preoccupazione in meno per me. Speriamo che si convincano a spostare i loro affari altrove.\n\nNel frattempo, c'è la piccola questione di recuperare la merce che mi hanno rubato!", 0x66c9c41c, 0x69ce9e05, 0x7623fe2d, 0xd3e5fc1b, 0x9a1f5c52, "....." },
  [888] = { "Bottino rubato", "Recupera la ⟦Shipment of Boots=Spedizione di Stivali⟧ e le ⟦Telescopic Lens=Lenti Telescopiche⟧ per Gazlowe a ⟦Ratchet=Porto Paranco⟧.", "Mi piacerebbe recuperare tutta la mia merce, ma so che non è possibile. Però ci sono un paio di cose che devo assolutamente avere!\n\nCome vedi, il mio osservatorio è pronto, ma gli manca la più piccola delle due lenti. La prima è arrivata con una carovana da Durotar, ma la seconda viaggiava per nave e non è mai arrivata. E poi non ho mai ricevuto la mia spedizione di stivali da Drizzlik, a ⟦Booty Bay=Baia del Bottino⟧!\n\nScendi all'accampamento dei pirati e vedi se riesci a trovarle.", "Hai trovato la mia roba, {name}?", "Che sollievo riavere tutta questa roba, quindi grazie per l'aiuto, {name}. Sai, mi farebbe comodo <un/una> {race} come te per dare una mano alla mia attività. Se mai cerchi lavoro, ricordati quanto paga bene Gazlowe!", 0x64d599c7, 0x739fc2b0, 0x0b53afc7, 0x23319024, 0xe9cacd44, "....." },
  [889] = { "⟦Spirit of the Wind=Spirito dell'Aria⟧", nil, nil, "Porta a Mangletooth 10 frammenti di sangue e ti benedirò con una grande velocità. Correrai con le zhevra e il vento sarà geloso di te.\n\nNon durerà a lungo, ma dovrebbe bastarti per viaggiare attraverso le ⟦Barrens=Savane⟧.", "Bene. Va' con lo spirito di Agamaggan a farti da guida, {race}. Torna da me se desideri altra magia di Agamaggan.", 0x379dc9e6, nil, nil, 0x8c28d61d, 0x2b6a6a7c, ".mm.." },
  [890] = { "Il carico scomparso", "Porta il ⟦Gazlowe's Ledger=Libro Mastro di Sparachiodi⟧ al capo del molo Dizzywig.", "Aspetto da una vita l'ultimo carico di merci da ⟦Booty Bay=Baia del Bottino⟧! Sono quasi sicuro che l'abbiano rubato i Filibustieri, ma giusto per esserne certo, puoi scendere al molo e chiedere a Dizzywig se la mia merce è già stata messa nel mio magazzino a mia insaputa?\n\nEcco, porta il mio libro mastro a Dizzywig e fagli confrontare i miei registri d'inventario con i suoi.", "Merce da spedire con la prossima nave, {name}?", "Ah, ti manda Gazlowe, eh? Un momento, fammi dare un'occhiata e controllare i miei registri, per essere sicuro di non aver spedito il carico di Gazlowe nel posto sbagliato.\n\nScommetto che aspetta quegli stivali da Drizzlek...", 0x6e986c05, 0xb6778f93, 0x3b8b55c6, 0x0751d23b, 0x749eab9a, "....." },
  [891] = { "I cannoni di Northwatch", "Il capitano Thalo'thas Brightsun di ⟦Ratchet=Porto Paranco⟧ vuole che tu raccolga 10 Theramore Medal e uccida la capitana Fairmount, il cannoniere Whessan e il cannoniere Smythe.", "Un'altra nave della mia flotta perduta per colpa di quegli umani fanatici di Northwatch Hold!\n\nQuei bastardi vanno sistemati. La paranoia li ha mandati in frenesia. Quei bifolchi sconsiderati dal grilletto facile sparano a qualunque cosa capiti loro a tiro.\n\nViaggia verso sud lungo la Merchant Coast fino alla roccaforte e cingi d'assedio le loro forze. Portami come prova le medaglie dei loro soldati. E per amore della mia flotta, uccidi la capitana Fairmount e i suoi cannonieri fanatici!", "La mia flotta è in pericolo, con la capitana Fairmount e i suoi maledetti cannonieri che sparano a raffica da Northwatch Hold. Voglio che anche i suoi soldati paghino. Riempimi la mano di medaglie prese dai loro morti e saprò che i miei corsari caduti sono stati vendicati.", "Ahimè, i giusti cannoni dell'⟦Alliance=Alleanza⟧ sono stati messi a tacere. Sarai <ricompensato/ricompensata> per il tuo aiuto, {name}.\n\nOra devo occuparmi del triste compito di recuperare i corpi dei caduti....", 0xe43eab3d, 0xf4eee744, 0xa8fff6eb, 0x7d3aa2a3, 0x84df7b53, "....." },
  [892] = { "Il carico scomparso", "Riporta il ⟦Gazlowe's Ledger=Libro Mastro di Sparachiodi⟧ a Gazlowe a ⟦Ratchet=Porto Paranco⟧.", "Dai miei registri è tutto in ordine, {name}. Torna pure da Gazlowe e digli che non ha fortuna. Non mi stupirei se fossero stati i pirati a fregargli la roba.\n\nNon posso fare altro per lui. Oh... però potresti dirgli che ho delle cose per lui da Undermine, quando ha tempo di passare a prenderle.", "Allora, che ha detto Dizzywig?", "Niente da fare, eh? Allora dev'essere stata colpa dei Filibustieri... Dizzywig è uno onesto, sono sicuro che non mi fregherebbe così. Dopotutto, è sul mio libro paga.\n\nA quanto pare ho della merce da recuperare, {name}. Che ne dici?", 0x6e986c05, 0xccb10e11, 0xd2dbc272, 0xf6aa07eb, 0xfba18b3c, "....." },
  [893] = { "Armi di prima scelta", "Porta uno ⟦Razormane Backstabber=Stilo dei Chiomaguzza⟧, una ⟦Charred Razormane Wand=Bacchetta dei Chiomaguzza Carbonizzata⟧ e uno ⟦Razormane War Shield=Scudo da Guerra dei Chiomaguzza⟧ a Tatternack Steelforge, a Camp Taurajo, nelle ⟦Barrens=Savane⟧.", "I verrospini ⟦Razormane=Chiomaguzza⟧ a sud, oltre il Field of Giants, non hanno fabbri esperti, da quel che mi dicono, ma a quanto pare hanno cominciato a fabbricare armi più robuste. Vorrei mettere le mani su qualche tipo diverso per studiarne le tecniche, se possibile.\n\nSe vuoi aiutare a portare onore all'⟦Horde=Orda⟧, portami degli esemplari delle loro armi. Trovami un pugnale dei loro predatori, una bacchetta dei loro veggenti e uno scudo dei loro guerrieri furiosi. Andranno benissimo!", "Anch'io dubito che quei miserabili verrospini possano raggiungere una qualche abilità nell'arte del fabbro, ma faccio ciò che comanda il Capoguerra, e imparerò ciò che posso sulla tribù ⟦Razormane=Chiomaguzza⟧.\n\nHo svolto compiti ben più umili, e lo faccio volentieri se aiuta il popolo degli orchi.", "Ottimi, davvero ottimi esemplari.\n\nI verrospini sono più avanti di quanto pensassi.\n\nTieni, {class}, prendi questo e levati di mezzo. Farò meglio a dare un'occhiata più da vicino a queste armi. Forse abbiamo sottovalutato il nemico, ed è il genere di errore che non possiamo permetterci.", 0x8d432675, 0x3e90d600, 0xc757cbc5, 0xced914b6, 0xc7bff642, "....." },
  [894] = { nil, "Accedi alla console di controllo nel centro di ricerca della ⟦Venture Company=S.P.R. & Co.⟧", "La ⟦Venture Company=S.P.R. & Co.⟧ ha allestito un piccolo centro di ricerca molto a nord di qui, a sud-ovest della ⟦Sludge Fen=Palude Fangosa⟧. Non so granché di quello che fanno, ma sono riuscito a scoprire che stanno facendo esperimenti con una cosa chiamata \"samophlange\".\n\nE che diavolo è un samophlange? Be', qualunque cosa sia, voglio esaminarlo, quindi mi serve qualcuno che vada a prenderlo.\n\nHo ottenuto una copia del manuale operativo del loro sistema di controllo: con quello dovresti riuscire a capire come sganciare il samophlange.", nil, "Sul pannello della console di controllo sono disposti in modo piuttosto disordinato vari pulsanti, leve e luci lampeggianti. Un piccolo indicatore mostra che l'apparato funziona a livelli ottimali e che le valvole di controllo da uno a tre sono attualmente aperte. Nella parte inferiore destra del pannello di controllo c'è una piccola serratura.", 0x59bd049c, 0x4672c678, 0x2862ca26, nil, 0x663259ed, "e..m." },
  [895] = { "RICERCATO: barone ⟦Longshore=Rivalunga⟧", "Porta la testa del barone ⟦Longshore=Rivalunga⟧ a Gazlowe a ⟦Ratchet=Porto Paranco⟧.", "RICERCATO!\n\nBarone ⟦Longshore=Rivalunga⟧, capitano dell'Heedless\n\nIl capitano ⟦Longshore=Rivalunga⟧ di Gilneas comanda le navi dei ⟦Southsea Freebooters=Filibustieri dei Mari del Sud⟧ ed è ricercato per pirateria. I resti devono essere riconoscibili!\n\n-- Gazlowe", "Che succede? Posso fare qualcosa per te? Merci da spedire, magari un lavoretto di ingegneria?", "Ahhhh! Quel genere di affari. Sai, una volta ho visto l'Heedless in mare aperto. Una nave temibile, o era una barca... quei marinai sono così pignoli!\n\nComunque, vederla scivolare sull'acqua era proprio uno spettacolo. Sono contento che il suo famigerato capitano non darà più fastidio alle mie navi.", 0x491ae825, 0xd4870698, 0xa3d7e5a0, 0x053eeee1, 0x55a4e1a1, "....." },
  [896] = { "La fortuna del minatore", "Recupera lo ⟦Cats Eye Emerald=Smeraldo Occhio di Gatto⟧ da uno dei Venture Co. Overseer o Enforcer per il capo del molo Dizzywig a ⟦Ratchet=Porto Paranco⟧.", "Essendo il capo del molo di un porto trafficato come ⟦Ratchet=Porto Paranco⟧, tengo sempre il dito sul polso delle informazioni. So tutto degli scambi di merci e denaro fra qui e la ⟦Booty Bay=Baia del Bottino⟧.\n\nL'ultima novità che ho sentito riguarda la miniera Boulder Lode della S.P.R. & Co., a nord-est della ⟦Sludge Fen=Palude Fangosa⟧. Uno dei minatori ha scoperto uno smeraldo grosso come un pugno. Conosco alcuni compratori che sarebbero interessati a mettere le mani su una cosa del genere, e sarei disposto a fare a metà sulla vendita.", "Se solo sapessimo quale dei minatori ha trovato lo smeraldo, sarebbe una passeggiata...", "Guarda che stazza, {name}! Diventeremo ricchi! Vediamo, in base alle quotazioni che ho visto sulle gemme dirette a Undermine, dovrei riuscire a calcolare la tua parte... il cinquanta per cento, non preoccuparti!\n\nDunque, vediamo... direi che questo dovrebbe andare bene. È un piacere fare affari con te, {name}.", 0xf0a4978e, 0xb7148907, 0x65b6bf5c, 0x6508ab66, 0x517d57ef, "....." },
  [897] = { "Il Falciatore", "Porta la ⟦Harvester's Head=Testa del Falciatore⟧ a Jorn Skyseer.", "Questa strana creatura simile a un insetto sembra estranea all'ordine naturale, come se non appartenesse alle ⟦Barrens=Savane⟧.", "Sembri turbat<o/a>, {name}. Come procedono le tue lezioni nelle ⟦Barrens=Savane⟧? Hai trovato qualcosa che ti inquieta?", "Non posso dire nulla sulla natura di questa bestia, perché il suo spirito è fuggito. Ma, come hai intuito, non appartiene alle ⟦Barrens=Savane⟧. Temo che possa annunciare un futuro cupo per il nostro popolo...\n\nMa per ora preparati, e speriamo che il tempo sveli il mistero di questa creatura.", 0x77d10133, 0x1420fa8f, 0x50e3911d, 0x4b2110ea, 0x2728ef86, "....." },
  [898] = { "Fuga dalla roccaforte", "Scorta sano e salvo Gilthares Firebough dal capitano Brightsun a ⟦Ratchet=Porto Paranco⟧.", "Finalmente! Qualcuno che mi salva!\n\nNon posso credere che tu abbia superato le guardie. Questi fanatici di Theramore sono fuori di testa. Hanno affondato la nostra nave e hanno imprigionato me, l'unico sopravvissuto. Mi hanno chiamato nemico e minaccia per l'⟦Alliance=Alleanza⟧.\n\nIo! Una minaccia per quella grande farsa della loro ⟦Alliance=Alleanza⟧? Ero un mozzo su una nave che trasportava liquore di contrabbando tra ⟦Ratchet=Porto Paranco⟧ e la ⟦Booty Bay=Baia del Bottino⟧.\n\nBasta chiacchiere. Mi aiuti a tornare a ⟦Ratchet=Porto Paranco⟧? Fammi sapere quando sei <pronto/pronta> e scapperemo.", "Sì?", "E pensare che credevamo Firebough morto da tempo!\n\nIl tuo eroismo ti è valso un posto d'onore presso i Thalo'dan Privateers, {name}.", 0x8b0a35e2, 0xa3ee7f7a, 0x63cf73fd, 0x0c07a888, 0x8a761a12, "....." },
  [899] = { "Divorato dall'odio", "Porta 60 Bristleback Quilboar Tusk a Mankrik al ⟦Crossroads=Crocevia⟧.", "Forse conosci il dolore dell'incertezza, forse no, {class}. Ma sappi questo: sto qui ogni giorno, dal sorgere del sole fino al tramonto, a scrutare l'orizzonte in cerca di altri di quei mostri. Da allora ho ucciso ogni uomo-maiale in cui mi sono imbattuto, ma la mia sete del loro sangue è tutt'altro che placata. Forse invece di dirigermi a nord verso il ⟦Crossroads=Crocevia⟧ avrei dovuto andare a Taurajo.\n\nTu, {class}... tu potresti aiutarmi.\n\nUccidili. Uccidine quanti più puoi. Portami le loro zanne, e festeggeremo insieme la loro morte.", "I verrospini la pagheranno, {name}. Lo giuro.", "{class}, prendi sul serio il mio compito, e per questo ti ringrazio.\n\nAnche se il mio desiderio di vendetta rimane, almeno posso sorridere vedendo che i verrospini hanno provato il dolore sulla propria pelle.", 0x6638a92b, 0x0ad06ad9, 0x504d3397, 0xe87e6a53, 0x3c792229, "....." },
  [900] = { nil, "Chiudi la Fuel Control Valve, la Regulator Valve e la Main Control Valve, poi usa di nuovo la console di controllo.", "Le tre valvole di controllo sono attualmente aperte. Le varie letture sul pannello di controllo ti fanno supporre che vadano chiuse prima di poter spegnere l'apparato.", "Le luci lampeggianti sulla console di controllo indicano che le valvole di controllo principali non sono state chiuse.", "Le luci delle tre valvole di controllo si affievoliscono mentre le valvole vengono chiuse. Le luci verdi sfumano lentamente nel giallo, e l'interruttore che controlla l'apparato ora si può muovere: con le valvole chiuse, è possibile spegnerlo.", 0x59bd049c, 0xc702a51e, 0x84fa6910, 0x016095ec, 0xd54462d9, "e...." },
  [901] = { nil, "Prendi la ⟦Console Key=Chiave della Console⟧ dall'inventore Sniggles per usarla sulla console di controllo.", "Con l'apparato disattivato, il pannello di controllo può essere aperto e il samophlange estratto dalla console. Con tutto il resto a posto, non resta che procurarsi la chiave per sbloccare la console.", "Le luci della console sono smorzate e gli indicatori e i quadranti segnano tutti zero: ogni cosa è ferma.", "Giri la chiave nella serratura e la console di controllo si sblocca. Una luce rossa in cima alla console si spegne e tutta l'energia defluisce dal terminale.", 0x59bd049c, 0x3bc295f6, 0xdda2316f, 0x90e09488, 0xec181a95, "e...." },
  [902] = { nil, "Riporta il Samophlange a Sputtervalve a ⟦Ratchet=Porto Paranco⟧.", "Aprendo il pannello frontale della console di controllo scopri un fitto groviglio di fili, tubi e altri strani oggetti meccanici, che per lo più non sembrano servire a niente. Spostandoli e scavando più a fondo nella console, trovi il samophlange. Con uno strattone lo estrai dal suo alloggiamento.", "Oh, sei tornat<o/a>, {name}! Hai il samophlange?", "Questo è... ehm... interessante... sì. Lo farò spedire al quartier generale della Tinkers' Union a Undermine. Sono sicuro che, dopo un'attenta dissezione e un po' di ricerca, riusciranno a capirci qualcosa.\n\nMa forse prima gli darò un'occhiatina io...", 0x59bd049c, 0xc6a03d7b, 0x6dc9a2ce, 0x2213d644, 0x020e9774, "e...." },
  [903] = { "I predatori delle ⟦Barrens=Savane⟧", "Raccogli 7 Prowler Claws dai Savannah Prowler per Sergra Darkthorn, al ⟦Crossroads=Crocevia⟧.", "Ora è il momento di dare la caccia a qualcosa che morde davvero. I predatori delle ⟦Barrens=Savane⟧ sono una razza tosta. Tosti, pieni di risorse, astuti... e letali. Li troverai tra l'erba alta. Molti sono a sud-ovest del ⟦Crossroads=Crocevia⟧.\n\nStai in guardia mentre li cacci, {name}, o potresti scoprire di non essere più il predatore, ma la preda.", "Come va la caccia, {name}? Hai trovato i predatori?", "Ah, vedo che ti sei dat<o/a> da fare, appostat<o/a> tra l'erba a cacciare predatori. Allora, credi che sia ora di affrontare un campione tra loro?", 0x4a3e1d81, 0xdcd78944, 0x922f66c4, 0xaec05ded, 0x3e6426e0, "....." },
  [905] = { "Gli Scytheclaw infuriati", "Uccidi i raptor Sunscale e raccogli le loro piume. Usa le piume sui 3 nidi degli Scytheclaw. Torna da Sergra Darkthorn a ⟦Crossroads=Crocevia⟧.", "Ora, {name}, la caccia si fa più impegnativa. Ora devi sconfiggere la tua preda, e poi trovare la strada per la sua tana.\n\nCaccia i raptor Sunscale a sud. Uccidili e prendi le piume che portano. Metti le piume sui nidi degli Scytheclaw a sud-ovest dell'⟦Stagnant Oasis=Oasi Stagnante⟧. Mostra ai loro simili che non hai paura di loro!", "Sei andat<o/a> ai nidi, {name}?", "Quindi sei <stato/stata> ai nidi e ci hai messo le piume delle tue prede. Ci voleva una bella dose di coraggio, non c'è dubbio.\n\nTi senti un po' più tost<o/a>, {name}? Perché sembri più tost<o/a> di quando sei arrivat<o/a> qui. Direi che le ⟦Barrens=Savane⟧ stanno facendo il loro lavoro.", 0x4d73067a, 0x8199dcd2, 0x2a21e74d, 0x8b091b50, 0xd4047437, "....." },
  [906] = { "Tradimento dall'interno", "Porta il ⟦Lok's Skull=Teschio di Lok⟧ a Thork al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", "Porta la testa di Lok a Thork al ⟦Crossroads=Crocevia⟧, {race}. <sbuffa> Dovrebbe capire cos'è successo alla mia tribù senza bisogno di parole... ah, non che crederebbe che Mangletooth abbia aiutato in <sbuffa> faccende simili. Ma sono sicuro che ti ricompenserà per un'impresa così grande. <sbuffa>\n\nContinuerò a benedirti con il potere di Agamaggan finché resterò in questa gabbia, {race}. Fino ad allora, addio.", "Sì, che c'è?", "Hai trovato il capo dei ⟦Razormane=Chiomaguzza⟧ e l'hai ucciso con le tue mani, {name}? Incredibile.\n\nSono senza parole, ma questo non significa che io sia senza gratitudine. La gente del ⟦Crossroads=Crocevia⟧ farebbe bene a rispettare la tua forza.\n\nDevo ammettere che pensavo che il capo di queste incursioni contro le nostre linee di rifornimento fosse un altro verrospino. Grazie ancora, {name}.", 0xabe2f634, 0x4c355197, 0x5127491a, 0xb4a62c76, 0x6332f935, "....." },
  [907] = { "Sauri del tuono infuriati", "Porta 3 ⟦Thunder Lizard Blood=Sangue di Sauro del Tuono⟧ a Jorn Skyseer a Camp Taurajo.", "Ora, {name}, devi affrontare i grandi sauri del tuono. Queste bestie sono così grandi che il suolo trema quando attraversano le pianure. Sta' attent<o/a> quando li combatti, perché basta un passo falso e potresti ritrovarti sotto le loro zampe.\n\nTroverai i sauri del tuono nelle ⟦Barrens=Savane⟧ meridionali. Sono noti come Stormsnout, Stormhide e Thunderhead. Torna da me dopo averli sconfitti.", "I sauri del tuono sono stati sconfitti, {name}?", "È bello vederti tornare con la prova della vittoria. Ed è bello sapere che ci sei riuscit<o/a> senza romperti le ossa.", 0xd908cdb9, 0xa9e2d30c, 0xb2ff357e, 0x288aa9eb, 0xeeed6543, "....." },
  [908] = { "Tra le rovine", "Porta il ⟦Fathom Core=Nucleo Profondo⟧ a Je'neu Sancrea, all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, a ⟦Ashenvale=Valtetra⟧.", "Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ si è insediato nelle Moonshrine Ruins degli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. La loro presenza può servire solo a costringere gli elementi ad agire contro di noi. Se nessuno li ferma, questa regione sarà loro per sempre.\n\n{name}, entra a ⟦Blackfathom=Fondocupo⟧ e trova la pietra profonda delle rovine; dovrebbe essere da qualche parte nell'acqua, lì vicino. Al suo interno c'è un Nucleo Profondo, un congegno che, se letto correttamente, rivela la storia di tutta l'attività elementale. Se l'avessi, io e l'Earthen Ring potremmo forse fare qualcosa per fermarli!", "Sei riuscit<o/a> a trovare il Nucleo Profondo? Senza, non avremo idea di cosa stia tramando esattamente il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ laggiù.", "È proprio quello che mi serve! Un Nucleo Profondo è un'incredibile fonte di informazioni da cui potremo trarre molto di buono. Qualunque cosa stia tramando là dentro il ⟦Twilight's Hammer=Martello del Crepuscolo⟧, e credimi se ti dico che non è niente di buono, ora i miei compagni e io lo scopriremo.\n\nOggi hai fatto un buon lavoro; l'Earthen Ring ti guarda con favore per averci aiutato. Hai aiutato anche l'⟦Horde=Orda⟧ intera, e per questo dovresti andarne fier<o/a>.", 0x09596e4f, 0xedf98535, 0x8b83bfb4, 0x55331311, 0x22dfd3c7, "....." },
  [909] = { "Il barone Aquanis", "Porta il ⟦Strange Water Globe=Globo d'Acqua Strano⟧ a Je'neu Sancrea all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, nella ⟦Ashenvale=Valtetra⟧.", "L'elementale d'acqua sconfitto ha lasciato dietro di sé uno strano globo d'acqua. Intuisci che l'oggetto, in qualche modo, nutriva di energia la creatura. Dentro il globo si agita un'acqua dall'aspetto putrido. Il globo stesso sembra immune a qualsiasi forza fisica.\n\nSe qualcuno può capire qualcosa di questo oggetto, è Je'neu Sancrea dell'Earthen Ring. Si trova all'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧ dell'Orda, nella ⟦Ashenvale=Valtetra⟧.", "Ah, eccoti di nuovo, {name}. Stavo leggendo le onde del mare, come faccio sempre. Che cosa ti porta all'avamposto?", "Questa... questa è una bella scoperta, {name}.\n\nDici di averla presa al barone Aquanis, negli Abissi di ⟦Blackfathom=Fondocupo⟧? Da tempo si pensa che il barone Aquanis sia un potere elementale corrotto; questo globo dimostrerà che cosa esattamente l'abbia corrotto. Non sarebbe una sorpresa se si rivelasse opera del ⟦Twilight's Hammer=Martello del Crepuscolo⟧, ma i nostri studi mostreranno anche come ci siano riusciti.\n\nHai fatto bene a portarmelo. Ti prego, prendi questo, insieme ai più calorosi saluti dell'Earthen Ring.", 0x6317c3fa, 0x5afab460, 0xeafedd21, 0xd1397112, 0x5fa18944, "....." },
  [912] = { "Travestimento da Stonesplinter Trogg", nil, nil, nil, nil, 0x7c1e89d9, nil, nil, nil, nil, ".mmmm" },
  [913] = { "Il grido del Thunderhawk", "Trova e uccidi un Thunderhawk, poi porta le sue ali a Jorn Skyseer a Camp Taurajo.", "Il thunderhawk, {name}, è una bestia feroce. È tempo che tu li affronti. Devi trovare dove si aggira e portarmi le sue ali come prova della tua caccia riuscita.\n\nFallo, e il tuo tempo con me volgerà al termine.", "È fatta? Hai ucciso il thunderhawk?", "Come il thunderhawk, dovresti essere fier<o/a>. Hai sconfitto ogni nemico che ti abbiamo messo davanti, e l'hai fatto con forza, coraggio e onore.\n\nMa il tuo cammino, {name}, continua. Anzi, scoprirai che i veri cacciatori lottano per sempre, percorrono per sempre il loro cammino con lo stesso orgoglio che hai mostrato a me.\n\nOra è tempo di andare avanti.", 0x168add81, 0x2e50c35a, 0x7c0fdf40, 0x1ce663e1, 0x12313ad2, "....." },
  [914] = { "I capi dei Druids of the Fang", "Porta le gemme di Cobrahn, Anacondra, Pythas e Serpentis a Nara Wildmane a ⟦Thunder Bluff=Picco del Tuono⟧.", "I druidi della ⟦Wailing Caverns=Caverna dei Lamenti⟧, i Druids of the Fang, sono un'aberrazione. Facevano parte di un ordine di nobili druidi che voleva risanare le ⟦Barrens=Savane⟧, ma ora cercano di rifare quella terra a immagine dei loro sogni distorti.\n\nI Druids of the Fang hanno quattro capi, e ognuno possiede una gemma del sogno. Ancora adesso i loro volti mi perseguitano! Sconfiggi i capi e portami le loro gemme, e le ⟦Barrens=Savane⟧ potranno conoscere di nuovo la pace.\n\nVa', {name}. Li troverai in agguato nelle profondità della ⟦Wailing Caverns=Caverna dei Lamenti⟧.", "I ricordi dei miei incubi mi perseguitano, {name}. Hai sconfitto i capi dei Druids of the Fang e preso le loro gemme?", "Ce l'hai fatta, {name}. Hai ucciso i capi dei Druids of the Fang. I miei sogni ora sono liberi dai loro volti malvagi, e hai aiutato a salvare le ⟦Barrens=Savane⟧ da un futuro maledetto.\n\nTi ringrazio, {name}. Ti ringrazio per me, per i druidi di ⟦Thunder Bluff=Picco del Tuono⟧ e per questa terra.", 0xe577280d, 0x4f7a87a2, 0x8280e4ae, 0x40d9e1ec, 0xbcdaf980, "....." },
  [916] = { "Veleno di Telalegno", "Porta 10 Webwood Venom Sac a Gilshalan Windwalker ad Aldrassil.", "Sono venuto a ⟦Shadowglen=Vallombra⟧ per osservare i ragni Telalegno che vivono nella ⟦Shadowthread Cave=Caverna Telabuia⟧. Sono parenti di una varietà di ragno molto più piccola; credo che l'albero del mondo abbia avuto su di loro un effetto profondo, e vorrei degli esemplari da studiare per confermarlo.\n\nPer prima cosa, mi serve un po' del loro veleno. Raccogli le sacche di veleno dei ragni Telalegno dentro e intorno alla ⟦Shadowthread Cave=Caverna Telabuia⟧, a nord. Poi potrò esaminarle per cercare somiglianze con il veleno dei loro cugini più piccoli.", "Hai raccolto le sacche di veleno, {name}?", "Grazie, {name}. Quando tornerò a Darnassus confronterò il veleno di queste sacche con quello di altri ragni. Sono convinto che avrà proprietà legate alla recente crescita del nostro nuovo albero del mondo.", 0x5ef3699f, 0xcd2d6c5d, 0x328f2ab5, 0x0d16764a, 0x93e71cf8, "....." },
  [917] = { "⟦Webwood Egg=Uovo di Telalegno⟧", "Porta un ⟦Webwood Egg=Uovo di Telalegno⟧ a Gilshalan, ad Aldrassil.", "Ora che ho il veleno dei ragni, vorrei degli esemplari vivi da studiare. Purtroppo catturare un ragno gigante vivo è più di quanto possa chiederti, giovane {class}. E un ragno gigante è più di quanto io stesso potrei gestire!\n\nMa se riesci a trovare un uovo non ancora schiuso, portare gli esemplari sarà molto più facile, e poi potrò far custodire i ragni non ancora nati.\n\nDeve esserci un nido nel profondo della ⟦Shadowthread Cave=Caverna Telabuia⟧. Ti prego, cerca un uovo nel nido e portamelo.", "Sei entrat<o/a> nella ⟦Shadowthread Cave=Caverna Telabuia⟧, {name}? Hai trovato un uovo di ragno?", "Ah, molto bene. Farò trasportare questo uovo e il veleno a Darnassus, poi ci tornerò quando avrò finito i miei studi qui. Mi aspetto di scoprire molto da questi esemplari, {name}. Mi sei stat<o/a> di grande aiuto.", 0x45dca847, 0xe3b29d22, 0x81a464b0, 0x04406a66, 0x2017b57d, "....." },
  [918] = { "Semi di timberling", "Porta 8 Timberling Seed a Denelan al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "I timberling di Teldrassil sono elementali della natura. In un certo senso riflettono l'ordine naturale di piante e animali sul nostro grande albero.\n\nPerciò è preoccupante vedere quanto si siano infuriati.\n\nCredo che abbia a che fare con il terreno. Sto sperimentando diversi metodi per nutrire le piante e vorrei provarli sui semi di timberling. Ti prego, puoi raccogliere i semi dei timberling intorno al ⟦Lake Al'Ameth=Lago Al'ameth⟧ e portarmeli?", "Hai i semi? Non vedo l'ora di piantarli.", "Ce l'hai fatta. Ottimo!\n\nPianterò questi semi in un terreno speciale che ho preparato. Credo che dai semi nasceranno timberling molto più docili. Forse più avanti potrai vedere i risultati!", 0xc2c5c9a3, 0x25b24cca, 0x6bd8e4d3, 0x0e19807b, 0xe481e8bb, "....." },
  [919] = { "Germogli di alberiano", "Porta 12 Timberling Sprout a Denalan al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Piccoli alberiani stanno germogliando intorno alle acque del ⟦Lake Al'Ameth=Lago Al'ameth⟧. Temo che per questi germogli non ci sia più niente da fare: dovremmo cercare di ripulirne la terra prima che crescano abbastanza da causare guai.\n\nMentre giri per il lago, se vedi dei germogli di alberiano, prendili. Aiutaci a mantenere pulita la nostra terra!", "Ciao, {name}. Hai trovato dei germogli vicino alle acque?", "Sono tanti! Temo che si stiano diffondendo a un ritmo pericoloso. Spero di riuscire a risolvere il mistero di cosa li stia contaminando.\n\nGrazie per il tuo aiuto, {name}. Grazie ai tuoi sforzi la terra è un posto più pulito.", 0x51165847, 0x6fa3313a, 0x3ae4085a, 0xe4c0ddfe, 0xf442a65d, "....." },
  [920] = { "La convocazione di Tenaron", "Parla con Tenaron Stormgrip in cima ad Aldrassil, a ⟦Shadowglen=Vallombra⟧.", "{name}, giusto? Ho sentito che Tenaron ti sta cercando. Lo troverai nella stanza più alta, in cima ad Aldrassil.\n\nAvremo anche vite lunghe, ma è meglio non farlo aspettare troppo.", nil, "Ah, {name}. Speravo che rispondessi prontamente alla mia convocazione. Ho un compito importante che vorrei affidarti.", 0xde22b969, 0x7548d88d, 0x92b7f833, nil, 0x7330b9e5, "...m." },
  [921] = { "La corona della terra", "Riempi la ⟦Crystal Phial=Fiala di Cristallo⟧ e riportala a Tenaron Stormgrip, in cima ad Aldrassil.", "È tempo che tu parta in cerca del tuo destino, {name}. Ma prima di essere pront<o/a> ad avventurarti nel mondo oltre le nostre foreste incantate, devi imparare molto sulla nostra storia recente.\n\nMolto è cambiato per il nostro popolo dalla Battaglia del ⟦Mount Hyjal=Monte Hyjal⟧. Nordrassil è una pallida ombra di ciò che era un tempo: il suo potere è stato usato per sconfiggere Archimonde e respingere la Legione Infuocata...\n\nC'è un compito che devi svolgere. Va' al pozzo lunare a nord di Aldrassil e portami una fiala della sua acqua.", "I pozzi lunari contengono le acque del ⟦Well of Eternity=Pozzo dell'Eternità⟧, l'antica fonte di magia che ha portato così tanti orrori nel nostro mondo.\n\nI druidi sfruttano le sue proprietà e le ⟦Sentinels=Sentinelle⟧ venerano i pozzi come santuari di Elune, ma la stregoneria è proibita a tutti.", "Così hai ascoltato la prima parte di ciò che accadde dopo la Battaglia del ⟦Mount Hyjal=Monte Hyjal⟧. C'è molto altro da raccontare, e il compito che hai iniziato qui proseguirà per il resto del tuo viaggio attraverso Teldrassil e fino a Darnassus.", 0x6a9c354f, 0x6f20ec86, 0x63729cf0, 0x92295015, 0x4972e13e, "....." },
  [922] = { nil, "Porta un ⟦Timberling Seed=Seme di Alberiano⟧ a Rellian Greenspyre a Darnassus.", "{name}, puoi portare uno dei semi che mi hai dato al mio amico Rellian Greenspyre? È un druido di Darnassus e, l'ultima volta che ci siamo parlati, mi ha rivelato il suo interesse per il mio lavoro sugli alberiani. Ha anche lui alcune idee e apprezzerà un seme campione con cui lavorare.\n\nGrazie, {name}. Mi sei stat<o/a> di grande aiuto. Spero che un giorno vedrai i frutti delle mie fatiche.\n\nDi solito troverai Rellian a passeggio lungo i sentieri dell'⟦Cenarion Enclave=Enclave Cenariana⟧, a Darnassus.", "Salve...\n\nCome posso aiutarti?", "Ah, un seme di alberiano? Volevo provare a coltivarne uno per aiutare Denalan nei suoi studi.\n\nMa temo di aver scoperto che in molti alberiani è cresciuta una corruzione, e i semi di queste creature portano la contaminazione dei genitori. Ripararli va oltre le mie capacità.\n\nDenalan è molto abile con tutto ciò che cresce. Potrebbe trovare una cura per i futuri alberiani. Potrebbe essere la loro unica speranza.", 0x57fb1b20, 0x0cd55696, 0x31859f95, 0x36a1f94a, 0x61b8489f, "e...." },
  [923] = { "Tumori", "Porta 5 Mossy Tumor a Rellian Greenspyre, a Darnassus.", "Nei timberling sta crescendo una malvagità. Stiamo cercando di scoprirne l'origine, ma finché non ci riusciremo... per tenere al sicuro Teldrassil dobbiamo abbattere i timberling che non possono più essere salvati. Quelli che vagano attorno al ⟦Wellspring Lake=Lago di Buonpozzo⟧, nel nord di Teldrassil, sono i più corrotti. Vanno eliminati!\n\nDistruggi i timberling che trovi laggiù e raccogli i tumori muschiosi che crescono su di loro. Portami i tumori, così che possano essere bruciati.", "Sei <stato/stata> al ⟦Wellspring Lake=Lago di Buonpozzo⟧, {name}? Hai dato la caccia ai timberling che ci sono?", "Ben fatto! Questi tumori sono il sintomo della malattia dei timberling. Sono pieni di un veleno che dobbiamo estirpare dalla nostra nuova terra.\n\nMi occuperò io di distruggere questi tumori. Grazie, {name}.", 0x9be57a52, 0xd33dba21, 0x8c75928f, 0x75561cf5, 0xab86b70c, "....." },
  [924] = { "Il Demon Seed", "Prendi una ⟦Flawed Power Stone=Pietra del Potere Difettosa⟧. Portala all'altare del fuoco prima che la pietra si esaurisca, poi torna da Ak'Zeloth.", "Il Demon Seed è un potente strumento della Legione Infuocata. Si trova in una grotta sul ⟦Dreadmist Peak=Picco di Brumafunesta⟧, sopra un altare del fuoco demoniaco.\n\nHo preparato delle pietre del potere che, poste vicino al Seed, ne spezzeranno il legame con la Legione.\n\nPrendi una pietra dal tavolo e portala all'altare del fuoco in cima al ⟦Dreadmist Peak=Picco di Brumafunesta⟧. Va' a ovest, poi a nord quando la strada si biforca. Il Picco sarà alla tua sinistra. La salita più sicura verso la cima è sul versante settentrionale.\n\nE sbrigati: il potere della pietra si consumerà col tempo.", "Il Demon Seed esiste ancora. Ne avverto il potere...", "Il tuo compito è concluso. Hai distrutto il Demon Seed come chiedeva Neeru. Ma questa non è la fine...\n\nLa distruzione del Demon Seed ha mandato ondate di potere attraverso l'etere, ondate di una forza sconvolgente. Le ho percepite, e sono certo che le abbiano percepite anche altri esseri. Altri che si chiederanno perché il loro giocattolo è stato rotto...\n\nMa, a prescindere dai guai futuri, ho qualcosa per te. Neeru l'ha mandato come compenso. E mi ha chiesto di ringraziarti.\n\nQuindi, grazie.", 0x07a08d0b, 0xc93af534, 0xbe65b854, 0x7f1f8d44, 0xf41f35c3, "....." },
  [926] = { "⟦Flawed Power Stone=Pietra del Potere Difettosa⟧", nil, nil, nil, "Queste pietre sono intrise di energia magica, ma volutamente difettose. Sono molto instabili e, una volta tolte dal tavolo, si consumeranno in fretta.", 0xbfd0ccf1, nil, nil, nil, 0x79072959, ".mmm." },
  [927] = { nil, "Porta il Moss-twined Heart a Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Il cuore di Blackmoss the Fetid è ricoperto da un muschio scuro e oleoso. A dire il vero, l'unico modo per capire che si tratta di un cuore è il suo battito lento e ritmico... un battito che continua ancora adesso.\n\nForse Denalan vorrà vedere questo cuore.", "{name}! Hai qualcosa per me?", "... Cos'è questo? Il cuore di un timberling?? È ricoperto di un muschio immondo!\n\nGrazie per avermelo portato, {name}. Esaminerò il cuore e, se la fortuna ci assiste, scoprirò la natura del muschio che lo avvolge.", 0x8ab57346, 0x174962f9, 0x3bdb0906, 0xdfd947e9, 0x5c540383, "e...." },
  [928] = { "La corona della terra", "Porta l'⟦Partially Filled Vessel=Ampolla Mezza Piena⟧ a Corithras Moonrage, a Dolanaar.", "Potrei dirti molto altro sui pozzi lunari e su Teldrassil, ma devo mandarti avanti. Corithras Moonrage ti aspetta. Ho versato la fiala d'acqua che mi hai portato in questa ampolla, da portare a lui.\n\nCerca Corithras. Lo troverai al pozzo lunare di Dolanaar. Segui la strada verso sud da Aldrassil fuori da ⟦Shadowglen=Vallombra⟧, e continua a seguire l'acciottolato quando la strada piega a ovest.\n\nMa bada di restare sulla strada, {name}. Di recente nelle foreste si aggirano bestie pericolose.", "Salute, {class}. A cosa devo il piacere di questo incontro?", "Ah, capisco. Ti ha mandato Tenaron. Be', allora sembra che abbiamo molto di cui parlare, molto da fare e poco tempo per farlo.\n\nCredo sia meglio cominciare.", 0x6a9c354f, 0x519e561b, 0x69be4dda, 0xa03c786d, 0xd5848e6f, "....." },
  [929] = { "La corona della terra", "Riempi la ⟦Jade Phial=Fiala di Giada⟧ e riportala a Corithras Moonrage, a Dolanaar.", "Prima lascia che ti dica di più sul compito che devi portare a termine. I druidi di Darnassus usano l'acqua dei pozzi lunari di Teldrassil, e il loro pozzo lunare va rifornito di tanto in tanto. Con queste fiale fatte apposta puoi raccogliere l'acqua dei pozzi lunari.\n\nPorta questa ampolla al pozzo lunare fuori da ⟦Starbreeze Village=Brezzastella⟧, a est, riempila con un po' della sua acqua e torna da me. Quando avrai completato il compito, riprenderò la storia da dove l'ha lasciata Tenaron...", "Ben ritrovat<o/a>, {name}. Hai completato il tuo compito?", "Dopo la Battaglia del ⟦Mount Hyjal=Monte Hyjal⟧, eravamo senza una guida. Nordrassil fumava per il fuoco che aveva scatenato, e la nostra immortalità (l'essenza stessa del nostro essere!) era perduta.\n\nFu in quel periodo difficile che il Traditore venne liberato dalla sua prigione e lo Shan'do Stormrage scomparve. Un'epoca buia per tutti.", 0x6a9c354f, 0x188ad811, 0x725fcab1, 0xd7878828, 0x95ab8c86, "....." },
  [930] = { "Il ⟦Glowing Fruit=Frutto Brillante⟧", "Porta il frutto brillante a Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Sotto le fronde di questa pianta luminosa pende un grosso frutto rotondo.\n\nSei cert<o/a> che Denalan vorrebbe studiarlo.", "{name}, sembra che tu abbia qualcosa da dirmi. Hai notizie sugli alberiani?", "L'hai trovato su Teldrassil? Interessante... questo frutto è esotico. Forse i suoi semi sono stati portati qui da molto lontano. Forse persino da Azeroth! E c'è qualcosa in questo frutto... sembra aver reagito in modo molto strano con il suolo di Teldrassil.\n\nGrazie, {name}. Ora, se vuoi scusarmi, devo studiarlo più a fondo...", 0xa2834fd5, 0x29dd07f4, 0x84397c8e, 0x2532fbc0, 0x2ea98bd6, "....." },
  [931] = { "La ⟦Shimmering Frond=Fronda Scintillante⟧", "Porta una ⟦Shimmering Frond=Fronda Scintillante⟧ a Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Le fronde di questa pianta scintillano nella luce della foresta, avvolgendola in un'aura pulsante e cangiante.\n\nPensi che Denalan ne vorrebbe un esemplare.", "Hai qualcosa per me?", "Dove l'hai preso? Non vedevo una pianta così da quando feci un viaggio nella ⟦Swamp of Sorrows=Palude del Dolore⟧... decenni fa! È incredibile che un esemplare sia arrivato fino a Teldrassil. E che sia cresciuto così tanto!\n\nGrazie, {name}. Perdona la mia brevità, ma c'è un esperimento che vorrei fare su questa fronda...", 0x3dda56af, 0xe2d17f64, 0xd3966077, 0xa03be4c2, 0xa5f2249f, "....." },
  [932] = { "Odio contorto", "Uccidi Lord Melenas e porta la sua testa a Tallonkai Swiftroot a Dolanaar.", "Devo avvertirti, {name}: questa faccenda deve restare tra noi. I satiri sono già abbastanza motivo di imbarazzo per noi, e questo è fin troppo vicino a casa.\n\nSi fa chiamare Lord Melenas. Risiede nella vicina grotta di ⟦Fel Rock=Vilroccia⟧, dove ha radunato un folto gruppo di guerrieri grell. Il suo cuore è nero come la notte, e trama qualcosa di estremamente malvagio.\n\nDevi trovarlo nella sua grotta, poco a nord di qui, e portarmi la sua testa.", "Hai già ucciso Lord Melenas? È fondamentale che ce ne occupiamo in fretta e in silenzio, {name}. Il fatto che esista ancora è un imbarazzo per tutti noi.", "Ora che Lord Melenas riposa in pace, posso finalmente passare ad altre faccende. Grazie, {name}.", 0x10738b8e, 0xa49ba15f, 0xbc655ff9, 0x7bab7e42, 0x4a8d372b, "....." },
  [933] = { "La corona della terra", "Riempi la ⟦Tourmaline Phial=Fiala di Tormalina⟧ e riportala a Corithras Moonrage, a Dolanaar.", "C'è un altro pozzo lunare a sud-est dell'ingresso di Darnassus, sulle rive delle ⟦Pools of Arlithrien=Pozze di Arlithrien⟧. Le ⟦Sentinels=Sentinelle⟧ hanno difficoltà a pattugliare la zona a causa degli attacchi e dell'indole sempre più aggressiva dei mezzorsi ⟦Gnarlpine=Mordipigna⟧.\n\nStai in guardia mentre cerchi il pozzo, e tieni le armi a portata di mano.", "All'inizio le notizie di attacchi di mezzorsi impazziti non furono prese sul serio. Chi avrebbe mai pensato che i pacifici uomini-orso si sarebbero abbandonati a una furia cieca? L'ennesimo dei problemi che ci affliggono qui, nella nostra nuova casa.", "Shan'do Stormrage non fece mai ritorno, i druidi caddero nello scompiglio e ancora oggi non sappiamo che ne sia stato di lui. Con la scomparsa di Malfurion, l'Arcidruido Fandral Staghelm assunse la guida dei druidi e convinse il Circle of Ancients di ⟦Darkshore=Rivafosca⟧ che era giunto il momento per il nostro popolo di ricostruire, e di riconquistare l'immortalità.\n\nCon l'approvazione del Circolo, Staghelm e i druidi più potenti fecero crescere Teldrassil, il nuovo Albero del Mondo.", 0x6a9c354f, 0x3d0857d5, 0x4d68f2e0, 0x531af2f0, 0x63415c4c, "....." },
  [934] = { "La corona della terra", "Riempi la ⟦Amethyst Phial=Fiala di Ametista⟧ e riportala a Corithras Moonrage, a Dolanaar.", "Non tutto andava bene a Teldrassil, però. I piani accurati di Staghelm per il nuovo Albero del Mondo si erano realizzati come sperava, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nMa non ne parlerò ancora. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nella Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e il più potente dei nostri pozzi. Prendi una fiala della sua acqua e torna da me.", "Insieme ai druidi, l'Oracle Tree e l'arcidruido hanno sorvegliato con cura la crescita di Teldrassil. Ma anche se abbiamo una nuova casa, la nostra vita immortale non ci è stata restituita.", "Trovarsi al cospetto dell'Oracle Tree... è quasi come sentire la saggezza prendere forma. Lasciami continuare il racconto...\n\nQuando Teldrassil fu cresciuto, l'arcidruido si rivolse ai draghi per avere le loro benedizioni, come quelle che i draghi avevano concesso a Nordrassil in tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di dare la sua benedizione, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm, e senza la sua benedizione la crescita di Teldrassil è stata imperfetta e imprevedibile...", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [935] = { "La corona della terra", "Porta l'⟦Filled Vessel=Ampolla Piena⟧ all'arcidruido Fandral Staghelm, a Darnassus.", "Senza le benedizioni di Alexstrasza la Protettrice della Vita e di Nozdormu il Senza Tempo, la crescita di Teldrassil non è stata priva di difetti. Si parla di strane bestie che sorgono dal terreno stesso dell'albero, e di mezzorsi impazziti che attaccano i viaggiatori di passaggio.\n\nPosso solo sperare che la soluzione che l'arcidruido sta cercando venga trovata presto. Verserò tutte le fiale che mi hai portato in questa ampolla, perché tu la consegni a Darnassus.\n\nPortala a Fandral Staghelm: lo troverai nel bosco dei druidi.", "So di non averti <convocato/convocata>, quindi non posso fare a meno di chiedermi perché tu sia <venuto/venuta> a parlarmi.\n\nQualunque cosa sia, ti prego, fa' in fretta.", "Ah sì, l'acqua che avevo richiesto. Tenaron e Corithras se la sono presa comoda nel farmela recapitare... forse non hanno scelto il più affidabile dei messaggeri... mmm.\n\nComunque sia, finalmente posso tornare al mio lavoro. Il peso dei problemi di Teldrassil grava sulle mie spalle. Un giogo di cui vorrei liberarmi presto.\n\nPrendi questo, potrebbe esserti utile.", 0x6a9c354f, 0x1325e4e5, 0x54cda088, 0xaf4b925e, 0xf477d1e8, "....." },
  [937] = { "La radura incantata", "Procurati 6 Bloodfeather Belt e portale alla sentinella Arynia Cloudsbreak, nella Oracle Glade.", "Sono stata mandata qui con un piccolo gruppo di ⟦Sentinels=Sentinelle⟧ per proteggere l'Oracle Tree dalle arpie che hanno fatto il nido tutto intorno alla radura. Poco a poco cerchiamo di respingerle.\n\nQuando l'Oracle Tree ha tentato di mandare un messaggero a Darnassus con un rapporto, il messaggero è stato attaccato e ucciso da un gruppo di arpie.\n\nSe te la senti, va' ai loro nidi, uccidile e riportami le loro cinture come prova delle tue imprese.", "I loro artigli taglienti e i loro becchi aguzzi potrebbero mettere a dura prova le tue capacità, {name}, ma ho fiducia che non fallirai in questo compito.", "Sono colpita da ciò che hai ottenuto qui in così poco tempo, {name}. Vorrei poterti chiedere di restare ad aiutarmi nei miei doveri... ma so nel mio cuore che ti attendono compiti più grandi.\n\nHo notato che l'Oracle Tree ha appena perso un pezzo della sua corteccia. Senza dubbio ha un compito che desidera veder portato a termine. Dovresti parlargli.", 0xc112d404, 0x3f1ffacf, 0x6aee024a, 0x465cb007, 0x5c5a347c, "....." },
  [938] = { nil, "Scorta Mist dalla sentinella Arynia Cloudsbreak, al pozzo lunare vicino all'Oracle Tree.", "La pelliccia della tigre dai denti a sciabola è di un grigio caratteristico, che si confonde con la foresta circostante. Mentre giace lì, noti che è gravemente ferita, con profonde lacerazioni sul dorso e sul ventre.\n\nAlza la testa e ti guarda, con una vivida intelligenza che brilla negli occhi azzurri. Sembra voler venire con te.", "Mist... È stata colpa mia! Le streghe mi hanno colta di sorpresa... Non avrei dovuto lasciare che ti prendessero...", "Oh, grazie, {name}! Temevo che non avrei mai più rivisto Mist, che nel mio cuore avrei conosciuto solo la sua morte, senza mai potermi riunire alla mia fedele compagna. Ti devo più di quanto tu possa immaginare, e hai la mia eterna gratitudine.", 0x0a6d119d, 0x87fed568, 0x72d756dc, 0xeca87270, 0x849d34d3, "e...." },
  [940] = { nil, "Consegna la ⟦Inscribed Bark=Corteccia Incisa⟧ all'arcidruido Fandral Staghelm, a Darnassus.", "La foresta sussurra delle tue imprese valorose, {name}. Quando ho sentito le arpie cacciate dai loro nidi, una calma più grande si è diffusa nella foresta, e le sue creature si sono sentite di nuovo al sicuro. Temevo di mandare un altro messaggero all'arcidruido, ma so che gli porterai il mio messaggio sano e salvo.\n\nConsegnagli questo, e sappi che la foresta veglierà su di te lungo i suoi sentieri fino alla foresta di pietra.", "Mmm... Porti con te lo spirito della foresta, forte dentro di te, {class}. Che affari hai con l'arcidruido dei Kaldorei?", "Mi chiedevo perché l'Oracle Tree non comunicasse con me da così tanto tempo... Pare che alcuni problemi si attenuino, mentre altri diventano preoccupazioni più grandi.\n\nTemo che il mio lavoro su Teldrassil non sarà mai completato, e che la nostra immortalità non ci sarà mai restituita.\n\nComunque sia, hai svolto bene il compito dell'Oracle Tree, e meriti una ricompensa per la tua diligenza.", 0x26414cf4, 0x3d134466, 0xd95bd925, 0xba14a37c, 0x4699ba60, "e...." },
  [941] = { "Piantare il cuore", "Pianta il ⟦Tainted Heart=Cuore Corrotto⟧ nella fioriera di Denalan.", "Ho tolto quel muschio immondo dal cuore, ma resta corrotto...\n\nProva a mettere il cuore nella mia fioriera. È piena di un terriccio nutriente che potrebbe purificarlo e guarirlo.", "Questa fioriera è piena di terriccio, preparato appositamente da Denalan.", "Metti il cuore nella fioriera, e quello si interra subito!\n\nPochi secondi dopo riemerge contorcendosi, purificato. Pulsa leggermente... come se ti invitasse a prenderlo.", 0x65f8fb52, 0xe00d7701, 0x54612342, 0xda090df6, 0x4660d6c8, "....." },
  [942] = { "Il prospettore distratto", "Porta il fossile misterioso all'archeologo Flagongut a ⟦Menethil Harbor=Porto di Menethil⟧.", "Questo fossile somiglia in modo impressionante a uno che vidi una volta a ⟦Ironforge=Forgiardente⟧. Un archeologo di nome Flagongut lo portò al nostro convegno annuale della ⟦Explorers' League=Lega degli Esploratori⟧. Era convinto che il fossile racchiudesse un potere che in qualche modo si poteva risvegliare.\n\nL'ultima volta che ne ho avuto notizia, Flagongut si era rintanato alla ⟦Deepwater Tavern=Locanda Acquefonde⟧ di ⟦Menethil Harbor=Porto di Menethil⟧, in attesa di una scorta per il Whelgar Excavation Site. Cercalo e mostragli il fossile di Remtravel. Forse saprà svelare i segreti del passato.\n\nLa nave per Menethil parte da Auberdine.", "Che cos'hai lì, amico?", "Oh, cielo! Dici che viene dalle lontane terre di Kalimdor?\n\nIncredibile! Semplicemente incredibile!", 0xb9653d3d, 0xfc29c252, 0x961f86d3, 0x8fb7e5ca, 0xd1acd945, "....." },
  [943] = { "Il prospettore distratto", "L'archeologo Flagongut, a ⟦Menethil Harbor=Porto di Menethil⟧, vuole che tu gli porti la ⟦Stone of Relu=Pietra di Relu⟧ e il ⟦Flagongut's Fossil=Fossile di Granrutto⟧.", "Il prospettore Whelgar ora custodisce il fossile originale nel suo sito di scavo nelle ⟦Wetlands=Paludi Grigie⟧. Quando ho scoperto la ⟦Stone of Relu=Pietra di Relu⟧, ho creduto che fosse la chiave per svelare il mistero del fossile.\n\nMentre ero in viaggio per incontrare Whelgar, sono stato attaccato dai raptor e la reliquia è andata perduta. Non so quale di quelle bestie chiazzate l'abbia inghiottita, ma se riesci a recuperarla potrò liberare il potere di questi manufatti.\n\nPortami sia la ⟦Stone of Relu=Pietra di Relu⟧ sia il fossile originale che custodisce lui.", "Con la ⟦Stone of Relu=Pietra di Relu⟧ potrò liberare i segreti nascosti del mio fossile e anche di quello di Remtravel, da ⟦Darkshore=Rivafosca⟧, {name}.", "Eccellente, {name}!\n\nOra vediamo se riesco a usare la pietra per decifrare i poteri dei fossili.", 0xb9653d3d, 0x2f21bebd, 0x53989e47, 0x7833064e, 0xa4671511, "....." },
  [944] = { "⟦The Master's Glaive=Gladio del Maestro⟧", "Raccogli informazioni, poi usa la ⟦Phial of Scrying=Fiala della Chiaroveggenza⟧ per creare una Scrying Bowl. Usa la ciotola per parlare con Onu.", "È strano che i naga siano qui, a ⟦Darkshore=Rivafosca⟧. Ma ancora più strano... è il ⟦Twilight's Hammer=Martello del Crepuscolo⟧. Quel culto venera gli antichi, antichissimi signori della terra. Signori sconfitti molto tempo fa.\n\nIl ⟦Master's Glaive=Gladio del Maestro⟧, a sud, è un luogo dove cadde uno di quegli antichi signori.\n\nVa' laggiù e cerca altri cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.\n\nPrendi questa fiala della chiaroveggenza. Usala per creare una ciotola della chiaroveggenza dopo aver perlustrato il ⟦Master's Glaive=Gladio del Maestro⟧. Poi parlami attraverso la ciotola.", "Il ⟦The Master's Glaive=Gladio del Maestro⟧, {name}.\n\nVa' laggiù, poi parla di nuovo con me.", "Il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ è al ⟦Master's Glaive=Gladio del Maestro⟧?\n\nSpiacevole.\n\nL'antico signore trafitto dal gladio è morto da tempo, ma questo non significa che non ne restino ancora frammenti di potere.\n\nIl ⟦Twilight's Hammer=Martello del Crepuscolo⟧ deve essere in cerca di quel potere.", 0xabfa3b4e, 0x950cae03, 0x671bb4a4, 0x27463bf7, 0xdb98b446, "....." },
  [945] = { "La fuga di Therylune", "Aiuta Therylune a fuggire, poi di' a Therysil, allo Shrine of Aessina, che sua sorella è salva.", "Aiuto!\n\nStavo girovagando per il ⟦Master's Glaive=Gladio del Maestro⟧ e questi luridi cultisti mi hanno circondata. Per fortuna sono brava a nascondermi!!\n\nPuoi aiutarmi a uscire di qui? E devo far sapere a mia sorella Therysil che sto bene. È a ⟦Ashenvale=Valtetra⟧, a sud, allo Shrine of Aessina.", nil, "Mia sorella era dove?? A Therylune non dispiace sporcarsi le mani, ma insomma! È una bella camminata, e il ⟦Master's Glaive=Gladio del Maestro⟧ è un posto malsano...\n\nBe', grazie, {name}. Sei stat<o/a> davvero gentile a farmi sapere che sta bene.", 0x108df69c, 0x3b1c1761, 0xed177776, nil, 0x2b7ac90f, "...m." },
  [947] = { "Funghi della caverna", "Porta 5 Scaber Stalk e 1 ⟦Death Cap=Cappella Mortifera⟧ a Barithras Moonshade ad Auberdine.", "Sto ideando una pozione che richiede funghi rari, funghi che crescono soltanto in una certa caverna. La caverna si trova dietro le ⟦Cliffspring Falls=Cascate di Altafonte⟧, a est e un po' a nord lungo le montagne.\n\nCi andrei io stesso, ma il ⟦Grove of the Ancients=Bosco degli Antichi⟧ mi ha consigliato di stare lontano da quel luogo. I nostri venerabili alleati percepiscono che la caverna è il nascondiglio di un nuovo male a ⟦Darkshore=Rivafosca⟧.\n\nTi prego, {name}, raccogli i funghi per me. E già che ci sei, esplora la caverna per confermare i timori degli Antichi.", "Hai i miei funghi, {name}? Sei stat<o/a> alla caverna?", "Mille grazie, {name}. Questi funghi sono esemplari magnifici!\n\nE quando eri alle ⟦Cliffspring Falls=Cascate di Altafonte⟧, hai trovato qualcosa che confermi gli avvertimenti degli Antichi?\n\nGli Antichi sono saggi, ma speravo che, questa volta, si sbagliassero.", 0xe674f448, 0xe01d023c, 0x2758e8e4, 0xcf4d0564, 0x4ed87853, "....." },
  [948] = { nil, "Parla con Onu nel ⟦Grove of the Ancients=Bosco degli Antichi⟧.", "Onu, un Ancient of Lore del ⟦Grove of the Ancients=Bosco degli Antichi⟧, è al corrente del tuo viaggio alle Cascate di Altafonte e desidera parlarti. Il bosco si trova a sud, adagiato vicino alle montagne.\n\nGli Antichi sono pazienti e saggi, {name}. Ma se Onu cerca il tuo consiglio su ciò che hai visto alle cascate, temo che sia urgente.", nil, "{name}. Sei qui.\n\nBene.\n\nAbbiamo questioni... di cui discutere. Tu e io.", 0x0014e886, 0xed0d7f6a, 0xf32fed85, nil, 0x8d028ef5, "e..m." },
  [949] = { "L'accampamento del Crepuscolo", "Trova un indizio nell'accampamento del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ al ⟦Master's Glaive=Gladio del Maestro⟧.", "Lo scopo del Martello del Crepuscolo al ⟦Master's Glaive=Gladio del Maestro⟧ non è noto. Ma dev'essere oscuro.\n\nPerquisisci il loro accampamento al Gladio... Cerca qualcosa che possa svelarci le loro intenzioni.\n\nPerché dobbiamo conoscere le loro intenzioni prima di decidere un piano.", nil, "Questo libro è scritto a mano in una lingua antica e illustrato da un maestro artista.", 0x08317362, 0x27ef0e95, 0x330bad56, nil, 0x76b4c2ab, "...m." },
  [950] = { "Ritorno da Onu", "Porta a Onu gli ⟦Insane Scribbles=Scarabocchi Folli⟧ che hai recuperato.", "Scrutare il Twilight Tome fa impazzire. Dopo un solo sguardo il testo comincia a ondeggiare e danzare, e quelli che erano splendidi fregi si contorcono in forme grottesche.\n\nRiesci soltanto a strappare una pagina di scarabocchi folli prima che uno svenimento ti colga.", "{name}. Sei tornat<o/a>.", "Una magia caotica e primordiale avvolge questa pergamena di scarabocchi. Vi percepisco l'opera degli antichi dèi.\n\nSperiamo che riveli lo scopo del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ a ⟦Darkshore=Rivafosca⟧...", 0xcaaab2e6, 0xf6b0f093, 0x4cbe9339, 0x6065f49a, 0x508596c3, "....." },
  [951] = { "Reliquie di Mathystra", "Porta 6 Mathystra Relic a Onu al ⟦Grove of the Ancients=Bosco degli Antichi⟧.", "La pergamena che hai trovato al ⟦Master's Glaive=Gladio del Maestro⟧ è una pagina di un testo antico... scritto dagli elfi! È pesantemente maledetta e contaminata dalla corruzione del ⟦Twilight's Hammer=Martello del Crepuscolo⟧, ma sembra che il culto stia usando antica magia elfica per riportare i suoi vecchi padroni nel nostro mondo.\n\nRaggiungi le rovine di Mathystra a nord-est e cerca reliquie antiche tra l'erba e le pietre spezzate. Studiandole, potremo capire in che modo il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ intende sfruttare la magia degli elfi.", "{name}. Le tue ricerche tra le ⟦Ruins of Mathystra=Rovine di Mathystra⟧ hanno dato frutti?", "Grazie. Queste reliquie risalgono a un'epoca in cui Mathystra splendeva. Quel bastione degli elfi, un tempo grandioso, è decaduto, ma ne restano frammenti di magia. Speriamo di riuscire a svelare i segreti di quel luogo prima dei nostri nemici...\n\nSta' all'erta, {name}.", 0x522689ce, 0x1bae28a2, 0x8ad041ac, 0xf6dded2e, 0xdf4141bd, "....." },
  [952] = { "⟦Grove of the Ancients=Bosco degli Antichi⟧", "Consegna il messaggio di Fandral a Onu, nel ⟦Grove of the Ancients=Bosco degli Antichi⟧ a ⟦Darkshore=Rivafosca⟧, a sud di Auberdine.", "Se hai avuto abbastanza tempo da portare messaggi per l'Oracle Tree, sono certo di poterti arruolare per consegnare un messaggio al ⟦Grove of the Ancients=Bosco degli Antichi⟧, a ⟦Darkshore=Rivafosca⟧, proprio a sud di Auberdine.\n\nProbabilmente dovrai procurarti un passaggio su un ippogrifo, ma ho abbastanza fiducia in te da credere che ce la farai. Porta questo a Onu, l'Antico del Sapere. Attende mie notizie, così come io attendevo notizie dalla Oracle Glade.", "Ah. {class}. Come può Onu esserti d'aiuto?", "Ah. Grazie, {name}. È strano, però. L'arcidruido sembra sempre così di fretta. La foresta sa che tutto avverrà a tempo debito. Shan'do Stormrage lo capiva.", 0x44207422, 0x8512a341, 0x323a6b71, 0xee3400fd, 0xe747f116, "....." },
  [953] = { "La caduta di ⟦Ameth'Aran=Ameth'aran⟧", "Studia le tavolette che narrano di ⟦Ameth'Aran=Ameth'aran⟧ e della sua caduta, poi torna dalla sentinella Tysha Moonblade, a ⟦Darkshore=Rivafosca⟧.", "A est troverai le rovine di ⟦Ameth'Aran=Ameth'aran⟧. Ora sono abitate dagli spiriti inquieti degli ⟦Highborne=Alti Nobili⟧ che un tempo vivevano tra le sue mura, ma un tempo era un luogo in cui i servitori di Azshara praticavano liberamente le loro potenti magie.\n\nMi hanno mandata a esplorare le rovine e mi sono imbattuta in due grandi tavolette, incise con la storia di ⟦Ameth'Aran=Ameth'aran⟧ e della sua caduta. Mentre leggevo le rune, gli spiriti mi hanno assalita e sono fuggita.\n\nTi prego, se puoi, va' alle rovine e decifra le tavolette al posto mio.", "Quando avrai studiato le tavolette e scoperto la caduta di Ameth'aran, porterò queste conoscenze ad Auberdine e informerò il Circle of Ancients.", "Abbiamo poche testimonianze del periodo della War of the Ancients, specialmente di quello vicino alla distruzione del ⟦Well of Eternity=Pozzo dell'Eternità⟧. Dati gli sconvolgimenti e gli eventi catastrofici che stavano avvenendo, non c'è da stupirsi.\n\nGrazie, {name}. Con il tuo aiuto il mio lavoro qui è concluso e potrò consegnare un rapporto completo al Circolo.", 0x6ea45cc6, 0x4162f8d3, 0x979f8038, 0x149e3567, 0xdcc1007d, "....." },
  [954] = { "⟦Bashal'Aran=Bashal'aran⟧", "Trova l'origine della strana aura blu tra le rovine di ⟦Bashal'Aran=Bashal'aran⟧.", "Le rovine di ⟦Bashal'Aran=Bashal'aran⟧, a est, sono invase da servitori demoniaci. Gli spiritelli e i satiri che si sono stabiliti nella zona si nutrono delle sue energie magiche, e i loro poteri crescono con l'esposizione continua.\n\nEppure ho notato che c'è un santuario a cui non si avvicinano. Sul lato occidentale delle rovine, in cima a una piccola altura, aleggia una strana aura blu... Deve esserci una spiegazione alla riluttanza dei demoni.\n\nVorrei che tu indagassi.", nil, "Ahh... A cosa mai devo l'onore straordinario della compagnia di un {race} come te? Davvero la dice lunga sui miei attuali compagni (senza offesa per i miei ospiti, i nobili grell e satiri) che la tua presenza possa considerarsi un miglioramento.\n\nMa ti prego, non lasciare che la mia lingua sgarbata ti scacci da questo luogo. Sono passati davvero molti anni, persino decenni, dall'ultima volta che ho avuto una compagnia civile.", 0x58cdf8a1, 0x3c376bcf, 0xaff407b3, nil, 0xb1c6dbd5, "...m." },
  [955] = { "⟦Bashal'Aran=Bashal'aran⟧", "Procura 8 Grell Earring per Asterion, a ⟦Bashal'Aran=Bashal'aran⟧.", "Se dovessi raccontarti la storia della mia vita, non ho dubbi che metterebbe a dura prova la tua pazienza. Diciamo che la mia è stata una vita lunga e dolorosa, e questa forma spettrale è forse il tormento peggiore di tutti.\n\nSono trattenuto qui per mezzo della magia. Anche se le mie parole possono sembrare poco sincere, ti assicuro che ti sarei grato oltre ogni dire se mi aiutassi a scoprire cosa mi tiene prigioniero. Mi vincola un sigillo, ed esaminando gli orecchini degli spiritelli e dei grell potrei trovarne una traccia.", "Quando avrò gli orecchini, lancerò l'incantesimo per cercare dove si trova il sigillo che mi vincola. Per secoli ho pensato alla libertà che mi darebbe la distruzione del sigillo... Forse quei secoli hanno logorato la mia mente al punto che non potrò mai più riprendermi...", "In effetti... I grell di ⟦Bashal'Aran=Bashal'aran⟧ non possiedono ciò che sto cercando... però ci sono venuti in contatto di recente. Di recente... intendo secondo il tuo tempo, non il mio. Per me il recente si estende nel velo del passato, quasi un'altra Era...", 0x58cdf8a1, 0xb1b08f05, 0x302949d5, 0xd4d00e5b, 0x1c6e13cb, "....." },
  [956] = { "⟦Bashal'Aran=Bashal'aran⟧", "Ottieni il ⟦Ancient Moonstone Seal=Sigillo di Pietraluna Antico⟧ e portalo ad Asterion a ⟦Bashal'Aran=Bashal'aran⟧.", "Se i grell sono venuti a stretto contatto con il sigillo che vincola la mia prigione eterna, credo di conoscerne la causa. Senza dubbio il sigillo è finito nelle mani dei satiri che li guidano.\n\nSento con forza che dev'essere così, {name}. Uno dei satiri deve certo possederlo. Se riuscirai a ottenerlo, mi porterai così vicino a varcare le sbarre della mia prigione che mi verrebbero le lacrime agli occhi.", "Le colonne di questo santuario sono per me come le sbarre di una prigione, {name}. Nessuna forza che ancora possiedo potrebbe spezzarle, e nessuna magia che padroneggio potrebbe distruggerle...\n\nPer più di mille anni le ho fissate, chiedendomi se, sopravvivendo infine persino alla pietra, sarei stato libero. O se allora mi avrebbero trattenuto sbarre invisibili...", "È... è difficile persino credere che ciò che stringo ora sia ciò che mi ha tenuto prigioniero tanto a lungo. Non perdiamo tempo, {name}. Quando il sigillo sarà distrutto, potrò di nuovo camminare libero per le foreste della terra.", 0x58cdf8a1, 0xfb2c025d, 0x0c0b89e8, 0x0eba01db, 0xc00d95ea, "....." },
  [957] = { "⟦Bashal'Aran=Bashal'aran⟧", "Distruggi il ⟦Ancient Moonstone Seal=Sigillo di Pietraluna Antico⟧ nell'antica fiamma di ⟦Ameth'Aran=Ameth'aran⟧, poi torna da Asterion a ⟦Bashal'Aran=Bashal'aran⟧.", "Fu l'arte di uno dei più potenti tra gli ⟦Highborne=Alti Nobili⟧ a creare il sigillo che formò la mia prigione. Ad ⟦Ameth'Aran=Ameth'aran⟧, le rovine a sud gemelle di queste, arde ancora oggi un'antica fiamma, di colore azzurro. In quella fiamma questo sigillo potrebbe essere distrutto.\n\nSii prudente tra le rovine, {name}...", "In verità, {name}, ho paura... Paura che il tuo arrivo, tutto questo, sia solo il frutto di una mente squilibrata. Riesci a immaginare che tortura sia? Io... Ti prego, devi fare presto.", "Sono libero, {name}! Ora posso vedere con i miei occhi i cambiamenti avvenuti nel nostro mondo... Ne ho conosciuto solo frammenti. Pensare che l'ultima volta che camminai libero il Pozzo esisteva ancora e gli ⟦Highborne=Alti Nobili⟧ tenevano corte con Azshara, la nostra amata regina.\n\nSento che il mio carceriere, il mio antico padrone, Athrikus, è ancora vivo... Già il mio senso di disperazione lascia il posto a pensieri di vendetta.", 0x58cdf8a1, 0x77a1d7fa, 0x7a4ea159, 0xfa5255d4, 0x0a963c92, "....." },
  [958] = { "Gli strumenti degli ⟦Highborne=Alti Nobili⟧", "Recupera 7 Reliquie degli ⟦Highborne=Alti Nobili⟧ per Thundris Windweaver, ad Auberdine.", "{class}. Ho un compito da chiederti.\n\nHai visto le rovine di ⟦Ameth'Aran=Ameth'aran⟧? Se non le hai viste, le troverai sul lato orientale della strada principale, un po' più a sud. Un tempo erano la dimora di molti potenti ⟦Highborne=Alti Nobili⟧, ora sono una testimonianza della distruzione che le loro pratiche hanno causato.\n\nLe ⟦Sentinels=Sentinelle⟧ mi hanno detto che gli spiriti degli ⟦Highborne=Alti Nobili⟧ sono ancora lì e che brandiscono i loro antichi strumenti magici. Quelle reliquie vanno sottratte, così che possiamo distruggerle.", "Se solo gli strumenti della loro rovina fossero stati distrutti nel cataclisma che ha distrutto il nostro mondo... Comunque, dobbiamo fare il possibile perché gli orrori del nostro passato non si ripetano in futuro.", "Anche se è di certo frutto della mia immaginazione, mi sembra quasi di percepire su di esse la contaminazione dell'immonda magia degli ⟦Highborne=Alti Nobili⟧. Le farò distruggere, perché il loro male, rimasto a lungo sopito, non possa mai più essere liberato.", 0xf1c555fe, 0x1bf755d6, 0xc1d7eb43, 0xc63c0c84, 0x53b1da4b, "....." },
  [959] = { "Guai al molo", "Il gruista Bigglefuzz di ⟦Ratchet=Porto Paranco⟧ vuole che tu recuperi la bottiglia di ⟦99-Year-Old Port=Porto di 99 Anni⟧ da Mad Magglish, che si nasconde nella ⟦Wailing Caverns=Caverna dei Lamenti⟧.", "Ops!\n\nHo avuto un piccolo incidente, come vedi! Il carico del mattino dalla ⟦Booty Bay=Baia del Bottino⟧ era enorme. Enorme, ti dico! Mai viste tante casse. Be', cercavo di sbrigarmi, così ho cominciato a scaricarne un po' più di quante ne potessi gestire. Ed è lì che è crollato tutto.\n\nPrima che capissi cosa stava succedendo, ho visto quella peste di Mad Magglish scappare con una bottiglia di porto di 99 anni. L'ho inseguito fino alla ⟦Wailing Caverns=Caverna dei Lamenti⟧. Lì dentro non ci entro di certo.\n\nForse tu hai abbastanza fegato per trovarlo?", "Il capo del porto mi sta addosso da quando Mad Magglish se l'è svignata con quel porto di 99 anni. A quanto pare, quella bottiglia era un regalo per Gazlowe da parte nientemeno che del barone Revilgaz in persona.\n\nSe hai abbastanza coraggio e pazienza da andare a cercare Mad Magglish e riprenderti quel porto, farò in modo che tu riceva una bella ricompensa.", "Superbo! E proprio quando stavo per perdere anche il lavoro! Farò in modo che Gazlowe riceva subito questo regalo.\n\nGrazie, {name}. Ben fatto, davvero!", 0x6013131a, 0x90fc1932, 0x0388702e, 0x5b209d4d, 0x2b9e98ad, "....." },
  [960] = { "Onu sta meditando", nil, nil, nil, "Sto meditando sul tuo compito, {name}. Medito sulle ragioni per cui il ⟦Twilight's Hammer=Martello del Crepuscolo⟧ e i naga sono qui.\n\nQuando sei pront<o/a>, usa la fiala della divinazione per creare una coppa della divinazione. Poi contattami attraverso la coppa.\n\nSe hai perso la tua fiala della divinazione, eccone un'altra.", 0x0ff81326, nil, nil, nil, 0xbfcb1ba3, ".mmm." },
  [961] = { "Onu sta meditando", nil, nil, nil, "La scoperta dei cultisti del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ è preoccupante. Devo meditare sulle loro intenzioni...\n\nQuando avrai altre informazioni, parlami attraverso una coppa della divinazione. Se ti serve una fiala della divinazione per creare una coppa, allora... eccone un'altra.", 0x0ff81326, nil, nil, nil, 0x10632bc8, ".mmm." },
  [962] = { nil, "La speziale Zamah, a ⟦Thunder Bluff=Picco del Tuono⟧, vuole che tu raccolga 10 Serpentbloom.", "La Royal Apothecary Society, che ha sede nella grande ⟦Undercity=Sepulcra⟧ di Lordaeron, mi ha mandata qui per un compito ben preciso, {name}. Forse vorrai aiutare me, e quindi la Dama Oscura, nei nostri sforzi per far progredire i Reietti.\n\nDi recente ho studiato un raro esemplare di flora chiamato Serpentbloom. Credo che, in quantità maggiori, quest'erba abbia grandi potenzialità.\n\nPurtroppo la Serpentbloom cresce solo nei recessi più bui della ⟦Wailing Caverns=Caverna dei Lamenti⟧, un pericoloso sistema di grotte che si trova nelle ⟦Barrens=Savane⟧.", "Non vedo l'ora di sapere se riuscirai a raccogliere abbastanza Serpentbloom nella ⟦Wailing Caverns=Caverna dei Lamenti⟧. Ho mandato molti a eseguire i miei ordini, ma nessuno è tornato.", "Ah, esemplari splendidi. Hai fatto un buon lavoro, {name}.", 0xea89f502, 0x5cf671d6, 0xd4d08318, 0xb23d9d2a, 0x898d5dc4, "e...." },
  [963] = { "Per un amore eterno", "Libera lo spirito di Anaya Dawnrunner e riporta il suo pendente a Cerellean Whiteclaw ad Auberdine.", "Dopo le battaglie al ⟦Well of Eternity=Pozzo dell'Eternità⟧, seppi che ⟦Ameth'Aran=Ameth'aran⟧ era stata distrutta e la sua gente uccisa, compreso il mio amore, Anaya.\n\nNon avrei mai pensato che, migliaia di anni dopo, il ricordo di Anaya avrebbe ancora tormentato i miei sogni. Vagando come in trance per i boschi di ⟦Darkshore=Rivafosca⟧, mi ritrovai tra le rovine di ⟦Ameth'Aran=Ameth'aran⟧... dove vidi lo spirito tormentato della mia amata.\n\nDeve essere liberata, ma non ho il coraggio di farlo. Il suo spirito deve essere distrutto.", "Con un grande dolore nel cuore, seguii lo Shan'do Stormrage nel letargo e portai il mio dolore nei sogni, dormendo per migliaia di anni.", "Grazie, {name}. Forse sarebbe stato meglio... se l'avessi fatto io. Ma nemmeno dopo tutte queste migliaia di anni riuscivo ad alzare la mano contro la mia amata.\n\nTi prego, vorrei restare solo con il mio dolore...", 0xeea4b9a0, 0x229907e1, 0x038cd4bb, 0x18987e92, 0x1a264e3b, "....." },
  [965] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Trova Balthule Shadowstrike vicino alla ⟦Tower of Althalaxx=Torre di Althalaxx⟧, a ⟦Darkshore=Rivafosca⟧.", "Salute, giovane {race}. Sono Elissa Starbreeze, e il mio compito è proteggere Auberdine da ogni male.\n\nA tal fine ho mandato Balthule Shadowstrike a osservare gli strani avvenimenti intorno alla ⟦Tower of Althalaxx=Torre di Althalaxx⟧, a nord-est.\n\nAvrebbe dovuto tornare già da tempo. Temo che abbia incontrato qualche pericolo imprevisto nella foresta. Ti sarei molto grata se lo trovassi e ti accertassi che stia bene.", nil, "Ti manda Elissa? Allora porti buone notizie. Io ho notizie preoccupanti da riferirle e nessun modo per fargliele avere.", 0x6dbe45ec, 0xdb947d32, 0xf74bdde2, nil, 0x7808df32, "...m." },
  [966] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Raccogli 4 Worn Parchment per Balthule Shadowstrike, vicino alla ⟦Tower of Althalaxx=Torre di Althalaxx⟧.", "Un gruppo di stregoni si è stabilito dentro e intorno alla torre. Sarei tornato prima ad Auberdine per fare rapporto a Elissa, ma temevo di perdermi qualcosa durante la mia assenza.\n\nDelgren sospettava che una simile compagnia potesse radunarsi alla torre, ma non sapeva perché.\n\nSono riuscito a mettere le mani su qualche brandello di pergamena che gli stregoni portano con sé, ma me ne servono altri per completare il quadro. Però ti avverto: non avventurarti nella torre, gli stregoni là dentro sono molto più potenti!", "Hai trovato altre loro pergamene? Se riesci a trovarle, dovrei poter ricostruire un quadro più ampio del culto.", "Molte grazie, {name}. Questo dovrebbe fare un po' di luce su questo raduno di stregoni...\n\nMmm... il Cult of the Dark Strand... Non ho mai sentito parlare di questo gruppo. Senza sapere nulla della loro storia, è quasi impossibile dire quali possano essere i loro piani.\n\nNon c'è più tempo da perdere. Delgren va avvertito immediatamente.", 0x6dbe45ec, 0x50a2d0dd, 0x43621fad, 0xc078402c, 0xc22bb9fd, "....." },
  [967] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Consegna la lettera di Balthule a Delgren the Purifier, nella foresta di ⟦Ashenvale=Valtetra⟧.", "Il mio maestro, Delgren the Purifier, è un paladino che ha generosamente offerto il suo aiuto per difendere le nostre foreste dalle forze dei demoni e dei non morti. Mi ha insegnato molto sulla ⟦Holy Light=Luce Sacra⟧ e sull'arte della battaglia.\n\nDelgren deve sapere subito delle attività del culto.\n\nLo troverai molto più a sud, all'⟦Maestra's Post=Accampamento di Maestra⟧, nella foresta di ⟦Ashenvale=Valtetra⟧. Sii rapid<o/a>: temo che la minaccia del Dark Strand cresca di ora in ora.", "Hai qualche faccenda da sbrigare con me, {class}?", "Se mi permetti, sembri un po' troppo ben equipaggiat<o/a> per essere un messaggero, eh? Immagino che Balthule volesse essere certo che la sua lettera arrivasse nelle mie mani. Vediamo cosa dice...\n\nSono notizie inquietanti. Quando si scoprono forze non morte o demoniache, aiuto le ⟦Sentinels=Sentinelle⟧ a distruggerle.\n\nAll'inizio non ero abituato ai modi degli Elfi della Notte, ma ho imparato a rispettarli profondamente come alleati.", 0x6dbe45ec, 0x6d6be3b8, 0xa0f446d1, 0xba59c4d3, 0xec7f73c4, "....." },
  [968] = { "Poteri Sotterranei", "Porta il ⟦Book: The Powers Below=Libro: Poteri Sotterranei⟧ a Gerrig Bonegrip nella Forlorn Cavern, a ⟦Ironforge=Forgiardente⟧.", "Anche se molto consunto e graffiato, il titolo di questo libro si legge ancora sulla copertina:\n\nPoteri Sotterranei\n\nAll'interno del libro c'è un elenco di nomi impronunciabili con titoli inquietanti, metodi di culto e sacrifici preferiti... molti dei quali comprendono creature umanoidi vive.\n\nSull'interno della copertina ci sono queste parole: «Bonegrip's Runes and Dooms, The Forlorn Cavern, ⟦Ironforge=Forgiardente⟧. Proprietario: Gerrig Bonegrip.»\n\nSe Bonegrip vende libri come questo, forse ricomprerà anche questo.", "Salve, <signore/signora>.\n\nPosso interessarti a uno dei miei tomi?", "Ah, una copia di Poteri Sotterranei. Un testo interessante, questo. E qualcuno potrebbe trovarlo utile...\n\nMa questa è ridotta proprio male. E guarda qui! Ci sono note a margine su quasi ogni pagina!\n\nMm... conosco questa copia. L'ho venduta a Bolgar l'anno scorso. Sei... un suo amico? Sì, lo immaginavo. Hai lo stesso fuoco negli occhi!\n\nBeh, per definizione, un amico di Bolgar è un mio amico. E noi ci prendiamo cura dei nostri, giusto?", 0x8858c96d, 0x4d442245, 0x931dde4e, 0x94f07e78, 0x6c99ccde, ".....", nil, nil, nil, 0xbcd83266, nil },
  [970] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Recupera una ⟦Glowing Soul Gem=Gemma dell'Anima Brillante⟧ e riportala a Delgren il Purificatore all'⟦Maestra's Post=Accampamento di Maestra⟧.", "La lettera di Balthule è allarmante. Questo Cult of the Dark Strand è una spina nel fianco che va estirpata. Ho avuto a che fare con un po' di quella feccia del Dark Strand a nord-est di qui, a Ordil'Aran. Uno di loro possiede una gemma dell'anima che credo custodisca il segreto del potere del culto.\n\nPortamela e potrò decifrare i segreti che racchiude.", "Hai trovato quella gemma dell'anima?", "Mm, una magia oscura incanta questa pietra dell'anima. Vediamo cosa c'è intrappolato dentro, che ne dici?", 0x6dbe45ec, 0xdf5dcec0, 0xf639e0e6, 0x74cacd19, 0x0a139b17, "....." },
  [971] = { "Sapere negli abissi", "Porta il ⟦Lorgalis Manuscript=Manoscritto di Lorgalis⟧ a Gerrig Bonegrip, nella Forlorn Cavern a ⟦Ironforge=Forgiardente⟧.", "Come forse saprai, colleziono conoscenze. Conoscenze antiche. Conoscenze potenti. Conoscenze che aprono porte, e conoscenze che possono risvegliare Coloro che Dormono.\n\nSi dice che un antico testo di sapere, il ⟦Lorgalis Manuscript=Manoscritto di Lorgalis⟧, si trovi in fondo agli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧, a ⟦Ashenvale=Valtetra⟧. Quel luogo era l'antica dimora di elfi morti da tempo. Elfi che possedevano un grande sapere prima che la loro città andasse in rovina.\n\nCerca il manoscritto negli ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. Fallo, e non lo dimenticherò. Nemmeno dopo... la fine dei giorni.", "Il viaggio fino a ⟦Ashenvale=Valtetra⟧ è lungo e il tuo compito non è facile. Ma se mi porti il manoscritto, {name}... la tua ricompensa sarà grande.", "Hai trovato il manoscritto! Che giorno gioioso! Ne verranno fatte copie da distribuire, e l'antico sapere di Lorgalis sarà finalmente noto ai miei fratelli e alle mie sorelle!\n\nIl tuo servizio vale per noi più di quanto immagini, {name}. Ma spero che questo dono ti mostri la gratitudine che riserviamo ai nostri alleati.", 0xadae7c9f, 0xed9d394b, 0x9d5e75c2, 0xfb9b685b, 0x2cf50e42, "....." },
  [972] = { "⟦Water Sapta=Sapta d'Acqua⟧", nil, nil, nil, "Prendi il Sapta d'Acqua e trova la pozza d'acqua corrotta a ⟦Silverpine=Pinargento⟧, {name}. Ho grande fiducia nelle tue capacità.", 0xcd2fb34a, nil, nil, nil, 0x5beca969, ".mmm." },
  [973] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Porta il ⟦Ilkrud Magthrull's Tome=Tomo di Ilkrud Magthrull⟧ a Delgren il Purificatore all'⟦Maestra's Post=Accampamento di Maestra⟧.", "Ilkrud Magthrull. Sì, lo conosco. È un potente stregone orco che risiede al ⟦Fire Scar Shrine=Santuario dello Sfregio Rovente⟧, un luogo di grande malvagità nel sud-ovest di ⟦Ashenvale=Valtetra⟧.\n\nFinora era stato poco più di una seccatura e non me n'ero occupato, ma pare che sia giunta la sua ora.", "Mi sembri un po' scoss<o/a>, {name}. Stai bene?", "Quella di oggi è stata una grande impresa, {name}. Dovresti essere molto fier<o/a> di te per aver affrontato uno stregone così potente.\n\nOra vediamo cosa possiamo imparare dagli scritti di Ilkrud.", 0x6dbe45ec, 0xbec21fbf, 0xa5e7b8bb, 0x3e2447c6, 0xca5719ec, "....." },
  [976] = { "Rifornimenti per Auberdine", "Parla con Delgren il Purificatore all'⟦Maestra's Post=Accampamento di Maestra⟧ dopo aver scortato Feero sano e salvo attraverso la foresta di ⟦Ashenvale=Valtetra⟧.", "Delgren mi ha chiesto di consegnare messaggi e rifornimenti alla sentinella Starbreeze ad Auberdine, ma non mi va di partire da solo. Nella foresta si aggirano nemici pericolosi e non voglio rischiare che questi rifornimenti e queste informazioni finiscano nelle mani sbagliate.\n\nSe tu e altri poteste farmi da scorta, potrei partire subito. Con la vostra protezione, non ho dubbi che riusciremo a portare queste merci sane e salve ad Auberdine.", "Le ⟦Sentinels=Sentinelle⟧ hanno un gran bisogno di rifornimenti per rafforzarsi a ⟦Darkshore=Rivafosca⟧.", "Oggi hai fatto un buon lavoro, {class}. I rifornimenti che abbiamo mandato in aiuto ad Auberdine serviranno subito ad affrontare le oscure minacce che infestano la foresta.\n\nPrendi questi, con la mia sincera gratitudine.", 0xcbd0f669, 0x33bf359a, 0x88ce1007, 0x30b8fa32, 0xde942b67, "....." },
  [981] = { "La ⟦Tower of Althalaxx=Torre di Althalaxx⟧", "Parla con Delgren il Purificatore all'⟦Maestra's Post=Accampamento di Maestra⟧.", "Per tutto il lavoro che hai svolto, meriti una buona ricompensa. Torna da Delgren e digli che Athrikus Narassin giace immobile per mano tua e che il Cult of the Dark Strand è sconfitto e disperso.", nil, "Sapevo che saresti stat<o/a> all'altezza del compito, {name}.\n\nPercepisco grandi imprese davanti a te, e che porrai rimedio a molti dei torti che affliggono le nostre terre. Porta con te le mie benedizioni, {name}, e anche questo dono.", 0x6dbe45ec, 0x01697167, 0xd28e1f05, nil, 0xda5abf55, "...m." },
  [982] = { "Oceano profondo, mare vasto", "Recupera lo ⟦Silver Dawning's Lockbox=Scrigno dell'Alba d'Argento⟧ e lo ⟦Mist Veil's Lockbox=Scrigno del Velo di Nebbia⟧ per Gorbold Steelhand ad Auberdine. Entrambi si trovano fra i relitti delle navi a nord del villaggio.", "Al largo della costa di ⟦Darkshore=Rivafosca⟧, a nord di qui, ci sono due navi naufragate: la Silver Dawning e la Mist Veil. Tempo fa, entrambe le navi sono finite in balia di quei maledetti murloc mentre attraversavano il vasto mare diretti ad Auberdine. Ora giacciono sul fondo dell'oceano, trofei di quei mostri.\n\nNessuno dei due capitani è sopravvissuto quella notte, e i loro diari di bordo e altri effetti sono ancora laggiù, chiusi negli scrigni. Vorrei che li recuperassi per noi; significherebbe molto per i membri degli equipaggi che vivono ancora da queste parti.", "I capitani di quelle navi erano bravi elfi della notte, e meritavano una sorte migliore di quella che è toccata loro. Forse prendersi cura dei loro effetti personali sarà il modo migliore per dare pace ai loro spiriti.", "Hai reso un gran servizio a tutti noi qui ad Auberdine, <ragazzo/ragazza>. Faremo in modo che i loro effetti vengano trattati come si deve.\n\nQuanto a te, ti prego, prendi questo. È il minimo che possa fare per chi ha avuto il coraggio di rimettere le cose a posto.", 0x7355073d, 0xcfdd6269, 0x145f3c4e, 0x2b87f83b, 0x1cb94298, ".....", nil, nil, nil, nil, 0xbe9c2983 },
  [983] = { nil, "Raccogli 6 Zampe di Crostaceo e inseriscile nel Buzzbox 827.", "Ehi! Aiutami con la mia ultima invenzione, il buzzbox. Puoi parlare con gente lontanissima!\n\nForse li hai già visti, sono scatole con delle leve sopra. L'unico problema è che hanno bisogno di manutenzione continua.\n\nOgnuno ha un guasto diverso, ma ho preso una decisione davvero furba. Li ho piazzati tutti vicino a creature che hanno i pezzi giusti per riparare quella macchina in particolare. Proprio ora il Buzzbox 827 fa le bizze. È appena a sud di Auberdine, vicinissimo. Servono 6 Zampe di Crostaceo per ripararlo. Ti pagherò...", "Il Buzzbox 827 se ne sta in un silenzio inquietante. Una sola spia lampeggiante indica che bisogna mettere 6 Zampe di Crostaceo nel suo scomparto.", "Mentre inserisci le Zampe di Crostaceo nella macchina, senti gli ingranaggi che cominciano a girare. A giudicare dai colpi che provengono dal Buzzbox, credi che le Zampe di Crostaceo vengano messe al loro posto. Presto la macchina comincia a ronzare, e senti una vocina che chiama dall'interno.\n\n«Pronto? Ehm... Pronto! L'hai riparato! Comunque sono Wizbang! Grazie mille... Ehi, non è che ne ripareresti un altro, eh?»", 0xed396ee3, 0xe5d8e072, 0xe3959d90, 0xd3d4bf05, 0xb8705f2d, "e...." },
  [984] = { "Quanto è grave la minaccia?", "Trova un accampamento di mezzorsi corrotti a ⟦Darkshore=Rivafosca⟧ e torna da Terenthis ad Auberdine.", "Alcuni dei miei fratelli sono stati salvati da un mezzorso corrotto a Teldrassil, e ho giurato di fermare altre atrocità prima che altri della nostra gente vengano feriti... o peggio.\n\nHo già visto un paio di indizi di corruzione a ⟦Darkshore=Rivafosca⟧, ma non ho ancora trovato segni diffusi. Credo che sarebbe logico proseguire l'indagine con i mezzorsi. Potresti trovare uno dei loro accampamenti e tornare da me se vedi segni di corruzione?", "Come va la ricerca, {name}?", "È davvero una pessima notizia, {name}.\n\nCon i mezzorsi così vicini ad Auberdine, dovremo prepararci all'inevitabile.\n\nGrazie, {name}.", 0xbceca2f9, 0xdbec2402, 0xe0cddc5b, 0xb0630bc5, 0x6c96ba7c, "....." },
  [985] = { "Quanto è grave la minaccia?", "Uccidi 8 Blackwood Pathfinder e 5 Windtalker e torna da Terenthis, ad Auberdine.", "Hai già dimostrato di saper spiare il nemico, {name}. Ma hai anche la stoffa per combatterlo?\n\nNon tutti gli avventurieri preferiscono lo scontro diretto all'arte della furtività e dell'elusione.\n\nSe pensi di essere all'altezza del compito, l'accampamento dei mezzorsi a sud di Auberdine è al momento la minaccia più grande per il nostro popolo. Lì troverai alcuni membri della tribù Blackwood. Uccidi 8 Pathfinder e 5 Windtalker, e torna qui da me.", "Non esitare a fare ciò che va fatto, giovane. So quanto ti debba ripugnare l'idea di uccidere le creature della foresta, ma in questo caso è necessario. Non si è ancora trovata una cura per la corruzione scatenata sulla foresta, e dobbiamo fare il possibile per fermarne l'avanzata finché non se ne troverà una.", "Lava il sangue dalle tue vesti, {name}, e non piangere per ciò che hai dovuto fare. Rendi grazie, piuttosto. Hai ridotto la minaccia per il nostro popolo qui ad Auberdine, anche se ⟦Darkshore=Rivafosca⟧ è ancora in pericolo per gli effetti del muschio vile.", 0xbceca2f9, 0x5ededd64, 0x44114385, 0xe43d21de, 0x467213bb, "....." },
  [986] = { "Un padrone perduto", "Trova 5 Fine Moonstalker Pelt e portale a Terenthis ad Auberdine.", "{name}, le tue capacità mi hanno già aiutato nella mia impresa. Posso chiederti ancora di aiutare Grimclaw e il suo padrone Volcor? Inoltre, posso confezionarti un mantello magico che ti permetterà di muoverti <indisturbato/indisturbata> tra le creature di Rivafosca mentre lo cerchi.\n\nPer creare il mantello mi serviranno cinque pelli pregiate di predaluna, prese da un capobranco o da una matriarca di predaluna, per avere materiale a sufficienza. Questi felini si trovano vicino al ⟦Wildbend River=Fiume Lettocurvo⟧, a sud, o ancora più a sud, vicino a ⟦Ashenvale=Valtetra⟧.", "In coscienza non posso permetterti di cercare Volcor finché non ti avrò confezionato quel mantello.", "Andranno benissimo, {name}. Mi metterò subito al lavoro sul mantello.\n\nDammi qualche istante, poi torna da me.\n\nOh, un'ultima cosa: dopo aver usato l'incantamento del mantello, le tue interazioni con gli altri saranno limitate. Se puoi evitarlo, non fare altro che parlare con gli altri. Qualcosa di più potrebbe dissolvere l'illusione.", 0x9437ffb8, 0xca85525c, 0x7310ed86, 0x249ed804, 0xbdb74a95, "....." },
  [990] = { "In marcia verso ⟦Ashenvale=Valtetra⟧", "Trova Raene Wolfrunner a ⟦Ashenvale=Valtetra⟧.", "{name}, la mia signora, Raene Wolfrunner, ti aspetta nella città di Astranaar, a ⟦Ashenvale=Valtetra⟧. Con il tuo aiuto, forse potremo almeno alleviare parte della corruzione che vi ha attecchito.\n\nDirigiti a sud da qui e resta vicino alla strada: se segui queste indicazioni arriverai senza problemi.", nil, "Ah, un {class} da ⟦Darkshore=Rivafosca⟧. Selarin ha fatto bene a mandarti qui così in fretta, {name}. Vorrei che il tuo viaggio non avvenisse in circostanze così gravi. Forse con il tuo aiuto potremo migliorare le cose.\n\nIo comincerei la visita parlando con gli altri cittadini di Astranaar. Qualcuno avrà di certo bisogno del tuo aiuto.", 0x2a43ad8f, 0x98ade4fe, 0x4a28ff7a, nil, 0x275f06e9, "...m." },
  [991] = { "La purificazione di Raene", "Trova Teronis a ⟦Ashenvale=Valtetra⟧.", "{name}, un mio vecchio amico sta aiutando anche lui le ⟦Sentinels=Sentinelle⟧ qui a ⟦Ashenvale=Valtetra⟧, ma non è ancora tornato.\n\nAveva delle piste per trovare un oggetto che, secondo lui, avrebbe potuto rallentare gli attacchi dei mezzorsi contro la nostra gente: una verga creata da un malvagio stregone, ormai morto.\n\nPrima di partire aveva detto di voler cercare una gemma per la verga.\n\nRiteneva che la gemma potesse essere nascosta nel santuario del ⟦Lake Falathim=Lago Falathim⟧, ai piedi della montagna a ovest. La gemma era custodita lì prima che il santuario venisse invaso.\n\nTrova il mio amico, {name}, ti prego.", nil, "Il corpo di Teronis giace straziato in cima all'isola. Per qualche ragione sconosciuta, i murloc non l'hanno toccato.\n\nI profondi squarci sul cadavere sono stati chiaramente inferti dalle armi e dagli artigli dei murloc.", 0x30e3be54, 0xc6c80ccb, 0x536c2270, nil, 0xe5bfb046, "...m." },
  [993] = { "Un padrone perduto", "Trova Volcor a ⟦Darkshore=Rivafosca⟧ e consegnagli il ⟦Enchanted Moonstalker Cloak=Mantello del Predaluna Incantato⟧.", "Il mantello è pronto, {name}. È giunto il momento di trovare Volcor. Posso solo sperare che siamo in tempo.\n\nLa magia del mantello, una volta invocata, non durerà a lungo: forse cinque minuti. Starà a te capire quando usarla: ti suggerirei di aspettare finché non trovi Grimclaw.\n\nSe ciò che mi ha detto è vero, troverai il suo padrone in una grotta a sud di qui. Grimclaw ti aspetterà lungo la strada. Quando lo vedi, fagli un cenno di saluto con la mano e ti indicherà la via verso il suo padrone.", nil, "Meraviglioso! Terenthis ha trovato qualcuno che mi aiutasse.\n\nE guarda, un mantello di predaluna...<tossisce> Oh... che male. Grazie, {name}.\n\nI mezzorsi mi hanno ferito prima che riuscissi a sfuggirgli. Dammi un momento e dovrei essere in grado di parlare ancora un po'.", 0x9437ffb8, 0x900ee79d, 0x246b1676, nil, 0x47b3ad53, "...m." },
  [994] = { "Fuga con la forza", "Proteggi Volcor finché non raggiungete la strada, poi parla con Terenthis ad Auberdine.", "D'accordo, {name}, useremo la forza. Andiamocene da qui appena sei <pronto/pronta>. Ci apriremo la strada combattendo fino alla via... Grimclaw dovrebbe essere ancora lì. Una volta arrivati, ci separeremo.\n\nTerenthis vorrà sentire subito la tua versione dei fatti, quindi dirigiti ad Auberdine quando saremo usciti da qui.", nil, "{name}! Sono lieto di vedere che sei <tornato/tornata> e che ce l'hai fatta. Il tuo aiuto a Volcor mi ha dato fiducia che possiamo superare le sfide che ci attendono qui a ⟦Darkshore=Rivafosca⟧ e oltre.", 0x2fba7967, 0x3c185ef0, 0x1806fdc3, nil, 0xcbf7190d, "...m." },
  [995] = { "Fuga furtiva", "Fuggi dalla grotta dei mezzorsi e raggiungi Terenthis ad Auberdine.", "D'accordo, allora... se ne sei sicur<o/a>, sgattaioleremo fuori di qui. Partiamo quando sei <pronto/pronta>.\n\nRicorda, dopo la fuga, raggiungi Terenthis ad Auberdine. Io ci andrò per conto mio, visto che probabilmente sarò più veloce di te.", "Sì, {name}?", "{name}! Sono lieto di vedere che sei <tornato/tornata> e che ce l'hai fatta. Il tuo aiuto a Volcor mi ha dato fiducia che possiamo superare le sfide che ci attendono qui a ⟦Darkshore=Rivafosca⟧ e oltre.", 0xad883aaf, 0x9dd2b11a, 0x65c47290, 0xabfc0333, 0xcbf7190d, "....." },
  [997] = { "La terra di Denalan", "Porta il pacco di ⟦Rare Earth=Terra Rara⟧ a Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Vai verso sud? Al ⟦Lake Al'Ameth=Lago Al'ameth⟧? Se è così, avrei un compito da chiederti...\n\nIl mio collega Denalan ha un accampamento sulla sponda orientale del lago, dove studia e fa esperimenti sulla flora di Teldrassil. Aveva chiesto un pacco di terre rare da Darnassus, che è arrivato in ritardo: è giunto qui a Dolanaar solo da poco.\n\nPuoi portargli il pacco?", "Hai qualcosa per me?", "Ah, eccola! Aspettavo questa terra rara da un bel po'. Spero che sia ancora fresca...\n\nGrazie per avermela portata, {name}. Sei <un/una> {race} che non risparmia il proprio tempo.", 0xa42c6191, 0x11448aaa, 0xcc1b2d88, 0xa03be4c2, 0x1cee6b9e, ".....", nil, nil, nil, nil, 0x8a75adc2 },
  [999] = { "Quando i sogni diventano incubi", nil, nil, nil, nil, 0x70340b99, nil, nil, nil, nil, ".mmmm" },
})
